_charge_stats_cache = {
    "timestamp": 0.0,
    "lines": ["Charging mode", "Gathering battery data..."],
    "percent": None,
    "ac_ok": None,
    "gauges": {},
}
_CHARGE_STATS_REFRESH = 5.0

