_cpu_prev_max_freq = {}

# Battery indicator render cache — only re-render when pct/charge state changes
_batt_render_cache = None
_batt_render_key = None

# Fan restore (Pi 5 active cooler exposes a cooling_device)
_fan_prev_states = {}
_fan_paths_cache = None

def _discover_backlight_paths():
    """Find writable backlight brightness sysfs nodes.

    Waveshare 4" DSI panels often expose a single backlight device like
    /sys/class/backlight/10-0045/brightness. We prefer known-good nodes first,
    then fall back to any other backlight entries.
    """
    global _backlight_paths
    if _backlight_paths is not None:
        return _backlight_paths

    preferred = [
        "/sys/class/backlight/10-0045/brightness",
        "/sys/waveshare/rpi_backlight/brightness",
        "/sys/class/backlight/rpi_backlight/brightness",
    ]

    paths = []
    try:
        # Add preferred paths if present
        for p in preferred:
            if Path(p).exists():
                paths.append(p)

        # Add any other backlight nodes
        for p in _glob_module.glob("/sys/class/backlight/*/brightness"):
            if p not in paths:
                paths.append(p)
    except Exception:
        pass

    _backlight_paths = paths
    return _backlight_paths

def _set_backlight_brightness(value):
    """Best-effort backlight control for DSI panels via /sys/class/backlight."""
    paths = _discover_backlight_paths()
    for p in paths:
        try:
            # cache previous value once
            if p not in _backlight_prev:
                try:
                    _backlight_prev[p] = int(Path(p).read_text().strip())
                except Exception:
                    _backlight_prev[p] = None
            Path(p).write_text(str(int(value)))
        except Exception:
            continue

def _restore_backlight():
    for p, prev in list(_backlight_prev.items()):
        if prev is None:
            continue
        try:
            Path(p).write_text(str(int(prev)))
        except Exception:
            pass


def _get_backlight_max_for_path(brightness_path):
    """Return max_brightness for a given brightness sysfs node, defaulting to 255."""
    try:
        max_path = str(Path(brightness_path).with_name("max_brightness"))
        return int(Path(max_path).read_text().strip())
    except Exception:
        return 255

def _wake_backlight_target():
    """Compute wake brightness target from the user's current setting."""
    paths = _discover_backlight_paths()
    if not paths:
        return None
    mx = _get_backlight_max_for_path(paths[0])
    pct = globals().get("_user_brightness_pct", 50)
    target = int(round(mx * (pct / 100.0)))
    if target < 1:
        target = 1
    if target > mx:
        target = mx
    return target

def _fade_backlight_to(target, duration_s=0.25, steps=12):
    """Fade backlight from current (or 0) to target in small steps."""
    if target is None:
        return
    # Ensure target is int
    try:
        target = int(target)
    except Exception:
        return
    if steps < 1:
        steps = 1
    dt = float(duration_s) / float(steps)
    # Start from 0 to avoid relying on cached previous brightness.
    for i in range(steps + 1):
        v = int(round(target * (i / float(steps))))
        _set_backlight_brightness(v)
        if dt > 0:
            time.sleep(dt)

def _wake_backlight_fade_in():
    """Wake backlight at the user's current brightness setting with a short
    fade-in (target computed by _wake_backlight_target from _user_brightness_pct)."""
    target = _wake_backlight_target()
    _fade_backlight_to(target, duration_s=0.25, steps=12)

def _set_wifi_block(block=True):
    """Block/unblock Wi‑Fi using rfkill (best-effort).

    Bounded: this runs on the main thread inside _enter_sleep_mode with the
    backlight already dark — an rfkill/sudo stall without a timeout would
    strand the loop before it ever reaches the wake-event wait (a camera
    that cannot be woken until power-cycle)."""
    try:
        subprocess.run(["sudo", "rfkill", "block" if block else "unblock", "wifi"],
                       check=False, timeout=5)
    except Exception:
        pass

def _idle_ethernet_down(settle_s=8.0):
    """Take link-less wired interfaces down to stop PHY polling (battery).

    The onboard PHY runs in polled-IRQ mode and keeps the MAC awake even
    with no cable attached. After a settle delay (carrier detection needs a
    moment post-boot) any ethernet interface still reporting no carrier is
    set administratively down. An interface with a live link (e.g. a dev
    bench cable) is left untouched; plugging in later just needs
    `ip link set <if> up`. Runs once from a startup daemon thread.
    """
    time.sleep(settle_s)
    try:
        for iface_path in _glob_module.glob("/sys/class/net/*"):
            name = os.path.basename(iface_path)
            if name == "lo" or os.path.isdir(os.path.join(iface_path, "wireless")):
                continue
            try:
                # ARPHRD_ETHER only — skip tunnels/bridges/other virtuals.
                if Path(iface_path, "type").read_text().strip() != "1":
                    continue
                # Admin-up check via IFF_UP: an unplugged-but-up interface
                # reports operstate "down" with carrier 0 — exactly the case
                # this function handles — so operstate can't be used here.
                flags = int(Path(iface_path, "flags").read_text().strip(), 16)
                if not (flags & 0x1):
                    continue  # already administratively down
                carrier = Path(iface_path, "carrier").read_text().strip()
            except Exception:
                continue
            if carrier == "0":
                subprocess.run(["sudo", "ip", "link", "set", name, "down"],
                               check=False, timeout=10)
                print(f"[Power] {name}: no link — set down to stop PHY polling")
    except Exception:
        pass

_cpu_policy_paths = None

def _get_cpu_policy_paths():
    global _cpu_policy_paths
    if _cpu_policy_paths is None:
        _cpu_policy_paths = _glob_module.glob("/sys/devices/system/cpu/cpufreq/policy*")
    return _cpu_policy_paths

def _set_cpu_low_power(enable=True):
    """Switch CPU governor and optionally clamp max freq (best-effort)."""
    try:
        pols = _get_cpu_policy_paths()
        for pol in pols:
            gov = Path(pol) / "scaling_governor"
            mx = Path(pol) / "scaling_max_freq"
            mn = Path(pol) / "scaling_min_freq"
            if gov.exists():
                if pol not in _cpu_prev_governor:
                    try:
                        _cpu_prev_governor[pol] = gov.read_text().strip()
                    except Exception:
                        _cpu_prev_governor[pol] = None
            if mx.exists() and pol not in _cpu_prev_max_freq:
                try:
                    _cpu_prev_max_freq[pol] = mx.read_text().strip()
                except Exception:
                    _cpu_prev_max_freq[pol] = None

            if enable:
                # governor
                try:
                    gov.write_text("powersave")
                except Exception:
                    pass
                # clamp max freq down to min freq
                try:
                    if mx.exists() and mn.exists():
                        mx.write_text(mn.read_text().strip())
                except Exception:
                    pass
            else:
                # restore
                try:
                    prev_g = _cpu_prev_governor.get(pol)
                    if prev_g:
                        gov.write_text(prev_g)
                except Exception:
                    pass
                try:
                    prev_m = _cpu_prev_max_freq.get(pol)
                    if prev_m:
                        mx.write_text(prev_m)
                except Exception:
                    pass
    except Exception:
        pass

# ---- CPU thermal cap (active during normal operation) ----
_CPU_THERMAL_CAP_KHZ = 1200000  # requested cap; clamps up to the lowest valid OPP
_CPU_4K_BOOST_KHZ   = 1800000  # 1.8 GHz boost for 4K video recording


def _cpufreq_read_khz(path):
    """Read a cpufreq sysfs value as int kHz, or None."""
    try:
        return int(Path(path).read_text().strip())
    except Exception:
        return None


def _cpufreq_clamp_to_valid(pol, target_khz):
    """Clamp a desired max frequency to a value the policy will accept.

    The Pi 5's stock OPP table bottoms out at 1.5 GHz, and the kernel rejects
    a scaling_max_freq below scaling_min_freq with EINVAL — a bare write of
    the 1.2 GHz cap silently fails and leaves the max at 2.4 GHz. Prefer the
    largest advertised OPP <= target, never below scaling_min_freq.
    """
    min_khz = _cpufreq_read_khz(Path(pol) / "scaling_min_freq") or 0
    try:
        raw = (Path(pol) / "scaling_available_frequencies").read_text()
        avail = sorted(int(tok) for tok in raw.split())
    except Exception:
        avail = []
    if avail:
        fits = [f for f in avail if min_khz <= f <= target_khz]
        return fits[-1] if fits else max(min_khz, avail[0])
    return max(target_khz, min_khz)


def _cpufreq_set_max(target_khz, label):
    """Set scaling_max_freq on every policy (clamped to a valid OPP) and
    verify by read-back. Returns the effective kHz, or None if nothing took."""
    effective = None
    try:
        for pol in _get_cpu_policy_paths():
            mx = Path(pol) / "scaling_max_freq"
            if not mx.exists():
                continue
            # The firmware never raises the policy floor. If something early
            # in boot left scaling_min_freq above the hardware minimum, both
            # the clamp below and the kernel would push our cap back up to it
            # (seen in the field as "requested 1200 MHz, effective 2400 MHz"
            # right at first frame) — reset the floor first.
            mn = Path(pol) / "scaling_min_freq"
            hw_min = _cpufreq_read_khz(Path(pol) / "cpuinfo_min_freq")
            cur_min = _cpufreq_read_khz(mn)
            if hw_min and cur_min and cur_min > hw_min:
                try:
                    mn.write_text(str(hw_min))
                    print(f"[CPU] {label}: scaling_min was {cur_min} kHz — "
                          f"reset to hw floor {hw_min} kHz")
                except Exception:
                    pass
            want = _cpufreq_clamp_to_valid(pol, target_khz)
            try:
                mx.write_text(str(want))
            except Exception as exc:
                print(f"[CPU] {label}: write {want} kHz to {mx} failed: {exc}")
            got = _cpufreq_read_khz(mx)
            if got is not None:
                effective = got
    except Exception as exc:
        print(f"[CPU] {label}: error: {exc}")
    if effective is None:
        print(f"[CPU] {label}: NOT applied (no cpufreq policy accepted a max)")
    elif effective != target_khz:
        print(f"[CPU] {label}: requested {target_khz // 1000} MHz, effective "
              f"{effective // 1000} MHz (nearest valid OPP)")
    else:
        print(f"[CPU] {label}: max freq {effective // 1000} MHz")
    return effective


def _apply_cpu_thermal_cap():
    """Cap CPU max frequency to reduce heat/power during normal operation.

    Uses 'ondemand' governor so the CPU still scales down when idle, but
    never exceeds the cap.  This runs once at startup; the existing
    _set_cpu_low_power sleep-mode logic saves/restores whatever the current
    (capped) state is, so sleep/wake still work correctly.  The effective
    cap is verified by read-back and logged — on a stock Pi 5 OPP table the
    1.2 GHz request clamps up to 1.5 GHz, which still eliminates the
    2.4 GHz bursts (and their higher DVFS core voltage) entirely.
    """
    try:
        for pol in _get_cpu_policy_paths():
            gov = Path(pol) / "scaling_governor"
            if not gov.exists():
                continue
            # ondemand (dynamic scaling), schedutil as fallback
            try:
                gov.write_text("ondemand")
            except Exception:
                try:
                    gov.write_text("schedutil")
                except Exception:
                    pass
    except Exception:
        pass
    return _cpufreq_set_max(_CPU_THERMAL_CAP_KHZ, "thermal cap")


def _thermal_cap_converge_worker():
    """Apply the thermal cap and re-assert until the read-back verifies.

    Field observation: at first frame the cap once read back 2400 MHz
    (requested 1200) while the cpufreq state looked normal again two
    minutes later — something early in boot can briefly hold the policy
    floor at the ceiling. Retry until the effective max lands at or below
    the clamped goal, then stop. Gives up quietly if sleep mode takes over
    (the sleep path owns the governor then, and every sleep/charge exit
    re-asserts the cap anyway).
    """
    goal = _CPU_THERMAL_CAP_KHZ
    try:
        for pol in _get_cpu_policy_paths():
            hw_min = _cpufreq_read_khz(Path(pol) / "cpuinfo_min_freq")
            if hw_min:
                goal = max(goal, hw_min)
    except Exception:
        pass
    for _attempt in range(6):
        # `_capture_cpu_performance` is no longer acquired by the 47 MP
        # capture or save paths (see its definition), so in practice only the
        # sleep and deferred-conversion branches can defer the cap now.  The
        # capture_cpu term stays as a belt-and-braces guard: if anything ever
        # holds that boost again, the cap must not fight it mid-flight.
        capture_cpu = globals().get('_capture_cpu_performance')
        if (sleep_mode_active or globals().get('_deferred_processing_busy', False)
                or (capture_cpu is not None and capture_cpu.active)):
            return
        effective = _apply_cpu_thermal_cap()
        if effective is not None and effective <= goal:
            return
        time.sleep(5.0)
    print("[CPU] thermal cap did NOT converge after 6 attempts — "
          "max CPU frequency may be uncapped this session")


def _set_cpu_4k_boost(enable=True):
    """Raise CPU max frequency to 1.8 GHz for 4K video, or restore to normal cap."""
    target_khz = _CPU_4K_BOOST_KHZ if enable else _CPU_THERMAL_CAP_KHZ
    _cpufreq_set_max(target_khz, "4K boost" if enable else "4K restore")


# TID of the main preview/UI loop thread, captured once the loop starts.  Used
# to pin that thread to a reserved core during 4K recording (see below).
_main_loop_tid = None


def _apply_video_cpu_affinity(reserve):
    """Reserve one CPU core for the preview/UI loop during 4K recording.

    The Pi 5 has no hardware H.264 encoder, so 4K is software-encoded by libav
    threads that otherwise saturate every core and starve the single-threaded
    preview loop — the cause of the live-view stutter while recording.  When
    `reserve` is True we pin the main loop thread to the top core and pin every
    other thread in the process (the encode workers included) onto the
    remaining cores, so the preview always has somewhere to run.  `reserve`
    False restores all threads to the full core set.

    Best-effort and fully guarded: a no-op on <4 cores or where affinity isn't
    supported, and never raises into a caller (firmware must not crash).  Note
    this does not raise the CPU clock — it only stops the encoder from crowding
    the UI thread off the cores, so it costs nothing on the battery budget.
    """
    try:
        if not hasattr(os, "sched_setaffinity"):
            return
        ncpu = os.cpu_count() or 1
        if ncpu < 4:
            return  # not worth carving a core out of a small SoC
        full = set(range(ncpu))
        reserved = ncpu - 1            # top core for the UI/preview thread
        workers = full - {reserved}    # encode workers + helper threads
        main_tid = _main_loop_tid
        if main_tid is None:
            # Without the main loop's TID we can't distinguish it from the
            # encode/helper threads below, so pinning "every other thread" onto
            # the worker cores would drag the UI thread off the reserved core
            # too — the opposite of the intent.  Skip entirely (nothing to
            # restore either, since we never pinned anything).
            return
        ui_set = {reserved} if reserve else full
        other_set = workers if reserve else full
        try:
            os.sched_setaffinity(main_tid, ui_set)
        except Exception:
            pass
        # Pin every *other* thread in this process onto the worker cores.  The
        # FfmpegOutput muxer is a separate subprocess (not in /proc/self/task),
        # so this targets the libav encode threads and our own helper threads.
        try:
            for entry in os.listdir("/proc/self/task"):
                try:
                    tid = int(entry)
                except ValueError:
                    continue
                if tid == main_tid:
                    continue
                try:
                    os.sched_setaffinity(tid, other_set)
                except Exception:
                    pass
        except Exception:
            pass
    except Exception:
        pass


def _fan_sysfs_paths():
    """Return a list of writable fan control nodes.

    On Pi 5 (and some hats/cases), the primary control is usually exposed as one or more
    /sys/class/thermal/cooling_device*/cur_state entries. The driver may override manual
    writes if the SoC is hot, so we treat this as best-effort.
    """
    global _fan_paths_cache
    if _fan_paths_cache is not None:
        return _fan_paths_cache

    paths = []
    base = Path("/sys/class/thermal")
    if base.exists():
        for cd in sorted(base.glob("cooling_device*")):
            t = (cd / "type")
            cs = (cd / "cur_state")
            if not (t.exists() and cs.exists()):
                continue
            try:
                typ = t.read_text().strip().lower()
            except Exception:
                typ = ""
            # Heuristics: prefer fan / pwm-fan devices
            if ("fan" in typ) or ("pwm" in typ):
                paths.append(str(cs))

    # Fallback to cooling_device0 if present
    p0 = Path("/sys/class/thermal/cooling_device0/cur_state")
    if str(p0) not in paths and p0.exists():
        paths.append(str(p0))

    _fan_paths_cache = paths
    return paths

def _set_fan_state(state):
    """Best-effort set fan cooling state (0=off)."""
    try:
        s = str(int(state))
    except Exception:
        s = "0"
    for p in _fan_sysfs_paths():
        try:
            Path(p).write_text(s)
        except Exception:
            pass

def _snapshot_fan_state():
    """Capture current fan state(s) for restore on wake."""
    global _fan_prev_states
    for p in _fan_sysfs_paths():
        if p in _fan_prev_states:
            continue
        try:
            _fan_prev_states[p] = Path(p).read_text().strip()
        except Exception:
            pass

def _restore_fan_state():
    """Restore fan state(s) captured before forcing (charge/sleep).

    If nothing was captured — a desync, or the fan was forced without a live
    snapshot (the state dict is shared across charge mode, sleep, and the
    exit-path hardware restore) — hand the fan back to the governor from a cool
    baseline (cur_state 0) instead of a no-op. Otherwise a forced-max fan can
    stay pinned high after the charger is unplugged, since our last write was
    max and nothing lowers it."""
    global _fan_prev_states
    if _fan_prev_states:
        for p, v in list(_fan_prev_states.items()):
            try:
                Path(p).write_text(str(v))
            except Exception:
                pass
        _fan_prev_states = {}
    else:
        _set_fan_state(0)

_fan_max_state_cache = None
def _fan_max_state():
    """Full-speed cooling level, read from the cooling device's max_state node
    (cached). Falls back to 4 (typical Pi 5 active-cooler levels) if unreadable;
    the kernel clamps an over-large write to the real max anyway."""
    global _fan_max_state_cache
    if _fan_max_state_cache is not None:
        return _fan_max_state_cache
    val = None
    for p in _fan_sysfs_paths():
        try:
            mx = int(Path(p.replace("cur_state", "max_state")).read_text().strip())
            if mx > 0:
                val = mx if val is None else max(val, mx)
        except Exception:
            pass
    _fan_max_state_cache = val if val is not None else 4
    return _fan_max_state_cache

# --- Charge-mode fan curve ---------------------------------------------------
# While charging we don't slam the fan to 100% (overkill + noisy) — start at a
# moderate baseline for airflow over the pack and step up with SoC temperature
# (the only thermal sensor this hardware exposes). Fractions of the cooling
# device's max level; the overheat safeguard still parks/escalates separately.
_CHARGE_FAN_BASE_FRAC = 0.40                       # moderate baseline (cool)
_CHARGE_FAN_CURVE = [(75.0, 1.0), (65.0, 0.8), (55.0, 0.6)]  # SoC C -> frac, high->low
_CHARGE_FAN_HYST_C = 3.0                            # step-down hysteresis
_charge_fan_level = 0                               # last applied level (0 = not forced)


def _charge_fan_frac(temp):
    for thr, frac in _CHARGE_FAN_CURVE:
        if temp >= thr:
            return frac
    return _CHARGE_FAN_BASE_FRAC


def _charge_fan_target_level(temp, current):
    """Cooling level for the charge fan at `temp` (°C, SoC proxy). Moderate
    baseline that steps up with heat; unknown temp -> baseline. Stepping DOWN
    requires temp to be _CHARGE_FAN_HYST_C below the boundary so it can't
    flip-flop at a threshold."""
    mx = _fan_max_state()
    if temp is None:
        return max(1, min(mx, int(round(mx * _CHARGE_FAN_BASE_FRAC))))
    lvl = max(1, min(mx, int(round(mx * _charge_fan_frac(temp)))))
    if current and lvl < current:
        lvl = max(1, min(mx, int(round(mx * _charge_fan_frac(temp + _CHARGE_FAN_HYST_C)))))
    return lvl


def _apply_charge_fan():
    """Drive the charge fan to the temp-stepped level and snapshot the governor
    state on first use (so unplug restores it). Called on charge entry and on
    the throttled reassert; always writes so the governor can't quietly lower it
    below our target."""
    global _charge_fan_forced, _charge_fan_level, _charge_fan_last_assert
    if not _charge_fan_forced:
        _snapshot_fan_state()
        _charge_fan_forced = True
    lvl = _charge_fan_target_level(_thermal_temp, _charge_fan_level)
    _set_fan_state(lvl)
    _charge_fan_level = lvl
    _charge_fan_last_assert = time.monotonic()


# How long the "Press shutter to wake" hint stays readable before the
# backlight blanks on sleep entry.
_SLEEP_HINT_HOLD_S = 1.2

# Touch handlers must never call _enter_sleep_mode() directly: the wake-hint
# toast below pumps cv2.waitKey, and _on_touch itself runs INSIDE the main
# loop's cv2.waitKey dispatch — a re-entrant pump from that context wedges
# the GUI event loop, so the main thread never reached the sleep wait and
# the shutter could no longer wake the camera (the hint sat frozen on
# screen; only the touch-initiated paths — swipe-up, charge-menu Sleep Now —
# were affected, which is why timer auto-sleep kept working). They set this
# request flag instead; the main loop enters sleep from its own context on
# the next iteration (same place auto-sleep runs). Same defer-to-loop
# pattern as _video_exit_requested.
_sleep_entry_requested = False


def _sleep_blocked_reason():
    """Why sleep must not be entered right now, or "" when it may.

    Only ACTIVE work blocks: a running recording, a long-exposure stack being
    built, a Brenizer sequence with tiles already on disk (its tile-to-tile
    exposure lock must survive to the last tile — sleeping would stop the
    pipeline and _apply_shutter_controls would hand the exposure back to AE
    mid-stitch), the charge screen (its own pipeline/backlight state) and the
    47 MP worker.  A merely SELECTED quiescent mode — video STANDBY, the LE
    idle panel, a Brenizer sequence with zero tiles — idles exactly like plain
    preview, so it must be allowed to dim and sleep: excluding those outright
    left a camera parked in video standby awake at 24 fps forever (battery).
    Single predicate so the auto-sleep gate, the deferred-request gate, the
    dim-step readout relax and the swipe-up gesture can never disagree.
    """
    try:
        with _video_lock:
            if _video_recording:
                return "video recording"
            if _video_recording_starting:
                # The GPIO thread is between committing to a recording and
                # start_encoder returning; _video_recording flips only at
                # the end of that, so this is the flag that keeps the
                # main loop from reconfiguring picam2 under it.
                return "video recording starting"
        with _le_lock:
            if _le_active and _le_state == "capturing":
                return "long-exposure capture"
        with _brenizer_lock:
            # Tiles already shot, or the completion screen up: the sequence
            # owns the locked exposure and the screen.  Zero tiles is nothing
            # but a sequence directory and a direction prompt.
            if _brenizer_active and (_brenizer_tile_idx > 0
                                     or _brenizer_locked_controls is not None
                                     or _brenizer_state != "awaiting_capture"):
                return "brenizer sequence"
        if charge_mode_active:
            return "charge mode"
        if _high_res_capture_busy.is_set():
            return "high-res capture"
    except Exception:
        # Never let a state read decide by raising: a lost sleep is a battery
        # regression, a sleep entered mid-capture would drop a shot.
        return "state unavailable"
    return ""


def _enter_sleep_mode():
    """Enter low-power 'fake sleep'."""
    global sleep_mode_active
    if sleep_mode_active:
        return

    # Quiescent creative modes are allowed to sleep now (see
    # _sleep_blocked_reason).  Video must still be EXITED here: video mode
    # runs the VIDEO configuration, and _exit_sleep_mode restores the STILL
    # one — waking would otherwise leave the flag set over a still pipeline.
    # LE-idle and a zero-tile Brenizer stay SELECTED across the sleep
    # instead: both already run on the ordinary still pipeline that
    # _start_still_pipeline_with_fallback() brings back on wake, neither has
    # anything in flight (no stack, no locked tile exposure), and the wake's
    # _apply_shutter_controls() re-derives their exposure from the same flags
    # that were set before the sleep — so the camera wakes in exactly the
    # state that went to sleep, with no surprise mode exit and no half-shot
    # sequence discarded.
    with _le_lock:
        _sleep_le_idle = _le_active
    with _brenizer_lock:
        _sleep_bren_idle = _brenizer_active
    if _video_mode_active:
        print("[Sleep] entering from video standby")
        _exit_video_mode()
    elif _sleep_le_idle:
        print("[Sleep] entering from long-exposure idle (mode kept)")
    elif _sleep_bren_idle:
        print("[Sleep] entering from Brenizer with no tiles shot (mode kept)")

    # Disarm flash sync: the pipeline is about to stop, so a live ring would
    # pin tens of MB through the whole sleep for frames that can never arrive.
    # The mode stays SELECTED — waking and pressing the shutter re-arms.
    _flash_disarm("sleep")

    # Clear any stale wake event BEFORE publishing sleep_mode_active: the
    # GPIO callbacks set the event iff they read the flag as True, so with
    # the old order a release landing between the two statements could have
    # its freshly-set wake event erased — a lost wake press.
    _sleep_wake_event.clear()
    sleep_mode_active = True

    # Stop camera pipeline to reduce ISP/CPU load
    try:
        picam2.stop()
    except Exception:
        pass

    # Wake hint: sleep can be entered by touch (swipe / Sleep Now) but wake
    # is the physical shutter button only, so say so before the panel goes
    # dark. Painted with one waitKey(1) (touch dispatched by it is swallowed
    # by the sleep guard in _on_touch); any failure must never block sleep.
    try:
        _hint_canvas = np.zeros((SCREEN_H, SCREEN_W, 3), dtype=np.uint8)
        _hint_block = make_rotated_text_block(
            [[{"text": "Press shutter to wake", "font_scale": 1.2}]],
            font_scale=1.2, thickness=2, rotate_180=True, max_h=40,
            pad_x=6, pad_y=4,
        )
        blit_add(_hint_canvas, _hint_block,
                 (SCREEN_W - _hint_block.shape[1]) // 2,
                 (SCREEN_H - _hint_block.shape[0]) // 2)
        _display_show("Camera", _hint_canvas)
        # Hold via waitKey pumps rather than time.sleep(): a blocking sleep
        # would leave any taps on the hint queued in the GUI event queue,
        # to be replayed as live taps on the restored UI after wake. Pumping
        # dispatches them now, into _on_touch's sleep guard, which swallows
        # them while sleep_mode_active is still set.
        _hint_start = time.monotonic()
        while time.monotonic() - _hint_start < _SLEEP_HINT_HOLD_S:
            _display_pump(50)
    except Exception:
        pass

    # Blank backlight (DSI panels typically expose /sys/class/backlight)
    _set_backlight_brightness(0)

    # Reduce power
    _set_wifi_block(True)
    # Wi-Fi is blocked during sleep, so the file download server is unreachable –
    # shut it down cleanly so it doesn't hold the port while the radio is off.
    try:
        _download_server_stop()
    except Exception:
        pass
    _set_cpu_low_power(True)
    # Force fan off (best-effort; driver may override if hot)
    _snapshot_fan_state()
    _set_fan_state(0)

def _exit_sleep_mode():
    """Wake from sleep: restore power settings and restart preview."""
    global sleep_mode_active, _current_backlight_level, _backlight_dimmed
    if not sleep_mode_active:
        return
    sleep_mode_active = False

    # Restore settings
    _wake_backlight_fade_in()
    # Sync internal brightness state to the user's level after fade-in completes
    _current_backlight_level = _BACKLIGHT_NORMAL_LEVEL
    _backlight_dimmed = False
    _set_cpu_low_power(False)
    # Lift the sleep block only when Wi-Fi is meant to be on: with the radio
    # off, _apply_wifi_state keeps the chip rfkill-blocked (its low-power
    # state), and waking must not undo that.
    if wifi_enabled:
        _set_wifi_block(False)
    # If Wi-Fi is enabled, bring the download server back up after wake.
    try:
        if wifi_enabled:
            _download_server_start()
    except Exception:
        pass
    _restore_fan_state()

    # Restart camera pipeline in still mode for instant capture.  Route
    # through the same fallback chain as boot / mode switch / charge-mode
    # exit: a raw configure() of the unbinned 47 MP mode reallocates the
    # largest buffer set in the firmware and can fail on a fragmented dma
    # heap — with no fallback that left the camera stopped forever on the
    # frozen "Press shutter to wake" screen ("shutter doesn't wake it").
    try:
        if _start_still_pipeline_with_fallback():
            time.sleep(0.1)
            _apply_shutter_controls()
        else:
            print("Wake: preview restart failed — fallback chain exhausted")
    except Exception as exc:
        print("Wake: preview restart error:", exc)


def _restore_hardware_state():
    """Best-effort hardware restore on any main-loop exit path (normal exit,
    fatal crash, SIGTERM): hand the fan back to the governor, bring the
    backlight up, undo the sleep/charge low-power CPU clamp (re-asserting the
    normal thermal cap), and unblock Wi-Fi if sleep mode rfkill-blocked it.
    Every step is guarded so one failure can't stop the others."""
    try:
        _restore_fan_state()
    except Exception:
        pass
    try:
        _restore_backlight()
        # Sleep/dim may have left the panel dark with nothing snapshotted to
        # restore — make sure the screen comes back at the user's brightness.
        if sleep_mode_active or _backlight_dimmed:
            target = _wake_backlight_target()
            if target is not None:
                _set_backlight_brightness(target)
    except Exception:
        pass
    try:
        _set_cpu_low_power(False)   # undo sleep/charge powersave clamp
    except Exception:
        pass
    try:
        _apply_cpu_thermal_cap()    # re-assert the normal 1.2 GHz cap
    except Exception:
        pass
    try:
        # Unblock only when the user's Wi-Fi setting is ON and sleep mode
        # blocked the radio mid-exit. With Wi-Fi off, the rfkill block IS the
        # persisted state (_apply_wifi_state) — leave it in place.
        if sleep_mode_active and wifi_enabled:
            _set_wifi_block(False)
    except Exception:
        pass


