# The whole PNG icon path — search order (theme override -> USB ->
# bundled), loader, tinter and compositor — lives with the theme section
# above, so the chain is described in one place.


# PLD button initialised lazily after gpiozero is imported (see _init_pld_button).
_pld_button = None


def _init_pld_button():
    """Initialise the PLD sense button (GPIO 6).  Called once after gpiozero is imported."""
    global _pld_button
    try:
        from gpiozero import Button as _Btn
        _pld_button = _Btn(6)
    except Exception:
        _pld_button = None


def _force_read_battery():
    global batt_percent_cached, batt_voltage_cached
    global batt_cell_voltage_cached, batt_pack_voltage_cached
    if not I2C_AVAILABLE:
        try:
            _batt_sense_record(False, False, None, None)
        except Exception:
            pass
        return None, None
    bus = None
    try:
        bus = smbus2.SMBus(1)
    except Exception:
        try:
            _batt_sense_record(True, False, None, None)
        except Exception:
            pass
        return None, None
    cap, volt, crate = _batt_read_gauge(bus)
    try:
        bus.close()
    except Exception:
        pass
    _update_battery_cache(cap, volt, crate)
    try:
        _batt_sense_record(True, True, cap, volt)
    except Exception:
        pass
    return volt, cap


def _read_vcgencmd_metric(args, strip_chars=""):
    try:
        output = subprocess.check_output(args, stderr=subprocess.DEVNULL, text=True)
    except Exception:
        return None
    if "=" not in output:
        return None
    metric = output.split("=", 1)[1].strip()
    if strip_chars:
        metric = metric.rstrip(strip_chars)
    try:
        return float(metric)
    except ValueError:
        return None


_CPU_TEMP_SYSFS_PATH = "/sys/class/thermal/thermal_zone0/temp"
_cpu_temp_sysfs_ok = True  # cache: once sysfs fails, stop re-probing it


def _read_cpu_temp():
    """SoC temperature in °C (float) or None. Prefers the sysfs thermal zone
    (no subprocess fork — this runs on the main thread every ~5 s); falls back
    to vcgencmd only if the sysfs read fails, and caches that outcome."""
    global _cpu_temp_sysfs_ok
    if _cpu_temp_sysfs_ok:
        try:
            return int(Path(_CPU_TEMP_SYSFS_PATH).read_text().strip()) / 1000.0
        except Exception:
            _cpu_temp_sysfs_ok = False
    return _read_vcgencmd_metric(["vcgencmd", "measure_temp"], "'C")


def _read_all_pmic_metrics():
    """Read all PMIC metrics in a single subprocess call.

    Returns dict with keys: cpu_volt, cpu_amp, input_volt, watts.
    Previously this required 4 separate subprocess calls.
    """
    result = {"cpu_volt": None, "cpu_amp": None, "input_volt": None, "watts": None}
    try:
        output = subprocess.check_output(
            ["vcgencmd", "pmic_read_adc"], stderr=subprocess.DEVNULL, text=True
        )
    except Exception:
        return result
    amperages = {}
    voltages = {}
    for raw_line in output.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) < 2:
            continue
        label = parts[0]
        value = parts[-1]
        if "=" not in value:
            continue
        try:
            val = float(value.split("=", 1)[1][:-1])
        except ValueError:
            continue
        # Extract individual metrics by label
        if label == "VDD_CORE_V":
            result["cpu_volt"] = val
        elif label == "VDD_CORE_A":
            result["cpu_amp"] = val
        elif label == "EXT5V_V":
            result["input_volt"] = val
        short_label = label[:-2]
        if label.endswith("A"):
            amperages[short_label] = val
        else:
            voltages[short_label] = val
    # Calculate total power
    total = 0.0
    for key, amps in amperages.items():
        volts = voltages.get(key)
        if volts is None:
            continue
        total += amps * volts
    result["watts"] = total if total > 0 else None
    return result


# Cache the resolved fan1_input sysfs path once found, so the charge-stats
# poll (every ~5 s) doesn't re-walk sysfs with rglob() every call. Cleared
# (re-walked) only if a read through the cached path fails.
_fan_rpm_path_cache = None


def _read_fan_rpm():
    global _fan_rpm_path_cache
    if _fan_rpm_path_cache is not None:
        try:
            with open(_fan_rpm_path_cache, "r") as fh:
                rpm = fh.read().strip()
            return f"{rpm} RPM"
        except Exception:
            _fan_rpm_path_cache = None  # stale/removed — fall through and re-walk
    try:
        base = Path("/sys/devices/platform/cooling_fan")
        for entry in base.rglob("fan1_input"):
            try:
                with open(entry, "r") as fh:
                    rpm = fh.read().strip()
                _fan_rpm_path_cache = entry
                return f"{rpm} RPM"
            except (FileNotFoundError, PermissionError):
                continue
    except Exception:
        pass
    return None


_pld_state_cache = {"ts": 0.0, "state": None}
_PLD_CACHE_TTL = 2.0  # Refresh AC power state every 2 seconds, not every frame


def _read_pld_state(use_cache=True):
    if _pld_button is None:
        return None
    if use_cache:
        now = time.monotonic()
        if now - _pld_state_cache["ts"] < _PLD_CACHE_TTL:
            return _pld_state_cache["state"]
    try:
        state = 0 if _pld_button.is_pressed else 1
    except Exception:
        state = None
    _pld_state_cache["ts"] = time.monotonic()
    _pld_state_cache["state"] = state
    return state


_CHARGE_TITLE_SCALE = 1.4
_CHARGE_BODY_SCALE = 1.0
_CHARGE_DIVIDER_SCALE = 0.5
_CHARGE_FOOTER_SCALE = 0.85
_CHARGE_LABEL_COLOR = UI_TEXT_DIM
_CHARGE_VALUE_COLOR = UI_TEXT_PRIMARY
_CHARGE_TITLE_COLOR = UI_ACCENT_SYSTEM
_CHARGE_FOOTER_COLOR = (130, 130, 130)
_CHARGE_OK_COLOR = (140, 220, 150)
_CHARGE_WARN_COLOR = (235, 175, 80)
_CHARGE_CRIT_COLOR = (240, 110, 110)
_CHARGE_HEADER_SCALE = 0.7
_CHARGE_HEADER_COLOR = UI_ACCENT_SYSTEM


def _charge_kv(label, value, value_color=None):
    return [
        {"text": f"{label}  ", "font_scale": _CHARGE_BODY_SCALE, "color": _CHARGE_LABEL_COLOR},
        {"text": value, "font_scale": _CHARGE_BODY_SCALE,
         "color": value_color if value_color is not None else _CHARGE_VALUE_COLOR},
    ]


def _charge_divider():
    return [{"text": " ", "font_scale": _CHARGE_DIVIDER_SCALE, "color": _CHARGE_LABEL_COLOR}]


def _charge_header(label):
    """Small caps-style section header ('BATTERY' / 'SYSTEM' / 'STORAGE') so
    the stats dump reads as grouped sections instead of one undifferentiated
    KV list."""
    return [{"text": label.upper(), "font_scale": _CHARGE_HEADER_SCALE,
             "color": _CHARGE_HEADER_COLOR}]


def _collect_power_stats(force_battery=False):
    if force_battery:
        _force_read_battery()
    with _batt_lock:
        pct = batt_percent_cached
        cell_volt = batt_cell_voltage_cached
        pack_volt = batt_pack_voltage_cached

    cpu_temp = _read_cpu_temp()
    # Single subprocess call for all PMIC metrics (was 4 separate calls)
    pmic = _read_all_pmic_metrics()
    cpu_volt = pmic["cpu_volt"]
    cpu_amp = pmic["cpu_amp"]
    input_volt = pmic["input_volt"]
    watts = pmic["watts"]
    fan = _read_fan_rpm()
    pld_state = _read_pld_state(use_cache=False)

    gauges = {}

    lines = [
        [{"text": "Charging Mode", "font_scale": _CHARGE_TITLE_SCALE,
          "color": _CHARGE_TITLE_COLOR}],
        _charge_divider(),
    ]

    # Explain an automatic overheat park so the user isn't left wondering why
    # the camera dropped back to the charge screen mid-shoot.
    if _charge_overheat_parked:
        lines.append(_charge_kv("Cooling down", "shooting paused",
                                value_color=_CHARGE_WARN_COLOR))

    lines.append(_charge_header("Battery"))

    # Battery group (percent is shown in the icon — keep this line for voltage).
    # On AC the gauge senses the charge rail rather than the cells, so the
    # voltage/SOC are unreliable (and read as a phantom with no pack installed).
    # The "AC Power: OK" line below already conveys the state, so omit the
    # smoothed battery readout while plugged in.
    if pld_state == 1:
        pass
    elif pack_volt is not None:
        lines.append(_charge_kv("Battery", f"{pack_volt:.2f} V"))
    elif cell_volt is not None:
        lines.append(_charge_kv("Battery", f"{cell_volt:.2f} V"))
    elif pct is not None:
        lines.append(_charge_kv("Battery", f"{pct:.1f}%"))
    else:
        lines.append(_charge_kv("Battery", "unavailable", value_color=UI_INACTIVE))

    # Pack-detection field: the RAW verdict of the X1200 fuel gauge's latest
    # poll, independent of the smoothed/latched display caches, so a "—" icon
    # can be triaged on the screen itself — no cells seen vs. UPS silent on
    # I2C vs. driver missing. Always shown on AC (where the smoothed line
    # above is withheld); on battery only when something is wrong, since the
    # voltage line already proves the pack is there.
    try:
        sense_txt, sense_sev, sense_hint = _batt_sense_describe(_batt_sense_snapshot())
        if pld_state == 1 or sense_sev != "ok":
            sense_color = {"ok": _CHARGE_OK_COLOR, "warn": _CHARGE_WARN_COLOR,
                           "crit": _CHARGE_CRIT_COLOR}.get(sense_sev, UI_INACTIVE)
            lines.append(_charge_kv("Pack", sense_txt, value_color=sense_color))
            if sense_hint:
                lines.append([{"text": sense_hint, "font_scale": _CHARGE_FOOTER_SCALE,
                               "color": _CHARGE_FOOTER_COLOR}])
    except Exception:
        pass

    if _batt_health_warn:
        lines.append(_charge_kv("Battery Health", "UNSTABLE — CHECK PACK",
                                value_color=_CHARGE_WARN_COLOR))

    if pld_state is not None:
        if pld_state == 1:
            lines.append(_charge_kv("AC Power", "OK", value_color=_CHARGE_OK_COLOR))
        else:
            lines.append(_charge_kv("AC Power", "LOST", value_color=_CHARGE_CRIT_COLOR))

    # Estimated runtime at the learned discharge pace — only meaningful when
    # actually running on battery. While charging, show time-to-full instead,
    # using the hardware charge rate (CRATE).
    if pld_state != 1:
        runtime_s = _batt_runtime_estimate_s()
        if runtime_s is not None:
            lines.append(_charge_kv("Est. Runtime", f"~{_format_runtime(runtime_s)}"))
    else:
        full_s = _batt_charge_estimate_s()
        if full_s is not None:
            lines.append(_charge_kv("Time to Full", f"~{_format_runtime(full_s)}"))

    lines.append(_charge_divider())
    lines.append(_charge_header("System"))

    # System / power group
    if input_volt is not None:
        lines.append(_charge_kv("Input", f"{input_volt:.2f} V"))
    if cpu_volt is not None or cpu_amp is not None:
        cpu_parts = []
        if cpu_volt is not None:
            cpu_parts.append(f"{cpu_volt:.3f} V")
        if cpu_amp is not None:
            cpu_parts.append(f"{cpu_amp:.3f} A")
        lines.append(_charge_kv("CPU Rail", " / ".join(cpu_parts)))
    if cpu_temp is not None:
        if cpu_temp < 65:
            temp_color = _CHARGE_VALUE_COLOR
        elif cpu_temp < 78:
            temp_color = _CHARGE_WARN_COLOR
        else:
            temp_color = _CHARGE_CRIT_COLOR
        lines.append(_charge_kv("CPU Temp", f"{cpu_temp:.1f} °C", value_color=temp_color))
        # Gauge fraction over a fixed 30-90 C display range (Pi 5 idle-to-hot
        # span) — reuses the exact tier color already computed above.
        gauges["cpu_temp"] = {
            "frac": max(0.0, min(1.0, (cpu_temp - 30.0) / (90.0 - 30.0))),
            "color": temp_color,
            "label": f"{cpu_temp:.0f}C",
        }
    if watts is not None:
        lines.append(_charge_kv("Power", f"{watts:.2f} W"))
    if fan:
        lines.append(_charge_kv("Fan", str(fan)))

    lines.append(_charge_divider())
    lines.append(_charge_header("Storage"))

    # Storage
    try:
        usage = shutil.disk_usage(LOCAL_PICTURES_DIR)
        free_gb = usage.free / (1024 ** 3)
        total_gb = usage.total / (1024 ** 3)
        free_mb = usage.free / (1024 * 1024)
        if free_mb < _DISK_CRITICAL_THRESHOLD_MB:
            storage_color = _CHARGE_CRIT_COLOR
            suffix = "  CRITICAL"
        elif free_mb < _DISK_WARN_THRESHOLD_MB:
            storage_color = _CHARGE_WARN_COLOR
            suffix = "  LOW"
        else:
            storage_color = _CHARGE_VALUE_COLOR
            suffix = ""
        lines.append(_charge_kv(
            "Storage",
            f"{free_gb:.1f} / {total_gb:.1f} GB free{suffix}",
            value_color=storage_color,
        ))
        if total_gb > 0:
            gauges["storage"] = {
                "frac": max(0.0, min(1.0, 1.0 - (free_gb / total_gb))),
                "color": storage_color,
                "label": f"{free_gb:.0f}G free",
            }
    except Exception:
        pass

    if _charge_shutdown_triggered:
        lines.append(_charge_divider())
        lines.append([{"text": "Shutting down – battery full",
                       "font_scale": _CHARGE_BODY_SCALE,
                       "color": _CHARGE_CRIT_COLOR}])

    lines.append(_charge_divider())
    lines.append([{"text": "Tap to exit charging mode",
                   "font_scale": _CHARGE_FOOTER_SCALE,
                   "color": _CHARGE_FOOTER_COLOR}])
    # Auto-shutdown only ever fires while AC power is actually present
    # (_maybe_trigger_charge_shutdown gates on the same pld_state == 1
    # signal) — showing this on a battery-only session promises a
    # shutdown that can't happen, since the runtime estimate above
    # already covers that case. Hidden when the user has disabled the
    # 95% auto power-off from the sleep submenu.
    if pld_state == 1 and _charge_auto_off_enabled:
        lines.append([{"text": "Unit will shut down at 95% charge",
                       "font_scale": _CHARGE_FOOTER_SCALE,
                       "color": _CHARGE_FOOTER_COLOR}])
    return lines, pct, gauges


def _update_charge_stats(force=False):
    now = time.monotonic()
    if not force and now - _charge_stats_cache["timestamp"] < _CHARGE_STATS_REFRESH:
        return (_charge_stats_cache["lines"], _charge_stats_cache["percent"],
                _charge_stats_cache.get("gauges", {}))
    lines, pct, gauges = _collect_power_stats(force_battery=force)
    ac_state = _read_pld_state(use_cache=True)
    ac_ok = (ac_state == 1)
    _charge_stats_cache["timestamp"] = now
    _charge_stats_cache["lines"] = lines
    _charge_stats_cache["percent"] = pct
    _charge_stats_cache["ac_ok"] = ac_ok
    _charge_stats_cache["gauges"] = gauges
    return lines, pct, gauges


def _maybe_trigger_charge_shutdown(percent):
    global _charge_shutdown_triggered
    if _charge_shutdown_triggered or globals().get("_deferred_processing_busy", False):
        return
    if percent is None:
        return
    # User toggle from the charge-menu sleep submenu.
    if not _charge_auto_off_enabled:
        return
    # Only auto-shutdown when AC power is plugged in during charge mode.
    ac_state = _read_pld_state(use_cache=False)
    if ac_state == 0:
        return
    if ac_state is None and _pld_button is not None:
        # The PLD hardware exists but this particular read glitched (True
        # "sensor unavailable" — no PLD GPIO at all — is the _pld_button is
        # None case below). Treat a glitch as unknown and do NOT shut down:
        # a single bad read must never be able to trigger `shutdown -h now`
        # while actually running on battery mid-session.
        return
    # ac_state is 1 (AC confirmed), or None with no PLD hardware present at
    # all — installations without the PLD GPIO still auto-shutdown at 95%.
    if percent >= 95.0:
        _charge_shutdown_triggered = True
        try:
            subprocess.Popen(
                ["sudo", "shutdown", "-h", "now", "Battery charged"],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
        except Exception as exc:
            print("Shutdown request failed:", exc)


def _charge_battery_present():
    """True when a battery pack is physically present. Keyed on cell voltage
    only — the authoritative presence signal that the no-battery detector acts
    on. The gauge's SOC (batt_percent_cached) can hold a stale/drifting value
    for a poll or two after a pack is pulled (it isn't suppressed until the
    no-battery latch trips), so trusting percent here would briefly force-enter
    charge mode on a no-pack USB session — exactly the "usable while tethered"
    case we must preserve."""
    with _batt_lock:
        return batt_cell_voltage_cached is not None


def _charge_should_force():
    """USB/AC power attached AND a battery pack present -> hold charge mode.

    On USB power with no pack inserted the camera stays fully usable. Returns
    False when the PLD sense GPIO is absent (_read_pld_state() is None) so a
    build without it is never trapped in charge mode. Also returns False while
    the user has chosen "Shoot while charging" (_charge_shoot_override) so the
    main loop doesn't drag them back to the charge screen."""
    if _read_pld_state() != 1:
        return False
    if _charge_shoot_override:
        return False
    return _charge_battery_present()


# --- Thermal safety watchdog (always-on, every mode) ---
# Only the SoC die temperature is readable on this hardware (no battery sensor:
# the fuel gauge exposes capacity/voltage only). The fan cools the shared
# enclosure, so SoC temp is the available proxy for an overheating condition.
_THERMAL_WARN_C = 82.0
_THERMAL_SHUTDOWN_C = 88.0
_THERMAL_SHUTDOWN_HOLD_S = 20.0
_THERMAL_CHECK_INTERVAL_S = 5.0
# "Shoot while charging" overheat safeguard. No pack/cell temperature exists on
# this hardware, so the SoC die temp is the proxy. Charging adds heat, so park
# to the cooling charge screen at a threshold BELOW the general warn line (82 C)
# and only re-enable shooting once well cooled (hysteresis) to avoid flapping.
_CHARGE_SHOOT_OVERHEAT_C = 80.0
_CHARGE_SHOOT_OVERHEAT_HOLD_S = 10.0
_CHARGE_SHOOT_RESUME_C = 68.0
_thermal_last_check = 0.0
_thermal_temp = None            # last SoC temp °C (or None when unreadable)
_thermal_status = "ok"          # "ok" | "warning" | "critical"
_thermal_over_since = None      # ts the temp first crossed the shutdown line


def _thermal_watchdog_check():
    """Throttled SoC-temp poll; safe-shutdown on sustained over-temp.

    Requires the temp to hold at/above _THERMAL_SHUTDOWN_C continuously for
    _THERMAL_SHUTDOWN_HOLD_S (~4 consecutive reads), so a single spike can't
    trip it. A missing reading fails open (never shuts down)."""
    global _thermal_last_check, _thermal_temp, _thermal_status, _thermal_over_since
    now = time.monotonic()
    if now - _thermal_last_check < _THERMAL_CHECK_INTERVAL_S:
        return
    _thermal_last_check = now
    temp = _read_cpu_temp()
    _thermal_temp = temp
    if temp is None:
        _thermal_status = "ok"
        _thermal_over_since = None
        return
    if temp >= _THERMAL_SHUTDOWN_C:
        _thermal_status = "critical"
        if _thermal_over_since is None:
            _thermal_over_since = now
        elif now - _thermal_over_since >= _THERMAL_SHUTDOWN_HOLD_S:
            safe_shutdown(f"high SoC temperature {temp:.0f}C")
    elif temp >= _THERMAL_WARN_C:
        _thermal_status = "warning"
        _thermal_over_since = None
    else:
        _thermal_status = "ok"
        _thermal_over_since = None


# --- Thermal load-shed governor (keeps sustained shooting in the low 60s) ---
# The 1.2 GHz cap bounds peak dissipation and the 82 C watchdog handles the
# pathological end, but nothing between them stops a long shooting session
# from settling in the 70s with the fan running flat out. This governor sheds
# per-frame work in two reversible steps so the SoC equilibrates inside the
# 60-65 C band instead: less heat generated beats more fan (battery budget).
# Everything it touches is preview-side cadence — capture quality, exposure
# state, and every mode's save path are untouched.
#
#   level 1 (>= 65 C sustained): preview readout + UI pacing 20 -> 15 fps,
#            MJPEG stream cap 15 -> 8 fps, histogram every 4th frame, focus
#            assist recomputes at most every 2nd frame.
#   level 2 (>= 70 C sustained): preview 15 -> 12 fps, focus assist every
#            3rd frame; everything else as level 1.
#
# Hysteresis brackets the requested band: step up at 65/70, step back down at
# 60/65, each edge debounced so a capture-burst spike or a breeze can't flap
# the rate. The dimmed-idle 10 fps state is always at/below these tiers, so
# the dim path keeps precedence everywhere the shed tiers are consulted.
_HEAT_SHED_L1_ENTER_C = 65.0
_HEAT_SHED_L1_EXIT_C = 60.0
_HEAT_SHED_L2_ENTER_C = 70.0
_HEAT_SHED_L2_EXIT_C = 65.0
_HEAT_SHED_ENTER_HOLD_S = 10.0   # sustained above the step-up line (2 polls)
_HEAT_SHED_EXIT_HOLD_S = 30.0    # sustained below the step-down line (6 polls)
_heat_shed_level = 0             # 0 = full rate, 1/2 = shed tiers
_heat_shed_hot_since = None
_heat_shed_cool_since = None


def _heat_shed_step(level, temp, now, hot_since, cool_since):
    """Pure hysteresis step: (new_level, hot_since, cool_since).

    Between the exit and enter lines the current level holds — that dead band
    IS the target range, so the system settles there rather than oscillating.
    An unreadable temp fails open to full rate (matches the watchdog)."""
    if temp is None:
        return 0, None, None
    enter_c = _HEAT_SHED_L1_ENTER_C if level == 0 else _HEAT_SHED_L2_ENTER_C
    exit_c = _HEAT_SHED_L2_EXIT_C if level == 2 else _HEAT_SHED_L1_EXIT_C
    if level < 2 and temp >= enter_c:
        if hot_since is None:
            return level, now, None
        if now - hot_since >= _HEAT_SHED_ENTER_HOLD_S:
            return level + 1, None, None
        return level, hot_since, None
    if level > 0 and temp <= exit_c:
        if cool_since is None:
            return level, None, now
        if now - cool_since >= _HEAT_SHED_EXIT_HOLD_S:
            return level - 1, None, None
        return level, None, cool_since
    return level, None, None


# MITIGATION (field): the load-shed tiers originally ALSO relaxed the sensor
# read-out floor (_PREVIEW_FRAME_DUR_SHED1/2_US via _preview_floor_us) and a
# level transition re-applied controls to the running pipeline. A field-
# reported failure — idle a few minutes, then the next capture freezes the
# app until the process dies — correlates with this governor's transitions
# (the only recent battery feature that acts after minutes of thermal drift
# with idle dim disabled). Until root-caused, the governor keeps every
# preview-SIDE shed (UI pacing, MJPEG stream cap, histogram cadence, focus/
# rangefinder overlay cadence — most of the battery win) but NEVER touches
# the sensor: _preview_floor_us ignores the shed tiers and a level change no
# longer re-applies controls. Flip to True to restore the readout shed once
# the stall is understood.
_HEAT_SHED_READOUT_ENABLED = False


def _thermal_shed_tick():
    """Advance the load-shed governor; called every main-loop iteration right
    after the watchdog (rides its _thermal_temp poll — no extra sensor reads).
    With _HEAT_SHED_READOUT_ENABLED the sensor readout floor is re-applied on
    a level change through the same guarded seam the idle dim uses; under the
    field mitigation (False) a transition only switches the preview-side
    cadences, which consult _heat_shed_level directly per frame — no pipeline
    controls are touched."""
    global _heat_shed_level, _heat_shed_hot_since, _heat_shed_cool_since
    prev = _heat_shed_level
    new_level, _heat_shed_hot_since, _heat_shed_cool_since = _heat_shed_step(
        prev, _thermal_temp, time.monotonic(),
        _heat_shed_hot_since, _heat_shed_cool_since)
    if new_level == prev:
        return
    _heat_shed_level = new_level
    try:
        print(f"[Thermal] load-shed level {prev} -> {new_level} "
              f"at {_thermal_temp:.0f}C")
    except Exception:
        pass
    if _HEAT_SHED_READOUT_ENABLED:
        _reapply_idle_preview_rate()


def _render_thermal_warning(canvas):
    """Composite a centered over-temp banner when the watchdog is alarmed. The
    20 s critical hold window guarantees it is on screen before any shutdown."""
    if _thermal_status == "ok" or _thermal_temp is None:
        return
    try:
        if _thermal_status == "critical":
            text = f"OVERHEAT  {_thermal_temp:.0f}°C  —  SHUTTING DOWN"
            color = _CHARGE_CRIT_COLOR
        else:
            text = f"HIGH TEMPERATURE  {_thermal_temp:.0f}°C"
            color = _CHARGE_WARN_COLOR
        block = make_rotated_text_block(
            [[{"text": text, "color": color}]],
            font_scale=1.0, thickness=2, rotate_180=True, max_h=80,
        )
        if block is None:
            return
        bx = max(0, (SCREEN_W - block.shape[1]) // 2)
        by = max(8, int(SCREEN_H * 0.08))
        blit_add_with_shadow(canvas, block, bx, by)
    except Exception:
        pass

# -------------------- UI helpers --------------------

_HIDDEN_CURSOR_PATHS = []
_XFIXES_DATA = None


def _restore_cursor():
    global _XFIXES_DATA
    if not _XFIXES_DATA:
        return
    libX11, libXfixes, display_ptr = _XFIXES_DATA
    try:
        libX11.XDefaultRootWindow.argtypes = [ctypes.c_void_p]
        libX11.XDefaultRootWindow.restype = ctypes.c_ulong
        root = libX11.XDefaultRootWindow(display_ptr)
        libXfixes.XFixesShowCursor.argtypes = [ctypes.c_void_p, ctypes.c_ulong]
        libXfixes.XFixesShowCursor.restype = None
        libXfixes.XFixesShowCursor(display_ptr, root)
        libX11.XFlush.argtypes = [ctypes.c_void_p]
        libX11.XFlush(display_ptr)
        libX11.XCloseDisplay.argtypes = [ctypes.c_void_p]
        libX11.XCloseDisplay.restype = ctypes.c_int
        libX11.XCloseDisplay(display_ptr)
    except Exception:
        pass
    finally:
        _XFIXES_DATA = None


def _cleanup_cursor_artifacts():
    while _HIDDEN_CURSOR_PATHS:
        path = _HIDDEN_CURSOR_PATHS.pop()
        try:
            os.remove(path)
        except FileNotFoundError:
            continue
        except Exception as exc:
            print("Cursor cleanup error:", exc)


def _ensure_cursor_hidden():
    display = os.environ.get("DISPLAY")
    if not display:
        # Nothing to do when we are not under X11; rely on the framebuffer stack.
        return

    global _XFIXES_DATA

    if _XFIXES_DATA:
        return

    try:
        libX11 = ctypes.CDLL("libX11.so.6")
        libXfixes = ctypes.CDLL("libXfixes.so.3")

        libX11.XOpenDisplay.argtypes = [ctypes.c_char_p]
        libX11.XOpenDisplay.restype = ctypes.c_void_p
        disp = libX11.XOpenDisplay(display.encode())
        if disp:
            libX11.XDefaultRootWindow.argtypes = [ctypes.c_void_p]
            libX11.XDefaultRootWindow.restype = ctypes.c_ulong
            root = libX11.XDefaultRootWindow(disp)
            libXfixes.XFixesHideCursor.argtypes = [ctypes.c_void_p, ctypes.c_ulong]
            libXfixes.XFixesHideCursor.restype = None
            libXfixes.XFixesHideCursor(disp, root)
            libX11.XFlush.argtypes = [ctypes.c_void_p]
            libX11.XFlush(disp)
            _XFIXES_DATA = (libX11, libXfixes, disp)
            atexit.register(_restore_cursor)
            return
    except OSError:
        pass
    except Exception as exc:
        print("Cursor XFixes hide error:", exc)

    try:
        fd, cursor_path = tempfile.mkstemp(prefix="cursor", suffix=".xbm")
        with os.fdopen(fd, "w") as cursor_file:
            cursor_file.write(
                "#define blank_width 1\n"
                "#define blank_height 1\n"
                "static unsigned char blank_bits[] = { 0x00 };\n"
            )

        mask_fd, mask_path = tempfile.mkstemp(prefix="cursor", suffix="mask.xbm")
        with os.fdopen(mask_fd, "w") as mask_file:
            mask_file.write(
                "#define blankm_width 1\n"
                "#define blankm_height 1\n"
                "static unsigned char blankm_bits[] = { 0x00 };\n"
            )

        _HIDDEN_CURSOR_PATHS.extend([cursor_path, mask_path])
        atexit.register(_cleanup_cursor_artifacts)

        subprocess.run(
            [
                "xsetroot",
                "-display",
                display,
                "-cursor",
                cursor_path,
                mask_path,
            ],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=False,
        )
    except FileNotFoundError:
        # xsetroot not installed; fall back to unclutter with aggressive settings.
        subprocess.Popen(
            [
                "unclutter",
                "-idle",
                "0.05",
                "-noevents",
                "-grab",
                "-display",
                display,
            ],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            start_new_session=True,
        )
    except Exception as exc:
        print("Cursor hide error:", exc)


# Run cursor hiding in background – the subprocess calls can take ~200ms
# and the cursor is not visible on the Pi touchscreen display anyway.
threading.Thread(target=_ensure_cursor_hidden, daemon=True).start()

LOCAL_PICTURES_DIR = "/home/pi/Pictures"
USB_MOUNT_POINT = "/home/pi/usb1"

# USB hotplug poll cadence (seconds).  Slower while idle/asleep to skip lsblk
# subprocess spawns, but the wait is chunked (see _USB_POLL_CHUNK_S) so a wake
# returns to the active cadence within one chunk rather than waiting out a long
# idle sleep — otherwise a drive swapped during sleep would route the next
# capture to a stale target.
_USB_POLL_S_ACTIVE = 15
_USB_POLL_S_DIMMED = 60
_USB_POLL_S_SLEEP = 120
_USB_POLL_CHUNK_S = 15

def _ensure_dir(path):
    try:
        os.makedirs(path, exist_ok=True)
    except Exception as exc:
        print(f"Directory create error for {path}: {exc}")

_ensure_dir(LOCAL_PICTURES_DIR)

_capture_dir_lock = threading.Lock()
_capture_dir = LOCAL_PICTURES_DIR
_usb_device = None
_usb_mounted_by_us = False
_is_usb_target = False
# The mountpoint the USB thread is actually using. Usually USB_MOUNT_POINT,
# but _usb_mount_thread ADOPTS an already-mounted partition's own mountpoint
# (e.g. an automounted /media/pi/DRIVE) — _is_usb_target must recognise that
# path too or fsync + SD-backup protection silently turns off. None when no
# drive is present.
_usb_active_mount = None

# USB file sync queue for committing files to USB drive
_usb_sync_queue = queue.Queue()

def _invalidate_icon_caches():
    """Drop cached icon PNGs so the next render re-resolves them.

    Called when the USB mount state changes so that icons supplied on a
    newly-plugged drive take effect, and icons loaded from a now-absent
    drive fall back to the SD set. The _ICON_BTN_CACHE (button ring
    backgrounds) is intentionally left alone — it does not contain any
    PNG icon data.
    """
    try:
        _icon_png_cache.clear()
    except Exception:
        pass
    try:
        _tinted_icon_cache.clear()
    except Exception:
        pass


def _set_capture_dir(path):
    global _capture_dir, _is_usb_target
    _ensure_dir(path)
    with _capture_dir_lock:
        prev_usb = _is_usb_target
        _capture_dir = path
        active_mount = _usb_active_mount
        _is_usb_target = path.startswith(USB_MOUNT_POINT) or (
            bool(active_mount) and path.startswith(active_mount)
        )
        usb_state_changed = prev_usb != _is_usb_target
    if usb_state_changed:
        _invalidate_icon_caches()
        # Rescan the USB `lut/` folder when the drive is inserted/removed.
        # globals().get-guarded because this also runs at module import, before
        # the LUT helpers below are defined.
        _lut_hook = globals().get("_lut_on_usb_change")
        if _lut_hook is not None:
            _lut_hook()

def _queue_usb_sync(file_path):
    """Queue a file for syncing to USB if capturing to USB drive."""
    if _is_usb_target and file_path and os.path.isfile(file_path):
        _usb_sync_queue.put(file_path)

def _usb_sync_worker():
    """Background thread that commits captured files to USB storage and
    copies them to the local Pictures directory as a backup.

    This ensures DNG and JPG files are properly flushed to the USB drive
    by calling fsync on each file after it's written. Without this,
    files may remain in the kernel buffer cache and be lost if the
    USB drive is removed before the OS flushes the data.

    After syncing to USB, each file is also copied to LOCAL_PICTURES_DIR
    so that a local backup exists on the Pi's SD card.
    """
    while True:
        file_path = _usb_sync_queue.get()
        if file_path is None:
            _usb_sync_queue.task_done()
            break
        try:
            # Open file and fsync to ensure data is committed to USB
            fd = os.open(file_path, os.O_RDONLY)
            try:
                os.fsync(fd)
            finally:
                os.close(fd)
            # Also sync the parent directory to ensure directory entry is committed
            parent_dir = os.path.dirname(file_path)
            if parent_dir:
                dir_fd = os.open(parent_dir, os.O_RDONLY | os.O_DIRECTORY)
                try:
                    os.fsync(dir_fd)
                finally:
                    os.close(dir_fd)
            # Copy to local Pictures directory as backup
            try:
                _ensure_dir(LOCAL_PICTURES_DIR)
                local_copy = os.path.join(
                    LOCAL_PICTURES_DIR, os.path.basename(file_path)
                )
                shutil.copy2(file_path, local_copy)
            except Exception as e:
                print(f"Local backup error for {file_path}: {e}")
        except Exception as e:
            print(f"USB sync error for {file_path}: {e}")
        finally:
            _usb_sync_queue.task_done()

_set_capture_dir(LOCAL_PICTURES_DIR)

def _detect_usb_partition():
    try:
        output = subprocess.check_output(
            ["lsblk", "-J", "-o", "NAME,MOUNTPOINT,TRAN,TYPE"],
            text=True,
        )
        info = json.loads(output)
    except Exception:
        return None, None

    def _iter_nodes(node):
        yield node
        for child in node.get("children", []) or []:
            yield from _iter_nodes(child)

    for dev in info.get("blockdevices", []) or []:
        if dev.get("tran") != "usb":
            continue
        for node in _iter_nodes(dev):
            if node.get("type") == "part":
                name = node.get("name")
                if name:
                    return f"/dev/{name}", node.get("mountpoint")
    return None, None

def _usb_mount_thread():
    global _usb_device, _usb_mounted_by_us, _usb_active_mount
    _ensure_dir(USB_MOUNT_POINT)
    while True:
        device, mountpoint = _detect_usb_partition()
        if device:
            target_mount = mountpoint or USB_MOUNT_POINT
            mounted_here = (
                _usb_mounted_by_us
                if mountpoint and target_mount == USB_MOUNT_POINT
                else False
            )
            if not mountpoint:
                if not os.path.ismount(target_mount):
                    result = subprocess.call(
                        ["mount", device, target_mount],
                        stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                    )
                    if result != 0:
                        time.sleep(15)
                        continue
                mounted_here = True
                mountpoint = target_mount
            if os.path.isdir(target_mount):
                # Publish the adopted mountpoint BEFORE _set_capture_dir so
                # _is_usb_target sees it (an automounted /media/... path does
                # not start with USB_MOUNT_POINT).
                _usb_active_mount = target_mount
                _set_capture_dir(target_mount)
                _usb_device = device
                _usb_mounted_by_us = mounted_here
        else:
            if _usb_device and _usb_mounted_by_us and os.path.ismount(USB_MOUNT_POINT):
                subprocess.call(
                    ["umount", USB_MOUNT_POINT],
                    stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                )
            _usb_active_mount = None
            _set_capture_dir(LOCAL_PICTURES_DIR)
            _usb_device = None
            _usb_mounted_by_us = False
        # Relax the poll cadence when the user isn't actively shooting: in the
        # dimmed-idle and (especially) deep-sleep states nothing is being
        # plugged/unplugged, so a slower scan skips an lsblk subprocess spawn
        # every cycle.  The wait is chunked and re-checks state each chunk, so
        # waking to shoot restores the active cadence within one chunk — a drive
        # swapped during sleep is picked up promptly instead of after the full
        # idle interval.  globals().get guards the boot window before the flags
        # exist.
        if globals().get("sleep_mode_active", False):
            target = _USB_POLL_S_SLEEP
        elif globals().get("_backlight_dimmed", False):
            target = _USB_POLL_S_DIMMED
        else:
            target = _USB_POLL_S_ACTIVE
        slept = 0.0
        while slept < target:
            time.sleep(min(_USB_POLL_CHUNK_S, target - slept))
            slept += _USB_POLL_CHUNK_S
            # Active again? Re-scan now rather than finishing a long idle wait.
            if (not globals().get("sleep_mode_active", False)
                    and not globals().get("_backlight_dimmed", False)):
                break

threading.Thread(target=_usb_mount_thread, daemon=True).start()

image_count = 0
# Guards the image_count increment — bumped from both the save worker and the
# long-exposure save thread, so a plain += can lose counts (HUD undercount).
_image_count_lock = threading.Lock()

# Film-advance metaphor: the HUD's "IC:" count should advance the instant the
# shutter fires, not ~1s later when the async JPG write completes. Every job
# handed to `_capture_save_queue` bumps this on the producer side (main loop
# or the hi-res worker thread); `_capture_save_worker` decrements it once the
# job is fully resolved (success OR failure — a failed save must never leak
# the count). The HUD adds this to `image_count` for display.
_captures_in_flight = 0
# Actual bytes the queued/processing save jobs pin in RAM (frame + raw
# payload), maintained alongside the count: incremented with each job's real
# size at queue time, decremented with the same size on resolve. Jobs of
# different sensor modes can coexist in the queue (the charge-mode dropdown
# can switch modes without draining pending saves), so the admission gate
# must sum real per-job sizes — estimating every queued job at the CURRENT
# mode's size undercounts leftover 47 MP jobs after a switch to a small mode.
_capture_bytes_in_flight = 0
_captures_in_flight_lock = threading.Lock()
# Brief post-capture emphasis window for the HUD count (accent color) so the
# advance is noticeable without showing any image — armed by
# _mark_capture_queued() each time a capture is queued for save.
_frame_advance_flash_until = 0.0
_FRAME_ADVANCE_FLASH_S = 0.4
# Rejection counterpart: a shutter press that could NOT capture (disk space
# critical) flashes the same HUD count in the danger accent instead — a
# per-press "no advance" cue on top of the standing NO SPACE banner, so
# mashing the shutter with a full disk never reads as captures succeeding.
_capture_blocked_flash_until = 0.0
_CAPTURE_BLOCKED_FLASH_S = 0.6


def _capture_job_bytes(full_frame, dng_raw, overlay_frame=None):
    """Actual bytes a save job pins in RAM until the worker resolves it: the
    full-res frame, (instant path) the raw DNG payload, and (double
    exposure) the first shot held as the overlay frame — at 47 MP the
    overlay alone is another ~143 MB, so leaving it untracked would let
    the admission gate re-admit past the budget. Defensive so the
    accounting can never throw on an odd job shape."""
    try:
        total = int(getattr(full_frame, "nbytes", 0) or 0)
        if dng_raw is not None:
            total += int(getattr(dng_raw[0], "nbytes", 0) or 0)
        if overlay_frame is not None:
            total += int(getattr(overlay_frame, "nbytes", 0) or 0)
        return total
    except Exception:
        return 0


def _mark_capture_queued(job_bytes=0):
    """Bump the optimistic in-flight counter/byte total and arm the brief HUD
    emphasis. Call exactly once per job handed to `_capture_save_queue`, with
    that job's `_capture_job_bytes` so the memory gate tracks real sizes."""
    global _captures_in_flight, _capture_bytes_in_flight
    global _frame_advance_flash_until
    with _captures_in_flight_lock:
        _captures_in_flight += 1
        _capture_bytes_in_flight += max(0, int(job_bytes))
    _frame_advance_flash_until = time.monotonic() + _FRAME_ADVANCE_FLASH_S


def _mark_capture_resolved(job_bytes=0):
    """Release one in-flight slot (and its bytes) once `_capture_save_worker`
    has fully resolved a job (saved or lost) — never leaves the optimistic
    count or byte total stuck above the real one."""
    global _captures_in_flight, _capture_bytes_in_flight
    with _captures_in_flight_lock:
        if _captures_in_flight > 0:
            _captures_in_flight -= 1
        _capture_bytes_in_flight = max(
            0, _capture_bytes_in_flight - max(0, int(job_bytes)))
        if _captures_in_flight == 0:
            # Self-correcting: with nothing in flight the byte total is zero
            # by definition, so an estimate mismatch can never accumulate.
            _capture_bytes_in_flight = 0


# Bounded so a capture burst can't accumulate full-resolution frames without
# limit and drive the Pi into swap/GC thrash when the JPEG encode + USB fsync
# falls behind. A full queue makes the producer (main loop) block on put() —
# backpressure that paces the shutter to save throughput WITHOUT ever dropping
# a capture. The count bound alone is NOT enough at big sensor modes: a job
# pins its full-res frame plus (instant path) the raw DNG payload until the
# save worker resolves it — ~53 MB at 11 MP but ~240 MB at unbinned 47 MP,
# where 8 queued jobs is ~1.9 GB and the kernel OOM-killer SIGKILLs the whole
# firmware (bypassing every per-frame exception guard: the app just exits).
# The shutter-press admission gate below (_capture_mem_budget_ok) therefore
# also caps the estimated queued BYTES; the count bound stays as the 11 MP-
# scale backstop.
_CAPTURE_SAVE_QUEUE_MAX = 8
# Byte budget for capture payloads pinned in the save pipeline. 600 MB admits
# 11+ jobs at 11 MP (the count bound engages first — behaviour unchanged) but
# only 2 at 47 MP, pacing a big-mode burst with the same blocked-shutter cue
# as a full disk instead of letting it OOM the process. A single capture is
# always admitted regardless of size, so no mode can ever be locked out.
# Low-RAM boards override this down to one 47 MP-class job — see the
# _LOW_MEM_BOARD block by the sensor-mode constants.
_CAPTURE_SAVE_MEM_BUDGET_BYTES = 600 * 1024 * 1024


def _capture_mem_budget_ok(job_bytes):
    """True when queueing another `job_bytes` capture keeps the save
    pipeline's pinned payload inside _CAPTURE_SAVE_MEM_BUDGET_BYTES.
    Compares against the ACTUAL queued byte total (jobs of different sensor
    modes can coexist after a mode switch, so per-job sizes are summed, not
    estimated from the current mode). Always True when nothing is in
    flight — the first shot must never be blocked, whatever the sensor
    mode's size."""
    with _captures_in_flight_lock:
        inflight = _captures_in_flight
        bytes_now = _capture_bytes_in_flight
    if inflight <= 0:
        return True
    return bytes_now + job_bytes <= _CAPTURE_SAVE_MEM_BUDGET_BYTES


