_DEFERRED_IMAGES_SOURCE = '"""Durable raw spool. No camera imports and no executable serialized objects."""\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport re\nimport shutil\nimport threading\nimport time\nimport uuid\nfrom functools import wraps\nfrom concurrent.futures import ThreadPoolExecutor\n\n\nclass ConversionPerformance:\n    """Borrow normal CPU throughput for a batch, then restore Charge policy.\n\n    Never change the minimum frequency, voltage, overclock configuration or\n    kernel thermal controls. Missing sysfs/OpenCV controls are non-fatal.\n    """\n    def __init__(self, policies, cv2):\n        self.policies = list(policies)\n        self.cv2 = cv2\n        self.saved = []\n        self.previous_threads = None\n        try:\n            available = len(os.sched_getaffinity(0))\n        except (AttributeError, OSError):\n            available = os.cpu_count() or 1\n        self.workers = min(4, max(1, available))\n\n    def __enter__(self):\n        for policy in self.policies:\n            policy = Path(policy)\n            governor, maximum = policy/\'scaling_governor\', policy/\'scaling_max_freq\'\n            try:\n                old_governor, old_maximum = governor.read_text().strip(), maximum.read_text().strip()\n                hardware_maximum = int((policy/\'cpuinfo_max_freq\').read_text().strip())\n                available = (policy/\'scaling_available_governors\').read_text().split()\n                target_governor = next((g for g in (\'performance\',\'schedutil\',\'ondemand\') if g in available), None)\n                if not target_governor or hardware_maximum <= 0:\n                    continue\n                self.saved.append((governor, maximum, old_governor, old_maximum))\n                maximum.write_text(str(min(hardware_maximum, 2400000)))\n                governor.write_text(target_governor)\n                print(\'[Deferred CPU] {}: governor={}, max={} kHz\'.format(\n                    policy.name, governor.read_text().strip(), maximum.read_text().strip()))\n            except Exception as exc:\n                print(\'[Deferred CPU] policy boost unavailable:\', exc)\n        if self.cv2 is None:\n            return self\n        try:\n            self.previous_threads = self.cv2.getNumThreads()\n            self.cv2.setNumThreads(self.workers)\n        except Exception as exc:\n            print(\'[Deferred CPU] OpenCV thread control unavailable:\', exc)\n        return self\n\n    def __exit__(self, *_error):\n        # Restore even after an exception or Stop after current image.\n        if self.previous_threads is not None:\n            try:\n                self.cv2.setNumThreads(self.previous_threads)\n            except Exception as exc:\n                print(\'[Deferred CPU] OpenCV restore failed:\', exc)\n        for governor, maximum, old_governor, old_maximum in reversed(self.saved):\n            for path, value in ((governor,old_governor),(maximum,old_maximum)):\n                try:\n                    path.write_text(value)\n                except Exception as exc:\n                    print(\'[Deferred CPU] policy restore failed:\', path, exc)\n\n\nclass CapturePerformance:\n    """Share a CPU-only boost across overlapping capture and save workers."""\n    def __init__(self, policies):\n        self.policies = policies\n        self.lock = threading.RLock()\n        self.users = 0\n        self.policy = None\n\n    @property\n    def active(self):\n        with self.lock:\n            return self.users > 0\n\n    def acquire(self):\n        with self.lock:\n            if self.users == 0:\n                self.policy = ConversionPerformance(self.policies(), None)\n                self.policy.__enter__()\n            self.users += 1\n\n    def release(self):\n        with self.lock:\n            if self.users == 0:\n                return\n            self.users -= 1\n            if self.users == 0:\n                self.policy.__exit__(None, None, None)\n                self.policy = None\n\n    def wrap(self, function):\n        @wraps(function)\n        def boosted(*args, **kwargs):\n            self.acquire()\n            try:\n                return function(*args, **kwargs)\n            finally:\n                self.release()\n        return boosted\n\n\ndef run_strips(function, height, rows, workers):\n    """Disjoint output strips; at most four strip temporaries live at once."""\n    workers = min(4,max(1,int(workers)))\n    starts = range(0,height,rows)\n    if workers == 1:\n        for row in starts:\n            function(row)\n    else:\n        with ThreadPoolExecutor(max_workers=workers,thread_name_prefix=\'raw-strip\') as pool:\n            for _ in pool.map(function,starts):\n                pass\n\n\ndef sync_directory(path):\n    if hasattr(os, \'O_DIRECTORY\'):\n        fd = os.open(path, os.O_RDONLY | os.O_DIRECTORY)\n        try:\n            os.fsync(fd)\n        finally:\n            os.close(fd)\n\n\ndef write_json(path, value):\n    path = Path(path)\n    temporary = path.with_suffix(\'.tmp\')\n    with temporary.open(\'w\', encoding=\'utf-8\') as stream:\n        json.dump(value, stream, allow_nan=False)\n        stream.flush()\n        os.fsync(stream.fileno())\n    os.replace(temporary, path)\n    sync_directory(path.parent)\n\n\nclass Spool:\n    def __init__(self, root):\n        self.root = Path(root)\n        self.lock = threading.RLock()\n\n    def path(self, identifier):\n        if not isinstance(identifier, str) or not re.fullmatch(\'[0-9a-f]{32}\', identifier):\n            raise ValueError(\'Invalid image identifier.\')\n        path = self.root / identifier\n        if path.is_symlink():\n            raise ValueError(\'Invalid image folder.\')\n        return path\n\n    def stage(self, buffer, metadata, thumbnail):\n        """Commit manifest last; incomplete saves never appear as good photos."""\n        self.root.mkdir(parents=True, exist_ok=True)\n        data = memoryview(buffer).cast(\'B\')\n        if shutil.disk_usage(self.root).free < len(data) + 256 * 1024 * 1024:\n            raise OSError(\'Not enough card space to save this raw frame.\')\n        identifier = uuid.uuid4().hex\n        directory = self.root / (\'.pending-\' + identifier)\n        directory.mkdir()\n        try:\n            digest = hashlib.sha256()\n            with (directory / \'frame.raw\').open(\'wb\') as stream:\n                for offset in range(0, len(data), 4 * 1024 * 1024):\n                    part = data[offset:offset + 4 * 1024 * 1024]\n                    stream.write(part)\n                    digest.update(part)\n                stream.flush()\n                os.fsync(stream.fileno())\n            with (directory / \'thumb.jpg\').open(\'wb\') as stream:\n                stream.write(thumbnail)\n                stream.flush()\n                os.fsync(stream.fileno())\n            value = dict(metadata, version=1, id=identifier, bytes=len(data),\n                         sha256=digest.hexdigest(), saved=time.time(), outputs={})\n            write_json(directory / \'image.json\', value)\n            write_json(directory / \'summary.json\', self.summary(value))\n            os.replace(directory, self.path(identifier))\n            sync_directory(self.root)\n            return identifier\n        except Exception:\n            # Keep incomplete data for diagnostics; never remove a committed shot.\n            raise\n\n    def read(self, identifier):\n        directory = self.path(identifier)\n        manifest = directory / \'image.json\'\n        if manifest.stat().st_size > 4 * 1024 * 1024:\n            raise ValueError(\'Image metadata is too large.\')\n        value = json.loads(manifest.read_text(encoding=\'utf-8\'))\n        if value.get(\'version\') != 1 or value.get(\'id\') != identifier:\n            raise ValueError(\'Unsupported image metadata.\')\n        return value\n\n    def verify(self, identifier):\n        value = self.read(identifier)\n        raw = self.path(identifier) / \'frame.raw\'\n        if raw.is_symlink() or raw.stat().st_size != value[\'bytes\']:\n            raise ValueError(\'The saved raw frame is incomplete.\')\n        digest = hashlib.sha256()\n        with raw.open(\'rb\') as stream:\n            for part in iter(lambda: stream.read(4 * 1024 * 1024), b\'\'):\n                digest.update(part)\n        if digest.hexdigest() != value[\'sha256\']:\n            raise ValueError(\'The saved raw frame failed its integrity check.\')\n        return value\n\n    def listing(self):\n        images = []\n        if self.root.exists():\n            for directory in self.root.iterdir():\n                if not re.fullmatch(\'[0-9a-f]{32}\', directory.name):\n                    continue\n                try:\n                    summary = directory / \'summary.json\'\n                    if directory.is_symlink() or summary.stat().st_size > 16384:\n                        continue\n                    value = json.loads(summary.read_text(encoding=\'utf-8\'))\n                    images.append(value)\n                except (OSError, ValueError):\n                    continue\n        return sorted(images, key=lambda value: value[\'saved\'], reverse=True)\n\n    @staticmethod\n    def summary(value):\n        return {key:value.get(key) for key in\n                (\'id\',\'label\',\'saved\',\'bytes\',\'mono\',\'model\',\'outputs\')}\n\n    def converted(self, identifier, outputs):\n        with self.lock:\n            value = self.read(identifier)\n            value[\'outputs\'].update(outputs)\n            write_json(self.path(identifier) / \'image.json\', value)\n            write_json(self.path(identifier) / \'summary.json\', self.summary(value))\n\n    def delete(self, identifier):\n        with self.lock:\n            self.read(identifier)\n            # Rename first so a power cut cannot leave a half-deleted visible job.\n            path = self.path(identifier)\n            trash = self.root / (\'.deleted-\' + identifier)\n            os.replace(path, trash)\n            sync_directory(self.root)\n            shutil.rmtree(trash)\n\n\ndef develop(plane, bits, blacks, cfa, metadata, cv2, np, workers=1):\n    """Develop in strips after demosaic; never allocate a full RGB float frame."""\n    white = float((1 << bits) - 1)\n    mono = cfa is None\n    if mono:\n        image = plane\n    else:\n        patterns = {(0,1,1,2): \'RGGB\', (2,1,1,0): \'BGGR\',\n                    (1,0,2,1): \'GRBG\', (1,2,0,1): \'GBRG\'}\n        pattern = patterns.get(tuple(cfa))\n        if pattern is None:\n            raise ValueError(\'Unsupported colour filter pattern.\')\n        balanced = np.empty_like(plane)\n        for y in range(2):\n            for x in range(2):\n                black = float(blacks[min(y*2+x, len(blacks)-1)])\n                # Work row strips below to bound the subtraction temporary.\n                for row in range(y, plane.shape[0], 128):\n                    part = plane[row:row+128:2,x::2].astype(np.float32)\n                    part = np.clip((part-black) * (65535.0/max(1,white-black)),0,65535)\n                    balanced[row:row+128:2,x::2] = part.astype(np.uint16)\n        image = cv2.cvtColor(balanced, getattr(cv2, \'COLOR_Bayer\'+pattern+\'2BGR_EA\'))\n        del balanced\n    result = np.empty((plane.shape[0], plane.shape[1], 3), dtype=np.uint8)\n    gains = metadata.get(\'ColourGains\', [1,1])\n    ccm = np.asarray(metadata.get(\'ColourCorrectionMatrix\', np.eye(3)),dtype=np.float32).reshape(3,3)\n    digital = max(0.01, min(64.0, float(metadata.get(\'DigitalGain\',1))))\n    def render_strip(row):\n        if mono:\n            black = float(blacks[0])\n            part = np.maximum(image[row:row+64].astype(np.float32)-black,0)/max(1,white-black)\n            part = np.repeat(part[:,:,None],3,axis=2)\n        else:\n            part = image[row:row+64].astype(np.float32)/65535.0\n            part *= np.asarray([gains[1],1,gains[0]],dtype=np.float32)\n            part = cv2.transform(part, ccm[::-1,::-1].copy())\n        part = np.clip(part*digital,0,1)\n        part = np.where(part<=0.0031308,12.92*part,1.055*np.power(part,1/2.4)-0.055)\n        result[row:row+64] = np.clip(part*255+0.5,0,255).astype(np.uint8)\n    run_strips(render_strip,plane.shape[0],64,workers)\n    return result\n'
