_DEFERRED_UI_SOURCE = '"""Embedded camera integration for durable 47 MP raw captures."""\n_deferred_enabled = bool(_PERSISTED_SETTINGS.get(\'defer_47mp_processing\', False))\n_deferred_spool = _deferred_backend[\'Spool\'](Path(LOCAL_PICTURES_DIR) / \'Unprocessed\')\n_deferred_processing_busy = False\n_deferred_render_workers = 1\n# Kept for the deferred batch conversion only. The 47 MP CAPTURE and SAVE\n# paths deliberately do NOT acquire it any more. It raised every policy to\n# 2.4 GHz on the performance governor, defeating the 1.2 GHz thermal cap\n# outright, and because it is refcounted across the capture worker AND the\n# multi-second LJ92 save, back-to-back shots never let the count reach zero\n# - the camera ran boosted continuously. Field case: the unit powered off\n# after a few 47 MP frames on battery, which it never did before the boost\n# landed. Measurement says the blackout is platform-bound anyway (sensor\n# stream-on plus the forks software quad-Bayer pass), so the boost bought\n# almost nothing on the capture side. Do not re-add it here.\n_capture_cpu_performance = _deferred_backend[\'CapturePerformance\'](_get_cpu_policy_paths)\n_deferred_stop = threading.Event()\n_deferred_status = {\'message\': \'Choose saved frames to convert.\', \'busy\': False, \'current\': None}\n\n\ndef _deferred_json(value):\n    if value is None or isinstance(value, (str, bool, int, float)):\n        return value\n    if isinstance(value, dict):\n        return {str(k): _deferred_json(v) for k,v in value.items()}\n    if isinstance(value, (tuple, list)):\n        return [_deferred_json(v) for v in value]\n    if hasattr(value, \'tolist\'):\n        return _deferred_json(value.tolist())\n    raise ValueError(\'Unsupported capture metadata: \' + type(value).__name__)\n\n\ndef _deferred_wanted():\n    return (_deferred_enabled and not globals().get(\'_bren_capturing\', False)\n            and not globals().get(\'double_exposure_enabled\', False)\n            and not globals().get(\'_flash_mode_active\', False)\n            and not globals().get(\'_le_active\', False))\n\n\ndef _deferred_snapshot(job):\n    raw, meta, cfg = job[7]\n    w,h = cfg[\'size\']\n    if not (40_000_000 <= w*h <= 55_000_000) or job[5] is not None:\n        return None\n    model = _dng_camera_model()\n    fixed = _dng_fixed_geometry(cfg)\n    key = \'{}:{}x{}\'.format(model,w,h)\n    fields = (\'SensorBlackLevels\',\'ExposureTime\',\'AnalogueGain\',\'DigitalGain\',\n              \'ColourGains\',\'ColourCorrectionMatrix\',\'SensorTimestamp\',\'QbcRaw\')\n    mono = bool(job[10]) if len(job)>10 else bool(_mono_raw_active())\n    value = dict(label=Path(job[4] or job[6]).name, model=model, mono=mono,\n                 metadata={k:meta[k] for k in fields if k in meta},\n                 config=dict(size=list(cfg[\'size\']), format=str(cfg[\'format\']), stride=int(cfg[\'stride\'])),\n                 ratio=float(job[2]), description=job[8], rotate=not _HQ_SENSOR_ACTIVE,\n                 film=job[3], writer=dict(force_mono=bool(_mono_sensor_active), camera_model=model,\n                    noise_table=_dng_noise_table_calib, geometry=fixed or _dng_geometry_persist.get(key),\n                    geometry_fixed=fixed is not None, baseline_exposure_ev=_dng_baseline_ev_calib,\n                    qbc=_dng_qbc_persist.get(key), qbc_eligible=_dng_qbc_eligible(cfg),\n                    imx294=_qbc_sensor_status() is True, pan_mono=mono))\n    # Freeze the selected film\'s colour transform, including customer LUTs.\n    # Rendering later never consults a newly selected/deleted LUT.\n    if job[3] and job[3] != \'none\':\n        try:\n            ramp = np.linspace(0,255,33).round().astype(np.uint8)\n            cube = np.stack(np.meshgrid(ramp,ramp,ramp,indexing=\'ij\'),axis=-1)\n            value[\'look\'] = apply_film_simulation_rgb(cube.reshape(33,1089,3),job[3]).reshape(33,33,33,3).tolist()\n        except Exception as exc:\n            value[\'look_error\'] = str(exc)\n    return _deferred_json(value)\n\n\nclass _DeferredSaveQueue(queue.Queue):\n    def put(self, item, block=True, timeout=None):\n        if item is not None:\n            snapshot = None\n            wanted = item[12] if len(item)>12 and isinstance(item[12],bool) else _deferred_wanted()\n            item = item[:12]\n            if wanted and item[7] is not None:\n                snapshot = _deferred_snapshot(item)\n            item = tuple(item) + (None,) * max(0,12-len(item)) + (snapshot,)\n        return super().put(item,block,timeout)\n\n\ndef _deferred_stage(raw, frame, snapshot):\n    if frame is None:\n        thumb = np.zeros((180,320,3),dtype=np.uint8)\n    else:\n        h,w = frame.shape[:2]\n        thumb = cv2.resize(frame,(max(1,int(w*min(1,320/w))),max(1,int(h*min(1,320/w)))))\n        if snapshot[\'mono\'] or snapshot[\'writer\'][\'force_mono\']:\n            thumb = cv2.cvtColor(cv2.cvtColor(thumb,cv2.COLOR_BGR2GRAY),cv2.COLOR_GRAY2BGR)\n        if snapshot[\'rotate\']:\n            thumb = cv2.flip(thumb,-1)\n    ok, encoded = cv2.imencode(\'.jpg\',thumb,[cv2.IMWRITE_JPEG_QUALITY,75])\n    if not ok:\n        raise RuntimeError(\'Could not create the capture thumbnail.\')\n    started = time.monotonic()\n    identifier = _deferred_spool.stage(raw[0],snapshot,encoded.tobytes())\n    print(\'[Deferred] raw frame durable in {:.3f}s: {}\'.format(time.monotonic()-started,identifier))\n    return identifier\n\n\ndef _deferred_apply_look(frame, cube, workers=1):\n    cube = np.asarray(cube,dtype=np.float32)\n    if cube.shape != (33,33,33,3):\n        raise ValueError(\'Invalid saved film transform.\')\n    def render_strip(row):\n        part = frame[row:row+32].astype(np.float32)*(32/255)\n        base = np.minimum(part.astype(np.int32),31)\n        frac = part-base\n        output = np.zeros_like(part)\n        for a in (0,1):\n            for b in (0,1):\n                for c in (0,1):\n                    weight = ((frac[:,:,0] if a else 1-frac[:,:,0]) *\n                              (frac[:,:,1] if b else 1-frac[:,:,1]) *\n                              (frac[:,:,2] if c else 1-frac[:,:,2]))\n                    output += cube[base[:,:,0]+a,base[:,:,1]+b,base[:,:,2]+c]*weight[:,:,None]\n        frame[row:row+32] = np.clip(output+0.5,0,255).astype(np.uint8)\n    _deferred_backend[\'run_strips\'](render_strip,frame.shape[0],32,workers)\n    return frame\n\n\ndef _deferred_convert(identifier, kind):\n    value = _deferred_spool.verify(identifier)\n    directory = _deferred_spool.path(identifier)\n    # Raw bytes stay mapped from disk. No duplicate full-size input buffer.\n    raw = np.memmap(directory/\'frame.raw\',dtype=np.uint8,mode=\'r\')\n    handoff = {}\n    scratch = directory/\'working.dng\'\n    outputs = {}\n    try:\n        if shutil.disk_usage(directory).free < 384*1024*1024:\n            raise OSError(\'At least 384 MB free card space is needed to convert an image.\')\n        _deferred_status[\'message\'] = \'Creating DNG: \'+value[\'label\']\n        _dng_write(raw,value[\'metadata\'],value[\'config\'],str(scratch),\n                   description=value.get(\'description\'), develop_result=handoff,\n                   **value[\'writer\'])\n        if kind in (\'jpg\',\'both\'):\n            if value.get(\'look_error\'):\n                raise ValueError(\'The capture film transform could not be saved. Convert DNG to retain the original image.\')\n            _deferred_status[\'message\'] = \'Developing JPG: \'+value[\'label\']\n            frame = _deferred_backend[\'develop\'](handoff[\'plane\'],handoff[\'bits\'],handoff[\'black\'],\n                            handoff[\'cfa\'],value[\'metadata\'],cv2,np,\n                            workers=globals().get(\'_deferred_render_workers\',1))\n            ob,tail = handoff[\'ob\'],handoff[\'trailing\']\n            frame = frame[:frame.shape[0]-tail if tail else None,ob:]\n            ratio = value.get(\'ratio\',0)\n            h,w = frame.shape[:2]\n            if ratio > 0:\n                if w/h > ratio:\n                    crop = max(1,round(h*ratio)); start=(w-crop)//2; frame=frame[:,start:start+crop]\n                else:\n                    crop = max(1,round(w/ratio)); start=(h-crop)//2; frame=frame[start:start+crop]\n            if value.get(\'look\'):\n                frame = _deferred_apply_look(frame,value[\'look\'],\n                                            workers=globals().get(\'_deferred_render_workers\',1))\n            if value[\'rotate\']:\n                frame = cv2.flip(frame,-1)\n            if not _save_jpg_with_exif(str(directory/\'working.jpg\'),frame,\n                    str(value.get(\'description\') or \'\')+\' | Captured: \'+value[\'label\']):\n                raise OSError(\'JPG encoding failed.\')\n            del frame\n        if value[\'rotate\']:\n            _rotate_dng_180(str(scratch))\n        for extension in ((\'jpg\',\'dng\') if kind==\'both\' else (kind,)):\n            working = directory/(\'working.\'+extension)\n            with working.open(\'rb\') as stream:\n                os.fsync(stream.fileno())\n            # Stable identifier prevents overwriting any original camera photo.\n            name = \'developed_\'+identifier+\'.\'+extension\n            os.replace(working,Path(LOCAL_PICTURES_DIR)/name)\n            _deferred_backend[\'sync_directory\'](LOCAL_PICTURES_DIR)\n            outputs[extension] = name\n        _deferred_spool.converted(identifier,outputs)\n    finally:\n        handoff.clear()\n        raw._mmap.close()\n        for extension in (\'jpg\',\'dng\'):\n            (directory/(\'working.\'+extension)).unlink(missing_ok=True)\n\n\ndef _deferred_start(ids,kind):\n    global _deferred_processing_busy, _web_update_preparing\n    if kind not in (\'jpg\',\'dng\',\'both\') or not isinstance(ids,list) or not 0<len(ids)<=1000:\n        raise ValueError(\'Select images and an output format.\')\n    ids = list(dict.fromkeys(ids))\n    for identifier in ids:\n        _deferred_spool.read(identifier)\n    with _web_update_gate:\n        if _deferred_processing_busy or _web_update_preparing:\n            raise ValueError(\'Wait for the current operation to finish.\')\n        ok,reason = _web_update_prepare()\n        if not ok:\n            raise ValueError(reason)\n        if getattr(globals().get(\'picam2\'), \'started\', False):\n            _web_update_cancel_prepare()\n            raise ValueError(\'Wait for the preview to stop in Charge mode.\')\n        _deferred_processing_busy = True\n        _deferred_status.update(busy=True,message=\'Starting conversion…\',current=None)\n        _deferred_stop.clear()\n    def worker():\n        global _deferred_processing_busy, _deferred_render_workers\n        errors=[]\n        try:\n            with _deferred_backend[\'ConversionPerformance\'](_get_cpu_policy_paths(),cv2) as performance:\n                _deferred_render_workers = performance.workers\n                for index,identifier in enumerate(ids):\n                    if _deferred_stop.is_set():\n                        break\n                    _deferred_status.update(current=identifier,completed=index,total=len(ids))\n                    try:\n                        _deferred_convert(identifier,kind)\n                    except Exception as exc:\n                        errors.append(identifier+\': \'+str(exc))\n            _deferred_status[\'message\'] = (\'Conversion stopped after the current image.\' if _deferred_stop.is_set()\n                 else \'Conversion finished.\') + (\' Errors: \'+\'; \'.join(errors) if errors else \'\')\n        finally:\n            with _web_update_gate:\n                _deferred_render_workers=1\n                _deferred_processing_busy=False\n                _deferred_status.update(busy=False,current=None)\n                _web_update_cancel_prepare()\n    try:\n        threading.Thread(target=worker,name=\'deferred-conversion\',daemon=True).start()\n    except Exception:\n        _deferred_processing_busy=False\n        _deferred_status[\'busy\']=False\n        _web_update_cancel_prepare()\n        raise\n\n\ndef _deferred_api(payload):\n    global _deferred_enabled\n    action=payload.get(\'action\')\n    if action==\'setting\':\n        if not isinstance(payload.get(\'enabled\'),bool):\n            raise ValueError(\'Choose a processing option.\')\n        with _web_update_gate:\n            capture_busy=globals().get(\'_high_res_capture_busy\')\n            if globals().get(\'_captures_in_flight\',0) or (capture_busy is not None and capture_busy.is_set()):\n                raise ValueError(\'Wait for the current capture to finish before changing processing.\')\n            _deferred_enabled=payload[\'enabled\']\n            _debounced_save_settings()\n    elif action==\'convert\':\n        _deferred_start(payload.get(\'ids\'),payload.get(\'kind\'))\n    elif action==\'stop\':\n        _deferred_stop.set()\n    elif action==\'delete\':\n        with _web_update_gate:\n            if _deferred_processing_busy:\n                raise ValueError(\'Stop conversion before deleting raw frames.\')\n            if payload.get(\'confirmed\') is not True:\n                raise ValueError(\'Confirm deletion of the original raw frame.\')\n            _deferred_spool.delete(payload.get(\'id\'))\n    else:\n        raise ValueError(\'Unknown image action.\')\n\n\ndef _deferred_page():\n    return \'\'\'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Unprocessed Images</title>\n<style>\n  :root {\n    --bg: #0f0e0c;\n    --panel: #17150f;\n    --panel-2: #1e1c16;\n    --text: #eae5da;\n    --muted: #8e8879;\n    --faint: #5b564b;\n    --accent: #c49a4a;\n    --accent-strong: #d8ae5c;\n    --accent-rgb: 196,154,74;\n    --on-accent: #171307;\n    --danger: #c25b4a;\n    --border: rgba(234,229,217,0.08);\n    --border-strong: rgba(234,229,217,0.16);\n    --r: 5px;\n    --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;\n    --mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;\n  }\n  * { box-sizing: border-box; }\n  html, body { margin: 0; padding: 0; background: var(--bg); color: var(--text);\n    font: 15px/1.4 var(--sans); -webkit-font-smoothing: antialiased; }\n  body { padding-left: env(safe-area-inset-left);\n    padding-right: env(safe-area-inset-right); }\n  header { position: sticky; top: 0; z-index: 10; background: rgba(15,14,12,0.97);\n    backdrop-filter: blur(8px); border-bottom: 1px solid var(--border); }\n  .wrap { max-width: 1100px; margin: 0 auto; padding: 14px 16px; }\n  /* -------- Masthead -------- */\n  .title-row { display: flex; align-items: flex-start;\n    justify-content: space-between; gap: 12px; margin-bottom: 4px; }\n  .wordmark { font-weight: 700; font-size: 20px; letter-spacing: 2.5px;\n    line-height: 1.1; }\n  .wordmark .dash { color: var(--accent); }\n  .byline { font-family: var(--mono); font-size: 8px; font-weight: 500;\n    letter-spacing: 1.8px; color: var(--muted); margin-top: 5px;\n    text-transform: uppercase; white-space: nowrap; }\n  /* Maintenance pages share the main interface\'s Settings layout. */\n  main.wrap { padding-top: 18px; padding-bottom: 40px; }\n  h1 { font-size: 18px; font-weight: 600; margin: 0 0 8px; }\n  h2 { font-size: 14px; font-weight: 600; margin: 0 0 12px; line-height: 1.5; }\n  p { line-height: 1.5; color: var(--muted); overflow-wrap: anywhere; }\n  a { color: var(--accent-strong); text-underline-offset: 3px; }\n  .page-nav { display: flex; flex-wrap: wrap; gap: 18px; padding-top: 14px;\n    font-size: 11px; font-weight: 600; letter-spacing: 1px; }\n  .page-nav span { color: var(--text); border-bottom: 2px solid var(--accent); padding-bottom: 9px; }\n  .page-nav a { color: var(--muted); text-decoration: none; }\n  section { background: var(--panel); border: 1px solid var(--border);\n    border-radius: 6px; padding: 16px; margin: 12px 0; min-width: 0; }\n  label { display: block; font-size: 14px; font-weight: 600; margin: 10px 0 4px; }\n  button, select, input { font-family: var(--sans); font-size: 14px; max-width: 100%; }\n  button { background: var(--panel-2); color: var(--text); border: 1px solid var(--border);\n    border-radius: var(--r); padding: 9px 14px; cursor: pointer; margin: 4px 4px 4px 0; }\n  button.primary { background: var(--accent); color: var(--on-accent); border-color: var(--accent); font-weight: 600; }\n  button.primary:hover:not(:disabled) { background: var(--accent-strong); }\n  button:hover:not(:disabled) { border-color: var(--border-strong); }\n  button:disabled, select:disabled, input:disabled { opacity: .5; cursor: default; }\n  button:focus-visible, select:focus-visible, input:focus-visible, a:focus-visible, summary:focus-visible {\n    outline: 2px solid var(--accent-strong); outline-offset: 3px; }\n  select { background: var(--panel-2); border: 1px solid var(--border-strong); color: var(--text);\n    border-radius: var(--r); padding: 8px 10px; margin: 4px 0 10px; color-scheme: dark; }\n  input[type=file] { display: block; width: 100%; margin: 8px 0; color: var(--muted); }\n  input::file-selector-button { font: inherit; background: var(--panel-2); color: var(--text);\n    border: 1px solid var(--border-strong); border-radius: var(--r); padding: 9px 12px; margin-right: 10px; }\n  input[type=checkbox] { accent-color: var(--accent); width: 16px; height: 16px; vertical-align: middle; }\n  #sensor, #port, #driver, #kind { width: 100%; max-width: 480px; display: block; }\n  .actions { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; }\n  .actions #kind { width: auto; margin: 4px 0; }\n  #status { white-space: pre-wrap; color: var(--text); }\n  #error { color: var(--danger); }\n  pre { font: 11px/1.6 var(--mono); white-space: pre-wrap; overflow-wrap: anywhere;\n    max-height: 350px; overflow: auto; background: var(--bg); border-radius: var(--r); padding: 12px; }\n  summary { cursor: pointer; font-size: 13px; color: var(--muted); }\n  progress { width: 100%; accent-color: var(--accent); }\n  [hidden] { display: none !important; }\n  article { display: flex; flex-wrap: wrap; gap: 14px; align-items: center;\n    padding: 16px; margin: 12px 0; background: var(--panel); border: 1px solid var(--border); border-radius: 6px; }\n  article img { width: 120px; border-radius: var(--r); }\n  article > div { flex: 1 1 220px; min-width: 0; }\n  article p { margin: 0 0 8px; font-size: 13px; }\n  article a { display: inline-block; margin-right: 12px; font-size: 13px; }\n  article button { display: block; color: var(--danger); }\n  @media (max-width: 480px) {\n    .actions { align-items: stretch; }\n    .actions button, .actions #kind { flex: 1 1 100%; margin-right: 0; }\n    select { width: 100%; }\n  }\n</style>\n<header><div class="wrap"><div class="title-row"><div><div class="wordmark">WLV<span class="dash">-</span>01</div><div class="byline">CAMERA CONTROL</div></div></div><nav class="page-nav" aria-label="Page"><a href="/">Back to camera</a><span>Unprocessed Images</span></nav></div></header><main class="wrap"><h1>Unprocessed Images</h1>\n<p>For ordinary 47 MP shots, save the raw frame now and create JPG/DNG files later. Other capture modes keep their normal processing.</p>\n<section><label>47 MP processing <select id="mode"><option value="now">Process immediately</option><option value="later">Process later</option></select></label>\n<p>Put the camera in Charge mode to convert images. The preview stays stopped during conversion. JPGs are developed from raw and may differ from immediate JPGs. Original raw frames are kept until you delete them.</p>\n<div class="actions"><button id="all">Select all</button><select id="kind"><option value="both">JPG and DNG</option><option value="jpg">JPG only</option><option value="dng">DNG only</option></select><button class="primary" id="convert">Convert selected</button><button id="stop">Stop after current image</button>\n</div></section><p id="status" role="status"></p><p id="error" role="alert"></p><div id="images"></div>\n<script>const token=\'\'\'+json.dumps(_DOWNLOAD_TOKEN)+\'\'\';const el=id=>document.getElementById(id);let busy=false,selected=new Set(),signature=\'\';\nasync function api(data){const r=await fetch(\'/api/unprocessed\',{method:data?\'POST\':\'GET\',headers:{\'X-WLV-Token\':token,\'Content-Type\':\'application/json\'},body:data?JSON.stringify(data):undefined});const d=await r.json();if(!r.ok)throw Error(d.reason||\'Request failed\');return d;}\nasync function act(data){el(\'error\').textContent=\'\';try{await api(data);await poll(false);}catch(e){el(\'error\').textContent=e.message;}}\nfunction link(id,kind){return \'/api/unprocessed/file?id=\'+id+\'&kind=\'+kind+\'&token=\'+encodeURIComponent(token);}\nasync function poll(repeat=true){try{const s=await api();busy=s.status.busy;el(\'status\').textContent=s.status.message;el(\'mode\').value=s.enabled?\'later\':\'now\';el(\'convert\').disabled=busy;el(\'stop\').disabled=!busy;\nconst sig=JSON.stringify(s.images);if(sig!==signature){signature=sig;el(\'images\').replaceChildren();for(const shot of s.images){const row=document.createElement(\'article\');const check=document.createElement(\'input\');check.type=\'checkbox\';check.checked=selected.has(shot.id);check.onchange=()=>check.checked?selected.add(shot.id):selected.delete(shot.id);row.append(check);const img=document.createElement(\'img\');img.src=link(shot.id,\'thumb\');img.alt=\'Capture thumbnail\';row.append(img);const text=document.createElement(\'div\');const title=document.createElement(\'p\');title.textContent=shot.label+\' · \'+(shot.mono?\'Mono Raw\':\'Raw\')+\' · \'+Math.round(shot.bytes/1048576)+\' MB\';text.append(title);for(const kind of [\'jpg\',\'dng\'])if(shot.outputs[kind]){const a=document.createElement(\'a\');a.href=link(shot.id,kind);a.textContent=\'Download \'+kind.toUpperCase()+\' \';text.append(a);}const remove=document.createElement(\'button\');remove.textContent=\'Delete original raw\';remove.onclick=()=>{if(confirm(\'Permanently delete this original raw frame? Converted JPG/DNG files will be kept.\'))act({action:\'delete\',id:shot.id,confirmed:true});};text.append(remove);row.append(text);el(\'images\').append(row);}}}catch(e){el(\'error\').textContent=e.message;}if(repeat)setTimeout(poll,2500);}\nel(\'mode\').onchange=()=>act({action:\'setting\',enabled:el(\'mode\').value===\'later\'});\nel(\'all\').onclick=()=>{for(const c of el(\'images\').querySelectorAll(\'input\')){c.checked=true;c.onchange();}};\nel(\'convert\').onclick=async()=>{if(busy)return;busy=true;el(\'convert\').disabled=true;await act({action:\'convert\',ids:[...selected],kind:el(\'kind\').value});};\nel(\'stop\').onclick=()=>act({action:\'stop\'});poll();</script></main></html>\'\'\'\n'
exec(compile(_DEFERRED_UI_SOURCE,'<deferred-ui>','exec'),globals())
