_capture_save_queue = _DeferredSaveQueue(maxsize=_CAPTURE_SAVE_QUEUE_MAX)


def _run_dng_queue_selftest():
    """Stress the capture-save admission gate with the REAL accounting
    functions: a producer fires simulated shutter presses far faster than a
    deliberately slow worker drains them, and the test asserts that (a) the
    byte budget engages the blocked-shutter path instead of over-admitting,
    (b) every admitted job is processed — none dropped or swapped away —
    and (c) the in-flight counters return exactly to zero (no leak that
    would wedge the shutter).  Runs before the real save worker thread
    exists, so the queue object is exercised without interference.
    WLV_DNG_QUEUE_SELFTEST=1 python3 wlf8.py"""
    passes = fails = 0

    def _check(label, ok, detail=""):
        nonlocal passes, fails
        if ok:
            passes += 1
            print(f"  PASS  {label}")
        else:
            fails += 1
            print(f"  FAIL  {label}  {detail}")

    job_bytes = _CAPTURE_SAVE_MEM_BUDGET_BYTES // 3 + 1   # 3rd press blocks
    test_queue = queue.Queue(maxsize=_CAPTURE_SAVE_QUEUE_MAX)
    processed = []

    def _slow_worker():
        while True:
            job = test_queue.get()
            if job is None:
                test_queue.task_done()
                return
            time.sleep(0.03)          # far slower than the producer
            processed.append(job[0])
            _mark_capture_resolved(job[1])
            test_queue.task_done()

    worker = threading.Thread(target=_slow_worker, daemon=True)
    worker.start()
    admitted, blocked = [], 0
    max_inflight_bytes = 0
    for press in range(40):
        if _capture_mem_budget_ok(job_bytes):
            test_queue.put((press, job_bytes))
            _mark_capture_queued(job_bytes)
            admitted.append(press)
        else:
            blocked += 1              # the shutter's danger-flash path
        with _captures_in_flight_lock:
            max_inflight_bytes = max(max_inflight_bytes,
                                     _capture_bytes_in_flight)
        time.sleep(0.002)
    test_queue.put(None)
    worker.join(timeout=30)
    _check("burst blocks past the byte budget", blocked > 0,
           f"blocked={blocked}")
    _check("budget never over-admitted",
           max_inflight_bytes <= _CAPTURE_SAVE_MEM_BUDGET_BYTES,
           f"peak={max_inflight_bytes}")
    _check("every admitted frame processed, in order, none lost",
           processed == admitted,
           f"admitted={len(admitted)} processed={len(processed)}")
    _check("in-flight accounting returns to zero",
           _captures_in_flight == 0 and _capture_bytes_in_flight == 0,
           f"count={_captures_in_flight} bytes={_capture_bytes_in_flight}")
    # A single press must always be admitted, whatever its size.
    _check("first shot always admitted",
           _capture_mem_budget_ok(_CAPTURE_SAVE_MEM_BUDGET_BYTES * 100))
    print(f"\nDNG queue selftest: {passes} passed, {fails} failed")
    return 0 if fails == 0 else 1


if os.environ.get("WLV_DNG_QUEUE_SELFTEST"):
    sys.exit(_run_dng_queue_selftest())


_capture_sequence_lock = threading.Lock()
_capture_sequence_timestamp = None
_capture_sequence_index = 0


def _start_capture_sequence():
    global _capture_sequence_timestamp, _capture_sequence_index
    with _capture_sequence_lock:
        ts = datetime.now().strftime("%Y%m%d_%H%M%S")
        # Same wall-clock second as the previous sequence: keep counting
        # instead of resetting to _001, so a rapid second capture can't
        # collide with one whose save is still queued (not yet on disk —
        # the on-disk existence check in _next_capture_basename can't see
        # it yet).
        if ts != _capture_sequence_timestamp:
            _capture_sequence_timestamp = ts
            _capture_sequence_index = 0


def _next_capture_basename():
    global _capture_sequence_timestamp, _capture_sequence_index
    with _capture_dir_lock:
        check_dir = _capture_dir
    with _capture_sequence_lock:
        if not _capture_sequence_timestamp:
            _capture_sequence_timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            _capture_sequence_index = 0
        _capture_sequence_index += 1
        timestamp = _capture_sequence_timestamp
        # Two shutter presses within the same wall-clock second restart the
        # sequence at _001 (see _start_capture_sequence), so the second
        # capture would silently OVERWRITE the first.  Bump past any basename
        # whose JPG/DNG (or in-flight ".jpg.tmp" from the atomic writer)
        # already exists on disk.  Bounded so a pathological directory can
        # never spin the shutter path forever.
        for _ in range(999):
            candidate = f"{timestamp}_{_capture_sequence_index:03d}"
            try:
                if not (os.path.exists(os.path.join(check_dir, candidate + ".jpg"))
                        or os.path.exists(os.path.join(check_dir, candidate + ".jpg.tmp"))
                        or os.path.exists(os.path.join(check_dir, candidate + ".dng"))):
                    break
            except Exception:
                break
            _capture_sequence_index += 1
        index = _capture_sequence_index
    return f"{timestamp}_{index:03d}"


def _prepare_output_frame(frame, target_dims, target_ratio):
    if frame is None:
        return None
    frame_to_use = frame
    if frame_to_use.ndim == 3 and frame_to_use.shape[2] == 4:
        # picamera2's "RGB888" 3-channel and "XBGR8888" 4-channel main streams
        # both deliver BGR-ordered pixel data. Drop the alpha but keep the BGR
        # order so the entire save path stays consistent with the live preview.
        frame_to_use = cv2.cvtColor(frame_to_use, cv2.COLOR_BGRA2BGR)
    # target_dims are precomputed from the full sensor frame; a frame that
    # had its optical-black columns cropped (see _frame_edge_ob_cols) is
    # narrower, so dims that no longer fit fall through to the exact
    # ratio recompute against the frame's real size (ratio <= 0 — the
    # "Full" selection — then saves the frame uncropped).
    fh, fw = frame_to_use.shape[:2]
    if (target_dims and target_dims[0] and target_dims[1]
            and target_dims[0] <= fw and target_dims[1] <= fh):
        frame_to_use = _center_crop(frame_to_use, target_dims[0], target_dims[1])
    elif target_ratio > 0:
        crop_w, crop_h = _largest_ratio_crop_dims(
            frame_to_use.shape[1], frame_to_use.shape[0], target_ratio
        )
        frame_to_use = _center_crop(frame_to_use, crop_w, crop_h)
    return frame_to_use


def _rotate_dng_180(dng_path):
    orientation_tag = 0x0112
    new_subfile_tag = 0x00FE
    sub_ifd_tag = 0x014A
    type_sizes = {
        1: 1,   # BYTE
        2: 1,   # ASCII
        3: 2,   # SHORT
        4: 4,   # LONG
        5: 8,   # RATIONAL
        7: 1,   # UNDEFINED
        9: 4,   # SLONG
        10: 8,  # SRATIONAL
    }

    if not dng_path or not os.path.isfile(dng_path):
        return
    try:
        with open(dng_path, "r+b") as handle:
            header = handle.read(8)
            if len(header) < 8:
                return
            endian = header[:2]
            if endian == b"II":
                fmt_prefix = "<"
            elif endian == b"MM":
                fmt_prefix = ">"
            else:
                return
            if struct.unpack(fmt_prefix + "H", header[2:4])[0] != 42:
                return
            first_ifd = struct.unpack(fmt_prefix + "I", header[4:8])[0]
            visited = set()
            ifd_queue = [first_ifd]

            def _read_value(entry_type, count, value_offset):
                if entry_type not in type_sizes:
                    return None
                total = type_sizes[entry_type] * count
                if total <= 4:
                    data = value_offset.to_bytes(4, "little" if fmt_prefix == "<" else "big")
                else:
                    handle.seek(value_offset)
                    data = handle.read(total)
                if entry_type == 3 and count == 1:
                    return struct.unpack(fmt_prefix + "H", data[:2])[0]
                if entry_type == 4 and count == 1:
                    return struct.unpack(fmt_prefix + "I", data[:4])[0]
                return None

            def _write_orientation(entry_type, count, value_offset):
                if entry_type != 3 or count != 1:
                    return
                total = type_sizes[entry_type] * count
                if total <= 4:
                    handle.seek(value_offset)
                    handle.write(struct.pack(fmt_prefix + "H", 3))
                    handle.write(b"\x00\x00")
                else:
                    handle.seek(value_offset)
                    handle.write(struct.pack(fmt_prefix + "H", 3))

            while ifd_queue:
                ifd_offset = ifd_queue.pop(0)
                if not ifd_offset or ifd_offset in visited:
                    continue
                visited.add(ifd_offset)
                handle.seek(ifd_offset)
                count_data = handle.read(2)
                if len(count_data) < 2:
                    continue
                entry_count = struct.unpack(fmt_prefix + "H", count_data)[0]
                entries_start = handle.tell()
                new_subfile_type = 0
                orientation_entry = None
                sub_ifd_offsets = []
                for _ in range(entry_count):
                    entry = handle.read(12)
                    if len(entry) < 12:
                        break
                    tag, entry_type, count, value_offset = struct.unpack(
                        fmt_prefix + "HHII", entry
                    )
                    if tag == new_subfile_tag:
                        value = _read_value(entry_type, count, value_offset)
                        if value is not None:
                            new_subfile_type = value
                    elif tag == orientation_tag:
                        orientation_entry = (entry_type, count, value_offset)
                    elif tag == sub_ifd_tag and entry_type == 4:
                        if count == 1:
                            sub_ifd_offsets.append(value_offset)
                        else:
                            total = type_sizes[entry_type] * count
                            handle.seek(value_offset)
                            data = handle.read(total)
                            for idx in range(count):
                                offset = struct.unpack(
                                    fmt_prefix + "I", data[idx * 4:(idx + 1) * 4]
                                )[0]
                                sub_ifd_offsets.append(offset)
                if new_subfile_type == 0 and orientation_entry is not None:
                    entry_type, count, value_offset = orientation_entry
                    if type_sizes.get(entry_type):
                        entry_index = None
                        handle.seek(entries_start)
                        for idx in range(entry_count):
                            entry = handle.read(12)
                            if len(entry) < 12:
                                break
                            tag = struct.unpack(fmt_prefix + "H", entry[:2])[0]
                            if tag == orientation_tag:
                                entry_index = idx
                                break
                        if entry_index is not None:
                            entry_value_pos = entries_start + entry_index * 12 + 8
                            _write_orientation(entry_type, count, entry_value_pos if type_sizes[entry_type] * count <= 4 else value_offset)
                for sub_offset in sub_ifd_offsets:
                    ifd_queue.append(sub_offset)
                handle.seek(entries_start + entry_count * 12)
                next_ifd_data = handle.read(4)
                if len(next_ifd_data) == 4:
                    next_ifd = struct.unpack(fmt_prefix + "I", next_ifd_data)[0]
                    if next_ifd:
                        ifd_queue.append(next_ifd)
    except Exception as exc:
        print("DNG rotate error:", exc)


# Per-unit DNG calibration (noise profile), produced by the standalone
# dng_calibrate.py script on the camera and keyed by the libcamera sensor
# model so a cartridge swap never applies the wrong table.
# Loaded ONCE at startup (_dng_load_calibration, called right after the
# sensor model is known) — the save path must never touch the filesystem
# for configuration per frame.
# NOTE: there is deliberately NO dead-pixel calibration path.  Direct
# analysis of production IMX294 frames showed zero interior dead pixels —
# every zero-valued pixel is frame-edge geometry (left optical-black
# columns + truncated trailing read-out rows), which the ActiveArea tags
# describe instead.
_DNG_CALIB_DIR = Path(__file__).with_name("calibration")
_dng_noise_table_calib = None     # {"gains": [{"gain","channels"}...]} or None
_dng_baseline_ev_calib = 0.0      # per-sensor BaselineExposure (EV; 0 = honest default)

# Learned frame-edge geometry per sensor + raw size (see
# _dng_detect_geometry): {"<model>:<w>x<h>": {"ob": int, "trailing": int}}.
# Persisted so dark frames — where the OB-band detection abstains — still
# get the same ActiveArea as every other file from that sensor.  Updated
# from confident per-frame measurements on the save worker (same
# self-correcting pattern as the mono verdict).
_dng_geometry_persist = {}
try:
    _g = _PERSISTED_SETTINGS.get("dng_frame_geometry")
    if isinstance(_g, dict):
        for _k, _v in _g.items():
            if isinstance(_v, dict):
                _dng_geometry_persist[str(_k)] = {
                    "ob": max(0, int(_v.get("ob") or 0)),
                    "trailing": max(0, int(_v.get("trailing") or 0)),
                }
except Exception:
    _dng_geometry_persist = {}


# Two threads write DNGs (the capture-save worker and the Burst SR merge
# worker), so the read-modify-write below is serialized — an unlocked
# update could drop one thread's confident OB measurement when both
# resolve the same sensor+size key at once.
_dng_geometry_lock = threading.Lock()


def _dng_geometry_update(key, det_ob, det_trailing):
    """Fold a frame's confident geometry measurements into the persisted
    per-sensor entry (trailing keeps the max ever seen so one clean frame
    can't shrink the claim; the OB width follows the last confident
    measurement).  Debounce-persists only on change."""
    try:
        with _dng_geometry_lock:
            entry = _dng_geometry_persist.get(key) or {}
            new = {
                "ob": int(det_ob) if det_ob is not None
                else int(entry.get("ob") or 0),
                "trailing": max(int(det_trailing),
                                int(entry.get("trailing") or 0)),
            }
            changed = new != entry
            if changed:
                _dng_geometry_persist[key] = new
        if changed:
            # A changed verdict changes the ActiveArea of every following
            # DNG (and the dimensions raw converters report), so name the
            # transition in the journal — a flip-flopping band width here
            # is a detection problem to root-cause, never normal drift.
            print(f"[DNG] frame geometry {key}: {entry or 'unset'} -> {new}")
            _debounced_save_settings()
    except Exception:
        pass


# Learned QBC software-remosaic verdict per sensor + raw size (see
# _dng_qbc_detect): {"<model>:<w>x<h>": bool}.  Persisted so frames whose
# own classification abstains (flat/dark scenes) get the same G-plane
# treatment as confidently classified ones — the same self-correcting
# pattern as the frame-edge geometry above.
_dng_qbc_persist = {}
try:
    _q = _PERSISTED_SETTINGS.get("dng_qbc_remosaic")
    if isinstance(_q, dict):
        for _k, _v in _q.items():
            _dng_qbc_persist[str(_k)] = bool(_v)
except Exception:
    _dng_qbc_persist = {}


def _dng_qbc_update(key, det):
    """Fold a frame's confident QBC-remosaic verdict into the persisted
    entry (the last confident classification wins, matching the OB-width
    policy).  Shares _dng_geometry_lock — the same two save workers write
    both.  Debounce-persists only on change."""
    if det is None or not key:
        return
    try:
        with _dng_geometry_lock:
            changed = _dng_qbc_persist.get(key) != bool(det)
            if changed:
                _dng_qbc_persist[key] = bool(det)
        if changed:
            _debounced_save_settings()
    except Exception:
        pass


def _dng_sensor_calib_id(model, mono):
    """Calibration identity for the ACTIVE cartridge.  The libcamera model
    string alone is not enough: colour and full-spectrum-mono variants of
    one sensor sit behind the same driver and report the same model (that
    ambiguity is the whole reason the runtime mono verdict exists), so
    keying files by model alone would let one variant's calibration
    silently overwrite — and later be applied to — the other.  Mono
    variants get a `_mono` suffix, matching the platform's own tuning-file
    convention (imx585_mono.json)."""
    return f"{model}_mono" if mono else model


def _dng_load_calibration(model):
    """Read calibration/<id>_noise_profile.json and
    calibration/<id>_baseline_exposure.json into module state, where <id>
    is the variant-qualified sensor identity (_dng_sensor_calib_id) for
    the CURRENT mono verdict.  Re-run on a verdict flip (see
    _set_mono_sensor_active) so a cartridge swap re-resolves the files;
    stale values are cleared first so a missing file can never leave the
    other variant's calibration active.  Missing or malformed files are
    silently absent — calibration is an enhancement, never a boot
    dependency."""
    global _dng_noise_table_calib, _dng_baseline_ev_calib
    if not model:
        return
    calib_id = _dng_sensor_calib_id(model, _mono_sensor_active)
    _dng_baseline_ev_calib = 0.0
    _dng_noise_table_calib = None
    path = _DNG_CALIB_DIR / f"{calib_id}_baseline_exposure.json"
    try:
        if path.is_file():
            with open(path) as fh:
                payload = json.load(fh)
            # Belt-and-braces variant check: a file that RECORDS which
            # cartridge variant measured it must match the active one.
            if ("mono" in payload
                    and bool(payload["mono"]) != bool(_mono_sensor_active)):
                print(f"[DNG] baseline exposure ignored — calibrated on the "
                      f"other cartridge variant ({path.name})")
            else:
                ev = float(payload["ev"])
                _dng_baseline_ev_calib = min(max(ev, -4.0), 4.0)
                print(f"[DNG] baseline exposure calibration loaded: "
                      f"{_dng_baseline_ev_calib:+.2f} EV ({path.name})")
    except Exception as exc:
        _dng_baseline_ev_calib = 0.0
        print(f"[DNG] calibration load failed ({path.name}): {exc}")
    path = _DNG_CALIB_DIR / f"{calib_id}_noise_profile.json"
    try:
        if path.is_file():
            with open(path) as fh:
                payload = json.load(fh)
            # A table that cannot produce calibrated coefficients is not a
            # table: require at least one entry with a positive gain and a
            # non-empty channel dict.  (The interpolator alone can't verify
            # this — it always returns SOMETHING, falling back to the
            # gain-derived default, which would let a malformed file log
            # "calibration loaded" while every frame silently wrote the
            # uncalibrated default.)
            usable = [float(e["gain"]) for e in payload.get("gains", [])
                      if float(e.get("gain", 0) or 0) > 0
                      and isinstance(e.get("channels"), dict)
                      and e["channels"]]
            if ("mono" in payload
                    and bool(payload["mono"]) != bool(_mono_sensor_active)):
                print(f"[DNG] noise calibration ignored — calibrated on the "
                      f"other cartridge variant ({path.name})")
            elif usable:
                _dng_noise_table_calib = payload
                print(f"[DNG] noise calibration loaded: gains "
                      f"{sorted(usable)} ({path.name})")
            else:
                print(f"[DNG] noise calibration ignored — no usable gain "
                      f"entries ({path.name})")
    except Exception as exc:
        _dng_noise_table_calib = None
        print(f"[DNG] calibration load failed ({path.name}): {exc}")


_dng_camera_model_cache = None


def _dng_camera_model():
    """'WLV-01 <sensor>' string for the DNG Model/UniqueCameraModel tags,
    resolved once from libcamera's reported sensor model (raw converters
    key rendering/calibration profiles off these strings, so they must be
    stable per cartridge, never per shot)."""
    global _dng_camera_model_cache
    if _dng_camera_model_cache is None:
        try:
            model = str(
                (picam2.camera_properties or {}).get("Model", "")).strip().lower()
        except Exception:
            model = ""
        _dng_camera_model_cache = f"WLV-01 {model}".strip() if model else "WLV-01"
    return _dng_camera_model_cache


def _dng_capture_mono_verdict(raw_buf, raw_meta, raw_cfg):
    """Mono-vs-colour classification of THIS raw payload, so the DNG's tags
    are never decided by a stale persisted verdict.  The save worker writes
    the DNG BEFORE its mono classify/develop stages examine the same
    payload, so on the first capture after a cartridge swap
    `_mono_sensor_active` still describes the previous cartridge — a mono
    frame would keep CFA tags (demosaiced into a checkerboard) and a colour
    frame would be written as LinearRaw.  Runs the same classification the
    JPG path trusts, on the same cheap centre row band as
    `_mono_classify_only`.  Returns True/False, or None when the frame
    abstains (dark/clipped/unknown format) — callers fall back to the
    persisted verdict, exactly like the JPG path keeps its previous one."""
    try:
        cfg = raw_cfg or {}
        info = _raw_format_info(cfg.get("format"))
        if info is not None and info[0]:
            return True     # native mono raw (R16): the format is the verdict
        row_band = None
        try:
            h = int(cfg.get("size")[1])
            if h > _MONO_CLASSIFY_BAND_ROWS:
                r0 = ((h - _MONO_CLASSIFY_BAND_ROWS) // 2) & ~3
                row_band = (r0, _MONO_CLASSIFY_BAND_ROWS)
        except Exception:
            row_band = None
        u16, bits = _raw_unpack_to_u16(raw_buf, cfg, row_band=row_band)
        if u16 is not None:
            return _classify_raw_mono(
                u16, bits, (raw_meta or {}).get("SensorBlackLevels"))
    except Exception as exc:
        print(f"[DNG] capture-time mono classify failed: {exc}")
    return None


# Declared frame-edge geometry for sensor+mode combinations whose dead
# edges are a fixed property of the DRIVER, not of the scene.  On the
# IMX294/IMX492 full-res read-outs both edges come straight out of the
# mode tables in imx294-imx492-v4l2-driver: `HOPBOUT_EN=1` transmits the
# horizontal optical-black region (the left band), and the IMX294 QBC
# modes carry `opb_size_v=0x22` / `y_out_size=0x160E` (5646) against an
# advertised 5648, so the last rows are never sent and the boundary row
# arrives partial.  Those numbers are identical on every unit running the
# same driver, so measuring them per frame is inference where a constant
# is exact.
#
# A declared entry therefore WINS over detection: no scene-dependent
# statistics run at all for these captures, which removes the whole class
# of edge cases the measurement path has to defend against (a dark scene
# edge reading as a band, gain-lifted read noise, a hard dark band at the
# bottom of the frame).  Detection stays the default for everything else,
# so an unlisted sensor keeps working with no entry — that is what keeps
# the firmware sensor-agnostic, and it is also how a new cartridge gets
# characterised: shoot one frame, read the `edge%` profile the DNG log
# prints, and add a line here.
#
# Keyed by libcamera model substring, then by the RAW payload size, so a
# sensor's binned modes (which set no HOPBOUT_EN and are complete) are
# simply absent and fall through to detection like any other mode.
# `ob` = left optical-black columns, `trailing` = dead bottom rows.
_DNG_FIXED_FRAME_GEOMETRY = {
    "imx294": {
        # 47 MP quad-Bayer read-out.  `ob` is the ActiveArea claim, NOT
        # the optical-black width: 94 flat OB columns (measured, mean
        # 202.5 DN) PLUS the 2 partially masked columns where the shield
        # edge falls mid-column — those are not image data and render as
        # a faint line down the rendered right edge if left in.  The
        # per-frame black level still comes from the flat 94 only
        # (_dng_ob_core_cols trims the transition back off).  Rows: 2
        # never-transmitted + 1 partial boundary row.
        (8432, 5648): {"ob": 96, "trailing": 3},
    },
}


def _dng_fixed_geometry(raw_cfg):
    """Declared frame-edge geometry for this capture, or None to measure.

    None is the sensor-agnostic default: any lookup that does not match
    exactly falls through to _dng_detect_geometry, so an unlisted sensor
    or mode behaves exactly as it does today."""
    try:
        model = str(
            (picam2.camera_properties or {}).get("Model", "")).strip().lower()
        if not model:
            return None
        size = (raw_cfg or {}).get("size") or ()
        key = (int(size[0]), int(size[1]))
        for name, modes in _DNG_FIXED_FRAME_GEOMETRY.items():
            if name in model:
                entry = modes.get(key)
                return dict(entry) if entry else None
    except Exception as exc:
        print(f"[DNG] fixed geometry lookup failed (measuring instead): {exc}")
    return None


def _dng_qbc_eligible(raw_cfg):
    """Hard gate for the QBC software-remosaic G-plane repair: only
    IMX294-class FULL-RESOLUTION (47 MP-family) captures may engage the
    detector at all — every other sensor and every binned mode writes its
    payload byte-identically, whatever the statistics say.  The sensor
    predicate is shared with the dropdown (_unbinned_preview_available:
    the sensors whose full-res read-outs are quad-Bayer and SW-remosaiced
    are exactly the ones whose unbinned preview is withheld), and the
    full-res-family discriminator mirrors the dropdown's crop filter —
    sharing EITHER dimension with the largest enumerated mode; the binned
    modes shrink in both and read out standard Bayer (only the full-res
    modes set HOPBOUT_EN in the driver's mode tables).  Any lookup
    failure gates OFF: a missed repair self-heals on the next capture, a
    wrong one would rewrite real photosites."""
    try:
        if _unbinned_preview_available():
            return False    # not a QBC-remosaic sensor (IMX585, IMX492...)
        w, h = (raw_cfg or {}).get("size", (0, 0))
        full_w = max(o["size"][0] for o in SENSOR_MODE_OPTIONS)
        full_h = max(o["size"][1] for o in SENSOR_MODE_OPTIONS)
        return bool(SENSOR_MODE_OPTIONS) and (
            int(w) == int(full_w) or int(h) == int(full_h))
    except Exception as exc:
        print(f"[DNG] QBC eligibility check failed (gating off): {exc}")
        return False


def _pan_mono_eligible(raw_cfg, mono_verdict=None, mono_raw=None, raw_meta=None):
    """Gate on the shutter-time mode and this payload's sensor verdict.
    IMX294 full-resolution conversion additionally requires affirmative
    per-frame QbcRaw metadata. Unknown sensors/layouts fail closed.
    """
    try:
        active = _mono_raw_active() if mono_raw is None else bool(mono_raw)
        if not active:
            return False
        is_mono = _mono_sensor_active if mono_verdict is None else bool(mono_verdict)
        if is_mono:
            return False
        qbc_sensor = _qbc_sensor_status()
        if qbc_sensor is None:
            return False        # unknown sensor identity -> fail closed
        if qbc_sensor and _dng_qbc_eligible(raw_cfg):
            return (raw_meta or {}).get("QbcRaw") is True
        return _dng_cfa_pattern((raw_cfg or {}).get("format")) is not None
    except Exception as exc:
        print(f"[DNG] Mono Raw eligibility check failed (gating off): {exc}")
        return False


def _wlv_save_dng(raw_buf, raw_meta, raw_cfg, dng_path, description=None,
                  mono_raw=None, mono_result=None):
    """Single seam for every DNG save: honest 12-bit values + LJ92 lossless
    compression via _dng_write (see the DNG WRITER section at the top of the
    file), with a capture-time mono verdict deciding CFA-vs-monochrome tags.
    Ordinary colour captures can fall back to the stock picamera2 writer.
    Quad raw and requested IMX294 47 MP Mono Raw must instead report failure
    if their layout/conversion cannot be verified, avoiding a mislabeled DNG.

    Returns the payload's mono classification (True/False, None when the
    frame abstained or the writer fell back) so the capture-save worker can
    reuse it instead of unpacking and classifying the same band a second
    time for the verdict-learning pass."""
    classified = None
    try:
        _imx294_require_quad_metadata(raw_meta, bool(mono_raw)
                                      and _qbc_sensor_status() is True
                                      and _dng_qbc_eligible(raw_cfg))
        classified = (False if (raw_meta or {}).get("QbcRaw") is True else
                      _dng_capture_mono_verdict(raw_buf, raw_meta, raw_cfg))
        try:
            geo_key = "{}:{}x{}".format(
                _dng_camera_model(),
                int((raw_cfg or {}).get("size", (0, 0))[0]),
                int((raw_cfg or {}).get("size", (0, 0))[1]))
        except Exception:
            geo_key = None
        fixed_geo = _dng_fixed_geometry(raw_cfg)
        st = _dng_write(raw_buf, raw_meta, raw_cfg, dng_path,
                        description=description,
                        mono_result=mono_result,
                        force_mono=classified if classified is not None
                        else _mono_sensor_active,
                        camera_model=_dng_camera_model(),
                        imx294=_qbc_sensor_status() is True,
                        noise_table=_dng_noise_table_calib,
                        geometry=fixed_geo or _dng_geometry_persist.get(geo_key),
                        geometry_fixed=fixed_geo is not None,
                        baseline_exposure_ev=_dng_baseline_ev_calib,
                        qbc=_dng_qbc_persist.get(geo_key),
                        qbc_eligible=_dng_qbc_eligible(raw_cfg),
                        # `classified` is THIS payload's own verdict; passing
                        # it keeps the DNG and the JPG from disagreeing after
                        # a cartridge swap, when the persisted global is
                        # still a cartridge behind.  `mono_raw` is the
                        # shutter-time mode pinned on the save job.
                        pan_mono=_pan_mono_eligible(
                            raw_cfg, mono_verdict=classified,
                            mono_raw=mono_raw, raw_meta=raw_meta))
        if geo_key:
            # Only the GEOMETRY verdict is skipped for a declared mode
            # (there is nothing to learn about a constant).  The QBC
            # verdict is an independent property of the payload and must
            # still persist — and the declaring sensor IS the one the
            # repair exists for, so gating both together left every
            # abstaining IMX294 frame with no fallback verdict and wrote
            # its synthetic G sites unrepaired.
            if fixed_geo is None:
                _dng_geometry_update(geo_key, st.get("det_ob"),
                                     st.get("det_trailing") or 0)
            _dng_qbc_update(geo_key, st.get("qbc"))
        print(f"[DNG] {os.path.basename(dng_path)}: "
              f"{st['width']}x{st['height']} {st['bits']}-bit "
              f"{'mono' if st['mono'] else 'CFA'} "
              f"{'LJ92' if st['compressed'] else 'uncompressed'} "
              f"{st['bytes'] / 1e6:.1f} MB "
              f"active {st['width'] - st['ob_cols']}x"
              f"{st['height'] - st['trailing_rows']}"
              f"+{st['ob_cols']}+0 "
              + ("declared " if st.get("geometry_fixed") else "")
              # The per-frame pedestal measured off the optical-black band,
              # next to the constant the ISP actually subtracted.  A gap
              # between them is a residual offset in every ISP-derived
              # frame, which the AWB gains then multiply unevenly (blue
              # gain is the largest under warm light) — shadows tint while
              # highlights stay clean.  The tuning's rpi.black_level is a
              # single value for every gain, so this is the only place the
              # drift is visible.
              + (f"black {st['black']}{'' if st.get('black_measured') else ' (constant)'} "
                 if st.get("black") else "")
              + (f"edge% {st['edge_profile']} " if st.get("edge_profile")
                 else "")
              + (f"QBC-G repaired {st['qbc_repaired']} "
                 f"(ratio {st['qbc_ratio']:.1f}, {st['t_qbc']:.2f}s) "
                 if st.get("qbc_repaired") else "")
              + (f"MonoRaw ({st['t_pan']:.2f}s) "
                 if st.get("pan_mono") else "")
              + f"(unpack {st['t_unpack']:.2f}s encode {st['t_encode']:.2f}s "
              f"write {st['t_write']:.2f}s)")
        return classified
    except Exception as exc:
        print(f"[DNG] 12-bit writer failed ({exc})")
        traceback.print_exc()
        if ((raw_meta or {}).get("QbcRaw") is True
                or (mono_raw and _qbc_sensor_status() is True
                    and _dng_qbc_eligible(raw_cfg))):
            # The stock writer only describes 2x2 Bayer. Surface the failure
            # so local recovery can retry without mislabelling quad raw.
            raise
        picam2.helpers.save_dng(raw_buf, raw_meta, raw_cfg, dng_path)
        # Verdict deliberately withheld on the fallback path: the caller
        # should classify from scratch rather than trust a half-failed run.
        return None


def _capture_settings_exif_desc(film_key):
    """One-line human-readable shooting-settings summary, attached to every
    JPG as EXIF ImageDescription/UserComment (the long-exposure path already
    tags its mode the same way).  Built at shutter time so the tag reflects
    the settings the shot was actually taken with.  Every part is guarded —
    a missing option table must never cost a capture."""
    parts = []
    try:
        # A manual speed is captured verbatim in every mode (the low-ISO
        # 47 MP trade only lengthens AUTO exposures, which this snapshot
        # records as "AUTO" — the DNG metadata carries the real value).
        parts.append(f"SS {SHUTTER_LABELS[current_shutter_idx]}")
    except Exception:
        pass
    try:
        # Anti-banding: record the mode and, when the manual exposure was
        # snapped, the effective speed the sensor actually used.
        _ab_opt = ANTIBANDING_OPTIONS[_antibanding_idx]
        if _ab_opt["period_us"]:
            _ab_part = f"AB {_ab_opt['label'].replace(' ', '')}"
            if _antibanding_eff_us:
                _ab_part += f" eff {format_shutter_speed(_antibanding_eff_us)}"
            parts.append(_ab_part)
    except Exception:
        pass
    try:
        parts.append(f"ISO {_current_iso_label()}")
    except Exception:
        pass
    try:
        ev = _current_exp_comp_label()
        if ev and ev != "0":
            parts.append(f"EV {ev}")
    except Exception:
        pass
    try:
        # Focus Point spot metering: record the servo's EV bias so the shot's
        # exposure provenance is readable off the file.
        if focus_point_enabled and abs(_spot_meter_bias_ev) >= 0.05:
            parts.append(f"Spot {_spot_meter_bias_ev:+.1f}EV")
    except Exception:
        pass
    try:
        if film_key and film_key != "none":
            parts.append(f"Film {_current_film_label()}")
    except Exception:
        pass
    try:
        # White balance: only worth recording when it isn't plain auto (and
        # never on mono, where AWB is neutralised).
        if not _mono_sensor_active and _wb_mode_idx:
            _wb_opt = WB_OPTIONS[_wb_mode_idx]
            if _wb_opt["mode"] is None and _wb_custom_gains:
                parts.append(f"WB Custom R{_wb_custom_gains[0]:.2f} "
                             f"B{_wb_custom_gains[1]:.2f}")
            else:
                parts.append(f"WB {_wb_opt['label']}")
    except Exception:
        pass
    try:
        with _aspect_button_lock:
            parts.append(f"Aspect {ASPECT_OPTIONS[_aspect_idx]['label']}")
    except Exception:
        pass
    try:
        modes = globals().get("SENSOR_MODE_OPTIONS") or []
        if modes:
            parts.append(str(modes[_sensor_mode_idx].get("label", "")))
    except Exception:
        pass
    return "WLV-01  " + "  ".join(p for p in parts if p)


# JPEG encoder quality for every capture written through
# _save_jpg_with_exif — one constant so the EXIF path and the bare-cv2
# fallback below it can never drift apart (a capture that fell back would
# otherwise silently change quality).
_JPG_QUALITY = 100


def _save_jpg_with_exif(jpg_path, frame_bgr, exif_desc):
    """Write a quality-`_JPG_QUALITY` JPG with `exif_desc` attached as EXIF
    ImageDescription + UserComment (plus DateTime/Software). The picture is
    encoded straight from the BGR frame by cv2 and the EXIF APP1 segment is
    spliced into the byte stream; PIL only BUILDS the few-hundred-byte EXIF
    block. A full PIL encode is kept as the fallback and a bare cv2 encode
    (no EXIF) as the last resort, so nothing here can lose a capture.
    Returns True if a file was written.

    Why not the old single PIL encode: `cv2.cvtColor` made a full RGB copy
    and `Image.fromarray(...).save()` copied it again inside Pillow, so at
    47 MP the encode stage held the rotated frame plus ~270 MB of copies —
    a save-worker high-water mark of ~470 MB against the ~238 MB the
    shutter admission gate books, which is OOM-killer territory on a 2 GB
    board (a SIGKILL no exception guard sees). The splice path's peak is
    the frame plus the ~20 MB encoded buffer.

    Writes are atomic: the encode lands in a same-directory `.tmp` file that
    is os.replace()d over the final path only on success, so a power cut or
    process kill mid-encode can never leave a truncated JPG at the final
    name (the gallery/download server only ever see complete files)."""
    tmp_path = jpg_path + ".tmp"

    def _discard_tmp():
        try:
            if os.path.exists(tmp_path):
                os.remove(tmp_path)
        except Exception:
            pass

    def _build_exif_payload():
        """The APP1 payload (the Exif NUL NUL header + TIFF block)."""
        exif = Image.Exif()
        exif[0x010E] = exif_desc     # ImageDescription
        # UserComment mirrors the description for tools that ignore one
        # tag or the other. Per the EXIF spec it is an UNDEFINED field
        # that must start with an 8-byte character-code header — without
        # it exiftool/exiv2 show the comment as corrupted.
        exif[0x9286] = b"ASCII\x00\x00\x00" + exif_desc.encode("ascii", "ignore")
        exif[0x0132] = datetime.now().strftime("%Y:%m:%d %H:%M:%S")  # DateTime
        exif[0x0131] = "WLV-01"      # Software
        blob = exif.tobytes()
        # Current Pillow returns the "Exif\0\0" APP1 header as part of
        # tobytes() (and its own JPEG writer emits that verbatim); older
        # ones return the bare TIFF block. Add it only when missing — two
        # prefixes make the segment unreadable to every parser.
        if not blob.startswith(b"Exif\x00\x00"):
            blob = b"Exif\x00\x00" + blob
        return blob

    def _verify_round_trip():
        # Confirm by REOPENING the written file that the description is
        # actually present — a header-only read, microseconds.  Field
        # case: sample JPGs arrived with no EXIF at all and nothing in
        # the journal said which path produced them; a write that
        # silently sheds its metadata must be loud.
        try:
            with Image.open(jpg_path) as _back:
                _got = _back.getexif().get(0x010E)
            if _got != exif_desc:
                print("[Save] WARNING: EXIF description did not "
                      f"round-trip for {os.path.basename(jpg_path)} "
                      f"(read back {_got!r})")
        except Exception as _vrf:
            print(f"[Save] WARNING: EXIF verify failed for "
                  f"{os.path.basename(jpg_path)}: {_vrf}")

    if not _PIL_AVAILABLE and exif_desc:
        # The cv2 fallback below writes a perfectly good JPG with NO EXIF at
        # all.  That is the right trade (a capture is never lost to a
        # metadata library), but it must never be silent: a camera whose
        # JPGs all arrive without their settings description is running this
        # branch, and this line is how a field journal says so.
        print(f"[Save] EXIF skipped (Pillow unavailable) — plain JPG for "
              f"{os.path.basename(jpg_path)}")
    if _PIL_AVAILABLE and exif_desc:
        payload = None
        try:
            payload = _build_exif_payload()
        except Exception as _eerr:
            print(f"[Save] EXIF build failed: {_eerr}")
        # 65533 is all an APP1 segment can carry (0xFFFF minus its own
        # 2-byte length field); a longer block cannot be spliced and Pillow
        # refuses it too, so let the PIL path below raise rather than
        # truncating the metadata here.
        if payload is not None and len(payload) <= 65533:
            try:
                ok, jpg_buf = cv2.imencode(
                    ".jpg", frame_bgr,
                    [int(cv2.IMWRITE_JPEG_QUALITY), _JPG_QUALITY])
                if not ok:
                    raise RuntimeError("cv2.imencode returned failure")
                buf = jpg_buf.reshape(-1)
                if buf.size < 2 or buf[0] != 0xFF or buf[1] != 0xD8:
                    raise RuntimeError("encoded JPG has no SOI marker")
                seg = (b"\xff\xe1"
                       + (len(payload) + 2).to_bytes(2, "big") + payload)
                # SOI, then APP1, then the rest of cv2's stream — APP1
                # immediately after SOI is the order the EXIF spec
                # requires, and that spec also says a JFIF APP0 shall not
                # be present alongside it, so cv2's APP0 (always the first
                # segment it emits) is skipped: the file then carries
                # exactly one, correctly placed, APP marker like every
                # camera JPEG.  Anything unexpected at that offset is
                # written through untouched.  Written piecewise into the
                # tmp file on purpose: concatenating a ~20 MB encoded
                # buffer just to prepend a few hundred bytes would double
                # the one allocation this path exists to avoid.
                start = 2
                if buf.size >= 6 and buf[2] == 0xFF and buf[3] == 0xE0:
                    _app0_len = (int(buf[4]) << 8) | int(buf[5])
                    if 4 + _app0_len <= buf.size:
                        start = 4 + _app0_len
                with open(tmp_path, "wb") as tmp_f:
                    tmp_f.write(b"\xff\xd8")
                    tmp_f.write(seg)
                    tmp_f.write(memoryview(buf)[start:])
                os.replace(tmp_path, jpg_path)
                _verify_round_trip()
                return True
            except Exception as _sperr:
                print(f"[Save] EXIF splice failed, falling back to PIL: "
                      f"{_sperr}")
                _discard_tmp()
        try:
            if payload is None:
                payload = _build_exif_payload()
            # The old primary path, kept as the fallback: cv2.cvtColor
            # produces a contiguous RGB array; Image.fromarray on a
            # [:, :, ::-1] reverse-stride view would be non-contiguous and
            # either fail or copy internally — going through cvtColor is
            # the cheap explicit path.  Both copies are why this is no
            # longer the path a 47 MP capture normally takes.
            rgb = cv2.cvtColor(frame_bgr, cv2.COLOR_BGR2RGB)
            img = Image.fromarray(rgb)
            img.save(tmp_path, "JPEG", quality=_JPG_QUALITY, exif=payload)
            os.replace(tmp_path, jpg_path)
            _verify_round_trip()
            return True
        except Exception as exif_err:
            print(f"[Save] PIL EXIF save error, falling back to cv2: {exif_err}")
            _discard_tmp()
    try:
        # imencode + explicit write (rather than cv2.imwrite on tmp_path)
        # because imwrite picks its encoder from the file extension and a
        # ".tmp" suffix would defeat it.
        ok, jpg_buf = cv2.imencode(".jpg", frame_bgr,
                                   [int(cv2.IMWRITE_JPEG_QUALITY), _JPG_QUALITY])
        if not ok:
            return False
        with open(tmp_path, "wb") as tmp_f:
            tmp_f.write(jpg_buf.tobytes())
        os.replace(tmp_path, jpg_path)
        return True
    except Exception as _werr:
        print(f"[Save] imwrite raised for {jpg_path}: {_werr}")
        _discard_tmp()
        return False


def _run_exif_selftest():
    """Prove _save_jpg_with_exif end to end: a written JPG must carry the
    description when Pillow is available, and the no-Pillow fallback must
    still produce a readable JPG while SAYING it shed the EXIF.  Runs after
    the imports but before any camera/GUI init:
    WLV_EXIF_SELFTEST=1 python3 wlf8.py"""
    import contextlib
    import io
    import tempfile
    global _PIL_AVAILABLE
    passes, fails = 0, 0

    def _check(label, ok, detail=""):
        nonlocal passes, fails
        if ok:
            passes += 1
            print(f"  PASS  {label}")
        else:
            fails += 1
            print(f"  FAIL  {label}  {detail}")

    frame = (np.random.default_rng(0).random((64, 64, 3))
             * 255).astype(np.uint8)
    desc = "SS 1/60; ISO 400; FlashSync @ 10.0fps; complete frame (seq 7)"
    with tempfile.TemporaryDirectory() as td:
        p1 = os.path.join(td, "exif_pil.jpg")
        wrote = _save_jpg_with_exif(p1, frame, desc)
        _check("splice path: file written", wrote and os.path.exists(p1))
        if _PIL_AVAILABLE:
            with Image.open(p1) as im:
                _ex = im.getexif()
                got = _ex.get(0x010E)
                got_uc = _ex.get(0x9286)
            _check("splice path: description present on REOPEN", got == desc,
                   repr(got))
            _check("splice path: UserComment present on REOPEN",
                   got_uc == b"ASCII\x00\x00\x00" + desc.encode("ascii"),
                   repr(got_uc))
            _check("splice path: reopened file decodes",
                   cv2.imread(p1) is not None)
            # The APP1 segment must sit immediately after SOI, ahead of
            # cv2's JFIF APP0 — the EXIF-spec order.  A splice that landed
            # anywhere else would still decode as a picture, so only this
            # byte check catches it.
            with open(p1, "rb") as _f:
                _head = _f.read(6)
                _app1_len = int.from_bytes(_head[4:6], "big")
                _f.seek(4 + _app1_len)
                _next_marker = _f.read(2)
            _check("splice path: APP1 first (FF D8 FF E1)",
                   _head[:4] == b"\xff\xd8\xff\xe1", repr(_head))
            # cv2's JFIF APP0 must have been dropped: the EXIF spec forbids
            # it beside APP1, and a stray one after APP1 is also out of
            # JFIF's own required position.
            _check("splice path: no JFIF APP0 after the EXIF APP1",
                   _next_marker != b"\xff\xe0", repr(_next_marker))
        else:
            print("  SKIP  Pillow unavailable on this machine — fallback "
                  "path is the live one")
        # The fallback: force the no-Pillow branch and prove the JPG still
        # lands (EXIF-less) with the journal line saying so.
        _was = _PIL_AVAILABLE
        _PIL_AVAILABLE = False
        try:
            p2 = os.path.join(td, "exif_fallback.jpg")
            _log = io.StringIO()
            with contextlib.redirect_stdout(_log):
                wrote2 = _save_jpg_with_exif(p2, frame, desc)
            _check("fallback: file written without Pillow",
                   wrote2 and os.path.exists(p2))
            _check("fallback: file decodes", cv2.imread(p2) is not None)
            _check("fallback: journals that EXIF was shed",
                   "EXIF skipped (Pillow unavailable)" in _log.getvalue(),
                   repr(_log.getvalue()))
        finally:
            _PIL_AVAILABLE = _was
        # No description: nothing to attach, plain encode, still a file.
        p3 = os.path.join(td, "exif_plain.jpg")
        _check("empty description: file still written",
               _save_jpg_with_exif(p3, frame, "") and os.path.exists(p3))
    print(f"\nEXIF selftest: {passes} passed, {fails} failed")
    return 0 if fails == 0 else 1


if os.environ.get("WLV_EXIF_SELFTEST"):
    sys.exit(_run_exif_selftest())


# Transient save-path warning surfaced on the live preview (rendered by the
# main loop next to the other HUD toasts). Set from the background save
# workers when a capture could not be written anywhere — the one failure the
# user must know about immediately.
_save_warning_text = None
_save_warning_started = 0.0
_save_warning_until = 0.0


def _post_save_warning(msg, duration_s=4.0):
    """Show a short save-failure warning on the preview HUD.  Called from the
    background save workers; plain assignments (text first, deadline last) are
    atomic enough for a display-only toast — no lock needed."""
    global _save_warning_text, _save_warning_started, _save_warning_until
    _save_warning_text = msg
    _save_warning_started = time.monotonic()
    _save_warning_until = _save_warning_started + duration_s


# ---- Monochrome-sensor capture path ----------------------------------------
# Glue over the pure MONO RAW core at the top of the file.  The verdict is
# learned from each capture's raw statistics (dark/clipped frames abstain and
# keep the last answer) and persisted so the AWB-neutral controls apply from
# the first frame after boot.  If the body is rebuilt with a colour sensor,
# the first well-lit capture flips the verdict back automatically.
_mono_sensor_active = _bool_value(
    _PERSISTED_SETTINGS.get("mono_sensor_detected", False), False)
# Platform mono tuning file adopted for the active sensor (empty = none).
# Discovered on a mono verdict, applied via LIBCAMERA_RPI_TUNING_FILE at the
# next boot — see the camera-setup section.
_mono_tuning_file = str(_PERSISTED_SETTINGS.get("mono_tuning_file") or "")
# Last (source, detail) logged for the JPG path so the console shows every
# transition (and the first capture) without spamming one line per shot.
_mono_jpg_source_last = None


def _log_mono_jpg_source(source, detail=""):
    """One console line whenever the JPG source path (raw develop vs ISP) or
    its reason changes — makes 'which pipeline made this JPG?' answerable
    from the journal instead of pixel forensics."""
    global _mono_jpg_source_last
    key = (source, detail)
    if key != _mono_jpg_source_last:
        _mono_jpg_source_last = key
        print(f"[Mono] JPG source: {source}" + (f" ({detail})" if detail else ""))


def _mono_awb_controls():
    """Controls that stop the ISP multiplying the fake Bayer channels of a
    monochrome sensor by per-channel AWB gains (one of the two checkerboard
    sources; the demosaic itself is handled by _maybe_develop_mono_frame).
    Empty for colour sensors so AWB runs normally.  Merged into every
    pipeline configuration built after the verdict is known.

    Only controls the running tuning actually advertises are included — a
    platform mono tuning may omit the AWB algorithm (no AwbEnable) while
    still exposing ColourGains, and passing unknown controls to
    configure()/set_controls raises.  Unity ColourGains alone still zeroes
    the ISP's per-phase gain block, which field measurement showed can leak
    a checkerboard even in a mono pipeline."""
    if not _mono_sensor_active:
        return {}
    full = {"AwbEnable": False, "ColourGains": (1.0, 1.0)}
    try:
        cam = globals().get("picam2")
        if cam is not None:
            avail = cam.camera_controls or {}
            return {k: v for k, v in full.items() if k in avail}
    except Exception:
        pass
    return full


def _set_mono_sensor_active(active):
    """Flip the learned mono-sensor verdict: bake the AWB-neutral controls
    into _STILL_CONTROLS (future pipeline builds), apply them to the running
    pipeline, adopt/clear the platform mono tuning file (next boot), and
    persist."""
    global _mono_sensor_active, _mono_tuning_file
    active = bool(active)
    if active == _mono_sensor_active:
        return
    _mono_sensor_active = active
    print(f"[Mono] Sensor classified as "
          f"{'monochrome' if active else 'colour'} from raw statistics")
    # Adopt (or drop) the platform's per-sensor mono tuning.  Applied via
    # LIBCAMERA_RPI_TUNING_FILE at the next boot — no mid-session camera
    # teardown; this session is already covered by the raw-developed JPGs
    # and the AWB neutralisation below.
    try:
        if active:
            cam = globals().get("picam2")
            model = str((cam.camera_properties or {}).get("Model", "")) if cam else ""
            tuning = _find_mono_tuning_file(model)
            if tuning and tuning != _mono_tuning_file:
                _mono_tuning_file = tuning
                print(f"[Mono] Mono tuning adopted (applies on next boot): {tuning}")
        elif _mono_tuning_file:
            _mono_tuning_file = ""
            print("[Mono] Mono tuning override cleared")
    except Exception as exc:
        print(f"[Mono] tuning discovery failed: {exc}")
    try:
        # _STILL_CONTROLS seeds future config builds; the named configs are
        # the already-built dicts that the restore paths (charge-mode exit,
        # video exit, hi-res restore, update prompts) hand straight back to
        # picam2.configure() — left unpatched, their stale build-time
        # controls snapshot would resurrect AWB on the next mode transition
        # and bring the gain checkerboard back to the ISP-derived paths.
        targets = [globals().get("_STILL_CONTROLS")]
        for _cfg_name in ("still_config", "preview_config",
                          "_high_res_capture_config"):
            cfg = globals().get(_cfg_name)
            try:
                if cfg is not None and cfg.get("controls") is not None:
                    targets.append(cfg["controls"])
            except Exception:
                pass
        for controls in targets:
            if controls is None:
                continue
            if active:
                controls.update(_mono_awb_controls())
            else:
                controls.pop("AwbEnable", None)
                controls.pop("ColourGains", None)
        # Same reconfigure-race guard as _apply_shutter_controls: never
        # set_controls while another thread owns a stop/configure/start
        # cycle — the baked _STILL_CONTROLS entry applies at next configure.
        busy = globals().get("_high_res_capture_busy")
        cam = globals().get("picam2")
        if cam is not None and not (busy is not None and busy.is_set()):
            if active:
                live = _mono_awb_controls()  # {} if AWB not advertised
                if live:
                    cam.set_controls(live)
            elif "AwbEnable" in (cam.camera_controls or {}):
                cam.set_controls({"AwbEnable": True})
    except Exception as exc:
        print(f"[Mono] AWB control update failed: {exc}")
    # A flip back to colour restored plain auto above — re-assert the user's
    # white-balance selection (preset AwbMode / custom gains) on top of it.
    if not active:
        try:
            _wb_sync_configs()
        except Exception:
            pass
    # A verdict flip changes the live main-stream size policy (mono
    # fast-path): ask the main loop for the guarded rebuild — no-op when
    # nothing about the running config would change.
    try:
        _req_rebuild = globals().get("_request_still_pipeline_rebuild")
        if _req_rebuild is not None:
            _req_rebuild()
    except Exception:
        pass
    # The dropdown's Mono Raw twins exist only on a COLOUR cartridge, and
    # the list was built at boot from the persisted verdict — so the first
    # boot after a mono->colour swap would otherwise hide the feature until
    # the next reboot.  Deferred to the main loop (this runs on the save
    # worker); the sensor mode itself is unchanged, so no pipeline restart.
    try:
        _req_modes = globals().get("_request_sensor_mode_options_rebuild")
        if _req_modes is not None:
            _req_modes()
    except Exception:
        pass
    # The verdict is part of the calibration identity (colour and mono
    # variants of one sensor share a libcamera model string): re-resolve
    # the per-cartridge NoiseProfile/BaselineExposure files so a swap can
    # never keep applying the other variant's values.  Cheap (two small
    # file reads), and only runs on an actual flip.
    try:
        cam = globals().get("picam2")
        _dng_load_calibration(str(
            (cam.camera_properties or {}).get("Model", "")).strip().lower()
            if cam else "")
    except Exception as exc:
        print(f"[DNG] calibration re-resolve failed: {exc}")
    _debounced_save_settings()


def _maybe_develop_mono_frame(dng_raw, isp_frame, mono_raw=None, prepared_mono=None):
    """When the capture's raw statistics say the sensor is monochrome, develop
    the JPG source directly from the raw payload (no demosaic — the source of
    the checkerboard the ISP bakes into mono captures) and return it as a BGR
    frame shaped like `isp_frame`.  Returns None to keep the ISP frame:
    colour sensor, a driver that already reports a native mono raw format
    (libcamera does no demosaic there), an unknown format, geometry mismatch,
    or any error — a capture must never be lost to this path."""
    try:
        raw_buf, raw_meta, raw_cfg = dng_raw
        fmt = (raw_cfg or {}).get("format")
        meta = raw_meta or {}
        if prepared_mono is not None:
            u16, bits, black16 = prepared_mono
            develop_label = "Mono Raw develop (shared DNG plane)"
        else:
            info = _raw_format_info(fmt)
            if info is None:
                _log_mono_jpg_source("ISP", f"raw format not understood: {fmt!r}")
                return None
            u16, bits = _raw_unpack_to_u16(raw_buf, raw_cfg)
            if u16 is None:
                _log_mono_jpg_source("ISP", f"raw unpack failed for {fmt!r}")
                return None
            black16 = meta.get("SensorBlackLevels")
            develop_label = "raw develop"
            if info[0] and meta.get("QbcRaw") is not True:
                # Native mono raw (R16 honoured): the driver itself declares the
                # data CFA-less, so no classification is needed — the format is
                # the verdict.  The JPG is still developed from raw rather than
                # trusting the ISP frame: field measurement (IMX585 mono, PiSP
                # mono pipeline, mono tuning active) showed the ISP main stream
                # can STILL carry diagonal-paired per-phase gains (~5% of level
                # after gamma) while the raw stream from the same request is
                # phase-flat.
                _set_mono_sensor_active(True)
            else:
                verdict = (False if meta.get("QbcRaw") is True else
                           _classify_raw_mono(u16, bits, black16))
                if verdict is not None:
                    _set_mono_sensor_active(verdict)
                if not _mono_sensor_active:
                    # Mono Raw: a COLOUR sensor deliberately shooting a
                    # panchromatic monochrome negative.  Develop the JPG from
                    # the SAME converted plane the DNG carries, so the pair a
                    # user sees in the gallery and the raw they edit are the
                    # same image.  Gated by _pan_mono_eligible, identically to
                    # the DNG side.  A failed conversion keeps the ISP frame.
                    if _pan_mono_eligible(raw_cfg, mono_verdict=verdict,
                                          mono_raw=mono_raw, raw_meta=raw_meta):
                        cfa = ([0, 1, 1, 2] if meta.get("QbcRaw") is True
                               else _dng_cfa_pattern(fmt))
                        converted = _pan_mono_frame_convert(
                            u16, bits, cfa, _raw_black_native(black16, bits),
                            imx294=_qbc_sensor_status() is True,
                            quad=meta.get("QbcRaw") is True)
                        if converted is None:
                            _log_mono_jpg_source("ISP", "Mono Raw convert failed")
                            return None
                        u16 = converted
                        develop_label = "Mono Raw develop"
                    else:
                        _log_mono_jpg_source("ISP", "colour sensor")
                        return None
        gray = _develop_mono_raw(u16, bits, black16, meta.get("DigitalGain", 1.0))
        if gray is None or isp_frame is None:
            _log_mono_jpg_source("ISP", "raw develop unavailable")
            return None
        gh, gw = gray.shape[:2]
        ih, iw = isp_frame.shape[:2]
        if meta.get("QbcRaw") is True and gh == ih and gw != iw:
            # The high-resolution capture has already removed OB columns
            # from its main stream. Apply the identical crop to raw develop.
            ob = _frame_edge_ob_cols(raw_cfg, gw)
            if ob and gw - ob == iw:
                gray = gray[:, ob:]
                gh, gw = gray.shape[:2]
        if (gh, gw) != (ih, iw) and not (ih < gh and iw < gw):
            # Equal shapes are the normal case. A main frame SMALLER than the
            # develop in both dimensions is the unbinned mono fast-path (the
            # live main stream runs at preview size purely as a fallback —
            # the full-res develop is the real output, so it wins). Anything
            # else is a genuine raw/main mismatch: keep the ISP frame.
            _log_mono_jpg_source("ISP", "raw/main geometry mismatch")
            return None
        _log_mono_jpg_source(develop_label, str(fmt))
        return cv2.cvtColor(gray, cv2.COLOR_GRAY2BGR)
    except Exception as exc:
        print(f"[Mono] raw develop failed (keeping ISP frame): {exc}")
        return None


def _frame_edge_dead_rows(raw_cfg, frame_h):
    """Dead sensor rows at the BOTTOM of an ISP-derived frame, from the same
    declared/learned geometry the DNG's ActiveArea uses.

    The JPG has no ActiveArea to hide anything with — the ISP demosaics the
    whole CFE buffer, dead rows included — so the truncated read-out rows
    reach the file as a coloured line, and the save rotate puts it along
    the TOP of the finished image.  Same rows, same source of truth, but
    the raw path can describe them where the JPG has to repair them.

    Requires an exact 1:1 row mapping (frame height == raw height): the
    mono fast-path runs the main stream at preview size, and a scaled
    guess about which rows are dead would repair real picture instead.
    Returns 0 whenever anything is unknown — this must never cost a
    capture, and a missed repair is only a line at one edge."""
    try:
        cfg = raw_cfg or {}
        raw_h = int((cfg.get("size") or (0, 0))[1])
        if not raw_h or int(frame_h) != raw_h:
            return 0
        geo = _dng_fixed_geometry(cfg)
        if geo is None:
            key = "{}:{}x{}".format(_dng_camera_model(),
                                    int(cfg.get("size")[0]), raw_h)
            geo = _dng_geometry_persist.get(key)
        rows = int((geo or {}).get("trailing") or 0)
        return max(0, min(rows, _DNG_TRAILING_MAX_ROWS))
    except Exception as exc:
        print(f"[Save] edge-row lookup skipped: {exc}")
        return 0


# _repair_frame_edge_rows lives up with the pure helpers (above the DNG
# selftest gate, which exercises it); only the OB-column twin is defined
# here, next to its save-worker/capture-path consumers.
def _frame_edge_ob_cols(raw_cfg, frame_w):
    """Left optical-black columns of an ISP-derived frame, from the same
    declared/learned geometry the DNG's ActiveArea uses.

    The full-res read-outs that transmit their OB region (HOPBOUT_EN)
    hand the ISP those columns as if they were picture, so they reach the
    JPG as a black band — the sensor's LEFT edge, which the 180° save
    rotate puts down the RIGHT of the finished image (field case: a
    23-24 px band on the IMX294 47 MP JPG).  The raw path declares the
    band (ActiveArea, `ob` = 96 there: 94 flat + 2 partially masked
    columns); the JPG has to physically crop it.

    Requires an exact 1:1 column mapping (frame width == raw width) so a
    scaled frame can never lose real picture.  Returns 0 whenever
    anything is unknown — a missed crop is only a band at one edge."""
    try:
        cfg = raw_cfg or {}
        raw_w = int((cfg.get("size") or (0, 0))[0])
        if not raw_w or int(frame_w) != raw_w:
            return 0
        geo = _dng_fixed_geometry(cfg)
        if geo is None:
            key = "{}:{}x{}".format(_dng_camera_model(), raw_w,
                                    int((cfg.get("size") or (0, 0))[1]))
            geo = _dng_geometry_persist.get(key)
        cols = int((geo or {}).get("ob") or 0)
        # Same floor as the DNG side (a band below _DNG_OB_MIN_COLS is
        # "no band"), and nothing plausible approaches a quarter frame.
        if cols < _DNG_OB_MIN_COLS:
            return 0
        return min(cols, raw_w // 4)
    except Exception as exc:
        print(f"[Save] OB column lookup skipped: {exc}")
        return 0


# Rows unpacked for a classify-only pass (stride-8 sampling of a 1024-row
# band of a 47 MP frame still yields >100k macro sites — two orders past
# _MONO_RAW_MIN_SAMPLES).
_MONO_CLASSIFY_BAND_ROWS = 1024


def _mono_classify_only(dng_raw):
    """Update the learned mono verdict from a capture's raw payload WITHOUT
    touching the JPG — for save jobs whose JPG must stay the ISP frame
    (mono_develop_ok=False: the binned 47 MP path, whose output is the
    closed-loop brightness-matched frame).  Load-bearing for verdict
    self-correction: the develop gate used to skip classification too, so a
    camera with a stale persisted mono verdict that only ever shot the
    binned 47 MP mode could never flip back to colour — AWB stayed
    neutralised and every capture stayed gray.  Same never-fatal contract
    as _maybe_develop_mono_frame."""
    try:
        raw_buf, raw_meta, raw_cfg = dng_raw
        info = _raw_format_info((raw_cfg or {}).get("format"))
        if info is None:
            return
        if (raw_meta or {}).get("QbcRaw") is True:
            _set_mono_sensor_active(False)
            return
        if info[0]:
            # Native mono raw (R16 honoured): the format is the verdict.
            _set_mono_sensor_active(True)
            return
        # Statistics need a subsample, not the frame: unpack only a centre
        # band (top edge on a 4-row boundary so the mod-4 phase lattice
        # stays CFA-aligned) — a few MB of copy instead of ~80 MB at 47 MP,
        # which mattered on 2 GB boards where this pass runs while the same
        # worker's DNG/JPG stages hold their own full-frame transients.
        row_band = None
        try:
            h = int((raw_cfg or {}).get("size")[1])
            if h > _MONO_CLASSIFY_BAND_ROWS:
                r0 = ((h - _MONO_CLASSIFY_BAND_ROWS) // 2) & ~3
                row_band = (r0, _MONO_CLASSIFY_BAND_ROWS)
        except Exception:
            row_band = None
        u16, bits = _raw_unpack_to_u16(raw_buf, raw_cfg, row_band=row_band)
        if u16 is None:
            return
        verdict = _classify_raw_mono(
            u16, bits, (raw_meta or {}).get("SensorBlackLevels"))
        if verdict is not None:
            _set_mono_sensor_active(verdict)
    except Exception as exc:
        print(f"[Mono] classify-only pass failed: {exc}")


def _capture_save_worker():
    global image_count
    while True:
        job = _capture_save_queue.get()
        if job is None:
            _capture_save_queue.task_done()
            break
        dequeued_at = time.monotonic()
        (
            full_frame,
            target_dims,
            target_ratio,
            film_key,
            jpg_path,
            overlay_frame,
            dng_path,
            dng_raw,
            exif_desc,
            mono_develop_ok,
        ) = job[:10]
        # Optional 11th element: the Mono Raw mode decision AS OF THE
        # SHUTTER PRESS.  The save queue is asynchronous, so resolving the
        # live dropdown here would let a mode change between shutter and
        # worker pickup convert the wrong capture — irreversibly, since the
        # colour information is gone once written.  None means "resolve
        # live" for any producer that predates this field.
        pan_mono_job = job[10] if len(job) > 10 else None
        if dng_raw is not None and (dng_raw[1] or {}).get("QbcRaw") is True:
            pan_mono_job = True
            mono_develop_ok = True
        # Optional 12th element: producer-side queue timestamp.  The wait
        # between shutter and worker pickup is the number that tunes queue
        # depth / worker throughput on real hardware, so it goes to the
        # journal alongside the [DNG] encode/write timings.
        queued_at = job[11] if len(job) > 11 else None
        if queued_at is not None:
            print(f"[Save] {os.path.basename(jpg_path or dng_path or '?')}: "
                  f"dequeued after {dequeued_at - queued_at:.2f}s "
                  f"(depth {_capture_save_queue.qsize()}, "
                  f"in-flight {_captures_in_flight})")
        # Snapshot the job's pinned-byte size NOW (before the mono develop
        # below can rebind full_frame) so resolve releases exactly what
        # queue-time accounted.
        job_bytes = _capture_job_bytes(full_frame, dng_raw, overlay_frame)
        # Drop the tuple's own references so the staged releases below
        # (dng_raw after its last consumer, full_frame after the rotate)
        # actually free their buffers — with the tuple alive they'd stay
        # pinned to the end of the job regardless.
        deferred_snapshot = job[12] if len(job)>12 else None
        job = None
        # NO CPU BOOST HERE — see _capture_cpu_performance's definition.  The
        # LJ92 encode below is genuinely CPU-bound and the boost did speed it
        # up, but it is also the longest-held half of the burst: a shot taken
        # while the previous save is still encoding kept the refcount above
        # zero, so the camera ran at the boosted clock CONTINUOUSLY instead of
        # in bursts.  That is what the thermal cap exists to prevent.
        try:
            if deferred_snapshot is not None:
                try:
                    _deferred_stage(dng_raw, full_frame, deferred_snapshot)
                    with _image_count_lock:
                        image_count += 1
                except Exception as stage_error:
                    print('[Deferred] staging failed; attempting DNG recovery:', stage_error)
                    _wlv_save_dng(dng_raw[0],dng_raw[1],dng_raw[2],dng_path,
                                  description=exif_desc,mono_raw=pan_mono_job)
                    _post_save_warning('Queue save failed — DNG saved instead')
                continue
            # DNG handling (off the main/preview thread): if dng_raw is present
            # the encode+write was deferred here — the instant path always,
            # and the binned 47 MP path since its capture_file was moved out
            # of the frozen-screen window (mono_develop_ok=False there keeps
            # its JPG on the brightness-matched ISP frame). Then rotate the
            # orientation tag and queue the USB sync, as before.
            # Tracks whether a DNG actually landed on disk (primary path or
            # recovery) — the RAW-only branch below must report honestly.
            dng_write_ok = False
            # Mono classification the DNG write already ran on this very
            # payload (None = no DNG write / abstained / writer fell back).
            dng_mono_verdict = None
            # The normal quad-mono pair needs one reconstruction, not one
            # each for RAW and JPG. This handoff lives only for this save job.
            mono_result = ({} if dng_raw is not None and overlay_frame is None
                           and (dng_raw[1] or {}).get("QbcRaw") is True
                           and not (dng_raw[1] or {}).get("WlvMonoDeveloped") else None)
            if dng_path:
                try:
                    if dng_raw is not None:
                        raw_buf, raw_meta, raw_cfg = dng_raw
                        dng_mono_verdict = _wlv_save_dng(
                            raw_buf, raw_meta, raw_cfg, dng_path,
                            description=exif_desc,
                            mono_raw=pan_mono_job, mono_result=mono_result)
                    # HQ sensor (IMX477) is mounted 180° from the other sensors,
                    # so its raw is already in the upright orientation — skip the
                    # baseline 180° orientation-tag flip the other sensors need.
                    if not _HQ_SENSOR_ACTIVE:
                        _rotate_dng_180(dng_path)
                    _queue_usb_sync(dng_path)
                    dng_write_ok = True
                except Exception as dng_err:
                    # Retry the raw into the on-board Pictures dir (USB
                    # yanked / target full) before giving up — mirrors the
                    # JPG fallback below. Only possible when the encode was
                    # deferred here (dng_raw present); high-res paths already
                    # wrote their file so there is nothing to re-save.
                    dng_recovered = False
                    try:
                        if (dng_raw is not None
                                and os.path.dirname(dng_path) != LOCAL_PICTURES_DIR):
                            _ensure_dir(LOCAL_PICTURES_DIR)
                            dng_fb = os.path.join(
                                LOCAL_PICTURES_DIR, os.path.basename(dng_path))
                            raw_buf, raw_meta, raw_cfg = dng_raw
                            _wlv_save_dng(raw_buf, raw_meta, raw_cfg, dng_fb,
                                          description=exif_desc,
                                          mono_raw=pan_mono_job, mono_result=mono_result)
                            if not _HQ_SENSOR_ACTIVE:
                                _rotate_dng_180(dng_fb)
                            _queue_usb_sync(dng_fb)
                            dng_recovered = True
                            print(f"[Save] Recovered DNG to {dng_fb}")
                    except Exception:
                        pass
                    dng_write_ok = dng_recovered
                    if not dng_recovered:
                        # Surface the lost RAW on the HUD — a print-only
                        # failure let missing DNGs go unnoticed in the field
                        # until the user browsed the gallery. (For a RAW-only
                        # job the branch below owns the messaging — both
                        # outputs are gone there, not just the RAW.)
                        print(f"[Save] DNG write/rotate error: {dng_err}")
                        traceback.print_exc()
                        if full_frame is not None:
                            _post_save_warning("RAW save failed — JPG kept")
            # RAW-only job: the 47 MP main-frame extraction failed after a
            # good raw grab. Skip the JPG stage entirely (the `continue`
            # still runs the finally below, so the in-flight slot is
            # released) and report what actually happened: "RAW saved" only
            # if the DNG write above truly landed — if it failed too, the
            # capture is lost and must be reported as lost.
            if full_frame is None:
                if dng_write_ok:
                    print(f"[Save] RAW-only job for "
                          f"{os.path.basename(jpg_path or '?')} — "
                          f"main frame unavailable, JPG skipped")
                    _post_save_warning("JPG failed — RAW saved")
                else:
                    print(f"[Save] ERROR: capture LOST (no JPG frame and the "
                          f"RAW write failed) for "
                          f"{os.path.basename(jpg_path or '?')}")
                    _post_save_warning("Capture lost — check storage")
                continue
            # Monochrome sensors: build the JPG from the same raw payload the
            # DNG uses so no demosaic checkerboard reaches the file (see
            # _maybe_develop_mono_frame).  Double exposure keeps the ISP
            # frame — the first shot exists only as an ISP frame, and both
            # blended shots must share one processing path.  The binned 47 MP
            # path passes mono_develop_ok=False: its raw payload is here only
            # for the deferred DNG write, while its JPG must stay the
            # closed-loop brightness-matched ISP frame (see
            # _hires_exposure_match_lut) — developing from raw would silently
            # replace that calibrated output.
            if dng_raw is not None and not mono_develop_ok:
                # The JPG must stay the ISP frame, but the mono verdict still
                # learns from the raw payload — without this, a stale mono
                # verdict never self-corrects on the binned 47 MP path.
                # The DNG write above already classified this very payload;
                # reuse its answer instead of unpacking the same centre band
                # a second time, and only classify from scratch when there
                # was no answer (no DNG write, abstained, writer fallback).
                if dng_mono_verdict is not None:
                    _set_mono_sensor_active(dng_mono_verdict)
                else:
                    _mono_classify_only(dng_raw)
            # Whether the JPG actually became the converted mono plane.  A
            # Mono Raw capture guarantees a MONOCHROME pair, so any path
            # that could not run the develop is desaturated below instead.
            mono_jpg_done = bool(dng_raw is not None and
                                 (dng_raw[1] or {}).get("WlvMonoDeveloped") is True)
            if (dng_raw is not None and overlay_frame is None and mono_develop_ok
                    and not mono_jpg_done):
                mono_frame = _maybe_develop_mono_frame(
                    dng_raw, full_frame, mono_raw=pan_mono_job,
                    prepared_mono=(mono_result or {}).get("plane"))
                if mono_result is not None:
                    mono_result.clear()
                if mono_frame is not None:
                    full_frame = mono_frame
                    mono_jpg_done = True
                    if _is_lut_key(film_key):
                        # User LUTs are baked against the tuning's display
                        # encode (what the preview and every ISP-derived save
                        # carry); the raw develop above is sRGB-encoded.
                        # Re-encode so the LUT sees the same input on every
                        # path — plain mono JPGs and built-in films untouched.
                        try:
                            _tx = _lut_mono_save_transcode()
                            if _tx is not None:
                                full_frame = cv2.LUT(full_frame, _tx)
                        except Exception as _tx_err:
                            print(f"[Mono] LUT transcode skipped: {_tx_err}")
            if (dng_raw is not None and (dng_raw[1] or {}).get("QbcRaw") is True
                    and not mono_jpg_done):
                # PiSP cannot interpret the preserved quad layout. Never save
                # that processed stream as a misleading monochrome JPG.
                raise RuntimeError("Quad raw saved; monochrome JPG development failed")
            # Mono Raw fallback for every path the develop above cannot
            # serve: double exposure (the blend is two ISP frames), Flash
            # Sync and the 47 MP paths (mono_develop_ok=False), or a develop
            # that declined.  The DNG for those is still written monochrome,
            # so without this the capture would pair a mono raw with a
            # COLOUR JPG.  Desaturating is luma-weighted rather than
            # panchromatic — the honest best available once the frame is no
            # longer a CFA payload — and it is applied to `full_frame`
            # BEFORE the aspect crop and the double-exposure blend below, so
            # every downstream stage (including the overlay) stays in the
            # same colour space.  One general rule beats a per-mode branch:
            # a new capture path cannot silently reintroduce the mismatch.
            if pan_mono_job and not mono_jpg_done and full_frame is not None:
                try:
                    full_frame = cv2.cvtColor(
                        cv2.cvtColor(full_frame, cv2.COLOR_BGR2GRAY),
                        cv2.COLOR_GRAY2BGR)
                    if overlay_frame is not None:
                        overlay_frame = cv2.cvtColor(
                            cv2.cvtColor(overlay_frame, cv2.COLOR_BGR2GRAY),
                            cv2.COLOR_GRAY2BGR)
                except Exception as _pm_exc:
                    print(f"[Mono] Mono Raw JPG desaturate skipped: {_pm_exc}")
            # The ISP frame carries the sensor's dead trailing rows (the
            # DNG hides the same rows behind ActiveArea; a JPG has no such
            # tag), and the save rotate below puts them along the top of
            # the finished image.  Repair before any crop, while the frame
            # is still row-aligned with the raw payload that names them.
            _edge_rows = _frame_edge_dead_rows(
                (dng_raw or (None, None, None))[2],
                full_frame.shape[0] if full_frame is not None else 0)
            if _edge_rows:
                full_frame = _repair_frame_edge_rows(full_frame, _edge_rows)
                overlay_frame = _repair_frame_edge_rows(
                    overlay_frame, _edge_rows)
            # OB column band — catch-up crop for the FIRST capture on an
            # uncharacterised sensor: the capture-time crop in
            # _perform_high_res_capture can only remove a band that was
            # already declared or learned, but the DNG write above has just
            # measured and persisted THIS frame's geometry, so by the JPG
            # stage the band is known even on the very first shot.  The
            # exact 1:1 width check makes this and the capture-time crop
            # mutually exclusive (a frame cropped there no longer matches
            # the raw width), and a double exposure's overlay is cut
            # identically so the blend stays aligned.  Detection abstains
            # (dark frame, writer fallback) -> no crop, matching the DNG's
            # own honesty; Brenizer tiles never pass through here, so an
            # uncharacterised sensor's first session keeps the band on
            # tiles until the learned geometry reaches the capture-time
            # crop.
            _edge_cols = _frame_edge_ob_cols(
                (dng_raw or (None, None, None))[2],
                full_frame.shape[1] if full_frame is not None else 0)
            if _edge_cols and full_frame is not None:
                _pre_w = full_frame.shape[1]
                full_frame = full_frame[:, _edge_cols:]
                if (overlay_frame is not None
                        and overlay_frame.shape[1] == _pre_w):
                    overlay_frame = overlay_frame[:, _edge_cols:]
                print(f"[Save] optical-black catch-up crop: {_edge_cols} "
                      f"column(s) -> {full_frame.shape[1]}x"
                      f"{full_frame.shape[0]}")
            # The raw payload's last consumers are above (DNG write, mono
            # develop/classify) — release it before the JPG stage so its
            # ~80 MB (47 MP) doesn't sit under the crop/film/rotate/encode
            # transients: that overlap is real OOM-killer pressure on a
            # 2 GB board.  raw_buf/raw_meta are this function's own locals
            # from the DNG write and would otherwise pin the buffer past
            # this point (and across iterations, until the next DNG job
            # rebinds them).
            dng_raw = raw_buf = raw_meta = None
            frame_to_save = _prepare_output_frame(full_frame, target_dims, target_ratio)
            if overlay_frame is not None:
                overlay_to_use = _prepare_output_frame(overlay_frame, target_dims, target_ratio)
                if overlay_to_use is not None and frame_to_save is not None:
                    if overlay_to_use.shape[:2] != frame_to_save.shape[:2]:
                        overlay_to_use = cv2.resize(
                            overlay_to_use,
                            (frame_to_save.shape[1], frame_to_save.shape[0]),
                            interpolation=cv2.INTER_AREA,
                        )
                    # Blend directly in uint8 (addWeighted rounds + saturates
                    # correctly) and write back into frame_to_save's own buffer.
                    # The old float32 round-trip allocated ~3x the frame as
                    # transient float arrays — at unbinned 47 MP (~0.5 GB of
                    # resident live camera buffers) that ~1.7 GB spike starved
                    # the pipeline of a 47 MP DMA buffer and froze the preview.
                    cv2.addWeighted(
                        frame_to_save, 0.5,
                        overlay_to_use, 0.5,
                        0.0, dst=frame_to_save,
                    )
            if film_key and film_key != "none":
                # Save path (background worker): block so a just-selected LUT is
                # guaranteed baked and present in the written JPG.
                frame_to_save = apply_film_simulation_rgb(frame_to_save, film_key, block=True)
            # HQ sensor (IMX477) is mounted 180° from the other sensors; its
            # frame is already upright, so skip the baseline 180° save rotate
            # (the other sensors need it to match the panel-flipped preview).
            if not _HQ_SENSOR_ACTIVE:
                frame_to_save = cv2.rotate(frame_to_save, cv2.ROTATE_180)
            # frame_to_save owns its buffer now (rotate and/or film sim
            # allocated fresh); release the job's source frames so the
            # encode's buffer isn't stacked on top of them — at 47 MP
            # that's ~122 MB back before the encode runs.  (On the
            # HQ no-rotate/no-film path frame_to_save can still be a view
            # of full_frame; dropping the reference is then merely a no-op.)
            full_frame = overlay_frame = mono_frame = None
            saved_path = None
            if _save_jpg_with_exif(jpg_path, frame_to_save, exif_desc):
                saved_path = jpg_path
            if saved_path is None:
                # The writer reports failure (missing dir, USB yanked
                # mid-session, disk full) WITHOUT raising — never silently
                # drop a capture.  Fall back to the on-board Pictures dir so
                # the frame is not lost, and surface a warning.
                print(f"[Save] WARNING: write failed for {jpg_path}; attempting fallback")
                try:
                    if os.path.dirname(jpg_path) != LOCAL_PICTURES_DIR:
                        _ensure_dir(LOCAL_PICTURES_DIR)
                        fb = os.path.join(LOCAL_PICTURES_DIR, os.path.basename(jpg_path))
                        if _save_jpg_with_exif(fb, frame_to_save, exif_desc):
                            saved_path = fb
                            print(f"[Save] Recovered capture to {fb}")
                except Exception as _ferr:
                    print(f"[Save] Fallback write failed: {_ferr}")
            if saved_path is not None:
                _queue_usb_sync(saved_path)
                with _image_count_lock:
                    image_count += 1
            else:
                print(f"[Save] ERROR: capture LOST (no writable location) for "
                      f"{os.path.basename(jpg_path)}")
                _post_save_warning("Save failed — check storage")
        except Exception as e:
            print("Save error:", e)
            _post_save_warning("Save error — check storage")
        finally:
            # Drop every large buffer local BEFORE releasing the accounting:
            # after _mark_capture_resolved() the admission gate believes this
            # job's bytes are free, so anything still referenced here would
            # sit under the NEXT admitted 47 MP job while the worker blocks
            # in queue.get() — frame_to_save (~143 MB rotated BGR) after
            # every save, and dng_raw/raw_buf (~95 MB) on the RAW-only
            # `continue` path, which skips the staged release above.  Plain
            # rebinds: locals may not exist on early error paths, so bind
            # them defensively via locals-safe assignment.
            full_frame = overlay_frame = dng_raw = None
            raw_buf = raw_meta = raw_cfg = mono_result = None
            frame_to_save = overlay_to_use = mono_frame = None
            # Release the optimistic in-flight slot (and its bytes) whether
            # the save succeeded or not — a failure must never leak either.
            _mark_capture_resolved(job_bytes)
            _record_activity(wake=True)
            _capture_save_queue.task_done()


focus_peaking_enabled = _bool_value(_PERSISTED_SETTINGS.get("focus_peaking_enabled", True), True)
focus_box_enabled = _bool_value(_PERSISTED_SETTINGS.get("focus_box_enabled", False), False)
# Focus Point: peaking confined to a movable box. A preview tap relocates the
# box (no zoom in this mode); a 2 s shutter hold zooms 2x into the boxed region.
focus_point_enabled = False  # derived from focus_mode_idx below
