def _pct_to_level(pct):
    return max(0, min(_BACKLIGHT_MAX, int(round(_BACKLIGHT_MAX * (pct / 100.0)))))

_USER_BRIGHTNESS_MIN_PCT = 10
_USER_BRIGHTNESS_MAX_PCT = 100
_USER_BRIGHTNESS_STEP_PCT = 10
_user_brightness_pct = _bounded_int(
    _PERSISTED_SETTINGS.get("user_brightness_pct", 50), 50,
    _USER_BRIGHTNESS_MIN_PCT, _USER_BRIGHTNESS_MAX_PCT,
)
_user_brightness_pct = max(
    _USER_BRIGHTNESS_MIN_PCT,
    min(_USER_BRIGHTNESS_MAX_PCT,
        int(round(_user_brightness_pct / _USER_BRIGHTNESS_STEP_PCT) * _USER_BRIGHTNESS_STEP_PCT)),
)
_BACKLIGHT_NORMAL_LEVEL = _pct_to_level(_user_brightness_pct)
_BACKLIGHT_DIM_LEVEL = _pct_to_level(10)
