# --- Power-saving timeouts (configured from the charge-menu sleep submenu) ---
# One shared Off/1/2/5/10/15-minute scale for the two idle power steps: the
# "low power" step (backlight dim + 10 fps preview, see _update_backlight) and
# the deeper auto-sleep step (camera/ISP stopped, radio off, CPU powersave —
# see the main-loop auto-sleep check). seconds == 0 means Off (never).
_POWER_TIMEOUT_OPTIONS = [
    {"key": "off", "label": "Off", "seconds": 0},
    {"key": "1m", "label": "1 min", "seconds": 60},
    {"key": "2m", "label": "2 min", "seconds": 120},
    {"key": "5m", "label": "5 min", "seconds": 300},
    {"key": "10m", "label": "10 min", "seconds": 600},
    {"key": "15m", "label": "15 min", "seconds": 900},
]
# Defaults preserve the firmware's historical behaviour: dim at 2 min,
# auto-sleep at 10 min.
_low_power_timeout_idx = _bounded_int(
    _PERSISTED_SETTINGS.get("low_power_timeout_idx", 2), 2, 0,
    len(_POWER_TIMEOUT_OPTIONS) - 1,
)
_sleep_timeout_idx = _bounded_int(
    _PERSISTED_SETTINGS.get("sleep_timeout_idx", 4), 4, 0,
    len(_POWER_TIMEOUT_OPTIONS) - 1,
)
