def _le_look_idx_from_key(key, default=0):
    for i, opt in enumerate(LONG_EXPOSURE_LOOKS):
        if opt["key"] == key:
            return i
    return default


# Default look = Trails (greenlit in architecture summary); default duration
# = 8 s timed (= LONG_EXPOSURE_DURATIONS_S index 1).  Persisted values
# override the defaults on next boot via _PERSISTED_SETTINGS.
_le_look_idx = _le_look_idx_from_key(
    _PERSISTED_SETTINGS.get("long_exposure_look_key"), default=0,
)
