# --- Custom film profiles (user-defined via the web UI) ---
# Snapshot of the built-in list so _rebuild_film_options() can reproduce it
# even after customs have been appended.
_BUILTIN_FILM_OPTIONS = list(FILM_OPTIONS)
_BUILTIN_FILM_KEYS = {opt["key"] for opt in FILM_OPTIONS}
_CUSTOM_FILM_PROFILES = {}      # profile id (str) -> profile dict
_custom_film_lock = threading.Lock()
# LUT cache for custom profiles, keyed by profile id. Dropped on edit/delete.
_custom_film_lut_cache = {}
_CUSTOM_FILM_MAX = 64           # upper bound on user-created profiles
_CUSTOM_FILM_NAME_MAX = 40      # characters

def _new_profile_id():
    return "custom_" + os.urandom(5).hex()

def _curve_points_from_tones(shadows, midtones, highlights):
    """Map -100..100 shadow/midtone/highlight sliders to a 5-point tone curve."""
    scale = 0.4  # max ±40 / 255 swing at each anchor
    def anchor(base, val):
        return int(max(0, min(255, base + val * scale)))
    return [
        (0, 0),
        (64, anchor(64, shadows)),
        (128, anchor(128, midtones)),
        (192, anchor(192, highlights)),
        (255, 255),
    ]

def _parse_hex_color(s):
    if not (isinstance(s, str) and len(s) == 7 and s[0] == "#"):
        return None
    try:
        return int(s[1:3], 16), int(s[3:5], 16), int(s[5:7], 16)
    except ValueError:
        return None

def _coerce_film_profile(payload, profile_id=None):
    """Validate+normalise a user-supplied custom film profile.

    Returns (profile_dict, None) on success or (None, reason) on failure.
    """
    if not isinstance(payload, dict):
        return None, "Invalid profile payload"
    name = payload.get("name")
    name = name.strip() if isinstance(name, str) else ""
    if not name:
        return None, "Profile name is required"
    if len(name) > _CUSTOM_FILM_NAME_MAX:
        return None, f"Profile name too long (max {_CUSTOM_FILM_NAME_MAX} chars)"
    def _clamped_int(key, lo, hi, default=0):
        try:
            return max(lo, min(hi, int(payload.get(key, default))))
        except (TypeError, ValueError):
            raise ValueError(f"Invalid {key}")
    def _clamped_float(key, lo, hi, default=0.0):
        try:
            return max(lo, min(hi, float(payload.get(key, default))))
        except (TypeError, ValueError):
            raise ValueError(f"Invalid {key}")
    try:
        shadows = _clamped_int("shadows", -100, 100)
        midtones = _clamped_int("midtones", -100, 100)
        highlights = _clamped_int("highlights", -100, 100)
        grain = _clamped_float("grain", 0.0, 40.0)
        clarity = _clamped_float("clarity", 0.0, 1.0)
        tint_strength = _clamped_float("tint_strength", 0.0, 1.0, default=1.0)
    except ValueError as exc:
        return None, str(exc)
    tint = payload.get("tint") or "#ffffff"
    tint_rgb = _parse_hex_color(tint)
    if tint_rgb is None:
        return None, "Invalid tint color (expected #rrggbb)"
    return {
        "id": profile_id or payload.get("id") or "",
        "name": name,
        "shadows": shadows,
        "midtones": midtones,
        "highlights": highlights,
        "grain": grain,
        "clarity": clarity,
        "tint": tint.lower(),
        # Stored in (B, G, R) order to match the BGR frame pipeline that
        # _apply_monochrome_tint feeds (tint[0]->ch0 of a BGR frame).  See the
        # redscale built-in's note; _parse_hex_color returns (R, G, B), so swap.
        "tint_rgb": (tint_rgb[2], tint_rgb[1], tint_rgb[0]),
        "tint_strength": tint_strength,
    }, None

def _custom_profile_payload(profile):
    """Shape a stored profile into the JSON-friendly form exposed to clients."""
    return {
        "id": profile["id"],
        "name": profile["name"],
        "shadows": profile["shadows"],
        "midtones": profile["midtones"],
        "highlights": profile["highlights"],
        "grain": profile["grain"],
        "clarity": profile["clarity"],
        "tint": profile["tint"],
        "tint_strength": profile["tint_strength"],
    }

def _list_custom_profile_payloads():
    with _custom_film_lock:
        profiles = list(_CUSTOM_FILM_PROFILES.values())
    return sorted(
        (_custom_profile_payload(p) for p in profiles),
        key=lambda p: p["name"].lower(),
    )

def _get_film_preset(key):
    """Return a preset dict (points/grain/clarity/tint) for built-in or custom key."""
    if key in _FILM_CURVE_DATA:
        return _FILM_CURVE_DATA[key]
    with _custom_film_lock:
        custom = _CUSTOM_FILM_PROFILES.get(key)
    if custom is None:
        return _FILM_CURVE_DATA["none"]
    return {
        "points": _curve_points_from_tones(
            custom["shadows"], custom["midtones"], custom["highlights"]
        ),
        "grain": custom["grain"],
        "clarity": custom["clarity"],
        "tint_rgb": custom["tint_rgb"],
        "tint_strength": custom["tint_strength"],
    }

def _rebuild_film_options(preserve_key=None):
    """Rebuild FILM_OPTIONS from built-ins + current custom set.

    Both ``FILM_OPTIONS`` and ``_film_idx`` are updated atomically under
    ``_film_button_lock`` so the live preview loop never sees an index that
    doesn't match the list. If ``preserve_key`` matches a current option,
    ``_film_idx`` is moved to it; otherwise it resets to 0.
    Returns the new ``_film_idx``.
    """
    global _film_idx
    with _custom_film_lock:
        customs = sorted(
            _CUSTOM_FILM_PROFILES.values(), key=lambda p: p["name"].lower()
        )
    combined = list(_BUILTIN_FILM_OPTIONS)
    for p in customs:
        combined.append({
            "label": p["name"],
            "short": p["name"][:8] if p["name"] else "Custom",
            "key": p["id"],
            "custom": True,
        })
    # User-supplied .cube LUTs discovered on the USB/SD lut folder.
    with _lut_registry_lock:
        lut_items = sorted(_LUT_PROFILES.items(), key=lambda kv: kv[1]["name"].lower())
    for k, info in lut_items:
        nm = info.get("name") or "LUT"
        combined.append({
            "label": nm,
            "short": nm[:8] if nm else "LUT",
            "key": k,
            "lut": True,
        })
    with _film_button_lock:
        FILM_OPTIONS[:] = combined
        new_idx = 0
        if preserve_key is not None:
            for i, opt in enumerate(FILM_OPTIONS):
                if opt["key"] == preserve_key:
                    new_idx = i
                    break
        _film_idx = new_idx
    return new_idx

def _load_custom_film_profiles_from_settings():
    raw = _PERSISTED_SETTINGS.get("custom_film_profiles", [])
    if not isinstance(raw, list):
        return
    for entry in raw:
        if not isinstance(entry, dict):
            continue
        pid = entry.get("id")
        if not (isinstance(pid, str) and pid.startswith("custom_")):
            continue
        profile, reason = _coerce_film_profile(entry, profile_id=pid)
        if profile is None:
            print(f"[Settings] Skipping invalid custom film profile: {reason}")
            continue
        _CUSTOM_FILM_PROFILES[pid] = profile

_load_custom_film_profiles_from_settings()
