def _set_film_profile_by_key(key):
    """Select a film profile by key string (works for built-ins and customs)."""
    global _film_idx
    for i, opt in enumerate(FILM_OPTIONS):
        if opt["key"] == key:
            _set_film_profile(i)
            return True
    return False

def _create_custom_profile(payload):
    profile, reason = _coerce_film_profile(payload)
    if profile is None:
        return None, reason
    with _custom_film_lock:
        if len(_CUSTOM_FILM_PROFILES) >= _CUSTOM_FILM_MAX:
            return None, f"Too many profiles (max {_CUSTOM_FILM_MAX})"
        pid = _new_profile_id()
        while pid in _CUSTOM_FILM_PROFILES:
            pid = _new_profile_id()
        profile["id"] = pid
        _CUSTOM_FILM_PROFILES[pid] = profile
    _rebuild_film_options(preserve_key=_current_film_key())
    _debounced_save_settings()
    return _custom_profile_payload(profile), None

def _update_custom_profile(pid, payload):
    if not (isinstance(pid, str) and pid.startswith("custom_")):
        return None, "Unknown profile"
    profile, reason = _coerce_film_profile(payload, profile_id=pid)
    if profile is None:
        return None, reason
    with _custom_film_lock:
        if pid not in _CUSTOM_FILM_PROFILES:
            return None, "Profile not found"
        _CUSTOM_FILM_PROFILES[pid] = profile
    _custom_film_lut_cache.pop(pid, None)
    _rebuild_film_options(preserve_key=_current_film_key())
    _debounced_save_settings()
    return _custom_profile_payload(profile), None

def _delete_custom_profile(pid):
    if not (isinstance(pid, str) and pid.startswith("custom_")):
        return False, "Unknown profile"
    with _custom_film_lock:
        if pid not in _CUSTOM_FILM_PROFILES:
            return False, "Profile not found"
        del _CUSTOM_FILM_PROFILES[pid]
    _custom_film_lut_cache.pop(pid, None)
    current_key = _current_film_key()
    # If the deleted profile was selected, fall back to "none".
    preserve = None if current_key == pid else current_key
    _rebuild_film_options(preserve_key=preserve)
    _debounced_save_settings()
    return True, "ok"


