def _apply_zoom(frame, zoom_factor, center_norm):
    # The geometry lives in _zoom_crop_origin (top of file) because the Face
    # Detect overlay has to walk this same crop forward to draw its bracket
    # in display space.  Two copies of it would drift the box off the face
    # the first time either changed, so there is one.
    if zoom_factor <= 1.0:
        return frame
    h, w = frame.shape[:2]
    x1, y1, crop_w, crop_h = _zoom_crop_origin(w, h, zoom_factor, center_norm)
    return frame[y1:y1 + crop_h, x1:x1 + crop_w]


def _get_double_preview_overlay(target_w, target_h, aspect_ratio, film_key, zoom_factor, zoom_center):
    global _double_preview_cache
    with _double_exposure_lock:
        if not double_exposure_enabled:
            return None
        first_frame = double_exposure_first_frame
        cache_key = (target_w, target_h, aspect_ratio, film_key, zoom_factor, zoom_center)
        cached = _double_preview_cache.get("image") if _double_preview_cache.get("key") == cache_key else None
    if first_frame is None:
        return None
    if cached is not None:
        return cached

    overlay = first_frame
    if overlay.ndim == 3 and overlay.shape[2] == 4:
        # 4-channel main streams are BGR-ordered like everything else in the
        # pipeline (see _prepare_output_frame's note), so drop alpha as
        # BGRA2BGR — BGRA2RGB would swap red/blue in the ghost overlay.
        overlay = cv2.cvtColor(overlay, cv2.COLOR_BGRA2BGR)

    if zoom_factor > 1.0 and zoom_center is not None:
        overlay = _apply_zoom(overlay, zoom_factor, zoom_center)

    if aspect_ratio > 0:
        crop_w, crop_h = _largest_ratio_crop_dims(overlay.shape[1], overlay.shape[0], aspect_ratio)
        overlay = _center_crop(overlay, crop_w, crop_h)

    if target_w > 0 and target_h > 0:
        overlay = cv2.resize(overlay, (target_w, target_h), interpolation=cv2.INTER_AREA)

    if film_key and film_key != "none":
        overlay = apply_film_simulation_rgb(overlay, film_key)

    with _double_exposure_lock:
        _double_preview_cache = {"key": cache_key, "image": overlay}
    return overlay

def _dismiss_all_popups(except_lock=None):
    """Close all popup menus. Optionally skip one lock (the popup being opened)."""
    _popup_locks = [
        (_focus_button_lock, "_focus_popup_visible", "_focus_popup_rects", "_focus_popup_bounds"),
        (_film_button_lock, "_film_popup_visible", "_film_popup_rects", "_film_popup_bounds"),
        (_aspect_button_lock, "_aspect_popup_visible", "_aspect_popup_rects", "_aspect_popup_bounds"),
        (_iso_button_lock, "_iso_popup_visible", "_iso_popup_rects", "_iso_popup_bounds"),
        (_shutter_button_lock, "_shutter_popup_visible", "_shutter_popup_rects", "_shutter_popup_bounds"),
        (_brenizer_lock, "_multishot_popup_visible", "_multishot_popup_rects", "_multishot_popup_bounds"),
    ]
    for lock, vis_name, rects_name, bounds_name in _popup_locks:
        if lock is except_lock:
            continue
        with lock:
            globals()[vis_name] = False
            globals()[rects_name] = []
            globals()[bounds_name] = None


def _viewfinder_slider_apply_at(x, y):
    """If (x, y) lies inside one of the active slider's hit zones, apply the
    corresponding option to the camera. Returns True when a value was applied.

    Used by both the tap path (LBUTTONUP) and the live-drag path
    (LBUTTONDOWN + MOUSEMOVE) so the camera preview reflects the change as
    the user's finger glides through the ticks.
    """
    with _viewfinder_lock:
        active_setting = _viewfinder_active_setting
        slider_rects = list(_viewfinder_slider_rects)
    if not active_setting or not slider_rects:
        return False
    for opt_idx, rect in slider_rects:
        if _point_in_rect(x, y, rect):
            # Skip no-op writes so we don't spam settings/save during a drag.
            # Read current idx under its setting's lock for consistency with
            # the main-UI setters.
            current = _viewfinder_setting_active_idx(active_setting)
            if opt_idx != current:
                _viewfinder_setting_apply(active_setting, opt_idx)
            return True
    return False


def _perform_tap_to_zoom(x, y, button_activity_saved_ts):
    """Tap-to-zoom logic shared between the main-UI fall-through path and
    the Viewfinder UI path. Caller is responsible for any UI-button barrier
    checks; this helper only validates that (x, y) lies inside the preview
    geometry before toggling zoom state.
    """
    global zoom_active, zoom_center_norm, _zoom_level_idx, _last_button_activity_time
    global _focus_point_norm, _focus_point_last_mask
    global _spot_meter_luma_ema, _spot_meter_next_update
    px, py, pw, ph = _preview_geom["x"], _preview_geom["y"], _preview_geom["w"], _preview_geom["h"]
    if pw <= 0 or ph <= 0:
        return
    if not (px <= x < px + pw and py <= y < py + ph):
        return
    rel_x = (x - px) / float(pw)
    rel_y = (y - py) / float(ph)
    rel_x = min(0.98, max(0.02, rel_x))
    rel_y = min(0.98, max(0.02, rel_y))
    # Face Detect: a preview tap is a zoom affordance like any other, so it
    # goes to the FACE rather than to the tapped point — that is the whole
    # premise of the mode, and a tap that zoomed somewhere else would make
    # the bracket a lie.  With no face tracked it falls through to the
    # ordinary tap-to-zoom below, so the mode never takes a control away.
    if face_detect_enabled and not zoom_active and _face_tracked_rect() is not None:
        if _face_zoom_into_face():
            _last_button_activity_time = button_activity_saved_ts
            return
    if ((face_detect_enabled or object_track_enabled)
            and zoom_active and _face_zoom_follow):
        # Tapping while the face zoom is up backs out of it, matching the
        # hold gesture — the zoom centre is the detector's, not the user's,
        # so re-centring it on a tap would just be overwritten next frame.
        # Object Track's tracking zoom backs out the same way.
        _face_zoom_into_face()
        _last_button_activity_time = button_activity_saved_ts
        return
    # Object Track: an unzoomed preview tap CHOOSES the subject (or, on the
    # subject already bracketed, lets it go) instead of zooming — zooming is
    # the shutter hold's job, which then goes to the subject.  While a plain
    # (non-tracking) zoom is up the tap keeps its ordinary meaning below.
    if object_track_enabled and not zoom_active:
        action = _obj_request_at(rel_x, rel_y)
        if action:
            _grip_flash("TRACK" if action == "track" else "TRACK OFF")
        _last_button_activity_time = button_activity_saved_ts
        return
    # Focus Point mode: a preview tap repositions the focus box rather than
    # toggling zoom. `_focus_point_norm` is kept in unzoomed (full-frame)
    # coordinates; while zoomed in the box is hidden (full-frame peaking), so a
    # tap is ignored there rather than writing a zoomed-space coordinate that
    # would misplace the box on zoom-out.
    if focus_point_enabled:
        if zoom_active:
            return
        _focus_point_norm = (rel_x, rel_y)
        # Drop the cached peaking mask so the next frame recomputes at the new
        # box location instead of reusing the stale mask on a skip frame.
        _focus_point_last_mask = None
        # Restart the spot-metering average so exposure re-converges on the
        # new box location without dragging the old region's history along.
        _spot_meter_luma_ema = None
        _spot_meter_next_update = 0.0
        _last_button_activity_time = button_activity_saved_ts
        _debounced_save_settings()
        return
    if zoom_active:
        dist = np.hypot(rel_x - zoom_center_norm[0], rel_y - zoom_center_norm[1])
        if dist < 0.08 and len(ZOOM_LEVELS) > 0:
            # Compute the next index in a local first so the GLOBAL is never
            # transiently set out of range while zoom_active is still True — the
            # main loop reads ZOOM_LEVELS[_zoom_level_idx] from another thread and
            # an out-of-range value there crashes the whole app.  Tapping past the
            # last level exits zoom (active cleared BEFORE idx reset to 0).
            next_idx = _zoom_level_idx + 1
            if next_idx >= len(ZOOM_LEVELS):
                zoom_active = False
                _zoom_level_idx = 0
            else:
                _zoom_level_idx = next_idx
    else:
        zoom_active = True
        _zoom_level_idx = 0
    zoom_center_norm = (rel_x, rel_y)
    # A zoom the user placed by hand is theirs: clear the follow flag so the
    # face tracker cannot drag it off the point they tapped.
    _face_zoom_clear()
    # Tap-to-zoom must not count as button activity, otherwise the auto-hide
    # timer would never expire while the user is just framing.
    _last_button_activity_time = button_activity_saved_ts


def _on_touch(event, x, y, flags, param):
    global zoom_active, zoom_center_norm, _zoom_level_idx
    global _aspect_popup_visible, _aspect_popup_rects, _aspect_popup_bounds
    global _film_popup_visible, _film_popup_rects, _film_popup_bounds
    global _iso_popup_visible, _iso_popup_rects, _iso_popup_bounds
    global _shutter_popup_visible, _shutter_popup_rects, _shutter_popup_bounds
    global _focus_popup_visible, _focus_popup_rects, _focus_popup_bounds
    global _multishot_popup_visible
    global _sensor_mode_popup_visible
    global charge_mode_active, flip_mode, _delete_confirm_active
    global _quit_confirm_active
    global double_exposure_enabled, double_exposure_first_frame, _double_preview_cache
    global _brenizer_show_help
    global _swipe_start_x, _swipe_start_y, _swipe_start_time
    global _touch_down_pos
    global _last_button_activity_time
    global _viewfinder_active_setting, _viewfinder_slider_dragging
    # Long-exposure mode settings written by the panel-chip handler below.
    # Without these declarations Python would treat the names as locals for
    # the whole function (because we assign them further down), and the
    # earlier `_le_touch_help = _le_show_help` read would raise
    # UnboundLocalError on every non-swipe tap — silently swallowed by the
    # cv2 mouse callback and dropping the entire button-rect dispatch.
    global _le_show_help, _le_look_idx, _le_duration_mode_idx
    global _le_duration_idx, _le_align_enabled
    global _le_help_seen, _brenizer_help_seen
    global _gesture_help_active, _gesture_help_seen
    # Charge-menu sleep submenu (power-saving configuration).
    global _power_menu_visible, _low_power_timeout_idx, _sleep_timeout_idx
    global _charge_auto_off_enabled
    # Deferred sleep entry (swipe-up / Sleep Now) — see _sleep_entry_requested.
    global _sleep_entry_requested

    # Drop touch input while the 47 MP capture worker owns picam2.  The
    # screen is on _black_canvas during that window so the user cannot
    # actually see anything to tap, but the touch screen still emits
    # events.  Many touch paths call picam2.set_controls() (ISO change,
    # shutter change, etc.), which would race the worker's mode-switch.
    if _high_res_capture_busy.is_set():
        return

    # Sleep is woken by the physical shutter button only (by design — the
    # panel is dark). Normally no touch event can even dispatch while asleep
    # (the sleep branch never pumps waitKey), but the wake-hint paint in
    # _enter_sleep_mode runs one waitKey(1) — swallow anything it dispatches.
    if sleep_mode_active:
        return

    # Low-power dim-idle: the ENTIRE wake gesture must be inert, not just its
    # release. The LBUTTONDOWN/MOUSEMOVE handlers below used to run while the
    # panel was dark, so a blind wake-tap that landed on the viewfinder
    # strip's slider live-applied a value on the button-down (or latched the
    # slider drag), silently rewriting shutter/ISO/EV away from what the user
    # had set — seen in the field as a wildly overexposed preview after wake.
    # Only the LBUTTONUP wakes (its swallow branch below); every other event
    # in the gesture is dropped here.
    if _backlight_dimmed and event != cv2.EVENT_LBUTTONUP:
        return

    # Track swipe start on button-down
    if event == cv2.EVENT_LBUTTONDOWN:
        _swipe_start_x = x
        _swipe_start_y = y
        _swipe_start_time = time.monotonic()
        # Store press position in canvas coords for visual feedback
        tx, ty = x, y
        if flip_mode == FLIP_MODE_MIRROR:
            tx = SCREEN_W - 1 - tx
        elif flip_mode == FLIP_MODE_MIRROR_ROTATE:
            ty = SCREEN_H - 1 - ty
        with _touch_down_lock:
            _touch_down_pos = (tx, ty)
        # If Viewfinder UI's slider is open and the press starts on the
        # panel, switch into live-drag mode and apply the value at the
        # initial position immediately. Subsequent MOUSEMOVE events will
        # update the camera in real time as the finger glides through dots.
        # Never while a modal owns the screen: the Wi-Fi overlay / gesture
        # card draw OVER the strip, and a press meant for them must not
        # live-apply a shutter/ISO/EV value underneath (and latch the drag,
        # which would also swallow the release before the modal dispatch).
        _modal_owns_screen = _gesture_help_active
        with _wifi_overlay_lock:
            if _wifi_overlay_visible:
                _modal_owns_screen = True
        if (not _modal_owns_screen and _ui_viewfinder_mode
                and _viewfinder_active_setting is not None):
            if _viewfinder_slider_apply_at(tx, ty):
                _viewfinder_slider_dragging = True
            else:
                with _viewfinder_lock:
                    bounds = _viewfinder_slider_bounds
                if bounds is not None and _point_in_rect(tx, ty, bounds):
                    _viewfinder_slider_dragging = True
        return

    if event == cv2.EVENT_MOUSEMOVE:
        # Live-drag: while a finger is held down on the Viewfinder slider,
        # update the camera value to whichever dot the finger is over.
        if _viewfinder_slider_dragging and (flags & cv2.EVENT_FLAG_LBUTTON):
            tx, ty = x, y
            if flip_mode == FLIP_MODE_MIRROR:
                tx = SCREEN_W - 1 - tx
            elif flip_mode == FLIP_MODE_MIRROR_ROTATE:
                ty = SCREEN_H - 1 - ty
            with _touch_down_lock:
                _touch_down_pos = (tx, ty)
            _viewfinder_slider_apply_at(tx, ty)
        return

    if event != cv2.EVENT_LBUTTONUP:
        return

    # Clear press highlight on finger lift
    with _touch_down_lock:
        _touch_down_pos = None

    # First touch from the low-power dim-idle state only wakes the camera back
    # to normal shooting — it must not zoom, hit a button, or re-sleep. Wake and
    # swallow the whole event (mirrors the sleep-mode swallow, which the dim
    # state previously lacked). The next tap dispatches normally.
    if _backlight_dimmed:
        _record_activity(wake=True)
        _record_button_activity()
        _swipe_start_x = None
        _swipe_start_y = None
        _swipe_start_time = None
        # A drag latched just before the dim landed must not resume on the
        # next finger-down's MOUSEMOVE stream.
        _viewfinder_slider_dragging = False
        return

    # If we were live-dragging the Viewfinder slider, the value has already
    # been applied via MOUSEMOVE. Apply the final position once more (in
    # case the user lifted between MOUSEMOVE samples) and exit drag mode.
    # The strip stays on the same setting — it's always visible now, so
    # no slider-close step is needed. Skip swipe detection so a long drag
    # isn't misread as a swipe gesture.
    if _viewfinder_slider_dragging:
        tx, ty = x, y
        if flip_mode == FLIP_MODE_MIRROR:
            tx = SCREEN_W - 1 - tx
        elif flip_mode == FLIP_MODE_MIRROR_ROTATE:
            ty = SCREEN_H - 1 - ty
        _viewfinder_slider_apply_at(tx, ty)
        _viewfinder_slider_dragging = False
        _swipe_start_x = None
        _swipe_start_y = None
        _swipe_start_time = None
        _record_button_activity()
        return

    # Speculatively reset the inactivity timer for any non-zoom interaction.
    # The zoom path at the bottom of this function restores the saved value
    # so tap-to-zoom presses don't keep the buttons visible. Doing this up
    # front means swipes, Wi-Fi modal taps, charge-mode taps and brenizer
    # completion taps all count as activity even though they return early.
    _button_activity_saved_ts = _last_button_activity_time
    _record_button_activity()

    # Detect swipe gestures (blocked during Brenizer capture)
    if _swipe_start_x is not None and _swipe_start_time is not None:
        dx = _swipe_start_x - x  # positive = leftward swipe
        dy = abs(y - _swipe_start_y) if _swipe_start_y is not None else 0
        dy_signed = (y - _swipe_start_y) if _swipe_start_y is not None else 0  # positive = downward
        dy_up = -dy_signed  # positive = upward
        elapsed = time.monotonic() - _swipe_start_time
        _swipe_start_x = None
        _swipe_start_y = None
        _swipe_start_time = None

        # Block swipe gestures whenever a modal or an active capture owns the
        # screen.  Swipes change shutter speed / sleep / toggle the UI (the
        # sleep swipe has its own, narrower gate below), and the
        # later per-mode touch blocks (Wi-Fi modal, long-exposure, video) all
        # come AFTER this point — so without these guards a stray swipe during a
        # handheld long-exposure stack would jump the exposure mid-stack or call
        # _enter_sleep_mode() (which STOPS the camera pipeline), and the same
        # during a video recording.  Previously only Brenizer was guarded.
        # The charge-menu power submenu is a modal too: a finger drag inside
        # it must reach the chip handler, not cycle the shutter (on a stopped
        # pipeline) or call _enter_sleep_mode() out from under the menu.
        # Charge mode too: its pipeline is stopped and its taps are handled
        # by the charge branch below — a swipe here could cycle the shutter
        # on the stopped pipeline or _enter_sleep_mode() with charge mode
        # still active, whose wake would then restart the preview pipeline
        # and lift the CPU clamp invisibly UNDER the charge screen.
        _swipes_blocked = (_brenizer_active or _gesture_help_active
                           or _power_menu_visible or charge_mode_active)
        # The swipe-up SLEEP gesture is the one swipe a merely SELECTED
        # quiescent mode must keep: video standby, the LE idle panel and a
        # zero-tile Brenizer now auto-sleep on the timer, so the gesture that
        # means the same thing cannot be the one path still refusing (it was
        # silently swallowed there).  Only ACTIVE work blocks it — the same
        # _sleep_blocked_reason the main loop's sleep gates use — plus the
        # modals, whose own drags must reach their menu rather than stop the
        # pipeline underneath it.  The shutter-cycling and viewfinder-toggle
        # swipes stay blocked in every mode exactly as before.
        _sleep_swipe_blocked = (_gesture_help_active or _power_menu_visible
                                or charge_mode_active)
        with _wifi_overlay_lock:
            if _wifi_overlay_visible:
                _swipes_blocked = True
                _sleep_swipe_blocked = True
        with _le_lock:
            if _le_active:
                _swipes_blocked = True
                if _le_show_help:
                    # First-run help card: a long vertical swipe dismisses
                    # it (below), it must not sleep the camera instead.
                    _sleep_swipe_blocked = True
        with _brenizer_lock:
            if _brenizer_active and _brenizer_show_help:
                _sleep_swipe_blocked = True
        with _video_lock:
            if _video_mode_active:
                _swipes_blocked = True
        if not _sleep_swipe_blocked and _sleep_blocked_reason():
            _sleep_swipe_blocked = True
        # UPWARD SWIPE (touch coords — the user swipes DOWN on the
        # 180°-mounted panel): enter sleep mode (strict thresholds to
        # avoid accidental activation during tap-to-zoom).  Hoisted above
        # the blocked-swipe set for the gate above; its thresholds
        # (>=150 px vertical, <=80 px horizontal) cannot also satisfy the
        # horizontal shutter swipes (<=100 px vertical), so the order is
        # otherwise a no-op.
        if not _sleep_swipe_blocked:
            if (dy_up >= _SWIPE_UP_MIN_DISTANCE
                    and abs(dx) <= _SWIPE_UP_MAX_HORIZONTAL
                    and elapsed <= _SWIPE_UP_MAX_TIME):
                print("[UI] Swipe-up detected – requesting sleep mode")
                # Deferred: _enter_sleep_mode() pumps waitKey for its wake
                # hint and must not run inside this touch callback (see the
                # _sleep_entry_requested comment). The main loop enters
                # sleep on its next iteration.
                _sleep_entry_requested = True
                return
        if not _swipes_blocked:
            # LEFT SWIPE: increase shutter speed (faster)
            if dx >= _SWIPE_MIN_DISTANCE and dy <= _SWIPE_MAX_VERTICAL and elapsed <= _SWIPE_MAX_TIME:
                print(f"[UI] Left swipe detected – increasing shutter speed")
                _cycle_shutter()
                return

            # RIGHT SWIPE: decrease shutter speed (slower / toward Auto)
            if -dx >= _SWIPE_MIN_DISTANCE and dy <= _SWIPE_MAX_VERTICAL and elapsed <= _SWIPE_MAX_TIME:
                print(f"[UI] Right swipe detected – decreasing shutter speed")
                _cycle_shutter_reverse()
                return

            # DOWNWARD SWIPE (touch coords — the user swipes UP on the
            # 180°-mounted panel): toggle Viewfinder UI (S/S + ISO panel)
            if (dy_signed >= _SWIPE_DOWN_MIN_DISTANCE
                    and abs(dx) <= _SWIPE_DOWN_MAX_HORIZONTAL
                    and elapsed <= _SWIPE_DOWN_MAX_TIME):
                print("[UI] Swipe-down detected – toggling Viewfinder UI")
                _toggle_viewfinder_mode()
                return

    if flip_mode == FLIP_MODE_MIRROR:
        x = SCREEN_W - 1 - x
    elif flip_mode == FLIP_MODE_MIRROR_ROTATE:
        y = SCREEN_H - 1 - y

    # --- Gesture walkthrough card: any tap dismisses ---
    if _gesture_help_active:
        _gesture_help_active = False
        if not _gesture_help_seen:
            _gesture_help_seen = True
            _debounced_save_settings()
        # Restart the auto-hide idle timer from now, not from whenever it
        # last ticked while the card held the screen — otherwise a user who
        # reads the walkthrough for a while gets dropped into minimal mode
        # almost immediately after dismissing it.
        _last_button_activity_time = time.monotonic()
        return

    # --- Wi-Fi selection overlay (modal) ---
    with _wifi_overlay_lock:
        _wifi_modal_active = _wifi_overlay_visible
        _wifi_modal_mode = _wifi_overlay_mode
    if _wifi_modal_active:
        # Count overlay interaction as real activity: only fall-through taps
        # reach the _record_activity() call further down, so a user scrolling
        # the list or typing a password never reset the idle timer — the
        # panel dimmed mid-interaction (eating the next tap as a wake) and
        # could even auto-sleep underneath the keyboard.
        _record_activity()
        _handle_wifi_overlay_touch(x, y, _wifi_modal_mode)
        return

    # --- Long-exposure mode touch handling ---
    # Help overlay: tap anywhere dismisses.  Panel: chip taps update settings.
    # During an active capture, all touch is blocked (the shutter button
    # ends the capture; touch would be too easy to fire accidentally while
    # holding the camera steady).
    with _le_lock:
        _le_touch_active = _le_active
        _le_touch_state = _le_state
        _le_touch_help = _le_show_help
        _le_touch_panel = _le_panel_visible
    if _le_touch_active:
        if _le_touch_state == "capturing":
            return
        if _le_touch_help:
            with _le_lock:
                _le_show_help = False
            if not _le_help_seen:
                _le_help_seen = True
                _debounced_save_settings()
            return
        if _le_touch_panel:
            for (kind, idx), rect in _le_panel_rects.items():
                if _point_in_rect(x, y, rect):
                    if kind == "look":
                        with _le_lock:
                            _le_look_idx = idx
                    elif kind == "duration_mode":
                        with _le_lock:
                            _le_duration_mode_idx = idx
                    elif kind == "duration":
                        with _le_lock:
                            _le_duration_idx = idx
                    elif kind == "align":
                        with _le_lock:
                            _le_align_enabled = (idx == 0)
                    elif kind == "exit":
                        _exit_long_exposure_mode()
                        return
                    _debounced_save_settings()
                    return
            return  # tap on dim background — swallow
        # Any other state (currently just "finishing" — the stop/save window
        # between the second shutter press and the idle panel reappearing)
        # is a modal transition with nothing on screen to tap: swallow the
        # touch instead of falling through to the Brenizer/video/normal UI
        # handling below.
        return

    # --- Brenizer mode touch handling ---
    with _brenizer_lock:
        bren_active = _brenizer_active
        bren_state = _brenizer_state
        bren_help = _brenizer_show_help

    if bren_active:
        if bren_help:
            # Tap anywhere to dismiss help overlay
            _brenizer_show_help = False
            if not _brenizer_help_seen:
                _brenizer_help_seen = True
                _debounced_save_settings()
            return
        if bren_state == "complete":
            # Handle completion screen buttons
            for key, rect in _brenizer_complete_rects.items():
                if _point_in_rect(x, y, rect):
                    if key == "done":
                        _exit_brenizer_mode()
                    elif key == "retake":
                        _brenizer_retake_last()
                    return
            return  # Block other touches on completion screen
        # Mid-sequence Exit chip: the one touch target while shooting tiles.
        # Abandons the sequence (tiles already captured stay on disk).
        if bren_state == "awaiting_capture":
            _bren_abort_rect = _brenizer_abort_rect
            if _bren_abort_rect and _point_in_rect(x, y, _bren_abort_rect):
                _exit_brenizer_mode()
                return
        # During active capture, block all other touch except shutter (GPIO)
        return

    # --- Video mode touch handling: block UI changes while recording ---
    with _video_lock:
        _vid_touch_recording = _video_recording
        _vid_touch_mode = _video_mode_active
    if _vid_touch_recording:
        # While actively recording, block all touch — shutter button (GPIO) controls stop
        return
    # Standby Exit chip — on-screen counterpart to the hold-to-exit gesture.
    # Direct _exit_video_mode() is safe here for the same reason the multishot
    # popup rows call it: cv2 mouse callbacks run on the main preview loop
    # thread (inside waitKey), never concurrently with capture_request().
    if _vid_touch_mode:
        _vid_exit_rect = _video_exit_chip_rect
        if _vid_exit_rect and _point_in_rect(x, y, _vid_exit_rect):
            _exit_video_mode()
            _record_activity(wake=True)
            return

    # Flash sync Boost/Ambient preview chip — same pattern as the video
    # standby Exit chip above (mouse callbacks run on the main preview loop
    # thread, so the setter's debounced save is safe here).  Display-only
    # toggle: works identically armed or not.
    with _flash_lock:
        _fpc_touch_mode = _flash_mode_active
    if _fpc_touch_mode:
        _fpc_rect = _flash_preview_chip_rect
        if _fpc_rect and _point_in_rect(x, y, _fpc_rect):
            _set_flash_preview_boost(not _flash_preview_boost_on)
            _grip_flash("PREVIEW BOOST" if _flash_preview_boost_on
                        else "PREVIEW AMBIENT")
            _record_button_activity()
            _record_activity(wake=True)
            return

    if charge_mode_active:
        # Quit confirmation overlay first if active — only an explicit Yes
        # terminates; any other tap dismisses (the X is pressed by accident
        # often enough that quitting must never be a single tap).
        if _quit_confirm_active:
            if _point_in_rect(x, y, _quit_confirm_yes_rect):
                _quit_confirm_active = False
                _terminate_application()
                return
            _quit_confirm_active = False
            return
        # Handle delete confirmation overlay first if active
        if _delete_confirm_active:
            if _point_in_rect(x, y, _delete_confirm_yes_rect):
                _delete_pictures_files()
                _delete_confirm_active = False
                _charge_stats_cache["timestamp"] = 0.0
                return
            # Cancel or tap anywhere else dismisses the confirmation
            _delete_confirm_active = False
            return
        # Sleep-button power submenu: tap a chip to configure the low-power /
        # sleep idle timeouts or the 95% auto power-off; "Sleep Now" keeps the
        # button's original immediate-sleep action. Tap inside the panel to
        # keep it open, outside to dismiss.
        if _power_menu_visible:
            for (kind, idx), rect in _power_menu_rects:
                if _point_in_rect(x, y, rect):
                    if kind == "low":
                        _low_power_timeout_idx = idx
                        _debounced_save_settings()
                    elif kind == "sleep":
                        _sleep_timeout_idx = idx
                        _debounced_save_settings()
                    elif kind == "autooff":
                        _charge_auto_off_enabled = (idx == 1)
                        # Refresh the cached stats so the "shut down at 95%"
                        # footer tracks the toggle immediately.
                        _charge_stats_cache["timestamp"] = 0.0
                        _debounced_save_settings()
                    elif kind == "sleepnow":
                        _power_menu_visible = False
                        _exit_charge_mode()
                        # Deferred for the same reason as the swipe-up path:
                        # the sleep entry's hint pump must run from the main
                        # loop, not from inside this touch callback.
                        _sleep_entry_requested = True
                    return
            if _power_menu_bounds and _point_in_rect(x, y, _power_menu_bounds):
                return
            _power_menu_visible = False
            return
        # Sensor-mode dropdown takes priority over everything else when open:
        # tap a row to apply, tap inside the panel (not on a row) to keep open,
        # tap outside to dismiss without changing mode.
        if _sensor_mode_popup_visible:
            for mode_idx, rect in _sensor_mode_popup_rects:
                if _point_in_rect(x, y, rect):
                    _sensor_mode_popup_visible = False
                    if mode_idx != _sensor_mode_idx:
                        _set_sensor_mode_idx(mode_idx, restart_pipeline=False)
                    return
            if _sensor_mode_popup_bounds and _point_in_rect(x, y, _sensor_mode_popup_bounds):
                return
            _sensor_mode_popup_visible = False
            return
        # Sensor-mode toggle button opens the dropdown.
        if _point_in_rect(x, y, _sensor_mode_button_rect):
            _sensor_mode_popup_visible = True
            _power_menu_visible = False
            return
        # In Charge mode the Sleep button opens the power-saving submenu
        # (idle timeouts + 95% auto power-off + Sleep Now); a second tap
        # closes it.
        if _point_in_rect(x, y, _sleep_button_rect):
            _power_menu_visible = not _power_menu_visible
            _sensor_mode_popup_visible = False
            return
        if _point_in_rect(x, y, _sensor_change_rect):
            _sensor_dialog_request.set()
            return
        if _point_in_rect(x, y, (170,330,390,376)):
            try:
                _deferred_api(dict(action='setting',enabled=not _deferred_enabled))
            except Exception as exc:
                _post_save_warning(str(exc))
            return
        # Brightness adjustment: stays in charge mode so the user can tap repeatedly.
        # The panel rect (with outer padding) absorbs any tap inside the
        # brightness strip so near-misses never dismiss the charging menu.
        if _point_in_rect(x, y, _brightness_panel_rect):
            if _point_in_rect(x, y, _brightness_minus_rect):
                _set_user_brightness_pct(_user_brightness_pct - _USER_BRIGHTNESS_STEP_PCT)
            elif _point_in_rect(x, y, _brightness_plus_rect):
                _set_user_brightness_pct(_user_brightness_pct + _USER_BRIGHTNESS_STEP_PCT)
            return
        # Trash button opens delete confirmation
        if _point_in_rect(x, y, _trash_button_rect):
            _delete_confirm_active = True
            return
        # Info button replays the gesture walkthrough over the charge screen.
        if _point_in_rect(x, y, _info_button_rect):
            _gesture_help_active = True
            return
        # Exit button (X) asks for confirmation before terminating the
        # application — accidental presses used to quit straight to desktop.
        if _point_in_rect(x, y, _exit_button_rect):
            _quit_confirm_active = True
            return
        # "Shoot while charging": leave the charge screen into live view while
        # staying on AC. Ignored while parked to cool (button greyed) so the
        # user can't override the overheat safeguard.
        if _point_in_rect(x, y, _charge_shoot_button_rect):
            if not _charge_overheat_parked:
                _enter_charge_shoot_mode()
            return
        # Back arrow: return to the shooting screen. While charge mode is
        # force-held (AC + pack) that means a "shoot while charging" session
        # (same path as the camera button); otherwise a plain exit. Ignored
        # while parked to cool, same as the Shoot button (drawn greyed).
        if _point_in_rect(x, y, _charge_back_button_rect):
            if not _charge_overheat_parked:
                if _charge_should_force():
                    _enter_charge_shoot_mode()
                else:
                    _exit_charge_mode()
            return
        # Default behaviour: tap anywhere else to exit charge mode. While charge
        # mode is force-held (USB power + battery present) exiting is pointless —
        # the main loop would re-enter it on the next frame and thrash the camera
        # pipeline — so swallow the tap and stay put. Sleep/Exit still work above.
        if not _charge_should_force():
            _exit_charge_mode()
        return
    _record_activity(wake=True)

    # If the UI is currently auto-hidden (minimal mode) and the user taps
    # in the region where a button would be, restore the UI without
    # triggering the underlying button. Tap-to-zoom presses fall through.
    if _ui_minimal_mode and _tap_hits_any_button(x, y):
        _toggle_minimal_mode()
        return

    # Normal-shooting info button: replays the gesture walkthrough (the
    # charge-menu info button does the same via _info_button_rect below).
    # Only meaningful outside minimal mode — the button isn't drawn there,
    # and a stale rect in that region is already absorbed by the
    # _tap_hits_any_button restore check above.
    if _point_in_rect(x, y, _gesture_info_button_rect):
        _gesture_help_active = True
        return

    # --- Viewfinder UI handling (3rd UI mode) ---
    # The strip is context-aware: it always shows one setting. A tap on
    # the header value/unit cycles to the next setting in the list; taps
    # on the slider apply a new value for the current setting; taps
    # outside the panel fall through to tap-to-zoom on the preview.
    if _ui_viewfinder_mode:
        with _viewfinder_lock:
            vf_value_label_rect = _viewfinder_value_label_rect
        vf_panel_rect = _viewfinder_panel_rect()

        # Header tap → cycle to the next setting.
        if _point_in_rect(x, y, vf_value_label_rect):
            _viewfinder_cycle_setting()
            _record_button_activity()
            return

        # Tap on a slider tick → apply the new value (drag is handled by
        # the LBUTTONDOWN + MOUSEMOVE path above).
        if _viewfinder_slider_apply_at(x, y):
            _record_button_activity()
            return

        # Tap anywhere else on the panel column → no-op (don't trigger
        # tap-to-zoom on the preview just because the user missed a tick).
        if _point_in_rect(x, y, vf_panel_rect):
            return

        # Tap outside the panel → tap-to-zoom on the preview area. Skip
        # the main-UI button/popup checks: those buttons aren't drawn in
        # viewfinder mode and their stale rects must not consume taps.
        # An armed custom-WB pick consumes the preview tap first.
        if _wb_pick_pending and _wb_try_pick_at(x, y):
            return
        _perform_tap_to_zoom(x, y, _button_activity_saved_ts)
        return

    with _film_button_lock:
        film_toggle_rect = _film_toggle_rect
        film_popup_visible = _film_popup_visible
        film_popup_rects = list(_film_popup_rects)
        film_popup_maps = list(_film_popup_maps)
        film_popup_bounds = _film_popup_bounds
    with _aspect_button_lock:
        toggle_rect = _aspect_toggle_rect
        popup_visible = _aspect_popup_visible
        popup_rects = list(_aspect_popup_rects)
        popup_maps = list(_aspect_popup_maps)
        popup_bounds = _aspect_popup_bounds
    with _shutter_button_lock:
        shutter_toggle_rect = _shutter_toggle_rect
        shutter_popup_visible = _shutter_popup_visible
        shutter_popup_rects = list(_shutter_popup_rects)
        shutter_popup_maps = list(_shutter_popup_maps)
        shutter_popup_bounds = _shutter_popup_bounds
    with _iso_button_lock:
        iso_toggle_rect = _iso_toggle_rect
        iso_popup_visible = _iso_popup_visible
        iso_popup_rects = list(_iso_popup_rects)
        iso_popup_maps = list(_iso_popup_maps)
        iso_popup_bounds = _iso_popup_bounds
    with _focus_button_lock:
        focus_toggle_rect = _focus_toggle_rect
        focus_popup_visible = _focus_popup_visible
        focus_popup_rects = list(_focus_popup_rects)
        focus_popup_bounds = _focus_popup_bounds
    if focus_popup_visible:
        for idx, rect in focus_popup_rects:
            if _point_in_rect(x, y, rect):
                _set_focus_mode(idx)
                if 0 <= idx < len(_FOCUS_MODE_FLASH_LABELS):
                    _grip_flash("FOCUS " + _FOCUS_MODE_FLASH_LABELS[idx])
                return
        if focus_toggle_rect and _point_in_rect(x, y, focus_toggle_rect):
            with _focus_button_lock:
                _focus_popup_visible = False
                _focus_popup_rects = []
                _focus_popup_bounds = None
            return
        if focus_popup_bounds is not None and _point_in_rect(x, y, focus_popup_bounds):
            return
        with _focus_button_lock:
            _focus_popup_visible = False
            _focus_popup_rects = []
            _focus_popup_bounds = None
        return
    if shutter_popup_visible:
        for idx, rect in shutter_popup_rects:
            if _point_in_rect(x, y, rect):
                # Decode section: 0 = shutter speeds, 1 = self-timer chips,
                # 2 = anti-banding chips, 3 = flash-sync free-run rate (only
                # present while flash sync is the selected mode; the
                # Boost/Ambient preview toggle is the on-screen chip, not a
                # popup section).
                sec_pos, local = divmod(idx, SECTION_STRIDE)
                # Resolved through the map captured when these rects were
                # drawn — never recomputed here, or a menu edit landing
                # between the frame and the tap would apply the neighbour.
                local = _menu_mapped(shutter_popup_maps, sec_pos, local)
                if local is None:
                    return
                if sec_pos == 0:
                    _set_shutter_option(local)
                elif sec_pos == 1:
                    _set_self_timer_idx(local)
                    _secs = SELF_TIMER_OPTIONS[local]["seconds"]
                    _grip_flash("TIMER OFF" if _secs <= 0 else f"TIMER {_secs}s")
                    # _set_self_timer_idx is popup-agnostic; close the shutter
                    # popup here so picking a timer dismisses the menu like a
                    # shutter-speed pick does.
                    with _shutter_button_lock:
                        _shutter_popup_visible = False
                        _shutter_popup_rects = []
                        _shutter_popup_bounds = None
                elif sec_pos == 2:
                    _set_antibanding_option(local)
                    _ab_opt = ANTIBANDING_OPTIONS[
                        max(0, min(int(local), len(ANTIBANDING_OPTIONS) - 1))]
                    _grip_flash("AB OFF" if not _ab_opt["period_us"]
                                else f"AB {_ab_opt['label']}")
                    # Popup-agnostic setter; close the popup like a
                    # shutter-speed pick does.
                    with _shutter_button_lock:
                        _shutter_popup_visible = False
                        _shutter_popup_rects = []
                        _shutter_popup_bounds = None
                return
        if shutter_toggle_rect and _point_in_rect(x, y, shutter_toggle_rect):
            with _shutter_button_lock:
                _shutter_popup_visible = False
                _shutter_popup_rects = []
                _shutter_popup_bounds = None
            return
        if shutter_popup_bounds is not None and _point_in_rect(x, y, shutter_popup_bounds):
            return
        with _shutter_button_lock:
            _shutter_popup_visible = False
            _shutter_popup_rects = []
            _shutter_popup_bounds = None
        return
    if iso_popup_visible:
        for idx, rect in iso_popup_rects:
            if _point_in_rect(x, y, rect):
                # Decode section: 0 = ISO chips, 1 = Exposure-comp chips.
                sec_pos, local = divmod(idx, SECTION_STRIDE)
                # Chip position -> table index through the map captured when
                # these rects were drawn (see _menu_mapped): the mode cannot
                # change while a popup is open, but the user's hidden set is
                # editable from an HTTP thread at any moment.
                local = _menu_mapped(iso_popup_maps, sec_pos, local)
                if local is None:
                    return
                if sec_pos == 0:
                    _set_iso_option(local)
                else:
                    _set_exp_comp_option(local)
                    # _set_exp_comp_option is popup-agnostic; close the ISO popup
                    # here so picking an EV value dismisses the menu like ISO does.
                    with _iso_button_lock:
                        _iso_popup_visible = False
                        _iso_popup_rects = []
                        _iso_popup_bounds = None
                return
        if iso_toggle_rect and _point_in_rect(x, y, iso_toggle_rect):
            with _iso_button_lock:
                _iso_popup_visible = False
                _iso_popup_rects = []
                _iso_popup_bounds = None
            return
        if iso_popup_bounds is not None and _point_in_rect(x, y, iso_popup_bounds):
            return
        with _iso_button_lock:
            _iso_popup_visible = False
            _iso_popup_rects = []
            _iso_popup_bounds = None
        return
    if film_popup_visible:
        for idx, rect in film_popup_rects:
            if _point_in_rect(x, y, rect):
                # Decode section: 0 = film profiles, 1 = white-balance chips.
                sec_pos, local = divmod(idx, SECTION_STRIDE)
                local = _menu_mapped(film_popup_maps, sec_pos, local)
                if local is None:
                    return
                if sec_pos == 0:
                    _set_film_profile(local)
                    _grip_flash("FILM " + _current_film_label())
                else:
                    _set_wb_option(local)
                return
        if film_toggle_rect and _point_in_rect(x, y, film_toggle_rect):
            with _film_button_lock:
                _film_popup_visible = False
                _film_popup_rects = []
                _film_popup_bounds = None
            return
        if film_popup_bounds is not None and _point_in_rect(x, y, film_popup_bounds):
            return
        with _film_button_lock:
            _film_popup_visible = False
            _film_popup_rects = []
            _film_popup_bounds = None
        return
    if popup_visible:
        for idx, rect in popup_rects:
            if _point_in_rect(x, y, rect):
                # Decode section: 0 = aspect ratios, 1 = grid overlay.
                sec_pos, local = divmod(idx, SECTION_STRIDE)
                local = _menu_mapped(popup_maps, sec_pos, local)
                if local is None:
                    return
                if sec_pos == 0:
                    _set_aspect_ratio(local)
                    _grip_flash("ASPECT " + ASPECT_OPTIONS[local]["label"])
                else:
                    _set_grid_overlay(local)
                return
        if toggle_rect and _point_in_rect(x, y, toggle_rect):
            with _aspect_button_lock:
                _aspect_popup_visible = False
                _aspect_popup_rects = []
                _aspect_popup_bounds = None
            return
        if popup_bounds is not None and _point_in_rect(x, y, popup_bounds):
            return
        with _aspect_button_lock:
            _aspect_popup_visible = False
            _aspect_popup_rects = []
            _aspect_popup_bounds = None
        return
    if _tap_hits(x, y, _charge_button_rect):
        if charge_mode_active:
            _exit_charge_mode()
        else:
            _enter_charge_mode()
        return
    if _tap_hits(x, y, _flip_button_rect):
        if flip_mode == FLIP_MODE_NORMAL:
            flip_mode = FLIP_MODE_MIRROR
        elif flip_mode == FLIP_MODE_MIRROR:
            flip_mode = FLIP_MODE_MIRROR_ROTATE
        else:
            flip_mode = FLIP_MODE_NORMAL
        _debounced_save_settings()
        return
    if _tap_hits(x, y, _double_exposure_button_rect):
        # Toggle like the other popup buttons (shutter / ISO / aspect): a second
        # press on the button closes the menu instead of re-opening it.
        if _multishot_popup_visible:
            _multishot_popup_visible = False
        else:
            _dismiss_all_popups(except_lock=_brenizer_lock)
            _multishot_popup_visible = True
        return
    # Handle multishot popup item taps (Double Exp / Brenizer / Video)
    if _multishot_popup_visible:
        for idx, rect in _multishot_popup_rects:
            if _point_in_rect(x, y, rect):
                _multishot_popup_visible = False
                # Decode (section, local) → original MULTISHOT_OPTIONS index
                # through the map captured when these rects were drawn, not a
                # freshly grouped list (see _menu_mapped).
                sec_pos, local = divmod(idx, SECTION_STRIDE)
                _opt_idx = _menu_mapped(_multishot_popup_maps, sec_pos, local)
                if _opt_idx is None:
                    return
                opt_key = MULTISHOT_OPTIONS[_opt_idx]["key"]
                if opt_key == "double_exposure":
                    # Exit video mode if active before toggling DE
                    if _video_mode_active:
                        _exit_video_mode()
                    _exit_burst_mode()
                    _exit_flash_mode()
                    with _double_exposure_lock:
                        double_exposure_enabled = not double_exposure_enabled
                    _clear_double_exposure_state()
                    # Double exposure blends two MAIN frames, so the unbinned
                    # mono fast-path (preview-size main) must hand the full
                    # stream back while it is on (and reclaim it after).
                    _request_still_pipeline_rebuild()
                    _grip_flash("DOUBLE EXP " + ("ON" if double_exposure_enabled else "OFF"))
                elif opt_key == "brenizer_5":
                    if _video_mode_active:
                        _exit_video_mode()
                    _enter_brenizer_mode(5)
                elif opt_key == "brenizer_6":
                    if _video_mode_active:
                        _exit_video_mode()
                    _enter_brenizer_mode(6)
                elif opt_key == "brenizer_9":
                    if _video_mode_active:
                        _exit_video_mode()
                    _enter_brenizer_mode(9)
                elif opt_key == "long_exposure":
                    if _video_mode_active:
                        _exit_video_mode()
                    _enter_long_exposure_mode()
                elif opt_key == "burst_sr":
                    # Toggle like double exposure: a second tap disarms.
                    with _bm_lock:
                        _bm_on = _bm_active
                    if _bm_on:
                        _exit_burst_mode()
                        _grip_flash("BURST SR OFF")
                    else:
                        if _video_mode_active:
                            _exit_video_mode()
                        # Refused at 47 MP (OOM risk) — the enter call posts
                        # its own HUD warning naming the reason.
                        if _enter_burst_mode():
                            _grip_flash("BURST SR ON")
                elif opt_key == "flash_sync":
                    # Toggle like double exposure: a second tap deselects
                    # (and disarms).  Selecting the mode allocates nothing —
                    # the shutter arms it.
                    with _flash_lock:
                        _flash_on = _flash_mode_active
                    if _flash_on:
                        _exit_flash_mode()
                        _grip_flash("FLASH SYNC OFF")
                    else:
                        if _video_mode_active:
                            _exit_video_mode()
                        if _enter_flash_mode():
                            _grip_flash("FLASH SYNC ON")
                elif opt_key == "video_1080p":
                    if _video_mode_active and _video_resolution_idx == 0:
                        _exit_video_mode()  # Toggle off
                    else:
                        if _video_mode_active:
                            _exit_video_mode()
                        _enter_video_mode(0)
                elif opt_key == "video_4k":
                    if _video_mode_active and _video_resolution_idx == 1:
                        _exit_video_mode()  # Toggle off
                    else:
                        if _video_mode_active:
                            _exit_video_mode()
                        _enter_video_mode(1)
                return
        # Tap inside the popup but not on a chip — swallow it (matches the
        # iso/shutter/focus popups) instead of letting it fall through to
        # whatever button sits underneath.
        if _multishot_popup_bounds and _point_in_rect(x, y, _multishot_popup_bounds):
            return
        # Tap outside popup bounds — dismiss
        _multishot_popup_visible = False
        return
    if focus_toggle_rect and _tap_hits(x, y, focus_toggle_rect):
        _dismiss_all_popups(except_lock=_focus_button_lock)
        with _focus_button_lock:
            _focus_popup_visible = True
        return
    if film_toggle_rect and _tap_hits(x, y, film_toggle_rect):
        _dismiss_all_popups(except_lock=_film_button_lock)
        with _film_button_lock:
            _film_popup_visible = True
        # Pick up .cube files dropped into the home/USB lut folders since the
        # last scan (SFTP copies, web uploads) without a reboot; runs off the
        # touch thread so the popup opens instantly, and the popup reads
        # FILM_OPTIONS per frame so new entries appear as soon as it lands.
        _lut_refresh_async()
        return
    if toggle_rect and _tap_hits(x, y, toggle_rect):
        _dismiss_all_popups(except_lock=_aspect_button_lock)
        with _aspect_button_lock:
            _aspect_popup_visible = True
        return
    if iso_toggle_rect and _tap_hits(x, y, iso_toggle_rect):
        _dismiss_all_popups(except_lock=_iso_button_lock)
        with _iso_button_lock:
            _iso_popup_visible = True
        return
    if shutter_toggle_rect and _tap_hits(x, y, shutter_toggle_rect):
        _dismiss_all_popups(except_lock=_shutter_button_lock)
        with _shutter_button_lock:
            _shutter_popup_visible = True
        return
    if _tap_hits(x, y, _wifi_button_rect):
        # Open the Wi-Fi selection / login overlay. Enables the radio if needed
        # and kicks off a background scan. If already connected, the overlay
        # will display the live IP / SSH credentials alongside the network list.
        _open_wifi_overlay()
        return
    barrier_rects = [
        _charge_button_rect,
        _sleep_button_rect,
        _flip_button_rect,
        _double_exposure_button_rect,
        _rangefinder_button_rect,
        _wifi_button_rect,
        _exit_button_rect,
        film_toggle_rect,
        toggle_rect,
        iso_toggle_rect,
        shutter_toggle_rect,
        film_popup_bounds,
        popup_bounds,
        iso_popup_bounds,
        shutter_popup_bounds,
        _multishot_popup_bounds,
    ]
    for rect in barrier_rects:
        if _point_in_rect_padded(x, y, rect, TAP_ZOOM_BARRIER_PAD):
            return
    # Custom-WB pick armed (film popup's Custom chip): the first clear tap on
    # the live preview is the sample point.  Placed after the button barrier
    # — the edge buttons overlap the preview, and a near-button tap must
    # neither sample nor zoom.  A pick that is never completed simply
    # expires (_WB_PICK_TIMEOUT_S).
    if _wb_pick_pending and _wb_try_pick_at(x, y):
        return
    _perform_tap_to_zoom(x, y, _button_activity_saved_ts)

def _pil_render_text_block(lines, font_scale, thickness, rotate_180, max_h, pad_x, pad_y, line_gap):
    """Render a text block using PIL/Pillow TrueType fonts.

    Segments may use per-segment font_scale via dict:
        {"text": "SS ", "font_scale": 1.2}
    Segments without an explicit font_scale inherit the block-level font_scale.

    Returns a numpy (H, W, 3) image, or None if PIL is unavailable.
    """
    if not _PIL_AVAILABLE:
        return None

    render_scale = max(1.0, float(TEXT_RENDER_SCALE))
    # Map cv2 HERSHEY_PLAIN scale to approximate PIL font size.
    # HERSHEY_PLAIN scale 1.0 ≈ 10 px cap height; PIL needs ~13 px for similar.
    base_pil_size = max(8, int(round(font_scale * render_scale * 13)))
    base_font = _load_pil_font(base_pil_size)
    if base_font is None:
        return None

    scaled_pad_x = int(round(pad_x * render_scale))
    scaled_pad_y = int(round(pad_y * render_scale))
    scaled_line_gap = int(round(line_gap * render_scale))

    dummy = Image.new("RGB", (1, 1))
    draw = ImageDraw.Draw(dummy)

    # Parse each line into measured segments, each with its own font.
    measured_lines = []
    max_w = 0
    total_h = 2 * scaled_pad_y
    for idx, raw_line in enumerate(lines):
        segments = []
        if isinstance(raw_line, (list, tuple)) and not isinstance(raw_line, str):
            for seg in raw_line:
                if isinstance(seg, dict):
                    text = seg.get("text", "")
                    seg_font_scale = seg.get("font_scale", None)
                    seg_color = seg.get("color", None)
                    seg_bold = bool(seg.get("bold", False))
                elif isinstance(seg, (list, tuple)) and seg:
                    text = str(seg[0])
                    seg_font_scale = None
                    seg_color = None
                    seg_bold = False
                else:
                    text = str(seg)
                    seg_font_scale = None
                    seg_color = None
                    seg_bold = False
                if not text:
                    continue
                if seg_font_scale is not None:
                    pil_size = max(8, int(round(seg_font_scale * render_scale * 13)))
                    seg_font = _load_pil_font(pil_size) or base_font
                else:
                    seg_font = base_font
                # Faux-bold via a same-colour stroke around the glyphs (no
                # dedicated bold TTF is shipped). Used to highlight the active
                # grip-mode setting on the HUD.
                seg_stroke = max(1, int(round(render_scale))) if seg_bold else 0
                bbox = draw.textbbox((0, 0), text, font=seg_font, stroke_width=seg_stroke)
                segments.append({
                    "text": text, "font": seg_font,
                    "w": max(1, bbox[2] - bbox[0]),
                    "x_off": -bbox[0], "y_off": -bbox[1],
                    "ascent": -bbox[1], "descent": bbox[3],
                    "color": seg_color, "stroke": seg_stroke,
                })
        else:
            text = str(raw_line) or " "
            bbox = draw.textbbox((0, 0), text, font=base_font)
            segments.append({
                "text": text, "font": base_font,
                "w": max(1, bbox[2] - bbox[0]),
                "x_off": -bbox[0], "y_off": -bbox[1],
                "ascent": -bbox[1], "descent": bbox[3],
            })

        if not segments:
            bbox = draw.textbbox((0, 0), " ", font=base_font)
            segments.append({
                "text": " ", "font": base_font,
                "w": max(1, bbox[2] - bbox[0]),
                "x_off": -bbox[0], "y_off": -bbox[1],
                "ascent": -bbox[1], "descent": bbox[3],
            })

        line_width = sum(s["w"] for s in segments)
        line_ascent = max(s["ascent"] for s in segments)
        line_descent = max(s["descent"] for s in segments)
        line_height = line_ascent + line_descent

        measured_lines.append({
            "segments": segments, "width": line_width,
            "height": max(1, line_height), "ascent": line_ascent,
        })
        max_w = max(max_w, line_width)
        total_h += max(1, line_height)
        if idx < len(lines) - 1:
            total_h += scaled_line_gap

    img_w = max(1, max_w + 2 * scaled_pad_x)
    img_h = max(1, total_h)

    pil_img = Image.new("RGB", (img_w, img_h), (0, 0, 0))
    draw = ImageDraw.Draw(pil_img)
    y = scaled_pad_y
    for idx, line in enumerate(measured_lines):
        x = scaled_pad_x
        for seg in line["segments"]:
            # Align all segments to the line's common baseline
            baseline_y = y + line["ascent"]
            seg_y = baseline_y - seg["ascent"]
            seg_fill = seg.get("color") or (255, 255, 255)
            seg_stroke = seg.get("stroke", 0)
            draw.text((x + seg["x_off"], seg_y + seg["y_off"]),
                      seg["text"], fill=seg_fill, font=seg["font"],
                      stroke_width=seg_stroke, stroke_fill=seg_fill)
            x += seg["w"]
        y += line["height"]
        if idx < len(measured_lines) - 1:
            y += scaled_line_gap

    img = np.array(pil_img)

    if rotate_180:
        img = cv2.rotate(img, cv2.ROTATE_180)

    target_h = max(1, int(round(img.shape[0] / render_scale)))
    target_w = max(1, int(round(img.shape[1] / render_scale)))
    if target_h > max_h:
        resize_scale = max_h / float(target_h)
        target_h = max_h
        target_w = max(1, int(round(target_w * resize_scale)))

    if target_h != img.shape[0] or target_w != img.shape[1]:
        img = cv2.resize(img, (target_w, target_h),
                         interpolation=cv2.INTER_AREA if target_h < img.shape[0] else cv2.INTER_LINEAR)
    return img


_text_block_cache = {}
# Sized to hold the steady-state HUD blocks (SS/ISO, zoom/IC) plus the recent
# variants produced while cycling shutter/ISO/EV/zoom and as image_count
# increments, so those stay resident instead of evicting each other and forcing
# PIL re-renders every frame. Each cached block is only a few KB.
_TEXT_BLOCK_CACHE_MAX = 128

# Histogram throttle — recompute every Nth frame, reuse the cached result
# between.  Active: every 2nd frame (imperceptible at 20fps).  Dimmed/idle:
# every 4th — the histogram is barely visible then, so skip the bincount.
_HIST_INTERVAL_ACTIVE = 2
_HIST_INTERVAL_DIMMED = 4
_hist_cached_img = None
_hist_frame_counter = 0


def make_rotated_text_block(
    lines,
    font_scale=0.7,
    thickness=1,
    rotate_180=True,
    max_h=BAR_H - 8,
    pad_x=8,
    pad_y=6,
    line_gap=6,
):
    # Build a hashable key from the text content and rendering parameters.
    # Each segment becomes a (text, font_scale_or_None, color_or_None) tuple
    # so that segment boundaries are preserved and differently-styled inputs
    # never collide.
    key_lines = []
    for raw_line in lines:
        if isinstance(raw_line, (list, tuple)) and not isinstance(raw_line, str):
            segs = []
            for seg in raw_line:
                if isinstance(seg, dict):
                    segs.append((seg.get("text", ""), seg.get("font_scale", None), seg.get("color", None), bool(seg.get("bold", False))))
                elif isinstance(seg, (list, tuple)) and seg:
                    segs.append((str(seg[0]), None, None, False))
                else:
                    segs.append((str(seg), None, None, False))
            key_lines.append(tuple(segs))
        else:
            key_lines.append(((str(raw_line), None, None, False),))
    cache_key = (tuple(key_lines), font_scale, thickness, rotate_180, max_h, pad_x, pad_y, line_gap)
    cached = _text_block_cache.get(cache_key)
    if cached is not None:
        return cached

    # Try PIL/TrueType first for cleaner text rendering.
    if _PIL_AVAILABLE:
        result = _pil_render_text_block(
            lines, font_scale, thickness, rotate_180, max_h, pad_x, pad_y, line_gap
        )
        if result is not None:
            if len(_text_block_cache) >= _TEXT_BLOCK_CACHE_MAX:
                try:
                    _text_block_cache.pop(next(iter(_text_block_cache)))
                except Exception:
                    _text_block_cache.clear()
            _text_block_cache[cache_key] = result
            return result

    # ---- Fallback: cv2 Hershey rendering ----
    font = cv2.FONT_HERSHEY_PLAIN

    render_scale = max(1.0, float(TEXT_RENDER_SCALE))
    # Same reason as the _ui_draw_text fallback: with no Pillow the theme's
    # text size has no _load_pil_font to ride, so apply it here.
    scaled_font_scale = font_scale * render_scale * _theme_text_scale
    scaled_thickness = max(1, int(round(thickness * render_scale)))
    scaled_pad_x = int(round(pad_x * render_scale))
    scaled_pad_y = int(round(pad_y * render_scale))
    scaled_line_gap = int(round(line_gap * render_scale))

    processed = []
    max_line_width = 0
    total_height = 2 * scaled_pad_y

    line_count = len(lines)
    for idx, raw_line in enumerate(lines):
        if isinstance(raw_line, (list, tuple)) and not isinstance(raw_line, str):
            segments = []
            for seg in raw_line:
                if isinstance(seg, dict):
                    text = seg.get("text", "")
                    seg_fs_override = seg.get("font_scale", None)
                    seg_color = seg.get("color", None)
                elif isinstance(seg, (list, tuple)) and seg:
                    text = str(seg[0])
                    seg_fs_override = None
                    seg_color = None
                else:
                    text = str(seg)
                    seg_fs_override = None
                    seg_color = None
                if not text:
                    continue
                if seg_fs_override is not None:
                    # The theme scale must ride the per-segment override too,
                    # or a block mixing explicit and inherited sizes (the HUD
                    # readout, the charge screen) would resize only half its
                    # text on a camera with no Pillow. Thickness is a ratio
                    # of the two scales, so it needs no term.
                    seg_scaled_fs = (seg_fs_override * render_scale
                                     * _theme_text_scale)
                    seg_thick = max(1, int(round(thickness * render_scale * seg_fs_override / font_scale)))
                else:
                    seg_scaled_fs = scaled_font_scale
                    seg_thick = scaled_thickness
                size, base = cv2.getTextSize(text, font, seg_scaled_fs, seg_thick)
                segments.append(
                    {
                        "text": text,
                        "font_scale": seg_scaled_fs,
                        "thickness": seg_thick,
                        "width": size[0],
                        "height": size[1],
                        "baseline": base,
                        "color": seg_color,
                    }
                )
        else:
            text = str(raw_line)
            if not text:
                text = " "
            size, base = cv2.getTextSize(text, font, scaled_font_scale, scaled_thickness)
            segments = [
                {
                    "text": text,
                    "font_scale": scaled_font_scale,
                    "thickness": scaled_thickness,
                    "width": size[0],
                    "height": size[1],
                    "baseline": base,
                }
            ]

        if not segments:
            size, base = cv2.getTextSize(" ", font, scaled_font_scale, scaled_thickness)
            segments = [
                {
                    "text": " ",
                    "font_scale": scaled_font_scale,
                    "thickness": scaled_thickness,
                    "width": size[0],
                    "height": size[1],
                    "baseline": base,
                }
            ]

        line_width = sum(seg["width"] for seg in segments)
        line_height = max(seg["height"] for seg in segments)

        processed.append({"segments": segments, "width": line_width, "height": line_height})
        max_line_width = max(max_line_width, line_width)
        total_height += line_height
        if idx < line_count - 1:
            total_height += scaled_line_gap

    width = max_line_width + 2 * scaled_pad_x
    height = max(total_height, 1)

    img = np.zeros((height, width, 3), dtype=np.uint8)
    y = scaled_pad_y
    for idx, line in enumerate(processed):
        y += line["height"]
        x = scaled_pad_x
        for seg in line["segments"]:
            _sc = seg.get("color")
            # Segment colors are already BGR (callers pass e.g. (0,0,255) for
            # red) and `img` is a BGR array, so write them straight through —
            # reversing here rendered every colored HUD warning in the wrong
            # hue (red -> blue) on the cv2/Hershey fallback path.
            _bgr = tuple(_sc) if _sc else (255, 255, 255)
            cv2.putText(
                img,
                seg["text"],
                (x, y),
                font,
                seg.get("font_scale", scaled_font_scale),
                _bgr,
                seg["thickness"],
                cv2.LINE_AA,
            )
            x += seg["width"]
        if idx < len(processed) - 1:
            y += scaled_line_gap

    if rotate_180:
        img = cv2.rotate(img, cv2.ROTATE_180)

    target_h = max(1, int(round(img.shape[0] / render_scale)))
    target_w = max(1, int(round(img.shape[1] / render_scale)))
    if target_h > max_h:
        resize_scale = max_h / float(target_h)
        target_h = max_h
        target_w = max(1, int(round(target_w * resize_scale)))

    if target_h != img.shape[0] or target_w != img.shape[1]:
        img = cv2.resize(
            img,
            (target_w, target_h),
            interpolation=cv2.INTER_AREA if (target_h < img.shape[0]) else cv2.INTER_LINEAR,
        )
    if len(_text_block_cache) >= _TEXT_BLOCK_CACHE_MAX:
        try:
            _text_block_cache.pop(next(iter(_text_block_cache)))
        except Exception:
            _text_block_cache.clear()
    _text_block_cache[cache_key] = img
    return img

_web_update_gate = threading.RLock()
_web_update_preparing = False


def _web_update_request_allowed(headers):
    """Reject unrelated Host names before issuing a privileged updater token."""
    import ipaddress
    import socket
    from urllib.parse import urlsplit
    try:
        host_header = headers.get('Host', '')
        host = urlsplit('//' + host_header).hostname
        local = socket.gethostname().lower()
        if host not in ('localhost', local, local + '.local'):
            ipaddress.ip_address(host)
        origin = headers.get('Origin')
        if origin and urlsplit(origin).netloc.lower() != host_header.lower():
            return False
        return bool(host)
    except (ValueError, TypeError):
        return False


def _web_update_charge_gate(function):
    def guarded():
        with _web_update_gate:
            if not _web_update_preparing:
                return function()
    return guarded


def _web_update_prepare():
    global _web_update_preparing
    with _web_update_gate:
        if globals().get('_deferred_processing_busy', False):
            return False, "Raw conversion is running. Stop after the current image before updating."
        if globals().get('_sensor_selector') is not None and _sensor_selector.power_pending:
            return False, "The camera is shutting down or restarting after a sensor change."
        if not charge_mode_active:
            return False, "Put the camera in Charge mode before installing an update."
        if (globals().get('_captures_in_flight', 0)
                or globals().get('_video_recording', False)
                or globals().get('_video_recording_starting', False)
                or (globals().get('_high_res_capture_busy') is not None
                    and _high_res_capture_busy.is_set())):
            return False, "Wait for the camera to finish saving before installing."
        _web_update_preparing = True
        return True, None


def _web_update_cancel_prepare():
    global _web_update_preparing
    with _web_update_gate:
        _web_update_preparing = False


def _web_update_open(camera_port):
    """Launch only on demand; the maintenance server survives camera shutdown."""
    import urllib.request
    if os.geteuid() != 0:
        raise RuntimeError("The updater needs the standard camera service running as root.")
    directory = Path('/var/lib/wlv-web-update')
    directory.mkdir(mode=0o700, parents=True, exist_ok=True)
    os.chmod(directory, 0o700)
    import fcntl
    with (directory / 'launch.lock').open('w') as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        # Identify the service that actually owns this process. Do not stop an
        # unrelated camera.service when running from a desktop/user service.
        stop_command = None
        candidates = [['systemctl'], ['sudo', '-n', '-u', 'pi',
                      'env', 'XDG_RUNTIME_DIR=/run/user/1000', 'systemctl', '--user']]
        for command in candidates:
            result = subprocess.run(command + ['show', 'camera.service', '-p', 'MainPID', '--value'],
                                    capture_output=True, text=True, timeout=10)
            if result.returncode == 0 and result.stdout.strip() == str(os.getpid()):
                stop_command = command + ['stop', 'camera.service']
                break
        if stop_command is None:
            raise RuntimeError("Start the camera using its camera.service before opening Updates.")
        access = directory / 'access.json'
        active = subprocess.run(['systemctl', 'is-active', '--quiet', 'wlv-web-update.service'],
                                timeout=10).returncode == 0
        token = json.loads(access.read_text())['token'] if active and access.exists() else secrets.token_urlsafe(32)
        config = dict(token=token, camera_token=_DOWNLOAD_TOKEN,
                      camera_url='http://127.0.0.1:' + str(camera_port),
                      target=str(Path(__file__).resolve()), stop_command=stop_command)
        tmp = access.with_suffix('.tmp')
        tmp.write_text(json.dumps(config), encoding='utf-8')
        os.chmod(tmp, 0o600)
        os.replace(tmp, access)
        if not active:
            worker = directory / 'worker.py'
            worker.write_text(_WEB_UPDATER_SOURCE, encoding='utf-8')
            os.chmod(worker, 0o600)
            subprocess.run(['systemctl', 'reset-failed', 'wlv-web-update.service'],
                           capture_output=True, timeout=10)
            subprocess.run(['systemd-run', '--unit=wlv-web-update', '--collect',
                            '--property=UMask=0077', '--property=KillMode=control-group',
                            '/usr/bin/python3', '-I', str(worker), '--directory', str(directory)],
                           check=True, capture_output=True, timeout=15)
        request = urllib.request.Request('http://127.0.0.1:8091/api/status',
                                         headers={'X-WLV-Token': token})
        for attempt in range(30):
            try:
                with urllib.request.urlopen(request, timeout=1) as response:
                    json.load(response)
                return dict(ok=True, port=8091, token=token)
            except Exception:
                time.sleep(0.1)
        raise RuntimeError("The update service could not start. Port 8091 must be available.")


# BEGIN EMBEDDED WEB UPDATER
_WEB_UPDATER_SOURCE = '#!/usr/bin/env python3\n"""Standalone, on-demand WLV maintenance server. Embedded into wlf8.py at release.\n\nNo camera imports; systemd owns this process independently of camera.service.\nUploaded scripts are intentionally trusted owner-provided code in this phase.\n"""\nimport argparse\nfrom contextlib import contextmanager\nimport hashlib\nimport hmac\nimport http.server\nimport json\nimport os\nfrom pathlib import Path, PurePosixPath\nimport re\nimport secrets\nimport selectors\nimport shutil\nimport stat\nimport subprocess\nimport tempfile\nimport threading\nimport time\nimport urllib.request\nimport zipfile\n\nPORT = 8091\nMAX_ZIP = 128 * 1024 * 1024\nMAX_EXPANDED = 512 * 1024 * 1024\nRESERVE = 512 * 1024 * 1024\nPROMPT_PREFIX = \'WLV_WEB_PROMPT \'\nACTIVE = {\'uploading\', \'installing\', \'question\'}\n\n\ndef atomic_json(path, value):\n    path = Path(path)\n    tmp = path.with_suffix(\'.tmp\')\n    with tmp.open(\'w\', encoding=\'utf-8\') as f:\n        json.dump(value, f)\n        f.flush()\n        os.fsync(f.fileno())\n    os.replace(tmp, path)\n\n\ndef driver_name(name):\n    return re.fullmatch(r\'install_[a-zA-Z0-9_]+_driver\\.sh\', name) is not None\n\n\ndef inspect_zip(path):\n    """Validate every member before extraction, including unused repo files."""\n    with zipfile.ZipFile(path) as archive:\n        infos = archive.infolist()\n        if not infos or len(infos) > 10000:\n            raise ValueError(\'The ZIP is empty or contains too many files.\')\n        names, seen, total = [], set(), 0\n        for item in infos:\n            name = item.filename\n            parts = PurePosixPath(name).parts\n            if (item.orig_filename != name or not parts or name.startswith(\'/\') or \'\\\\\' in name or \':\' in name\n                    or any(p in (\'\', \'..\', \'.\') for p in name.rstrip(\'/\').split(\'/\'))\n                    or \'\\x00\' in name or any(ord(c) < 32 for c in name)):\n                raise ValueError(\'The ZIP contains an unsafe file path.\')\n            key = name.rstrip(\'/\').casefold()\n            if key in seen:\n                raise ValueError(\'The ZIP contains duplicate file paths.\')\n            seen.add(key)\n            mode = item.external_attr >> 16\n            kind = stat.S_IFMT(mode)\n            if kind not in (0, stat.S_IFREG, stat.S_IFDIR) or item.flag_bits & 1:\n                raise ValueError(\'Links, special files and encrypted ZIPs are not supported.\')\n            total += item.file_size\n            if total > MAX_EXPANDED:\n                raise ValueError(\'The ZIP expands beyond the 512 MB limit.\')\n            if not item.is_dir():\n                names.append(name)\n        roots = {str(PurePosixPath(n).parent) for n in names\n                 if PurePosixPath(n).name in (\'wlf8.py\', \'update.sh\')\n                 or driver_name(PurePosixPath(n).name)}\n        if len(roots) != 1:\n            raise ValueError(\'Use one release folder containing camera software or a driver installer.\')\n        root = roots.pop()\n        prefix = \'\' if root == \'.\' else root + \'/\'\n        if root != \'.\' and len(PurePosixPath(root).parts) != 1:\n            raise ValueError(\'Release files must be at the ZIP root or inside one enclosing folder.\')\n        files = {n[len(prefix):]: n for n in names if n.startswith(prefix)}\n        software = all(n in files for n in (\'wlf8.py\', \'update.sh\'))\n        drivers = sorted(n for n in files if driver_name(n))\n        if not software and not drivers:\n            raise ValueError(\'Camera software requires both update.sh and wlf8.py in the same folder.\')\n        # models/ carries the bundled inference models (see models/README.md).\n        # They are data, not code, so nothing below syntax-checks them; a\n        # release that omits the folder stays valid and the firmware features\n        # that want a model report themselves unavailable.\n        selected = {n: original for n, original in files.items()\n                    if n in (\'wlf8.py\', \'update.sh\') or driver_name(n)\n                    or n.startswith(\'patches/libcamera/\')\n                    or n.startswith(\'models/\')}\n        # Check parent/file collisions before creating anything.\n        for name in selected:\n            if any(str(parent) in selected for parent in PurePosixPath(name).parents):\n                raise ValueError(\'The ZIP contains conflicting file paths.\')\n        return {\'software\': software, \'drivers\': drivers, \'files\': selected,\n                \'expanded\': total}\n\n\ndef extract_release(path, destination, package):\n    with zipfile.ZipFile(path) as archive:\n        for name, original in package[\'files\'].items():\n            dest = Path(destination) / name\n            dest.parent.mkdir(parents=True, exist_ok=True)\n            with archive.open(original) as src, dest.open(\'xb\') as out:\n                shutil.copyfileobj(src, out, 1024 * 1024)\n    if package[\'software\']:\n        data = (Path(destination) / \'wlf8.py\').read_bytes()\n        if len(data) < 100 * 1024:\n            raise ValueError(\'The camera software file is incomplete.\')\n        compile(data, \'wlf8.py\', \'exec\')\n        if not (Path(destination) / \'update.sh\').stat().st_size:\n            raise ValueError(\'The system update script is empty.\')\n    for name in [\'update.sh\'] * bool(package[\'software\']) + package[\'drivers\']:\n        result = subprocess.run([\'bash\', \'-n\', str(Path(destination) / name)],\n                                capture_output=True, text=True, timeout=30)\n        if result.returncode:\n            raise ValueError(\'The installation script has a syntax error: \' + name)\n\n\ndef replace_firmware(source, target):\n    """Backup must succeed; replacement stays on the destination filesystem."""\n    source, target = Path(source), Path(target)\n    data = source.read_bytes()\n    compile(data, \'wlf8.py\', \'exec\')\n    previous = target.stat()\n    shutil.copy2(target, str(target) + \'.bak\')\n    fd, tmp = tempfile.mkstemp(prefix=\'.wlf8-update-\', dir=target.parent)\n    try:\n        with os.fdopen(fd, \'wb\') as f:\n            f.write(data)\n            f.flush()\n            os.fsync(f.fileno())\n        os.chmod(tmp, stat.S_IMODE(previous.st_mode))\n        os.chown(tmp, previous.st_uid, previous.st_gid)\n        if hashlib.sha256(Path(tmp).read_bytes()).digest() != hashlib.sha256(data).digest():\n            raise ValueError(\'Camera software verification failed.\')\n        os.replace(tmp, target)\n        directory = os.open(target.parent, os.O_RDONLY | os.O_DIRECTORY)\n        try:\n            os.fsync(directory)\n        finally:\n            os.close(directory)\n    finally:\n        if os.path.exists(tmp):\n            os.unlink(tmp)\n\n\n@contextmanager\ndef stage_driver(release, driver):\n    """The installer\'s sudo -u checkout-owner helpers must be able to read it.\n\n    Stage only driver payload, never access.json/status/firmware. Root owns the\n    staging directory and grants read/traverse, not write, to other users.\n    """\n    with tempfile.TemporaryDirectory(prefix=\'wlv-driver-\') as temporary:\n        destination = Path(temporary)\n        shutil.copy2(Path(release) / driver, destination / driver)\n        patches = Path(release) / \'patches/libcamera\'\n        if patches.exists():\n            shutil.copytree(patches, destination / \'patches/libcamera\')\n        for path in destination.rglob(\'*\'):\n            os.chmod(path, 0o755 if path.is_dir() else 0o644)\n        os.chmod(destination, 0o755)\n        yield destination\n\n\nclass Manager:\n    def __init__(self, directory, config):\n        self.directory = Path(directory)\n        self.config = config\n        self.lock = threading.RLock()\n        self.answer_ready = threading.Event()\n        self.answer_value = None\n        self.state_file = self.directory / \'state.json\'\n        self.state = {\'phase\': \'idle\', \'message\': \'Choose an update ZIP.\', \'log\': [],\n                      \'package\': None, \'question\': None, \'camera_stopped\': False}\n        if self.state_file.exists():\n            self.state.update(json.loads(self.state_file.read_text()))\n            if self.state[\'phase\'] in ACTIVE:\n                self.state.update(phase=\'failed\', question=None,\n                                  message=\'The previous update was interrupted. Do not assume it completed. Review the log before retrying.\')\n            if self.state.get(\'boot_id\') != self.boot_id():\n                self.state.update(camera_stopped=False, package=None)\n                if self.state[\'phase\'] in (\'ready\', \'rebooting\'):\n                    self.state.update(phase=\'idle\', message=\'The camera restarted. You can install another update.\')\n        self.save()\n\n    @staticmethod\n    def boot_id():\n        return Path(\'/proc/sys/kernel/random/boot_id\').read_text().strip()\n\n    def save(self):\n        self.state[\'boot_id\'] = self.boot_id()\n        atomic_json(self.state_file, self.state)\n\n    def change(self, **fields):\n        with self.lock:\n            self.state.update(fields)\n            self.save()\n\n    def snapshot(self):\n        with self.lock:\n            return json.loads(json.dumps(self.state))\n\n    def reboot(self):\n        with self.lock:\n            if self.state[\'phase\'] == \'rebooting\':\n                return  # A repeated click/request must not schedule another restart.\n            if self.state[\'phase\'] not in (\'ready\', \'failed\'):\n                raise ValueError(\'Wait until installation completes before restarting.\')\n            # Let systemd choose a fresh name. A fixed transient timer/service\n            # name can collide with an existing or failed restart attempt.\n            result = subprocess.run([\'systemd-run\', \'--collect\', \'--on-active=3s\',\n                                     \'--timer-property=AccuracySec=1s\',\n                                     \'/usr/bin/systemctl\', \'reboot\'],\n                                    capture_output=True, text=True, timeout=15)\n            if result.returncode:\n                detail = (result.stderr or result.stdout or \'No system details returned.\').strip()\n                self.log(\'Restart scheduling failed: \' + detail)\n                raise ValueError(\'Could not schedule the restart. See installation details, then try again.\')\n            self.change(phase=\'rebooting\', question=None,\n                        message=\'Restarting. Return to the camera web page once the camera starts.\')\n\n    def log(self, line):\n        line = re.sub(r\'\\x1b\\[[0-9;]*[A-Za-z]\', \'\', line)[-4096:]\n        with self.lock:\n            self.state[\'log\'] = (self.state[\'log\'] + [line])[-160:]\n            self.save()\n\n    def upload(self, stream, length, label):\n        with self.lock:\n            if self.state[\'phase\'] in ACTIVE or self.state[\'phase\'] in (\'ready\', \'rebooting\'):\n                raise ValueError(\'Finish the current update and restart before uploading another ZIP.\')\n            if length <= 0 or length > MAX_ZIP:\n                raise ValueError(\'Choose a ZIP smaller than 128 MB.\')\n            if shutil.disk_usage(self.directory).free < length + MAX_EXPANDED + RESERVE:\n                raise ValueError(\'Not enough free space to safely unpack this update.\')\n            self.change(phase=\'uploading\', message=\'Receiving update ZIP…\', package=None,\n                        question=None, selection=None, log=[])\n        work = Path(tempfile.mkdtemp(prefix=\'incoming-\', dir=self.directory))\n        try:\n            path = work / \'upload.zip\'\n            with path.open(\'wb\') as f:\n                remaining = length\n                while remaining:\n                    block = stream.read(min(1024 * 1024, remaining))\n                    if not block:\n                        raise ValueError(\'Upload interrupted. Please upload the ZIP again.\')\n                    f.write(block)\n                    remaining -= len(block)\n            self.change(message=\'Checking update files…\')\n            package = inspect_zip(path)\n            release = work / \'release\'\n            release.mkdir()\n            extract_release(path, release, package)\n            dest = self.directory / \'release\'\n            if dest.exists():\n                shutil.rmtree(dest)\n            os.replace(release, dest)\n            public = {\'software\': package[\'software\'], \'drivers\': package[\'drivers\'],\n                      \'libcamera_drivers\': [name for name in package[\'drivers\']\n                          if \'--update-libcamera\' in (dest / name).read_text(encoding=\'utf-8\')],\n                      \'label\': label[:100], \'id\': secrets.token_hex(16)}\n            self.change(phase=\'uploaded\', package=public, message=\'Update checked. Choose what to install.\')\n        except Exception as exc:\n            self.change(phase=\'failed\', package=None, message=str(exc))\n            raise\n        finally:\n            shutil.rmtree(work)\n\n    def start(self, payload):\n        with self.lock:\n            package = self.state.get(\'package\')\n            if self.state[\'phase\'] not in (\'uploaded\', \'failed\') or not package:\n                raise ValueError(\'Upload an update ZIP first, or wait for the current update.\')\n            if payload.get(\'package_id\') != package[\'id\'] or payload.get(\'confirmed\') is not True:\n                raise ValueError(\'Review and confirm the currently uploaded update.\')\n            kind = payload.get(\'kind\')\n            if kind == \'software\' and not package[\'software\']:\n                raise ValueError(\'This ZIP does not contain both update.sh and wlf8.py.\')\n            if kind == \'driver\' and payload.get(\'driver\') not in package[\'drivers\']:\n                raise ValueError(\'Choose a driver provided in this ZIP.\')\n            if kind not in (\'software\', \'driver\'):\n                raise ValueError(\'Choose camera software or camera driver.\')\n            if kind == \'driver\':\n                script = (self.directory / \'release\' / payload[\'driver\']).read_text(encoding=\'utf-8\')\n                if \'WLV_WEB_UI\' not in script or PROMPT_PREFIX.strip() not in script:\n                    raise ValueError(\'This driver installer predates web confirmations. Ask for an updated ZIP.\')\n                if payload.get(\'libcamera\') and \'--update-libcamera\' not in script:\n                    raise ValueError(\'This driver does not support the camera-library option.\')\n                if (payload.get(\'libcamera\') and payload[\'driver\'] == \'install_imx294_imx492_driver.sh\'\n                        and not (self.directory / \'release/patches/libcamera/apply_qbc.py\').is_file()):\n                    raise ValueError(\'This ZIP is missing the libcamera patch files. Ask for a complete driver release.\')\n            self.change(phase=\'installing\', message=\'Preparing camera…\', question=None,\n                        selection=kind, driver=payload.get(\'driver\'),\n                        libcamera=bool(payload.get(\'libcamera\')), log=[], job=secrets.token_hex(16))\n            threading.Thread(target=self.install, args=(dict(payload),), daemon=False).start()\n\n    def question(self, text):\n        prompt_id = secrets.token_hex(16)\n        self.answer_ready.clear()\n        self.answer_value = None\n        self.change(phase=\'question\', question={\'id\': prompt_id, \'text\': str(text)[:2000]},\n                    message=\'Your answer is needed to continue.\')\n        self.answer_ready.wait()  # Disconnects and elapsed time never imply consent.\n        answer = self.answer_value\n        self.change(phase=\'installing\', question=None, message=\'Continuing installation…\')\n        return answer\n\n    def answer(self, payload):\n        with self.lock:\n            question = self.state.get(\'question\')\n            if (not question or payload.get(\'id\') != question[\'id\']\n                    or payload.get(\'job\') != self.state.get(\'job\')\n                    or type(payload.get(\'answer\')) is not bool or self.answer_ready.is_set()):\n                raise ValueError(\'This question is no longer waiting for an answer.\')\n            self.answer_value = payload[\'answer\']\n            self.answer_ready.set()\n\n    def run_script(self, command, interactive=False, working_directory=None):\n        import pwd\n        account = pwd.getpwuid(os.geteuid())\n        env = dict(os.environ, DEBIAN_FRONTEND=\'noninteractive\', NEEDRESTART_MODE=\'a\',\n                   WLV_WEB_UI=\'1\', WLV_NO_REBOOT=\'1\', HOME=account.pw_dir,\n                   USER=account.pw_name, LOGNAME=account.pw_name)\n        env[\'PATH\'] = env.get(\'PATH\') or \'/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin\'\n        process = subprocess.Popen(command, cwd=working_directory or self.directory / \'release\', env=env,\n                                   stdin=subprocess.PIPE if interactive else subprocess.DEVNULL,\n                                   stdout=subprocess.PIPE, stderr=subprocess.STDOUT,\n                                   start_new_session=True)\n        deadline = time.monotonic() + 7200\n        pending = b\'\'\n        selector = selectors.DefaultSelector()\n        selector.register(process.stdout, selectors.EVENT_READ)\n        try:\n            while selector.get_map():\n                if time.monotonic() > deadline:\n                    raise TimeoutError(\'Installation exceeded two hours. Review the log before retrying.\')\n                for key, _ in selector.select(1):\n                    chunk = os.read(key.fileobj.fileno(), 4096)\n                    if not chunk:\n                        selector.unregister(key.fileobj)\n                        continue\n                    pending += chunk\n                    while b\'\\n\' in pending or len(pending) > 16384:\n                        if b\'\\n\' in pending:\n                            line, pending = pending.split(b\'\\n\', 1)\n                        else:\n                            line, pending = pending[:16384], pending[16384:]\n                        text = line.decode(\'utf-8\', errors=\'replace\').rstrip(\'\\r\')\n                        if interactive and text.startswith(PROMPT_PREFIX):\n                            before = time.monotonic()\n                            answer = self.question(json.loads(text[len(PROMPT_PREFIX):]))\n                            deadline += time.monotonic() - before\n                            process.stdin.write(b\'y\\n\' if answer else b\'n\\n\')\n                            process.stdin.flush()\n                        else:\n                            self.log(text)\n            if pending:\n                self.log(pending.decode(\'utf-8\', errors=\'replace\'))\n            rc = process.wait(timeout=max(1, deadline - time.monotonic()))\n            if rc:\n                raise RuntimeError(\'The installer stopped (exit %s). See installation details below.\' % rc)\n        finally:\n            selector.close()\n            if process.poll() is None:\n                import signal\n                os.killpg(process.pid, signal.SIGTERM)\n                try:\n                    process.wait(timeout=15)\n                except subprocess.TimeoutExpired:\n                    os.killpg(process.pid, signal.SIGKILL)\n                    process.wait()\n            process.stdout.close()\n            if process.stdin:\n                process.stdin.close()\n\n    def install(self, payload):\n        try:\n            if shutil.disk_usage(self.directory).free < RESERVE:\n                raise ValueError(\'At least 512 MB free space is required before installation.\')\n            if not self.state.get(\'camera_stopped\'):\n                self.config = json.loads((self.directory / \'access.json\').read_text())\n                request = urllib.request.Request(self.config[\'camera_url\'] + \'/api/web-update/prepare\',\n                    data=b\'{}\', headers={\'X-WLV-Token\': self.config[\'camera_token\'],\n                                        \'Content-Type\': \'application/json\'})\n                try:\n                    with urllib.request.urlopen(request, timeout=15) as response:\n                        result = json.load(response)\n                except urllib.error.HTTPError as exc:\n                    result = json.load(exc)\n                    raise ValueError(result.get(\'reason\', \'Camera preparation failed.\')) from exc\n                if not result.get(\'ok\'):\n                    raise ValueError(result.get(\'reason\', \'Put the camera in Charge mode first.\'))\n                subprocess.run(self.config[\'stop_command\'], check=True, timeout=90,\n                               stdin=subprocess.DEVNULL, capture_output=True)\n                self.change(camera_stopped=True)\n            release = self.directory / \'release\'\n            if payload[\'kind\'] == \'driver\':\n                self.change(message=\'Installing camera driver. This can take a while…\')\n                with stage_driver(release, payload[\'driver\']) as staged:\n                    command = [\'bash\', str(staged / payload[\'driver\']), \'--no-reboot\']\n                    if payload.get(\'libcamera\'):\n                        command.append(\'--update-libcamera\')\n                    self.run_script(command, interactive=True, working_directory=staged)\n            else:\n                self.change(message=\'Installing system updates…\')\n                self.run_script([\'bash\', str(release / \'update.sh\')], interactive=True)\n                self.change(message=\'Installing camera software…\')\n                replace_firmware(release / \'wlf8.py\', self.config[\'target\'])\n            os.sync()\n            self.change(phase=\'ready\', question=None,\n                        message=\'Installation completed. Restart the camera to apply the update.\')\n        except Exception as exc:\n            if not self.state.get(\'camera_stopped\'):\n                # If stopping the service failed, release the application\'s\n                # Charge-mode gate so it does not remain stuck in preparation.\n                try:\n                    request = urllib.request.Request(self.config[\'camera_url\'] + \'/api/web-update/cancel-prepare\',\n                        data=b\'{}\', headers={\'X-WLV-Token\': self.config[\'camera_token\']})\n                    with urllib.request.urlopen(request, timeout=5):\n                        pass\n                except Exception:\n                    pass\n            self.log(str(exc))\n            self.change(phase=\'failed\', question=None,\n                        message=(\'Update stopped: \' + str(exc)[:500] +\n                                 (\' System or driver changes may already have been applied; review the details before retrying or restarting.\'\n                                  if self.state.get(\'camera_stopped\') else \' You can retry when the camera is ready.\')))\n\n\nPAGE = \'\'\'<!doctype html><html lang="en"><meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1"><title>Camera updates</title>\n<style>\n  :root {\n    --bg: #0f0e0c;\n    --panel: #17150f;\n    --panel-2: #1e1c16;\n    --text: #eae5da;\n    --muted: #8e8879;\n    --faint: #5b564b;\n    --accent: #c49a4a;\n    --accent-strong: #d8ae5c;\n    --accent-rgb: 196,154,74;\n    --on-accent: #171307;\n    --danger: #c25b4a;\n    --border: rgba(234,229,217,0.08);\n    --border-strong: rgba(234,229,217,0.16);\n    --r: 5px;\n    --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;\n    --mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;\n  }\n  * { box-sizing: border-box; }\n  html, body { margin: 0; padding: 0; background: var(--bg); color: var(--text);\n    font: 15px/1.4 var(--sans); -webkit-font-smoothing: antialiased; }\n  body { padding-left: env(safe-area-inset-left);\n    padding-right: env(safe-area-inset-right); }\n  header { position: sticky; top: 0; z-index: 10; background: rgba(15,14,12,0.97);\n    backdrop-filter: blur(8px); border-bottom: 1px solid var(--border); }\n  .wrap { max-width: 1100px; margin: 0 auto; padding: 14px 16px; }\n  /* -------- Masthead -------- */\n  .title-row { display: flex; align-items: flex-start;\n    justify-content: space-between; gap: 12px; margin-bottom: 4px; }\n  .wordmark { font-weight: 700; font-size: 20px; letter-spacing: 2.5px;\n    line-height: 1.1; }\n  .wordmark .dash { color: var(--accent); }\n  .byline { font-family: var(--mono); font-size: 8px; font-weight: 500;\n    letter-spacing: 1.8px; color: var(--muted); margin-top: 5px;\n    text-transform: uppercase; white-space: nowrap; }\n  /* Maintenance pages share the main interface\'s Settings layout. */\n  main.wrap { padding-top: 18px; padding-bottom: 40px; }\n  h1 { font-size: 18px; font-weight: 600; margin: 0 0 8px; }\n  h2 { font-size: 14px; font-weight: 600; margin: 0 0 12px; line-height: 1.5; }\n  p { line-height: 1.5; color: var(--muted); overflow-wrap: anywhere; }\n  a { color: var(--accent-strong); text-underline-offset: 3px; }\n  .page-nav { display: flex; flex-wrap: wrap; gap: 18px; padding-top: 14px;\n    font-size: 11px; font-weight: 600; letter-spacing: 1px; }\n  .page-nav span { color: var(--text); border-bottom: 2px solid var(--accent); padding-bottom: 9px; }\n  .page-nav a { color: var(--muted); text-decoration: none; }\n  section { background: var(--panel); border: 1px solid var(--border);\n    border-radius: 6px; padding: 16px; margin: 12px 0; min-width: 0; }\n  label { display: block; font-size: 14px; font-weight: 600; margin: 10px 0 4px; }\n  button, select, input { font-family: var(--sans); font-size: 14px; max-width: 100%; }\n  button { background: var(--panel-2); color: var(--text); border: 1px solid var(--border);\n    border-radius: var(--r); padding: 9px 14px; cursor: pointer; margin: 4px 4px 4px 0; }\n  button.primary { background: var(--accent); color: var(--on-accent); border-color: var(--accent); font-weight: 600; }\n  button.primary:hover:not(:disabled) { background: var(--accent-strong); }\n  button:hover:not(:disabled) { border-color: var(--border-strong); }\n  button:disabled, select:disabled, input:disabled { opacity: .5; cursor: default; }\n  button:focus-visible, select:focus-visible, input:focus-visible, a:focus-visible, summary:focus-visible {\n    outline: 2px solid var(--accent-strong); outline-offset: 3px; }\n  select { background: var(--panel-2); border: 1px solid var(--border-strong); color: var(--text);\n    border-radius: var(--r); padding: 8px 10px; margin: 4px 0 10px; color-scheme: dark; }\n  input[type=file] { display: block; width: 100%; margin: 8px 0; color: var(--muted); }\n  input::file-selector-button { font: inherit; background: var(--panel-2); color: var(--text);\n    border: 1px solid var(--border-strong); border-radius: var(--r); padding: 9px 12px; margin-right: 10px; }\n  input[type=checkbox] { accent-color: var(--accent); width: 16px; height: 16px; vertical-align: middle; }\n  #sensor, #port, #driver, #kind { width: 100%; max-width: 480px; display: block; }\n  .actions { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; }\n  .actions #kind { width: auto; margin: 4px 0; }\n  #status { white-space: pre-wrap; color: var(--text); }\n  #error { color: var(--danger); }\n  pre { font: 11px/1.6 var(--mono); white-space: pre-wrap; overflow-wrap: anywhere;\n    max-height: 350px; overflow: auto; background: var(--bg); border-radius: var(--r); padding: 12px; }\n  summary { cursor: pointer; font-size: 13px; color: var(--muted); }\n  progress { width: 100%; accent-color: var(--accent); }\n  [hidden] { display: none !important; }\n  article { display: flex; flex-wrap: wrap; gap: 14px; align-items: center;\n    padding: 16px; margin: 12px 0; background: var(--panel); border: 1px solid var(--border); border-radius: 6px; }\n  article img { width: 120px; border-radius: var(--r); }\n  article > div { flex: 1 1 220px; min-width: 0; }\n  article p { margin: 0 0 8px; font-size: 13px; }\n  article a { display: inline-block; margin-right: 12px; font-size: 13px; }\n  article button { display: block; color: var(--danger); }\n  @media (max-width: 480px) {\n    .actions { align-items: stretch; }\n    .actions button, .actions #kind { flex: 1 1 100%; margin-right: 0; }\n    select { width: 100%; }\n  }\n</style>\n<header><div class="wrap"><div class="title-row"><div><div class="wordmark">WLV<span class="dash">-</span>01</div><div class="byline">CAMERA CONTROL</div></div></div><nav class="page-nav" aria-label="Page"><span>Camera updates</span></nav></div></header><main class="wrap"><h1>Camera updates</h1><p>Upload the ZIP supplied for your camera. Choose which part to update.</p>\n<section><label for="file">Update ZIP</label><input id="file" type="file" accept=".zip,application/zip">\n<button class="primary" id="upload">Upload and check</button><progress id="progress" hidden max="100"></progress>\n<p id="package"></p><label for="kind">What would you like to install?</label>\n<select id="kind" disabled><option value="software">Camera software — system update + camera application</option><option value="driver">Camera driver</option></select>\n<div id="driverOptions" hidden><label for="driver">Driver installer</label><select id="driver"></select>\n<label id="libraryOption"><input id="libcamera" type="checkbox"> Also update the camera libraries (libcamera)</label></div>\n<p>Connect external power and put the camera in Charge mode. The camera screen will stop during installation. Driver and system updates may need an internet connection on the camera.</p>\n<label><input id="confirm" type="checkbox"> I am ready to install this update and will keep the camera powered on.</label>\n<button class="primary" id="install" disabled>Install selected update</button></section>\n<section aria-live="polite"><h2 id="status">Connecting…</h2><p id="error"></p>\n<div id="question" hidden><p id="questionText"></p><button class="primary" id="yes">Yes, continue</button> <button id="no" class="secondary">No</button></div>\n<div id="restart" hidden><button class="primary" id="reboot">Restart now</button> <button id="later" class="secondary">Later</button><p id="laterText" hidden>You can leave this page open or close it. The update is installed; the camera stays stopped until you restart it.</p></div>\n<details><summary>Installation details</summary><pre id="log"></pre></details></section></main>\n<script>\nconst $=id=>document.getElementById(id);\nconst token=location.hash.slice(1)||sessionStorage.getItem(\'wlvUpdateToken\')||\'\';\nif(location.hash){sessionStorage.setItem(\'wlvUpdateToken\',token);history.replaceState(null,\'\',location.pathname);}\nlet state=null,busy=false,lastPackage=\'\',answering=false,rebootPending=false;\nasync function api(path,data){const r=await fetch(path,{method:data?\'POST\':\'GET\',headers:{\'X-WLV-Token\':token,\'Content-Type\':\'application/json\'},body:data?JSON.stringify(data):undefined,cache:\'no-store\'});const result=await r.json();if(!r.ok)throw Error(result.reason||\'Request failed\');return result;}\nfunction choices(){const p=state&&state.package;const active=busy||rebootPending||state&&[\'uploading\',\'installing\',\'question\',\'ready\',\'rebooting\'].includes(state.phase);$(\'driverOptions\').hidden=$(\'kind\').value!==\'driver\';$(\'install\').disabled=!p||active||!$(\'confirm\').checked;$(\'upload\').disabled=!!active;$(\'kind\').disabled=!p||active;$(\'driver\').disabled=!!active;$(\'confirm\').disabled=!!active;$(\'libcamera\').disabled=!!active;const libraries=p&&(p.libcamera_drivers||[]).includes($(\'driver\').value);$(\'libraryOption\').hidden=!libraries;if(!libraries)$(\'libcamera\').checked=false;}\nfunction render(s){if(state&&state.phase===\'rebooting\'&&![\'rebooting\',\'idle\'].includes(s.phase))return;state=s;$(\'status\').textContent=s.message;$(\'log\').textContent=(s.log||[]).join(\'\\\\n\');\nif(s.package&&s.package.id!==lastPackage){lastPackage=s.package.id;$(\'package\').textContent=s.package.label;$(\'kind\').options[0].disabled=!s.package.software;$(\'kind\').options[1].disabled=!s.package.drivers.length;$(\'kind\').value=s.package.software?\'software\':\'driver\';$(\'driver\').replaceChildren(...s.package.drivers.map(n=>new Option(n.replace(/^install_/,\'\').replace(/_driver\\\\.sh$/,\'\').replaceAll(\'_\',\' / \').toUpperCase(),n)));$(\'confirm\').checked=false;}\nif(!s.package){$(\'package\').textContent=\'\';lastPackage=\'\';}\nif(s.selection&&[\'installing\',\'question\',\'ready\'].includes(s.phase)){$(\'kind\').value=s.selection;if(s.driver)$(\'driver\').value=s.driver;$(\'libcamera\').checked=!!s.libcamera;$(\'confirm\').checked=true;}\n$(\'question\').hidden=!s.question;$(\'questionText\').textContent=s.question?s.question.text:\'\';$(\'yes\').disabled=$(\'no\').disabled=answering;\n$(\'restart\').hidden=!(s.phase===\'ready\'||s.phase===\'failed\'&&s.camera_stopped);$(\'later\').hidden=s.phase!==\'ready\';$(\'reboot\').disabled=rebootPending||s.phase===\'rebooting\';$(\'later\').disabled=rebootPending;choices();}\nasync function poll(){try{render(await api(\'/api/status\'));}catch(e){if(!state||state.phase!==\'rebooting\')$(\'status\').textContent=\'Connection interrupted. Reconnecting…\';}setTimeout(poll,2000);}\n$(\'kind\').onchange=choices;$(\'driver\').onchange=choices;$(\'confirm\').onchange=choices;\n$(\'upload\').onclick=()=>{const f=$(\'file\').files[0];if(!f){$(\'error\').textContent=\'Choose an update ZIP first.\';return;}if(f.size>134217728){$(\'error\').textContent=\'Choose a ZIP smaller than 128 MB.\';return;}\nbusy=true;choices();$(\'error\').textContent=\'\';$(\'progress\').hidden=false;\nconst x=new XMLHttpRequest();x.open(\'POST\',\'/api/upload\');x.setRequestHeader(\'X-WLV-Token\',token);x.setRequestHeader(\'X-Update-Name\',encodeURIComponent(f.name));x.upload.onprogress=e=>{if(e.lengthComputable)$(\'progress\').value=100*e.loaded/e.total;};x.onload=()=>{busy=false;$(\'progress\').hidden=true;try{const s=JSON.parse(x.responseText);if(x.status!==200)throw Error(s.reason);render(s);}catch(e){$(\'error\').textContent=e.message;}choices();};x.onerror=()=>{busy=false;choices();$(\'error\').textContent=\'Upload connection lost. Check the status before trying again.\';};x.send(f);};\n$(\'install\').onclick=async()=>{busy=true;choices();$(\'error\').textContent=\'\';try{render(await api(\'/api/install\',{package_id:state.package.id,kind:$(\'kind\').value,driver:$(\'driver\').value,libcamera:$(\'libcamera\').checked,confirmed:$(\'confirm\').checked}));}catch(e){$(\'error\').textContent=e.message;}finally{busy=false;choices();}};\nasync function answer(value){if(!state.question||answering)return;answering=true;$(\'yes\').disabled=$(\'no\').disabled=true;try{await api(\'/api/answer\',{id:state.question.id,job:state.job,answer:value});}catch(e){$(\'error\').textContent=e.message;}finally{answering=false;}}\n$(\'yes\').onclick=()=>answer(true);$(\'no\').onclick=()=>answer(false);\n$(\'reboot\').onclick=async()=>{if(rebootPending||state&&state.phase===\'rebooting\')return;rebootPending=true;$(\'reboot\').disabled=true;$(\'later\').disabled=true;$(\'error\').textContent=\'\';choices();try{render(await api(\'/api/reboot\',{}));}catch(e){$(\'error\').textContent=e.message;}finally{rebootPending=false;if(state)render(state);}};\n$(\'later\').onclick=()=>{$(\'laterText\').hidden=false;};\nif(token)poll();else $(\'status\').textContent=\'Open Updates from the camera web interface to connect.\';\n</script></html>\'\'\'\n\n\nclass Handler(http.server.BaseHTTPRequestHandler):\n    def log_message(self, *_args):\n        pass  # Never log headers, credentials or uploaded filenames.\n\n    def send(self, status, value, html=False):\n        data = (value if html else json.dumps(value)).encode(\'utf-8\')\n        self.send_response(status)\n        self.send_header(\'Content-Type\', \'text/html; charset=utf-8\' if html else \'application/json\')\n        self.send_header(\'Content-Length\', str(len(data)))\n        self.send_header(\'Cache-Control\', \'no-store\')\n        self.send_header(\'X-Content-Type-Options\', \'nosniff\')\n        self.send_header(\'Referrer-Policy\', \'no-referrer\')\n        self.send_header(\'X-Frame-Options\', \'DENY\')\n        self.end_headers()\n        self.wfile.write(data)\n\n    def authorized(self):\n        return hmac.compare_digest(self.headers.get(\'X-WLV-Token\', \'\'), self.server.token)\n\n    def do_GET(self):\n        if self.path == \'/\':\n            self.send(200, PAGE, html=True)\n        elif not self.authorized():\n            self.send(403, {\'reason\': \'Open Updates from the camera web interface again.\'})\n        elif self.path == \'/api/status\':\n            self.send(200, self.server.manager.snapshot())\n        else:\n            self.send(404, {\'reason\': \'Not found\'})\n\n    def do_POST(self):\n        self.close_connection = True\n        if not self.authorized():\n            self.send(403, {\'reason\': \'Open Updates from the camera web interface again.\'})\n            return\n        try:\n            length = int(self.headers.get(\'Content-Length\', \'0\'))\n            if self.headers.get(\'Transfer-Encoding\'):\n                raise ValueError(\'A fixed upload size is required.\')\n            manager = self.server.manager\n            if self.path == \'/api/upload\':\n                from urllib.parse import unquote\n                self.connection.settimeout(60)\n                manager.upload(self.rfile, length, unquote(self.headers.get(\'X-Update-Name\', \'Update ZIP\')))\n            else:\n                if not 0 < length <= 4096:\n                    raise ValueError(\'Invalid request size.\')\n                self.connection.settimeout(15)\n                payload = json.loads(self.rfile.read(length))\n                if not isinstance(payload, dict):\n                    raise ValueError(\'Invalid request.\')\n                if self.path == \'/api/install\':\n                    manager.start(payload)\n                elif self.path == \'/api/answer\':\n                    manager.answer(payload)\n                elif self.path == \'/api/reboot\':\n                    manager.reboot()\n                else:\n                    raise ValueError(\'Unknown update action.\')\n            self.send(200, manager.snapshot())\n        except Exception as exc:\n            self.send(400, {\'reason\': str(exc)[:2000]})\n\n\ndef main():\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\'--directory\', required=True)\n    args = parser.parse_args()\n    directory = Path(args.directory)\n    os.umask(0o077)\n    import fcntl\n    with (directory / \'service.lock\').open(\'w\') as lock:\n        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)\n        config = json.loads((directory / \'access.json\').read_text())\n        server = http.server.ThreadingHTTPServer((\'0.0.0.0\', PORT), Handler)\n        server.token = config[\'token\']\n        server.manager = Manager(directory, config)\n        server.serve_forever()\n\n\nif __name__ == \'__main__\':\n    main()\n'
# END EMBEDDED WEB UPDATER

# -------------------- Update prompt --------------------

UPDATE_FILENAME = "update.py"
UPDATE_SH_FILENAME = "update.sh"
_UPDATE_WINDOW_NAME = "Camera Update"


def _wrap_update_lines(text, width=36):
    if not text:
        return [""]
    wrapped = []
    for raw_line in str(text).splitlines():
        segments = textwrap.wrap(raw_line, width=width) or [""]
        wrapped.extend(segments)
    return wrapped or [""]


def _find_update_file():
    candidates = []
    candidates.append(Path(USB_MOUNT_POINT) / UPDATE_FILENAME)
    with _capture_dir_lock:
        capture_dir = _capture_dir
    if capture_dir:
        candidates.append(Path(capture_dir) / UPDATE_FILENAME)
    seen = set()
    for path in candidates:
        try:
            resolved = Path(path)
        except Exception:
            continue
        key = resolved.resolve().as_posix() if resolved.exists() else str(resolved)
        if key in seen:
            continue
        seen.add(key)
        if resolved.is_file():
            return resolved
    return None


def _find_update_sh_file(update_path=None):
    candidates = []
    if update_path is not None:
        try:
            candidates.append(Path(update_path).parent / UPDATE_SH_FILENAME)
        except Exception:
            pass
    candidates.append(Path(USB_MOUNT_POINT) / UPDATE_SH_FILENAME)
    with _capture_dir_lock:
        capture_dir = _capture_dir
    if capture_dir:
        candidates.append(Path(capture_dir) / UPDATE_SH_FILENAME)
    seen = set()
    for path in candidates:
        try:
            resolved = Path(path)
        except Exception:
            continue
        key = resolved.resolve().as_posix() if resolved.exists() else str(resolved)
        if key in seen:
            continue
        seen.add(key)
        if resolved.is_file():
            return resolved
    return None


# Current firmware is ~750 KB; anything drastically smaller can't possibly be
# a valid replacement, so reject it outright before it ever touches the
# installed file (single-file firmware, no fallback UI if it bricks on boot).
_UPDATE_MIN_SIZE_BYTES = 100 * 1024


def _apply_update_from_file(update_path):
    dest_path = Path(__file__).resolve()
    tmp_path = None
    try:
        data = Path(update_path).read_bytes()
    except Exception as exc:
        return False, f"Read error: {exc}"

    # Validate before touching the installed firmware. A truncated/corrupt
    # update.py has no way to be recovered from on this appliance (no other
    # UI), so a syntax check + minimum-size sanity check gate the install.
    if len(data) < _UPDATE_MIN_SIZE_BYTES:
        return False, "Update file is corrupt — not installed (file too small)"
    try:
        compile(data, str(update_path), "exec")
    except (SyntaxError, ValueError) as exc:
        return False, f"Update file is corrupt — not installed ({exc})"
    except Exception as exc:
        return False, f"Update file is corrupt — not installed ({exc})"

    # Snapshot the currently-running firmware before replacing it so a bad
    # install can be rolled back (see _finalize_update_and_reboot, which
    # re-validates the installed file and restores this backup on failure).
    # The .bak also doubles as a manual-recovery path over SSH:
    # `cp "wlf8.py.bak" wlf8.py`.
    bak_path = Path(str(dest_path) + ".bak")
    try:
        shutil.copy2(dest_path, bak_path)
    except Exception as exc:
        print("Update backup error (continuing):", exc)

    try:
        fd, tmp_path = tempfile.mkstemp(
            prefix=f"{dest_path.stem}_update_",
            suffix=".tmp",
            dir=str(dest_path.parent),
        )
        with os.fdopen(fd, "wb") as tmp:
            tmp.write(data)
            tmp.flush()
            os.fsync(tmp.fileno())
        os.replace(tmp_path, dest_path)
        os.chmod(dest_path, 0o755)
    except Exception as exc:
        if tmp_path and os.path.exists(tmp_path):
            try:
                os.remove(tmp_path)
            except Exception:
                pass
        return False, f"Write error: {exc}"
    try:
        Path(update_path).unlink()
    except Exception as exc:
        print("Update cleanup error:", exc)
    return True, None


# Hard ceiling so a hung/misbehaving update.sh can never stall the update
# flow (or the boot-time background path) indefinitely.
_UPDATE_SH_TIMEOUT_S = 600


def _mark_update_sh_failed(script_path):
    """Rename a failed update.sh to update.sh.failed so it cannot re-execute
    on every subsequent boot. Guarded: a rename error just leaves the
    original script in place, which is safe (worst case, one more attempt)."""
    try:
        script_path = Path(script_path)
        failed_path = script_path.with_name(script_path.name + ".failed")
        if failed_path.exists():
            failed_path.unlink()
        script_path.rename(failed_path)
    except Exception as exc:
        print("update.sh failure-rename error:", exc)


def _run_update_sh(script_path):
    script_path = Path(script_path)
    try:
        try:
            os.chmod(script_path, 0o755)
        except Exception:
            pass
        result = subprocess.run(
            ["bash", str(script_path)],
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            stdin=subprocess.DEVNULL,
            text=True,
            check=False,
            timeout=_UPDATE_SH_TIMEOUT_S,
        )
    except subprocess.TimeoutExpired:
        _mark_update_sh_failed(script_path)
        return False, f"update.sh timed out after {_UPDATE_SH_TIMEOUT_S}s — not re-run"
    except Exception as exc:
        _mark_update_sh_failed(script_path)
        return False, f"update.sh error: {exc}"
    if result.stdout:
        print(result.stdout)
    if result.returncode != 0:
        tail_lines = (result.stdout or "").strip().splitlines()
        tail = tail_lines[-1] if tail_lines else ""
        _mark_update_sh_failed(script_path)
        return False, f"update.sh exit {result.returncode}: {tail}"
    try:
        script_path.unlink()
    except Exception as exc:
        print("update.sh cleanup error:", exc)
    try:
        os.sync()
    except Exception:
        pass
    return True, None


def _run_update_sh_background(script_path):
    def _worker():
        # Defer until lazy startup has finished so the script's I/O (and the
        # trailing os.sync()) doesn't stall the camera pipeline during boot.
        _lazy_load_ready.wait()
        ok, err = _run_update_sh(script_path)
        if ok:
            print(f"Background update.sh completed: {script_path}")
        else:
            print(f"Background update.sh failed: {err}")

    # Non-daemon so interpreter exit waits for the script; otherwise a mid-run
    # shutdown could leave apt/dpkg or partial writes in an inconsistent state.
    threading.Thread(
        target=_worker,
        name="update-sh-bg",
        daemon=False,
    ).start()


def _finalize_update_and_reboot():
    # Re-validate the just-installed firmware before committing to a reboot.
    # A write that landed truncated/corrupted despite passing the pre-install
    # compile() check in _apply_update_from_file would otherwise brick the
    # camera with no UI to recover — so read it back and compile() again, and
    # roll back to the pre-update .bak (written by _apply_update_from_file)
    # on any failure. The .bak is left in place either way for manual
    # recovery over SSH.
    dest_path = Path(__file__).resolve()
    bak_path = Path(str(dest_path) + ".bak")
    try:
        installed = dest_path.read_bytes()
        compile(installed, str(dest_path), "exec")
    except Exception as exc:
        print("Post-install verification failed:", exc)
        if bak_path.exists():
            try:
                shutil.copy2(bak_path, dest_path)
                os.chmod(dest_path, 0o755)
            except Exception as restore_exc:
                print("Update rollback error:", restore_exc)
                return False, f"Update verification failed and rollback errored: {restore_exc}"
        return False, "Update verification failed — previous firmware restored"
    try:
        _display_close_all()
    except Exception:
        pass
    return _issue_system_reboot()


def _show_update_status(window_name, message):
    canvas = np.zeros((SCREEN_H, SCREEN_W, 3), dtype=np.uint8)
    lines = [[line] for line in _wrap_update_lines(message)]
    block = make_rotated_text_block(
        lines,
        font_scale=1.1,
        thickness=1,
        rotate_180=True,
        max_h=SCREEN_H - 120,
        pad_x=12,
        pad_y=10,
        line_gap=8,
    )
    bh, bw = block.shape[:2]
    bx = max(0, (SCREEN_W - bw) // 2)
    by = max(0, (SCREEN_H - bh) // 2)
    blit_add(canvas, block, bx, by)
    _display_show(window_name, canvas)
    _display_pump(1)


def _show_update_error(window_name, message):
    acknowledged = {"value": False}

    def _ack_cb(event, x, y, flags, param):
        if event == cv2.EVENT_LBUTTONUP:
            acknowledged["value"] = True

    _display_set_mouse_callback(window_name, _ack_cb)
    while not acknowledged["value"]:
        canvas = np.zeros((SCREEN_H, SCREEN_W, 3), dtype=np.uint8)
        lines = [["Update failed"]]
        for line in _wrap_update_lines(message):
            lines.append([line])
        lines.append(["Tap to continue"])
        block = make_rotated_text_block(
            lines,
            font_scale=1.0,
            thickness=1,
            rotate_180=True,
            max_h=SCREEN_H - 120,
            pad_x=12,
            pad_y=10,
            line_gap=8,
        )
        bh, bw = block.shape[:2]
        bx = max(0, (SCREEN_W - bw) // 2)
        by = max(0, (SCREEN_H - bh) // 2)
        blit_add(canvas, block, bx, by)
        _display_show(window_name, canvas)
        key = _display_pump(50)
        if key != -1:
            acknowledged["value"] = True
    _display_set_mouse_callback(window_name, lambda *args: None)


def _prompt_for_update(update_path):
    window_name = _UPDATE_WINDOW_NAME
    selection = {"choice": None}
    sh_path = _find_update_sh_file(update_path)
    btn_w = 180
    btn_h = 110
    center_y = SCREEN_H // 2 + 60
    yes_rect = (
        SCREEN_W // 2 - btn_w - 20,
        center_y,
        SCREEN_W // 2 - 20,
        center_y + btn_h,
    )
    no_rect = (
        SCREEN_W // 2 + 20,
        center_y,
        SCREEN_W // 2 + btn_w + 20,
        center_y + btn_h,
    )

    def _touch_cb(event, x, y, flags, param):
        if event == cv2.EVENT_LBUTTONUP:
            if _point_in_rect(x, y, yes_rect):
                selection["choice"] = True
            elif _point_in_rect(x, y, no_rect):
                selection["choice"] = False

    _display_open_window(window_name)
    _display_set_mouse_callback(window_name, _touch_cb)

    while selection["choice"] is None:
        canvas = np.zeros((SCREEN_H, SCREEN_W, 3), dtype=np.uint8)
        lines = [
            ["Software update available"],
            [f"{update_path.name} detected on USB"],
        ]
        if sh_path is not None:
            lines.append([f"{sh_path.name} will also run"])
        lines.append(["Install update now?"])
        block = make_rotated_text_block(
            lines,
            font_scale=1.15,
            thickness=1,
            rotate_180=True,
            max_h=SCREEN_H - 220,
            pad_x=14,
            pad_y=12,
            line_gap=10,
        )
        bh, bw = block.shape[:2]
        bx = max(0, (SCREEN_W - bw) // 2)
        by = max(40, (SCREEN_H - bh) // 2 - 60)
        blit_add(canvas, block, bx, by)

        for label, rect, color in (
            ("Yes", yes_rect, (60, 140, 80)),
            ("No", no_rect, (80, 80, 80)),
        ):
            x1, y1, x2, y2 = rect
            cv2.rectangle(canvas, (x1, y1), (x2, y2), color, -1)
            cv2.rectangle(canvas, (x1, y1), (x2, y2), (230, 230, 230), 2)
            btn_block = make_rotated_text_block(
                [[label]],
                font_scale=1.05,
                thickness=1,
                rotate_180=True,
                max_h=max(20, (y2 - y1) - 24),
                pad_x=10,
                pad_y=8,
            )
            bh2, bw2 = btn_block.shape[:2]
            bbx = x1 + max(0, (x2 - x1 - bw2) // 2)
            bby = y1 + max(0, (y2 - y1 - bh2) // 2)
            blit_add(canvas, btn_block, bbx, bby)

        _display_show(window_name, canvas)
        key = _display_pump(50)
        if key in (ord("y"), ord("Y")):
            selection["choice"] = True
        elif key in (ord("n"), ord("N"), 27):
            selection["choice"] = False

    _display_set_mouse_callback(window_name, lambda *args: None)
    choice = selection.get("choice")

    if choice and Path(update_path).is_file():
        # Re-check in case the user added update.sh after the prompt appeared.
        if sh_path is None or not Path(sh_path).is_file():
            sh_path = _find_update_sh_file(update_path)
        # Run update.sh BEFORE replacing the firmware file. If the script
        # fails, the old firmware is left untouched instead of ending up
        # half-applied (new firmware installed, companion script never run).
        sh_ok, sh_err = True, None
        if sh_path and Path(sh_path).is_file():
            _show_update_status(
                window_name,
                "Running update.sh...\nDo not power off",
            )
            sh_ok, sh_err = _run_update_sh(sh_path)
        if not sh_ok:
            _show_update_error(window_name, sh_err)
            choice = False
        else:
            _show_update_status(window_name, "Applying update...\nDo not power off")
            success, error = _apply_update_from_file(update_path)
            if not success:
                _show_update_error(window_name, error)
                choice = False
            else:
                reboot_ok, reboot_err = _finalize_update_and_reboot()
                if reboot_ok:
                    sys.exit(0)
                else:
                    _show_update_error(window_name, reboot_err)
                    choice = False

    _display_close_window(window_name)
    _display_pump(1)
    return choice


def _prompt_for_update_sh(sh_path):
    """Yes/No prompt for a bare update.sh with no accompanying update.py.
    Mirrors _prompt_for_update's touch/keyboard prompt shell, but there is no
    firmware file to replace or reboot into afterward — it just runs (or
    doesn't run) the script."""
    window_name = _UPDATE_WINDOW_NAME
    selection = {"choice": None}
    btn_w = 180
    btn_h = 110
    center_y = SCREEN_H // 2 + 60
    yes_rect = (
        SCREEN_W // 2 - btn_w - 20,
        center_y,
        SCREEN_W // 2 - 20,
        center_y + btn_h,
    )
    no_rect = (
        SCREEN_W // 2 + 20,
        center_y,
        SCREEN_W // 2 + btn_w + 20,
        center_y + btn_h,
    )

    def _touch_cb(event, x, y, flags, param):
        if event == cv2.EVENT_LBUTTONUP:
            if _point_in_rect(x, y, yes_rect):
                selection["choice"] = True
            elif _point_in_rect(x, y, no_rect):
                selection["choice"] = False

    _display_open_window(window_name)
    _display_set_mouse_callback(window_name, _touch_cb)

    while selection["choice"] is None:
        canvas = np.zeros((SCREEN_H, SCREEN_W, 3), dtype=np.uint8)
        lines = [
            ["Update script found"],
            [f"{sh_path.name} detected on USB"],
            ["Run update script now?"],
        ]
        block = make_rotated_text_block(
            lines,
            font_scale=1.15,
            thickness=1,
            rotate_180=True,
            max_h=SCREEN_H - 220,
            pad_x=14,
            pad_y=12,
            line_gap=10,
        )
        bh, bw = block.shape[:2]
        bx = max(0, (SCREEN_W - bw) // 2)
        by = max(40, (SCREEN_H - bh) // 2 - 60)
        blit_add(canvas, block, bx, by)

        for label, rect, color in (
            ("Yes", yes_rect, (60, 140, 80)),
            ("No", no_rect, (80, 80, 80)),
        ):
            x1, y1, x2, y2 = rect
            cv2.rectangle(canvas, (x1, y1), (x2, y2), color, -1)
            cv2.rectangle(canvas, (x1, y1), (x2, y2), (230, 230, 230), 2)
            btn_block = make_rotated_text_block(
                [[label]],
                font_scale=1.05,
                thickness=1,
                rotate_180=True,
                max_h=max(20, (y2 - y1) - 24),
                pad_x=10,
                pad_y=8,
            )
            bh2, bw2 = btn_block.shape[:2]
            bbx = x1 + max(0, (x2 - x1 - bw2) // 2)
            bby = y1 + max(0, (y2 - y1 - bh2) // 2)
            blit_add(canvas, btn_block, bbx, bby)

        _display_show(window_name, canvas)
        key = _display_pump(50)
        if key in (ord("y"), ord("Y")):
            selection["choice"] = True
        elif key in (ord("n"), ord("N"), 27):
            selection["choice"] = False

    _display_set_mouse_callback(window_name, lambda *args: None)
    choice = selection.get("choice")

    if choice and Path(sh_path).is_file():
        _show_update_status(window_name, "Running update.sh...\nDo not power off")
        sh_ok, sh_err = _run_update_sh(sh_path)
        if not sh_ok:
            _show_update_error(window_name, sh_err)

    _display_close_window(window_name)
    _display_pump(1)
    return choice


def _check_for_pending_update(deadline=6.0):
    # This loop exists to give a just-inserted USB drive time to finish
    # mounting before we give up looking for update.py — it only matters
    # while a USB device is physically present but not yet mounted. If
    # nothing is plugged in at all (or it's already mounted and simply has
    # no update file), waiting the full deadline can't materialize one, so
    # skip straight to a single immediate check and free up boot time.
    update_path = _find_update_file()
    if update_path is None:
        usb_mounted = bool(globals().get("_usb_active_mount"))
        device_present = False
        if not usb_mounted:
            try:
                device_present = bool(_detect_usb_partition()[0])
            except Exception:
                device_present = False
        if usb_mounted or not device_present:
            return None
        deadline_ts = time.monotonic() + max(0.0, float(deadline))
        while time.monotonic() < deadline_ts:
            time.sleep(0.3)
            update_path = _find_update_file()
            if update_path is not None:
                break
    if update_path and update_path.is_file():
        return update_path
    return None


_pending_update_lock = threading.Lock()
_pending_update_path = None
_update_prompt_ready = threading.Event()
_lazy_load_ready = threading.Event()

# Bare update.sh (no accompanying update.py) found at boot: queued through
# the same prompt machinery as update.py instead of running silently.
_pending_update_sh_path = None
_update_sh_prompt_ready = threading.Event()
# Set on a "No" answer so a declined bare update.sh isn't re-queued for the
# rest of this boot session.
_update_sh_declined = False


def _queue_update_prompt(update_path):
    global _pending_update_path
    if not update_path:
        return
    with _pending_update_lock:
        _pending_update_path = update_path
    _update_prompt_ready.set()


def _queue_update_sh_prompt(sh_path):
    global _pending_update_sh_path
    if not sh_path:
        return
    with _pending_update_lock:
        _pending_update_sh_path = sh_path
    _update_sh_prompt_ready.set()


def _lazy_startup_loader():
    update_path = _check_for_pending_update()
    if update_path:
        _queue_update_prompt(update_path)
    else:
        sh_path = _find_update_sh_file()
        if sh_path is not None and not _update_sh_declined:
            _queue_update_sh_prompt(sh_path)

    # Preload film LUTs and other optional assets so they do not block startup.
    try:
        for key in list(_FILM_CURVE_DATA.keys()):
            _film_lut_for(key)
    except Exception as exc:
        print("Lazy load error:", exc)

    # Discover user `.cube` LUTs on the USB/SD lut folder, surface them in the
    # film dropdown, and restore a persisted LUT selection now that its key
    # exists. _rebuild_film_options already re-selects the persisted key, so a
    # single prebake of the now-current selection bakes it off the boot path
    # (no redundant second thread).
    try:
        # Make sure the internal home-folder LUT dir exists so users can drop
        # .cube files into it (SFTP/web upload) without any manual setup.
        _lut_ensure_internal_dir()
        _lut_scan_and_register()
        _rebuild_film_options(preserve_key=_persisted_film_key)
        _lut_prebake_for_current()
    except Exception as exc:
        print("LUT lazy load error:", exc)

    # Pre-warm icon button cache so the first few frames don't stutter while
    # rendering every button from scratch.  We use a tiny dummy destination
    # image just to satisfy the bounds calculation; only the (size, active,
    # accent_color, opacity) cache key matters.
    try:
        _btn_size = 72
        _dummy = np.zeros((_btn_size + 40, _btn_size + 40, 3), dtype=np.uint8)
        _warm_bounds = (0, 0, _btn_size, _btn_size)
        _warm_colors = [
            ((180, 180, 180), 0.9),       # default inactive
            (UI_ACCENT_SYSTEM, 0.9),      # flip / sleep
            (UI_ACCENT_EXPOSURE, 0.9),    # charge / shutter / iso manual
            (UI_ACCENT_SYSTEM, 0.85),     # sleep
            ((200, 200, 200), 0.85),      # exit / x-exit
            (UI_ACCENT_CREATIVE, 0.9),    # wifi / film / aspect / double-exp
            (UI_INACTIVE, 0.9),           # unified inactive
            (UI_ACCENT_FOCUS, 0.9),       # rangefinder active
        ]
        for _color, _opacity in _warm_colors:
            for _active in (False, True):
                _render_icon_button(_dummy, _warm_bounds, active=_active,
                                    accent_color=_color, inner_opacity=_opacity)
    except Exception as exc:
        print("Icon cache warm-up error:", exc)

    _lazy_load_ready.set()


