_SENSOR_UI_SOURCE = '"""Embedded into wlf8.py after the display and web helpers are defined."""\n_sensor_recovery = False\n_sensor_dialog_request = threading.Event()\n_sensor_change_rect = (410, 330, 630, 376)\n_sensor_guard = _sensor_backend[\'StartupGuard\'](\'/var/lib/wlv-sensor/startup.pending\')\n_sensor_selector = _sensor_backend[\'Selector\']()\n_sensor_boot_complete = threading.Event()\n\n\ndef _sensor_apply(profile, port, action):\n    global _web_update_preparing\n    with _web_update_gate:\n        if _web_update_preparing and not _sensor_selector.power_pending:\n            raise ValueError(\'An update or sensor change is already preparing.\')\n        if _sensor_selector.power_pending:\n            return\n        ok, reason = _web_update_prepare()\n        if not ok:\n            raise ValueError(reason)\n        try:\n            _sensor_selector.apply(profile, port, action)\n        except Exception:\n            _web_update_cancel_prepare()\n            raise\n\n\ndef _sensor_page():\n    options = \'\'.join(\'<option value="\' + key + \'">\' + value[0] + \'</option>\'\n                      for key, value in _sensor_backend[\'PROFILES\'].items())\n    try:\n        current = _sensor_selector.current()\n    except Exception:\n        current = {\'profile\': \'\', \'port\': \'\'}\n    return \'\'\'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n<title>Camera sensor</title><style>\n  :root {\n    --bg: #0f0e0c;\n    --panel: #17150f;\n    --panel-2: #1e1c16;\n    --text: #eae5da;\n    --muted: #8e8879;\n    --faint: #5b564b;\n    --accent: #c49a4a;\n    --accent-strong: #d8ae5c;\n    --accent-rgb: 196,154,74;\n    --on-accent: #171307;\n    --danger: #c25b4a;\n    --border: rgba(234,229,217,0.08);\n    --border-strong: rgba(234,229,217,0.16);\n    --r: 5px;\n    --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;\n    --mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;\n  }\n  * { box-sizing: border-box; }\n  html, body { margin: 0; padding: 0; background: var(--bg); color: var(--text);\n    font: 15px/1.4 var(--sans); -webkit-font-smoothing: antialiased; }\n  body { padding-left: env(safe-area-inset-left);\n    padding-right: env(safe-area-inset-right); }\n  header { position: sticky; top: 0; z-index: 10; background: rgba(15,14,12,0.97);\n    backdrop-filter: blur(8px); border-bottom: 1px solid var(--border); }\n  .wrap { max-width: 1100px; margin: 0 auto; padding: 14px 16px; }\n  /* -------- Masthead -------- */\n  .title-row { display: flex; align-items: flex-start;\n    justify-content: space-between; gap: 12px; margin-bottom: 4px; }\n  .wordmark { font-weight: 700; font-size: 20px; letter-spacing: 2.5px;\n    line-height: 1.1; }\n  .wordmark .dash { color: var(--accent); }\n  .byline { font-family: var(--mono); font-size: 8px; font-weight: 500;\n    letter-spacing: 1.8px; color: var(--muted); margin-top: 5px;\n    text-transform: uppercase; white-space: nowrap; }\n  /* Maintenance pages share the main interface\'s Settings layout. */\n  main.wrap { padding-top: 18px; padding-bottom: 40px; }\n  h1 { font-size: 18px; font-weight: 600; margin: 0 0 8px; }\n  h2 { font-size: 14px; font-weight: 600; margin: 0 0 12px; line-height: 1.5; }\n  p { line-height: 1.5; color: var(--muted); overflow-wrap: anywhere; }\n  a { color: var(--accent-strong); text-underline-offset: 3px; }\n  .page-nav { display: flex; flex-wrap: wrap; gap: 18px; padding-top: 14px;\n    font-size: 11px; font-weight: 600; letter-spacing: 1px; }\n  .page-nav span { color: var(--text); border-bottom: 2px solid var(--accent); padding-bottom: 9px; }\n  .page-nav a { color: var(--muted); text-decoration: none; }\n  section { background: var(--panel); border: 1px solid var(--border);\n    border-radius: 6px; padding: 16px; margin: 12px 0; min-width: 0; }\n  label { display: block; font-size: 14px; font-weight: 600; margin: 10px 0 4px; }\n  button, select, input { font-family: var(--sans); font-size: 14px; max-width: 100%; }\n  button { background: var(--panel-2); color: var(--text); border: 1px solid var(--border);\n    border-radius: var(--r); padding: 9px 14px; cursor: pointer; margin: 4px 4px 4px 0; }\n  button.primary { background: var(--accent); color: var(--on-accent); border-color: var(--accent); font-weight: 600; }\n  button.primary:hover:not(:disabled) { background: var(--accent-strong); }\n  button:hover:not(:disabled) { border-color: var(--border-strong); }\n  button:disabled, select:disabled, input:disabled { opacity: .5; cursor: default; }\n  button:focus-visible, select:focus-visible, input:focus-visible, a:focus-visible, summary:focus-visible {\n    outline: 2px solid var(--accent-strong); outline-offset: 3px; }\n  select { background: var(--panel-2); border: 1px solid var(--border-strong); color: var(--text);\n    border-radius: var(--r); padding: 8px 10px; margin: 4px 0 10px; color-scheme: dark; }\n  input[type=file] { display: block; width: 100%; margin: 8px 0; color: var(--muted); }\n  input::file-selector-button { font: inherit; background: var(--panel-2); color: var(--text);\n    border: 1px solid var(--border-strong); border-radius: var(--r); padding: 9px 12px; margin-right: 10px; }\n  input[type=checkbox] { accent-color: var(--accent); width: 16px; height: 16px; vertical-align: middle; }\n  #sensor, #port, #driver, #kind { width: 100%; max-width: 480px; display: block; }\n  .actions { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; }\n  .actions #kind { width: auto; margin: 4px 0; }\n  #status { white-space: pre-wrap; color: var(--text); }\n  #error { color: var(--danger); }\n  pre { font: 11px/1.6 var(--mono); white-space: pre-wrap; overflow-wrap: anywhere;\n    max-height: 350px; overflow: auto; background: var(--bg); border-radius: var(--r); padding: 12px; }\n  summary { cursor: pointer; font-size: 13px; color: var(--muted); }\n  progress { width: 100%; accent-color: var(--accent); }\n  [hidden] { display: none !important; }\n  article { display: flex; flex-wrap: wrap; gap: 14px; align-items: center;\n    padding: 16px; margin: 12px 0; background: var(--panel); border: 1px solid var(--border); border-radius: 6px; }\n  article img { width: 120px; border-radius: var(--r); }\n  article > div { flex: 1 1 220px; min-width: 0; }\n  article p { margin: 0 0 8px; font-size: 13px; }\n  article a { display: inline-block; margin-right: 12px; font-size: 13px; }\n  article button { display: block; color: var(--danger); }\n  @media (max-width: 480px) {\n    .actions { align-items: stretch; }\n    .actions button, .actions #kind { flex: 1 1 100%; margin-right: 0; }\n    select { width: 100%; }\n  }\n</style>\n<header><div class="wrap"><div class="title-row"><div><div class="wordmark">WLV<span class="dash">-</span>01</div><div class="byline">CAMERA CONTROL</div></div></div><nav class="page-nav" aria-label="Page"><a href="/">Back to camera</a><span>Camera sensor</span></nav></div></header><main class="wrap"><h1>Camera sensor</h1><p>\'\'\' + (\'The camera could not start. Choose the connected sensor or install its driver using Updates. The camera will stay here until you choose an action.\' if _sensor_recovery else \'Put the camera in Charge mode and wait for photos to finish saving before changing sensors.\') + \'\'\'</p>\n<section><label>Sensor<select id="sensor"><option value="">Choose sensor</option>\'\'\' + options + \'\'\'</select></label>\n<label>Camera connector<select id="port"><option value="">Choose connector</option><option value="cam1">CAM1 (usual connector)</option><option value="cam0">CAM0</option></select></label>\n<p>To swap sensors: apply and shut down, wait until fully off, then disconnect power before changing the sensor. If you have already swapped it, apply and restart.</p>\n<div class="actions"><button class="primary" id="off">Apply and shut down</button><button id="restart">Apply and restart</button>\n<button id="updates">Open Updates</button></div></section><p id="status" role="status"></p>\n<script>const token=\'\'\' + json.dumps(_DOWNLOAD_TOKEN) + \'\'\';\nconst get=id=>document.getElementById(id);let busy=false;\nconst current=\'\'\' + json.dumps(current) + \'\'\';get(\'sensor\').value=current.profile;get(\'port\').value=current.port;\nasync function post(path,body){const r=await fetch(path,{method:\'POST\',headers:{\'X-WLV-Token\':token,\'Content-Type\':\'application/json\'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.reason||\'Action failed\');return d;}\nfunction disable(value){busy=value;for(const id of [\'off\',\'restart\',\'updates\',\'sensor\',\'port\'])get(id).disabled=value;}\nasync function apply(action){if(busy)return;disable(true);get(\'status\').textContent=\'Saving sensor selection…\';try{await post(\'/api/sensor/apply\',{profile:get(\'sensor\').value,port:get(\'port\').value,action});get(\'status\').textContent=action===\'poweroff\'?\'Shutting down. Wait until the camera is fully off before disconnecting power.\':\'Restarting. If the camera cannot start, this recovery screen will be available again.\';}catch(e){get(\'status\').textContent=e.message;disable(false);}}\nget(\'off\').onclick=()=>apply(\'poweroff\');get(\'restart\').onclick=()=>apply(\'reboot\');\nget(\'updates\').onclick=async()=>{if(busy)return;disable(true);try{const d=await post(\'/api/web-update/open\',{});const u=new URL(location.href);u.port=d.port;u.pathname=\'/\';u.hash=d.token;location.assign(u);}catch(e){get(\'status\').textContent=e.message;disable(false);}};\n</script></main></html>\'\'\'\n\n\ndef _sensor_draw_button(canvas, rect, label, active=False):\n    x1, y1, x2, y2 = rect\n    cv2.rectangle(canvas, (x1, y1), (x2, y2), (157, 203, 233) if active else (65, 65, 65), -1)\n    block = make_rotated_text_block([[label]], font_scale=0.75, thickness=1,\n                                    rotate_180=True, max_h=y2-y1-8, pad_x=4, pad_y=2)\n    h, w = block.shape[:2]\n    blit_add(canvas, block, x1 + max(0, (x2-x1-w)//2), y1 + max(0, (y2-y1-h)//2))\n\n\ndef _sensor_dialog(recovery=False):\n    """Camera-independent local UI; recovery never returns to camera startup."""\n    global charge_mode_active, _sensor_recovery\n    _sensor_recovery = bool(recovery)\n    if recovery:\n        charge_mode_active = True\n        # Keep recovery reachable on an already configured network.\n        # Do not persist a partial settings snapshot before camera setup has\n        # populated all runtime settings. Only enable the radio here.\n        threading.Thread(target=_apply_wifi_state, args=(True,), daemon=True).start()\n        _download_server_start()\n    selected = \'\'\n    port = \'\'\n    message = \'Camera could not start. Select sensor or open Updates on the web.\' if recovery else \'Select the sensor you will connect. Swap only with power disconnected.\'\n    try:\n        previous = _sensor_selector.current()\n        if previous.get(\'profile\') in _sensor_backend[\'PROFILES\']:\n            selected, port = previous[\'profile\'], previous.get(\'port\', \'cam1\')\n    except Exception:\n        pass\n    presses = queue.Queue()\n    window = \'Camera Sensor\'\n    def touched(event, x, y, flags, param):\n        if event == cv2.EVENT_LBUTTONUP:\n            presses.put((x, y))\n    _display_open_window(window)\n    _display_set_mouse_callback(window, touched)\n    try:\n        while True:\n            canvas = np.zeros((SCREEN_H, SCREEN_W, 3), dtype=np.uint8)\n            buttons = []\n            for i, (key, value) in enumerate(_sensor_backend[\'PROFILES\'].items()):\n                rect = (30 + (i % 2)*390, 210 + (i//2)*60, 390+(i%2)*390, 262+(i//2)*60)\n                buttons.append((rect, key))\n                _sensor_draw_button(canvas, rect, value[0], key == selected)\n            for rect, action, label in (\n                    ((30,150,260,198), \'poweroff\', \'Apply + shut down\'),\n                    ((280,150,520,198), \'reboot\', \'Apply + restart\'),\n                    ((540,150,770,198), \'port\', port.upper() or \'Select connector\'),\n                    ((30,85,260,135), \'back\', \'Stay here\' if recovery else \'Cancel\')):\n                buttons.append((rect, action))\n                _sensor_draw_button(canvas, rect, label)\n            block = make_rotated_text_block([[s] for s in _wrap_update_lines(message)], font_scale=0.8,\n                                            thickness=1, rotate_180=True, max_h=80, pad_x=8, pad_y=4)\n            h, w = block.shape[:2]\n            blit_add(canvas, block, max(0,(SCREEN_W-w)//2), 395)\n            _display_show(window, canvas)\n            _display_pump(100)\n            try:\n                x, y = presses.get_nowait()\n            except queue.Empty:\n                continue\n            if _sensor_selector.power_pending:\n                continue\n            for rect, action in buttons:\n                if not _point_in_rect(x,y,rect):\n                    continue\n                if action in _sensor_backend[\'PROFILES\']:\n                    selected = action\n                elif action == \'port\':\n                    port = \'cam0\' if port == \'cam1\' else \'cam1\'\n                elif action == \'back\' and not recovery:\n                    return\n                elif action in (\'poweroff\', \'reboot\'):\n                    try:\n                        _sensor_apply(selected, port, action)\n                        message = \'Shutting down. Wait until fully off.\' if action == \'poweroff\' else \'Restarting camera…\'\n                    except Exception as exc:\n                        message = str(exc)\n    finally:\n        _display_close_window(window)\n\n\ndef _sensor_recover(reason):\n    """Never allow recovery UI trouble to trigger another camera-service crash."""\n    global _sensor_recovery, charge_mode_active\n    _sensor_recovery = True\n    charge_mode_active = True\n    _sensor_boot_complete.set()  # Recovery is stable; retain the disk marker.\n    print(\'[Sensor recovery]\', reason)\n    while True:\n        try:\n            _sensor_dialog(recovery=True)\n        except Exception as exc:\n            print(\'[Sensor recovery] display unavailable:\', exc)\n            # HTTP remains available even with a disconnected/failed display.\n            try:\n                _download_server_start()\n            except Exception:\n                pass\n            time.sleep(5)\n\n\ndef _sensor_startup_begin():\n    if not _sensor_boot_allowed:\n        _sensor_recover(_sensor_pending_error or \'Camera startup was interrupted %d times in a row.\'\n                        % globals().get(\'_sensor_boot_attempts\', 0))\n    attempts = globals().get(\'_sensor_boot_attempts\', 0)\n    budget = _sensor_backend[\'STARTUP_MAX_ATTEMPTS\']\n    original_hook = sys.excepthook\n    def startup_error(kind, value, tb):\n        if not _sensor_boot_complete.is_set():\n            traceback.print_exception(kind, value, tb)\n            if globals().get(\'_sensor_boot_last_attempt\', False):\n                _sensor_recover(str(value))\n            # Budget left: exit non-zero so camera.service\'s Restart=on-failure\n            # retries, exactly as it did before the guard existed. The marker\n            # counts this attempt and recovery opens once the budget is spent.\n            print(\'[Sensor] camera startup failed on attempt %d of %d; exiting so \'\n                  \'camera.service restarts it\' % (attempts, budget))\n        original_hook(kind, value, tb)\n    sys.excepthook = startup_error\n    def watchdog():\n        if not _sensor_boot_complete.wait(120):\n            # A native camera call cannot be interrupted safely from Python.\n            # systemd restarts this process; the marker counts the attempt.\n            print(\'[Sensor] camera startup stalled for 120 s on attempt %d of %d; \'\n                  \'exiting so camera.service restarts it\' % (attempts, budget))\n            try:\n                sys.stdout.flush()\n            except Exception:\n                pass\n            os._exit(1)\n    threading.Thread(target=watchdog, name=\'camera-startup-guard\', daemon=True).start()\n\n\ndef _sensor_startup_healthy():\n    _sensor_boot_complete.set()\n    try:\n        _sensor_guard.healthy()\n    except Exception as exc:\n        print(\'[Sensor] Could not clear startup marker:\', exc)\n'
exec(compile(_SENSOR_UI_SOURCE, '<sensor-ui>', 'exec'), globals())
# END EMBEDDED SENSOR_UI

_sensor_startup_begin()

# -------------------- Camera setup --------------------
_boot_phase("module init (settings/UI/servers)")
_update_splash("Initializing camera...", 0.40)

# ---- Mono sensor tuning file ------------------------------------------------
# The Pi ships per-sensor "_mono" tuning variants (e.g. imx585_mono.json)
# that configure the rpi IPA for CFA-less sensors — no colour-sensor AWB/CCM
# processing, mono-appropriate contrast/denoise.  When the learned verdict is
# mono and the platform provides a matching tuning for the active sensor, the
# firmware adopts it via LIBCAMERA_RPI_TUNING_FILE.  The variable must be set
# BEFORE Picamera2() starts the camera manager, but the sensor model is only
# knowable afterwards — so discovery happens at runtime (verdict flip in
# _set_mono_sensor_active), persists as `mono_tuning_file`, and takes effect
# on the next boot.  The current session is already artifact-free via the
# raw-developed JPGs and AWB neutralisation, so no mid-session camera
# teardown is needed.  Data-driven: any sensor with a _mono tuning works.
_MONO_TUNING_DIRS = (
    "/usr/share/libcamera/ipa/rpi/pisp",        # Pi 5
    "/usr/share/libcamera/ipa/rpi/vc4",         # Pi 4 and earlier
    "/usr/local/share/libcamera/ipa/rpi/pisp",  # self-built libcamera
    "/usr/local/share/libcamera/ipa/rpi/vc4",
)


def _find_mono_tuning_file(model):
    """Absolute path of the platform-provided mono tuning for a sensor model
    ('imx585' -> imx585_mono.json), or None when the platform ships none."""
    model = str(model or "").strip().lower()
    if not model:
        return None
    fname = f"{model}_mono.json"
    for d in _MONO_TUNING_DIRS:
        path = os.path.join(d, fname)
        try:
            if os.path.isfile(path):
                return path
        except Exception:
            pass
    return None


# Apply the persisted override now, unless the user already forces a tuning
# via the environment (their choice wins) — or unless the boot-time prefetch
# already applied it, which it must, because libcamera reads the variable
# when it initialises and that happens on the prefetch thread.
_mono_tuning_env_applied = False
if _early_tuning_applied:
    # Same file, same decision, just taken before the camera-stack import.
    _mono_tuning_env_applied = True
    # Keep the global the sensor-swap guard below compares against exactly
    # in step with what was actually applied.
    _mono_tuning_file = _early_tuning_applied
elif (_mono_sensor_active and _mono_tuning_file
        and os.path.isfile(_mono_tuning_file)
        and not os.environ.get("LIBCAMERA_RPI_TUNING_FILE")):
    os.environ["LIBCAMERA_RPI_TUNING_FILE"] = _mono_tuning_file
    _mono_tuning_env_applied = True
    print(f"[Mono] Using mono sensor tuning: {_mono_tuning_file}")

# Collect the prefetch started before the cv2/numpy import — by now it has
# normally finished, and this import is a sys.modules hit.
_prefetch_hit = False
_prefetch_join_s = 0.0
if _early_prefetch_thread is not None:
    _join_t0 = time.monotonic()
    _early_prefetch_thread.join(timeout=60.0)
    # Non-zero means the main thread reached here FIRST and had to wait on
    # the camera stack — the overlap ran out of runway rather than paying
    # off, and the prefetch is on the critical path after all.
    _prefetch_join_s = time.monotonic() - _join_t0
    _prefetch_hit = (not _early_prefetch_thread.is_alive()
                     and _early_prefetch_error is None)
from picamera2 import Picamera2
_boot_phase("picamera2/libcamera import"
            + (" [prefetched]" if _prefetch_hit else "")
            + (f" (waited {_prefetch_join_s:.2f}s on prefetch)"
               if _prefetch_join_s > 0.05 else ""))
picam2 = Picamera2()
_boot_phase("Picamera2() camera-manager init")

# Sensor-swap guard: the tuning override was chosen for the sensor that was
# installed when the verdict was learned.  If a different sensor is found at
# boot, drop the stale override and re-init the camera without it — the wrong
# tuning must never be applied to the wrong sensor.
if _mono_tuning_env_applied:
    try:
        _model_now = str(
            (picam2.camera_properties or {}).get("Model", "")).strip().lower()
    except Exception:
        _model_now = ""
    if os.path.basename(_mono_tuning_file) != f"{_model_now}_mono.json":
        print(f"[Mono] Sensor changed (now '{_model_now or 'unknown'}') — "
              f"dropping stale mono tuning override")
        os.environ.pop("LIBCAMERA_RPI_TUNING_FILE", None)
        _mono_tuning_env_applied = False
        _mono_tuning_file = ""
        _debounced_save_settings()
        try:
            picam2.close()
        except Exception as _close_exc:
            print(f"[Mono] camera close for tuning reset failed: {_close_exc}")
        picam2 = Picamera2()


def _detect_hq_sensor():
    """True when the active primary sensor is the Raspberry Pi HQ Camera
    (Sony IMX477).  That module is physically mounted 180° from the other
    supported sensors (IMX492/294/585), so its live preview and saved
    files need an extra 180° rotation to come out upright while the rest
    of the pipeline stays sensor-agnostic.  Detection is data-driven off
    libcamera's reported sensor model — no hardcoded resolution/mode — so
    it stays inert for every other sensor."""
    try:
        props = picam2.camera_properties
        model = str(props.get("Model", "")).strip().lower() if props else ""
    except Exception as exc:
        print(f"[Camera] sensor model lookup failed: {exc}")
        return False
    return "imx477" in model


# Single source of truth for the HQ-sensor orientation compensation.  Read by
# the preview loop (adds a 180° preview rotate) and the save paths (skip their
# baseline 180° rotate so the net result is upright).  Off for every other
# sensor, so the standard single-rotation invariant is unchanged.
_HQ_SENSOR_ACTIVE = _detect_hq_sensor()
if _HQ_SENSOR_ACTIVE:
    print("[Camera] Raspberry Pi HQ sensor (IMX477) detected — applying 180° "
          "orientation compensation to preview and captures")

# Per-unit DNG calibration (NoiseProfile table + BaselineExposure; see
# _dng_load_calibration): loaded once here, keyed by the reported sensor
# model so a cartridge swap can never apply another sensor's values.
# There is deliberately NO dead-pixel calibration — see the DNG notes.
try:
    _dng_load_calibration(str(
        (picam2.camera_properties or {}).get("Model", "")).strip().lower())
except Exception as _dng_calib_exc:
    print(f"[DNG] calibration probe failed: {_dng_calib_exc}")


# The 47 MP sensor mode (IMX492 / IMX294 driver) is exposed as TWO dropdown
# options sharing the same sensor read-out:
#   - "(binned preview)"  — key _HIGH_RES_KEY: the read-out is too slow for
#     a smooth live preview, so the live pipeline runs the 2x2-binned 11 MP
#     mode and only switches to 8432x5648 for the capture itself (via the
#     _perform_high_res_capture worker).  This is the original behaviour.
#   - "(unbinned preview)" — key _HIGH_RES_UNBINNED_KEY: the live pipeline
#     runs the 47 MP read-out 1:1 like any other selected mode.  The preview
#     rate is sensor-limited (a few fps) but shows the exact full-resolution
#     framing, and captures fire instantly from the running pipeline with no
#     mode switch, no exposure-transfer gain boost, and live AE.
# The binned entry keeps the plain enumerated key so previously persisted
# settings keep their existing behaviour.
_HIGH_RES_KEY = "8432x5648@12"
_HIGH_RES_UNBINNED_KEY = _HIGH_RES_KEY + "-unbinned"

# Mono Raw keys share their base mode plus this suffix. Runtime high-res
# routing strips it so the IMX294 47 MP twin retains binned preview.
_MONO_RAW_SUFFIX = "-monoraw"


def _is_mono_raw_key(key):
    """Whether a sensor-mode key selects the Mono Raw save path."""
    return bool(key) and str(key).endswith(_MONO_RAW_SUFFIX)


def _mono_raw_base_key(key):
    """The underlying sensor mode of a Mono Raw key (identity otherwise)."""
    k = str(key or "")
    return k[:-len(_MONO_RAW_SUFFIX)] if _is_mono_raw_key(k) else k


def _mono_raw_active():
    """Whether the CURRENTLY selected sensor mode is a Mono Raw entry."""
    try:
        return _is_mono_raw_key(
            SENSOR_MODE_OPTIONS[_sensor_mode_idx].get("key"))
    except Exception:
        return False


def _imx294_quad_raw_available():
    """A new platform advertises this control even during binned preview."""
    try:
        return (_qbc_sensor_status() is True
                and "QbcRaw" in picam2.camera_controls)
    except Exception:
        return False


def _imx294_start_quad_capture(camera):
    """QbcRaw is consumed from requests, not Camera.start()'s IPA controls.

    Picamera2 clears its pending controls at start. Send this AFTER start so
    the next recycled request carries it to the PiSP raw-processing hook.
    The drain must reject earlier frames until their metadata confirms it.
    """
    if 'QbcRaw' not in camera.camera_controls:
        raise RuntimeError('47 MP Mono Raw requires the updated libcamera QbcRaw control')
    camera.start()
    camera.set_controls({'QbcRaw': True})


def _imx294_require_quad_metadata(metadata, requested):
    if requested and (metadata or {}).get('QbcRaw') is not True:
        raise RuntimeError('47 MP Mono Raw was not confirmed by libcamera; colour RAW was not saved as monochrome')


def _mono_raw_variant_available(opt, full_w=0, full_h=0):
    """Offer ordinary CFA modes, plus IMX294 47 MP with QbcRaw support.
    Unknown sensor identities, true mono sensors and unsupported full-res
    quad crops remain excluded. Full resolution always uses binned preview.
    """
    try:
        if _mono_sensor_active or not opt:
            return False
        if opt.get("key") in (_HIGH_RES_KEY, _HIGH_RES_UNBINNED_KEY):
            return (opt.get("key") == _HIGH_RES_KEY
                    and _imx294_quad_raw_available())
        status = _qbc_sensor_status()
        if status is None:
            # Sensor identity unreadable.  The save gate refuses in this
            # state, so offering the row would give the user an entry that
            # silently writes an ordinary colour file — worse than not
            # offering it.  Dropdown and gate fail closed together.
            return False
        if status is False:
            return True         # no remosaic on this sensor, any mode is fine
        w, h = opt.get("size") or (0, 0)
        if full_w and full_h and (int(w) == int(full_w)
                                  or int(h) == int(full_h)):
            return False        # full-res family on a QBC sensor
        return True
    except Exception:
        return False


def _unbinned_preview_available():
    """Whether the "(unbinned preview)" 47 MP dropdown variant is offered
    for the attached sensor.  Data-driven off libcamera's reported model
    (same pattern as _detect_hq_sensor), never off a resolution.

    On the IMX294 the full-resolution modes read out a 4x4 quad-Bayer CFA,
    which the platform handles by remosaicing every CFE buffer in software
    and computing AWB/AGC stats in software (see the QBC platform-stack
    notes).  Running that per frame on a live 47 MP read-out drags the
    preview far below usable, so the unbinned variant is withheld there —
    the "(binned preview)" entry still delivers the full 47 MP capture at
    shutter press.  Unknown/unreadable model errs toward offering the
    option (the historical behaviour)."""
    try:
        model = str(
            (picam2.camera_properties or {}).get("Model", "")).strip().lower()
    except Exception as exc:
        print(f"[Camera] sensor model lookup for unbinned preview failed: {exc}")
        return True
    return "imx294" not in model


def _qbc_sensor_status():
    """TRI-STATE quad-Bayer verdict for the attached sensor: True (its
    full-res read-outs are QBC and get software-remosaiced), False
    (definitely not), or None (the model could not be read).

    `_unbinned_preview_available()` deliberately fails OPEN on a lookup
    error — offering the unbinned row is the historical behaviour and the
    worst case there is a slow preview.  A SAFETY gate cannot reuse that:
    "unknown" collapses into "not QBC", which would let the Mono Raw
    conversion run on a remosaiced payload where most sites are
    interpolated.  Callers that must fail closed test for `is False`."""
    try:
        model = str(
            (picam2.camera_properties or {}).get("Model", "")).strip().lower()
    except Exception as exc:
        print(f"[Camera] sensor model lookup for QBC status failed: {exc}")
        return None
    if not model:
        return None
    return "imx294" in model


# Product-level dropdown allowlist, keyed by libcamera model substring.
#
# A driver can advertise more read-outs than the product ships as user
# choices.  The IMX492 driver advertises ~7 modes, of which only two are
# part of the WLV-01 shooting story: the 10.7 MP binned mode for everyday
# use, and the full 47.6 MP read-out as the "(binned preview)" variant
# (live pipeline on the binned mode, switching to the full read-out only
# at shutter press).  The intermediate crops and the "(unbinned preview)"
# variant — a few-fps live pipeline at 47 MP — are withheld there.
#
# This is a product decision, not one derivable from the sensor's own
# numbers (3792x2824 is a crop of the 2x2-binned 4216x2824, so neither an
# aspect nor a bin-factor rule picks it), so it is an explicit list of
# dropdown keys.  The expanded 47 MP variant keys are part of that list,
# so it alone decides whether the unbinned row is offered — the
# quad-Bayer verdict (_unbinned_preview_available) stays a separate
# question, since it also gates the DNG QBC repair.  Two safety
# properties: a model named nowhere here keeps every 12-bit mode it
# advertises (the sensor-agnostic default), and a list that matches NONE
# of the advertised modes is ignored rather than emptying the dropdown.
_SENSOR_MODE_DROPDOWN_ALLOWLIST = {
    "imx492": ("3792x2824@12", _HIGH_RES_KEY),
    # IMX294: the two-mode story plus the low-light read-out.  Its driver
    # advertises the same 10.7 MP 3792x2824 binned read-out plus a family
    # of narrower binned crops that the aspect-ratio control already
    # covers, so those are withheld — except 4176x2176, which the product
    # ships as the "(low light)" mode (_SENSOR_MODE_LABEL_NOTES; its ISO
    # story is what the low-ISO work calibrated).  The unbinned 47 MP row
    # is withheld here for the same reason it is withheld by
    # _unbinned_preview_available: a quad-Bayer read-out cannot
    # live-preview usably.  Mono Raw twins are NOT listed and do not need
    # to be — the allowlist filters base read-outs before the variant
    # expansion, so a mode that is offered automatically carries its Mono
    # Raw variant.
    "imx294": ("3792x2824@12", "4176x2176@12", _HIGH_RES_KEY),
}


def _sensor_mode_allowlist():
    """Dropdown-key allowlist for the attached sensor, () when unrestricted."""
    try:
        model = str(
            (picam2.camera_properties or {}).get("Model", "")).strip().lower()
    except Exception as exc:
        print(f"[Camera] sensor model lookup for mode allowlist failed: {exc}")
        return ()
    for name, keys in _SENSOR_MODE_DROPDOWN_ALLOWLIST.items():
        if name in model:
            return keys
    return ()


def _mem_total_bytes():
    """Board RAM from /proc/meminfo (0 if unreadable — treated as roomy)."""
    try:
        with open("/proc/meminfo") as fh:
            for line in fh:
                if line.startswith("MemTotal:"):
                    return int(line.split()[1]) * 1024
    except Exception:
        pass
    return 0


# Camera dmabufs live OUTSIDE the process heap, so they never show in the
# app's RSS but still consume system RAM: at 47 MP each buffer set (main
# RGB888 + R16 raw) is ~240 MB, and buffer_count=2 pins ~480 MB before a
# single capture allocation happens. On small-RAM boards that standing cost
# is what pushes the first 47 MP capture into the kernel OOM-killer (field
# kill report: python3 killed with only ~385 MB anon-rss — the pressure was
# the pipeline, not the app). Below this RAM threshold the 47 MP configs
# drop to buffer_count=1: preview pipelining is lost (the unbinned preview
# is sensor-limited to a few fps anyway) but the footprint halves. Boards
# with >= 3 GiB keep the historical double-buffering unchanged.
_LOW_MEM_BOARD = 0 < _mem_total_bytes() < 3 * 1024 * 1024 * 1024
_HIGH_RES_BUFFER_COUNT = 1 if _LOW_MEM_BOARD else 2
if _LOW_MEM_BOARD:
    print(f"[Camera] Low-memory board ({_mem_total_bytes() // (1024*1024)} MB): "
          f"47 MP pipelines run buffer_count=1")
    # Save-pipeline admission (see _capture_mem_budget_ok): one 47 MP-class
    # job at a time on a 2 GB board.  A queued job pins ~200 MB, and the
    # worker stacks its own stage transients (DNG write, film sim, rotate,
    # the JPG encode buffer) on top — two pinned 47 MP jobs plus one
    # job's transients is OOM-killer territory with the live pipeline's
    # dmabufs also resident.  ~250 MB admits exactly one 47 MP job (the
    # first shot is always admitted regardless of size) while still
    # queueing several 11 MP-class jobs; a second 47 MP press waits with
    # the same danger-flash pacing cue as a full disk.
    _CAPTURE_SAVE_MEM_BUDGET_BYTES = 250 * 1024 * 1024


# Mutual exclusion between the one-off 47 MP CMA warm (see _hires_warm_kick,
# defined further down) and anything that allocates camera buffers: a 47 MP
# capture, and every still-pipeline (re)start.  The warm holds ~240 MB of
# dma-heap buffers, then ~240 MB of process memory, for a few seconds; a
# shutter press landing inside that window would configure a SECOND 47 MP
# set alongside it (review finding), which on a 2 GB board / 512 MB CMA
# reservation is exactly the allocation failure the warm exists to avoid.
# Sampling the busy flag once at the start of the warm cannot close that
# window, so the warm holds this lock for its entire allocation-and-touch
# interval and checks the abort event between steps; the capture paths
# CLAIM the lock (abort + wait, bounded, then hold it for the capture), the
# pipeline-start seam merely YIELDS it (abort + wait, then release), since
# the preview-size sets it allocates only need the warm's memory gone.
# Defined here, ahead of _start_still_pipeline_with_fallback, because the
# boot pipeline start runs during module init.
_hires_warm_lock = threading.Lock()
_hires_warm_abort = threading.Event()
_HIRES_WARM_YIELD_S = 6.0   # bound on waiting for the warm to let go
_hires_warm_rearm = False   # set by a yield: the warm should try again later


def _hires_warm_claim(reason):
    """Capture path: make the warm abort, wait for it to release its
    memory, and hold the lock for the capture.  Returns True when the lock
    is held.  Bounded — a warm that somehow will not let go costs the
    capture a logged wait, never the capture itself."""
    _hires_warm_abort.set()
    t0 = time.monotonic()
    got = _hires_warm_lock.acquire(timeout=_HIRES_WARM_YIELD_S)
    waited = time.monotonic() - t0
    if not got:
        print(f"[HiRes] CMA warm did not yield to {reason} in "
              f"{_HIRES_WARM_YIELD_S:.0f}s — proceeding")
    elif waited > 0.05:
        print(f"[HiRes] {reason} waited {waited:.2f}s for the CMA warm")
    return got


def _hires_warm_release(held):
    """Counterpart of _hires_warm_claim; safe to call with held=False."""
    if held:
        try:
            _hires_warm_lock.release()
        except RuntimeError:
            pass


def _hires_warm_yield(reason):
    """Pipeline (re)start seam: make an in-flight warm abort and wait for
    it to release its memory, then continue; the warm re-arms for a later
    idle period.  Costs one uncontended lock round trip when no warm is
    running.  Never raises."""
    global _hires_warm_rearm
    try:
        if _hires_warm_lock.acquire(blocking=False):
            _hires_warm_lock.release()
            return
        _hires_warm_rearm = True
        _hires_warm_abort.set()
        t0 = time.monotonic()
        if _hires_warm_lock.acquire(timeout=_HIRES_WARM_YIELD_S):
            _hires_warm_lock.release()
            print(f"[HiRes] {reason} waited {time.monotonic() - t0:.2f}s "
                  f"for the CMA warm to yield")
        else:
            print(f"[HiRes] CMA warm did not yield to {reason} in "
                  f"{_HIRES_WARM_YIELD_S:.0f}s — proceeding")
    except Exception as exc:
        print(f"[HiRes] CMA warm yield error: {exc}")


def _mem_available_bytes_boot():
    """MemAvailable from /proc/meminfo (0 if unreadable)."""
    try:
        with open("/proc/meminfo") as fh:
            for line in fh:
                if line.startswith("MemAvailable:"):
                    return int(line.split()[1]) * 1024
    except Exception:
        pass
    return 0


# Final say on the save-pipeline byte budget: clamp the static ceilings
# above to a conservative fraction of the RAM actually FREE at startup, so
# an unusually loaded boot (desktop session, another service pinning
# memory) tightens the admission gate instead of trusting board-size
# heuristics alone.  The floor keeps 11 MP-class bursts usable — and the
# first shot is always admitted whatever the budget, so no mode is ever
# locked out.  WLV_CAPTURE_MEM_BUDGET_MB overrides everything (field A/B).
_CAPTURE_SAVE_MEM_FRACTION = 0.35
_mem_avail_boot = _mem_available_bytes_boot()
if _mem_avail_boot > 0:
    _CAPTURE_SAVE_MEM_BUDGET_BYTES = max(
        128 * 1024 * 1024,
        min(_CAPTURE_SAVE_MEM_BUDGET_BYTES,
            int(_mem_avail_boot * _CAPTURE_SAVE_MEM_FRACTION)))
try:
    _budget_env = os.environ.get("WLV_CAPTURE_MEM_BUDGET_MB", "")
    if _budget_env:
        _CAPTURE_SAVE_MEM_BUDGET_BYTES = max(
            64, int(_budget_env)) * 1024 * 1024
except Exception:
    pass
print(f"[Save] capture queue byte budget: "
      f"{_CAPTURE_SAVE_MEM_BUDGET_BYTES // (1024 * 1024)} MB "
      f"(MemAvailable at boot: {_mem_avail_boot // (1024 * 1024)} MB)")

# Live-main fast-path: whenever the saved capture is never sourced from
# the live main stream, the full-resolution RGB main the ISP renders on
# every live frame is pure overhead — ~32 MB per frame at the binned
# 11 MP modes (~650 MB/s of ISP write traffic at 20 fps) up to ~143 MB
# per frame at unbinned 47 MP — all discarded at save time.  Two cases
# qualify: a MONO sensor (the JPG develops from the raw stream,
# `_maybe_develop_mono_frame`, in every still mode), and the binned
# 47 MP mode on ANY cartridge (the shutter always routes through
# `_perform_high_res_capture`, which stops the pipeline and builds its
# own full-size config at press — the live main has no consumer at all
# there).  When the fast-path is active the live main stream runs at
# PREVIEW size instead: identical JPG/DNG output, instant capture
# retained where it exists, and the unbinned mono pipeline can afford
# double-buffering again even on low-memory boards (~97 MB per buffer
# set vs ~240 MB). The full-size main stream is kept whenever it IS the
# product: colour sensors outside binned 47 MP (their JPG is the ISP
# frame), double exposure (blends two main frames), and Brenizer (tiles
# are main frames) — those transitions, and a runtime mono-verdict flip,
# request a guarded pipeline rebuild via
# _still_pipeline_rebuild_requested, handled on the main loop.  (The
# double-exposure / Brenizer exclusions are kept in binned 47 MP too,
# even though both capture through the mode-switch helper there —
# conservative, free, and structurally identical to the mono gate.)
_still_pipeline_rebuild_requested = False


def _live_still_main_size():
    """Main-stream size for the live still pipeline of the ACTIVE mode."""
    try:
        if (not double_exposure_enabled
                and not _brenizer_active
                and preview_size and preview_size[0] > 0):
            if _mono_sensor_active:
                return preview_size
            # Binned 47 MP on any cartridge: the live main stream is never
            # captured (see the fast-path comment above).  Key resolved
            # from the live selection, not the boot-time _active_mode
            # snapshot — _set_sensor_mode_idx never refreshes that.
            try:
                _mode_key = SENSOR_MODE_OPTIONS[_sensor_mode_idx].get("key")
            except Exception:
                _mode_key = None
            if _mono_raw_base_key(_mode_key) == _HIGH_RES_KEY:
                return preview_size
    except Exception:
        pass
    return (FULL_W, FULL_H)


def _request_still_pipeline_rebuild():
    """Ask the main loop to re-derive the live still pipeline (fast-path
    engage/disengage). Safe from any thread — the actual stop/configure/
    start runs only on the main loop, which also no-ops the request when
    nothing about the config would change."""
    global _still_pipeline_rebuild_requested
    _still_pipeline_rebuild_requested = True


# Set when the learned mono/colour verdict flips: which Mono Raw twins the
# dropdown offers depends on it, and the list was built once at boot.
_sensor_mode_options_rebuild_requested = False


def _request_sensor_mode_options_rebuild():
    """Ask the main loop to rebuild SENSOR_MODE_OPTIONS.  Safe from any
    thread — the list is read by the UI and indexed by _sensor_mode_idx, so
    only the main loop may swap it."""
    global _sensor_mode_options_rebuild_requested
    _sensor_mode_options_rebuild_requested = True


def _rebuild_sensor_mode_options():
    """Re-enumerate the dropdown and re-point _sensor_mode_idx at the same
    selection (MAIN LOOP ONLY).  Used after a cartridge-verdict flip, which
    adds or removes the Mono Raw twins.  The selected key is preserved
    where it still exists; a Mono Raw key that no longer does falls back to
    its base read-out, matching the boot-time migration.  The sensor mode
    itself never changes here, so no pipeline restart is implied."""
    global SENSOR_MODE_OPTIONS, _sensor_mode_idx
    global _sensor_mode_options_rebuild_requested
    _sensor_mode_options_rebuild_requested = False
    try:
        current = SENSOR_MODE_OPTIONS[_sensor_mode_idx].get("key")
    except Exception:
        current = None
    try:
        rebuilt = _build_sensor_mode_options()
    except Exception as exc:
        print(f"[Camera] sensor-mode rebuild failed: {exc}")
        return
    if not rebuilt:
        print("[Camera] sensor-mode rebuild produced nothing — keeping list")
        return
    wanted = current
    if wanted is not None and not any(o["key"] == wanted for o in rebuilt):
        wanted = _mono_raw_base_key(wanted)
    new_idx = 0
    for i, o in enumerate(rebuilt):
        if o["key"] == wanted:
            new_idx = i
            break
    SENSOR_MODE_OPTIONS = rebuilt
    _sensor_mode_idx = new_idx
    print(f"[Camera] sensor-mode list rebuilt after cartridge verdict flip "
          f"({len(rebuilt)} entries, selection {SENSOR_MODE_OPTIONS[new_idx]['key']})")
    if wanted != current:
        _debounced_save_settings()
# The 2x2-binned live mode the binned-preview variant runs on (and that video
# mode falls back to for BOTH variants — see _enter_video_mode).
_HIGH_RES_BINNED_W, _HIGH_RES_BINNED_H = 3792, 2840
# Presented-frame blackout counter for the SYNCHRONOUS 47 MP paths (Brenizer
# tiles, double exposure), whose capture blocks the loop and clears it in
# a finally.  The threaded binned path only uses it for the first
# presented frame; its hold-still cue is held on _hires_blackout_active /
# _high_res_capture_done for however long the read-out actually takes.
_HIGH_RES_BLACK_FLASH_FRAMES = 30


def _enumerate_raw_modes_fast():
    """(size, bit_depth) for every raw mode the sensor advertises, WITHOUT
    reconfiguring the camera once.  Returns [] when unavailable, so the
    caller falls back to picamera2's `sensor_modes` property.

    Boot-critical: `sensor_modes` configures the camera ONCE PER ADVERTISED
    MODE — it reports each mode's fps / exposure / crop limits, and those are
    only readable from a configured pipeline.  Every one of those configures
    allocates (and frees) that mode's full raw buffer set and runs an IPA
    configure.  On a small sensor that is a handful of cheap round trips; on
    the 47 MP IMX492/IMX294 driver it is ~7 modes whose raw buffers are tens
    of MB each, which is *seconds* of the boot path spent measuring numbers
    this firmware never reads.  The sensor-mode dropdown needs size and bit
    depth only, and libcamera already enumerated both during `Picamera2()`
    init (`_raw_modes`, built with no configure at all) — so read them from
    there and skip the mode-by-mode reconfiguration entirely.

    Stays sensor-agnostic: the values are exactly the ones `sensor_modes`
    reports for the same modes (same libcamera stream-config enumeration,
    same bit-depth derivation), so the persisted mode keys are unchanged."""
    try:
        modes = list(getattr(picam2, "_raw_modes", None) or [])
    except Exception as exc:
        print(f"[Camera] fast raw-mode enumeration unavailable: {exc}")
        return []
    out = []
    for m in modes:
        try:
            size = m.get("size") or (0, 0)
            info = _raw_format_info(m.get("format"))
        except Exception:
            continue
        if info is None:
            # Unparsed format — no honest bit depth, so it cannot become a
            # dropdown entry.  Parity note: the formats this drops are the
            # ones `sensor_modes` also keeps out of the 12-bit dropdown
            # (a PiSP-compressed variant reports bit_depth 16 through
            # picamera2's own SensorFormat, and a non-raw format is
            # skipped there for lack of a size), so skipping here can
            # never hide a mode the slow path would have offered.
            continue
        out.append({"size": size, "bit_depth": info[1]})
    return out


# Human-readable notes appended to a sensor mode's dropdown label, keyed
# by raw size.  LABELS ONLY — the dropdown key stays "{w}x{h}@{bits}", so
# a persisted sensor_mode_key keeps meaning exactly the same mode and an
# updated camera never loses its selection.  An entry for a size the
# attached sensor does not advertise is simply never used, so this stays
# sensor-agnostic: a cartridge that has the mode gets the note, one that
# does not is unaffected.
_SENSOR_MODE_LABEL_NOTES = {
    (4176, 2176): "low light",
}


def _sensor_mode_options_from_raw(raw_modes):
    """Filter a list of raw-mode dicts ({"size", "bit_depth"}) down to the
    12-bit dropdown entries, deduplicated by key.  Shared by both
    enumeration paths so they can only ever differ in where the modes came
    from, never in how they are interpreted."""
    seen = set()
    options = []
    for m in raw_modes:
        size = m.get("size") or (0, 0)
        try:
            w, h = int(size[0]), int(size[1])
        except Exception:
            continue
        if w <= 0 or h <= 0:
            continue
        try:
            bd = int(m.get("bit_depth") or 0)
        except Exception:
            bd = 0
        if bd != 12:
            continue
        key = f"{w}x{h}@{bd}"
        if key in seen:
            continue
        seen.add(key)
        mp = (w * h) / 1e6
        label = f"{w}x{h}  {bd}-bit  ({mp:.1f} MP)"
        note = _SENSOR_MODE_LABEL_NOTES.get((w, h))
        if note:
            label += f"  ({note})"
        options.append({
            "key": key,
            "size": (w, h),
            "bit_depth": bd,
            "mp": mp,
            "label": label,
        })
    return options


def _build_sensor_mode_options():
    """Enumerate the sensor's raw modes into a list ordered by ascending
    megapixels.  Each entry has a stable key (used for persistence) plus
    a human-readable label for the dropdown UI.  All 12-bit modes the
    sensor reports are exposed; other bit depths are filtered out.

    The 47 MP mode is expanded into two entries — "(binned preview)" and
    "(unbinned preview)" — see the _HIGH_RES_KEY comment above.  The
    unbinned entry is withheld on sensors where it can't preview usably
    (_unbinned_preview_available) and on sensors whose dropdown is
    restricted to a product allowlist (_sensor_mode_allowlist)."""
    options = _sensor_mode_options_from_raw(_enumerate_raw_modes_fast())
    if not options:
        # Degrade fast path -> slow path -> hardcoded default, in that
        # order.  The trigger is "no usable 12-bit mode was produced", NOT
        # "nothing parsed": a fast path that yields only non-12-bit modes
        # leaves the dropdown empty just as surely as one that yields
        # nothing at all, and on that camera the hardcoded IMX492 entry
        # below is a worse answer than one slow-but-authoritative
        # enumeration (it can name a mode the attached sensor does not
        # have, leaving the pipeline unable to start).  Costs one camera
        # configure per advertised mode, so it must stay unreachable on a
        # healthy camera.
        try:
            options = _sensor_mode_options_from_raw(
                list(getattr(picam2, "sensor_modes", []) or []))
            print("[Camera] mode enumeration fell back to sensor_modes "
                  "(one camera configure per mode)")
        except Exception as exc:
            print(f"[Camera] sensor_modes lookup failed: {exc}")
            options = []
    options.sort(key=lambda o: (o["mp"], o["bit_depth"]))
    # Product allowlist (IMX492: the 10.7 MP mode + the 47 MP binned-preview
    # entry only).  Applied before the expansion below so the allowlist is
    # written in the same dropdown keys the UI and persistence use.  It is
    # ignored outright if it matches nothing the sensor advertises — a
    # driver that renamed its modes must not leave the camera with an empty
    # dropdown and no way to start a pipeline.
    allow = _sensor_mode_allowlist()
    if allow:
        kept = [o for o in options if o["key"] in allow]
        if kept:
            for o in options:
                if o not in kept:
                    print(f"[Camera] withholding {o['label']} — not offered "
                          f"on this sensor")
            options = kept
        else:
            print("[Camera] mode allowlist matched none of the advertised "
                  "modes — keeping the full list")
    # Expand the 47 MP mode into its two preview variants (adjacent rows,
    # binned first).  Keys stay distinct so persistence picks the right one.
    # The unbinned row needs BOTH a sensor that can preview it and (where
    # one applies) the product allowlist naming it.
    qbc_full_res = not _unbinned_preview_available()
    offer_unbinned = (not qbc_full_res
                      and (not allow or _HIGH_RES_UNBINNED_KEY in allow))
    # Largest enumerated dimensions, measured BEFORE the crop filter below
    # narrows the list — the Mono Raw twin filter needs the true full-res
    # family even when that filter is skipped (unknown model / non-QBC).
    _mr_full_w = max((o["size"][0] for o in options), default=0)
    _mr_full_h = max((o["size"][1] for o in options), default=0)
    # On a sensor whose full-resolution read-outs can't live-preview usably
    # (IMX294 — every full-res mode is quad-Bayer, remosaiced in software
    # per frame; see _unbinned_preview_available), withhold ALL full-res
    # crops from the dropdown, not just the unbinned 47 MP variant: the
    # driver also advertises cropped read-outs (e.g. the 43.4 MP
    # 7680x5648 entry, a width crop at full height) that run their
    # quad-Bayer read-out 1:1 as the live pipeline, with no binned-preview
    # variant to save them.  The discriminator — computed from the
    # enumerated list, never hardcoded — is sharing EITHER full-res
    # dimension: a crop keeps the full read-out's width or height while a
    # binned mode shrinks in both.  The _HIGH_RES_KEY entry is exempt (its
    # "(binned preview)" expansion below runs the live pipeline on the
    # binned mode, touching the full read-out only at shutter press), and
    # the filter never empties the dropdown.
    if qbc_full_res and options:
        full_w = max(o["size"][0] for o in options)
        full_h = max(o["size"][1] for o in options)
        kept = [o for o in options
                if (o["size"][0] < full_w and o["size"][1] < full_h)
                or o["key"] == _HIGH_RES_KEY]
        if kept:
            for o in options:
                if o not in kept:
                    print(f"[Camera] withholding {o['label']} — quad-Bayer "
                          f"read-out can't live-preview usably on this sensor")
            options = kept
    expanded = []
    for o in options:
        if o["key"] == _HIGH_RES_KEY:
            expanded.append(dict(o, label=o["label"] + "  (binned preview)"))
            if _mono_raw_variant_available(o, _mr_full_w, _mr_full_h):
                expanded.append(dict(o, key=o["key"] + _MONO_RAW_SUFFIX,
                                     label=o["label"] + "  (Mono Raw, binned preview)"))
            if offer_unbinned:
                expanded.append(dict(
                    o,
                    key=_HIGH_RES_UNBINNED_KEY,
                    label=o["label"] + "  (unbinned preview)",
                ))
        else:
            expanded.append(o)
            # Mono Raw twin: identical read-out, identical pipeline — only
            # the SAVE path differs (panchromatic conversion to a single
            # luminance plane, see _pan_mono_convert).  Offered as its own
            # dropdown entry rather than a hidden toggle because it is
            # destructive of colour: the choice should be visible where it
            # was made.  Withheld where it is meaningless or unsound: on a
            # true mono cartridge (nothing to convert) and on any QBC
            # full-res read-out, whose delivered buffer is already
            # software-remosaiced — only 6 of 16 true photosites survive
            # there, so a panchromatic image built from it would be mostly
            # interpolation.  _HIGH_RES_KEY is excluded by construction
            # (it captures the full-res remosaiced payload).
            if _mono_raw_variant_available(o, _mr_full_w, _mr_full_h):
                expanded.append(dict(
                    o,
                    key=o["key"] + _MONO_RAW_SUFFIX,
                    label=o["label"] + "  (Mono Raw)",
                ))
    return expanded


SENSOR_MODE_OPTIONS = _build_sensor_mode_options()
# Split out as its own boot phase: this step is the one whose cost scales
# with the sensor (mode count x raw buffer size), so a field journal shows
# immediately whether a slow boot on one sensor is enumeration or bring-up.
_boot_phase(f"sensor mode enumeration ({len(SENSOR_MODE_OPTIONS)} modes)")
for _opt in SENSOR_MODE_OPTIONS:
    print(f"[Camera] available sensor mode: {_opt['label']}  key={_opt['key']}")

# Fallback if sensor_modes returned nothing (shouldn't happen on a working
# camera) — keep the previously-hardcoded IMX492 mode so the app can still
# launch and the dropdown will show that one entry.
if not SENSOR_MODE_OPTIONS:
    SENSOR_MODE_OPTIONS = [{
        "key": "3792x2840@12",
        "size": (3792, 2840),
        "bit_depth": 12,
        "mp": 3792 * 2840 / 1e6,
        "label": "3792x2840  12-bit  (10.8 MP)",
    }]

# Pick mode: persisted key if it still matches an available mode, else the
# lowest-MP option (per product requirement).
_persisted_sensor_key = _PERSISTED_SETTINGS.get("sensor_mode_key")
# Migration: a persisted unbinned-preview selection on a sensor that no
# longer offers it (IMX294 — see _unbinned_preview_available) lands on the
# binned entry of the SAME 47 MP mode, not the lowest-MP fallback.  The
# corrected key is re-persisted on the next settings save.
if (_persisted_sensor_key == _HIGH_RES_UNBINNED_KEY
        and not any(o["key"] == _HIGH_RES_UNBINNED_KEY
                    for o in SENSOR_MODE_OPTIONS)):
    print("[Camera] Persisted unbinned 47 MP mode is not offered on this "
          "sensor — falling back to the binned-preview variant")
    _persisted_sensor_key = _HIGH_RES_KEY
# Same migration for a persisted Mono Raw selection that is no longer
# offered (a mono cartridge was fitted, or the mode itself vanished): land
# on the SAME read-out's ordinary colour entry rather than the lowest-MP
# fallback, so a cartridge swap changes the output format and nothing else.
# Sequential (not elif) so a remapped key is re-checked by the generic
# catch-all below — the base read-out may itself not be offered.
if (_is_mono_raw_key(_persisted_sensor_key)
        and not any(o["key"] == _persisted_sensor_key
                    for o in SENSOR_MODE_OPTIONS)):
    print("[Camera] Persisted Mono Raw mode is not offered on this sensor "
          "— falling back to the colour entry of the same read-out")
    _persisted_sensor_key = _mono_raw_base_key(_persisted_sensor_key)
if (_persisted_sensor_key
        and not any(o["key"] == _persisted_sensor_key
                    for o in SENSOR_MODE_OPTIONS)):
    # Any other persisted key the sensor no longer offers (a cartridge swap,
    # or a mode withheld by the product allowlist) falls back to the
    # lowest-MP entry below — logged so a field journal explains the reset.
    print(f"[Camera] Persisted sensor mode {_persisted_sensor_key} is not "
          f"offered on this sensor — falling back to the lowest-MP mode")
_sensor_mode_idx = 0
for _i, _opt in enumerate(SENSOR_MODE_OPTIONS):
    if _opt["key"] == _persisted_sensor_key:
        _sensor_mode_idx = _i
        break

_active_mode = SENSOR_MODE_OPTIONS[_sensor_mode_idx]

# 47 MP binned-preview variant: live pipeline runs the binned mode and only
# switches to 8432x5648 at shutter press.  The unbinned-preview variant (and
# every other mode) runs the selected read-out 1:1 via the else branch.
# Constants are defined above _build_sensor_mode_options().
if _mono_raw_base_key(_active_mode["key"]) == _HIGH_RES_KEY:
    SENSOR_MODE_W, SENSOR_MODE_H = _HIGH_RES_BINNED_W, _HIGH_RES_BINNED_H
    SENSOR_MODE_BITS = 12
    # Capture is the mode's FULL read-out (8432x5648 on the 47 MP
    # sensors), never a cropped/derived size.  The preview lores is
    # shaped to this same aspect via _preview_lores_size below, so the
    # viewfinder shows the capture's framing (ScalerCrop centre-crops
    # the binned read-out to match).
    _CAPTURE_FULL_W, _CAPTURE_FULL_H = _active_mode["size"]
else:
    SENSOR_MODE_W, SENSOR_MODE_H = _active_mode["size"]
    SENSOR_MODE_BITS = _active_mode["bit_depth"]
    _CAPTURE_FULL_W, _CAPTURE_FULL_H = _active_mode["size"]

_SENSOR_MODE_CFG = {
    "output_size": (SENSOR_MODE_W, SENSOR_MODE_H),
    "bit_depth": SENSOR_MODE_BITS,
}

FULL_W, FULL_H = SENSOR_MODE_W, SENSOR_MODE_H
print(f"[Camera] Selected sensor mode: {_active_mode['label']}")
if _mono_raw_base_key(_active_mode["key"]) == _HIGH_RES_KEY:
    print(f"[Camera] Live pipeline forced to {SENSOR_MODE_W}x{SENSOR_MODE_H}@"
          f"{SENSOR_MODE_BITS}-bit; full {_CAPTURE_FULL_W}x{_CAPTURE_FULL_H} "
          f"used only at shutter press")
elif _active_mode["key"] == _HIGH_RES_UNBINNED_KEY:
    print(f"[Camera] Live pipeline runs the unbinned {SENSOR_MODE_W}x"
          f"{SENSOR_MODE_H} read-out 1:1; preview rate is sensor-limited")

# Lores/preview stream shaped to the active mode's capture aspect (see
# _preview_lores_size) — never a fixed size, so a 16:9 sensor previews its
# full native FOV instead of a silent 4:3 crop.
preview_size = _preview_lores_size(_CAPTURE_FULL_W, _CAPTURE_FULL_H)
_geom_cache = {
    (preview_size[1], preview_size[0]): _compute_display_geometry(preview_size[0], preview_size[1])
}
preview_config = picam2.create_preview_configuration(
    main={"size": preview_size, "format": "RGB888"},
    lores=None,
    display=None,  # no internal preview thread
    raw={"size": (SENSOR_MODE_W, SENSOR_MODE_H), "format": "R16"},
    sensor=_SENSOR_MODE_CFG,
)
# Default "auto" range (1/8000..20s) – full sensor capability
DEFAULT_FRAME_LIMITS = (125, 20000000)
# Preview sensor readout cadence.  The display only shows 20 fps, so there is
# no point reading the full main+raw+lores pipeline any faster — frame duration
# only needs to be >= the exposure time, so bounding the readout to the display
# rate is invisible to exposure/capture but cuts how often the heavy pipeline
# runs (a big battery win).  Keep these in sync with TARGET_FPS / TARGET_FPS_IDLE
# (50000us = 20 fps, 100000us = 10 fps).
_PREVIEW_FRAME_DUR_US = 50000              # 20 fps preview readout (matches display)
_PREVIEW_FRAME_DUR_IDLE_US = 100000        # 10 fps when backlight dimmed
# Thermal load-shed readout tiers (see _thermal_shed_tick): the sensor +
# pipeline rate drops with the UI pacing so the whole per-frame chain sheds
# together. Keep in sync with TARGET_FPS_SHED1/2.
_PREVIEW_FRAME_DUR_SHED1_US = 66666        # 15 fps at shed level 1 (>= 65 C)
_PREVIEW_FRAME_DUR_SHED2_US = 83333        # 12 fps at shed level 2 (>= 70 C)
# Pin the preview frame duration to the display rate (was (125, 33333), which let
# the sensor free-run far above 20 fps).  In AUTO mode the AE compensates with
# ISO; for manual slow-shutter speeds the preview is digitally brightened.
_PREVIEW_FRAME_LIMITS = (_PREVIEW_FRAME_DUR_US, _PREVIEW_FRAME_DUR_US)
# AGC constraint mode, pinned to Normal (ConstraintNormal = 0) rather than
# left to the IPA default.  The tuning defines two lists: "normal" carries a
# single LOWER bound (it can only ever ASK FOR MORE light), while "highlight"
# adds an UPPER bound — "the brightest 1% of pixels must not exceed 0.4 of
# full scale" — which clamps exposure DOWN to protect highlights.  Field case
# (journal-confirmed with RPiAgc:DEBUG): after a binned-mode 47 MP capture the
# preview settled ~2 stops under with AGC's own region metering asking for
# 2.16x MORE light and an UPPER constraint overruling it every frame
# ("Initial Y 0.0739 target 0.162 gives gain 2.16" -> "Final gain 1.00
# (target_Y 0.4)").  The top-quantile statistic that constraint reads comes
# back mis-scaled from the QBC round trip, so the constraint binds on a scene
# it had not bound on moments earlier, and it re-imposes itself on every
# frame — which is why seeding AE's starting point could never hold.
# Pinning Normal removes the UPPER bound from the loop entirely, so a bad
# top-quantile reading can no longer darken the preview; the region metering
# (which measures correctly) owns the exposure.  It is also the right mode
# for a viewfinder that must match the capture: highlight-priority AE
# deliberately under-exposes the scene to hold speculars, which is not what
# this camera promises.  Set alongside AeMeteringMode everywhere that is
# applied, and re-asserted live in _apply_shutter_controls.
_AE_CONSTRAINT_NORMAL = 0

preview_config["controls"]["AeMeteringMode"] = 2
preview_config["controls"]["AeConstraintMode"] = _AE_CONSTRAINT_NORMAL
preview_config["controls"]["NoiseReductionMode"] = 0
preview_config["controls"]["FrameDurationLimits"] = _PREVIEW_FRAME_LIMITS
# Persisted white-balance selection first, mono neutralisation second — on a
# mono sensor the WB dict is empty and the neutral gains must win regardless.
preview_config["controls"].update(_wb_controls())
preview_config["controls"].update(_mono_awb_controls())

_STILL_CONTROLS = {
    "AeMeteringMode": 2,
    "AeConstraintMode": _AE_CONSTRAINT_NORMAL,
    "NoiseReductionMode": 0,
    "FrameDurationLimits": _PREVIEW_FRAME_LIMITS,
}
# Persisted user white balance (preset AwbMode or measured custom gains) so a
# saved selection applies from the first configured frame after boot.
_STILL_CONTROLS.update(_wb_controls())
# Persisted mono-sensor verdict: neutralise the per-channel AWB gains before
# the first pipeline build so a mono sensor never sees them (see
# _set_mono_sensor_active, which keeps this dict in sync when the verdict
# flips at runtime).
_STILL_CONTROLS.update(_mono_awb_controls())


_live_main_size = _live_still_main_size()
still_config = picam2.create_still_configuration(
    main={"size": _live_main_size, "format": "RGB888"},
    lores={"size": preview_size, "format": "RGB888", "preserve_ar": True},
    raw={"size": (SENSOR_MODE_W, SENSOR_MODE_H), "format": "R16"},
    sensor=_SENSOR_MODE_CFG,
    controls=dict(_STILL_CONTROLS),
    # Unbinned 47 MP is the one live pipeline whose buffer set is huge; on
    # low-memory boards it runs single-buffered (see _HIGH_RES_BUFFER_COUNT)
    # — unless the mono fast-path shrank the main stream, which makes
    # double-buffering affordable again (smoother sensor-limited preview).
    buffer_count=(2 if _live_main_size != (FULL_W, FULL_H)
                  else (_HIGH_RES_BUFFER_COUNT
                        if _active_mode["key"] == _HIGH_RES_UNBINNED_KEY
                        else 2)),
)
if _live_main_size != (FULL_W, FULL_H):
    print(f"[Camera] Live-main fast-path: live main stream at "
          f"{_live_main_size[0]}x{_live_main_size[1]} (capture path never "
          f"reads the live main in this mode)")

# Built only when the 47 MP mode is selected.  When non-None the high-res
# helper rebuilds still_config in place to the 47 MP shape, captures, then
# rebuilds it again to the 11 MP shape and restarts.
if _mono_raw_base_key(_active_mode["key"]) == _HIGH_RES_KEY:
    # main and raw are the mode's full read-out (8432x5648) — the sensor
    # block selects the same full 47 MP mode, so the capture is the
    # entire frame with no ScalerCrop involvement.
    _high_res_capture_config = picam2.create_still_configuration(
        main={"size": (_CAPTURE_FULL_W, _CAPTURE_FULL_H), "format": "RGB888"},
        raw={"size": (_CAPTURE_FULL_W, _CAPTURE_FULL_H), "format": "R16"},
        sensor={"output_size": (_CAPTURE_FULL_W, _CAPTURE_FULL_H),
                "bit_depth": 12},
        controls=dict(_STILL_CONTROLS),
        buffer_count=_HIGH_RES_BUFFER_COUNT,
    )
    print(f"[Camera] High-res capture config built: {_CAPTURE_FULL_W}x{_CAPTURE_FULL_H} @ 12-bit, buffer_count={_HIGH_RES_BUFFER_COUNT}")
else:
    _high_res_capture_config = None

_aspect_capture_dims = [
    _largest_ratio_crop_dims(_CAPTURE_FULL_W, _CAPTURE_FULL_H, opt["ratio"])
    for opt in ASPECT_OPTIONS
]


def _rebuild_camera_configs_for_active_sensor_mode():
    """Recompute preview_size, preview/still configs, the optional high-res
    capture config, and aspect dims from the currently-selected
    SENSOR_MODE_OPTIONS entry.  Does not (re)start the pipeline — callers
    either let charge-mode exit re-apply still_config or invoke
    `_set_sensor_mode_idx` which handles the restart."""
    global SENSOR_MODE_W, SENSOR_MODE_H, SENSOR_MODE_BITS, _SENSOR_MODE_CFG
    global FULL_W, FULL_H, preview_size, preview_config, still_config
    global _aspect_capture_dims, _high_res_capture_config
    global _CAPTURE_FULL_W, _CAPTURE_FULL_H

    opt = SENSOR_MODE_OPTIONS[_sensor_mode_idx]
    if _mono_raw_base_key(opt["key"]) == _HIGH_RES_KEY:
        SENSOR_MODE_W, SENSOR_MODE_H = _HIGH_RES_BINNED_W, _HIGH_RES_BINNED_H
        SENSOR_MODE_BITS = 12
        # Capture is the mode's full read-out (8432x5648).  See the
        # matching block at module load.
        _CAPTURE_FULL_W, _CAPTURE_FULL_H = opt["size"]
    else:
        SENSOR_MODE_W, SENSOR_MODE_H = opt["size"]
        SENSOR_MODE_BITS = opt["bit_depth"]
        _CAPTURE_FULL_W, _CAPTURE_FULL_H = opt["size"]

    _SENSOR_MODE_CFG = {
        "output_size": (SENSOR_MODE_W, SENSOR_MODE_H),
        "bit_depth": SENSOR_MODE_BITS,
    }
    FULL_W, FULL_H = SENSOR_MODE_W, SENSOR_MODE_H
    preview_size = _preview_lores_size(_CAPTURE_FULL_W, _CAPTURE_FULL_H)
    _geom_cache[(preview_size[1], preview_size[0])] = _compute_display_geometry(
        preview_size[0], preview_size[1]
    )
    _geom_cache[(FULL_H, FULL_W)] = _compute_display_geometry(FULL_W, FULL_H)

    preview_config = picam2.create_preview_configuration(
        main={"size": preview_size, "format": "RGB888"},
        lores=None,
        display=None,
        raw={"size": (SENSOR_MODE_W, SENSOR_MODE_H), "format": "R16"},
        sensor=_SENSOR_MODE_CFG,
    )
    preview_config["controls"]["AeMeteringMode"] = 2
    preview_config["controls"]["AeConstraintMode"] = _AE_CONSTRAINT_NORMAL
    preview_config["controls"]["NoiseReductionMode"] = 0
    preview_config["controls"]["FrameDurationLimits"] = _PREVIEW_FRAME_LIMITS
    preview_config["controls"].update(_wb_controls())
    preview_config["controls"].update(_mono_awb_controls())

    _live_main = _live_still_main_size()
    still_config = picam2.create_still_configuration(
        main={"size": _live_main, "format": "RGB888"},
        lores={"size": preview_size, "format": "RGB888", "preserve_ar": True},
        raw={"size": (SENSOR_MODE_W, SENSOR_MODE_H), "format": "R16"},
        sensor=_SENSOR_MODE_CFG,
        controls=dict(_STILL_CONTROLS),
        # See the module-level build: unbinned 47 MP single-buffers on
        # low-memory boards — unless the mono fast-path shrank the main
        # stream, which makes double-buffering affordable again.
        buffer_count=(2 if _live_main != (FULL_W, FULL_H)
                      else (_HIGH_RES_BUFFER_COUNT
                            if opt["key"] == _HIGH_RES_UNBINNED_KEY else 2)),
    )
    if _live_main != (FULL_W, FULL_H):
        print(f"[Camera] Live-main fast-path: live main stream at "
              f"{_live_main[0]}x{_live_main[1]} (capture path never "
              f"reads the live main in this mode)")

    if _mono_raw_base_key(opt["key"]) == _HIGH_RES_KEY:
        # main and raw are the mode's full read-out (8432x5648) — no crop.
        _high_res_capture_config = picam2.create_still_configuration(
            main={"size": (_CAPTURE_FULL_W, _CAPTURE_FULL_H),
                  "format": "RGB888"},
            raw={"size": (_CAPTURE_FULL_W, _CAPTURE_FULL_H), "format": "R16"},
            sensor={"output_size": (_CAPTURE_FULL_W, _CAPTURE_FULL_H),
                    "bit_depth": 12},
            controls=dict(_STILL_CONTROLS),
            buffer_count=_HIGH_RES_BUFFER_COUNT,
        )
        print(f"[Camera] High-res capture config rebuilt: {_CAPTURE_FULL_W}x{_CAPTURE_FULL_H} @ 12-bit, buffer_count={_HIGH_RES_BUFFER_COUNT}")
    else:
        _high_res_capture_config = None

    _aspect_capture_dims = [
        _largest_ratio_crop_dims(_CAPTURE_FULL_W, _CAPTURE_FULL_H, o["ratio"])
        for o in ASPECT_OPTIONS
    ]


def _set_sensor_mode_idx(new_idx, restart_pipeline=True):
    """Switch to a different sensor mode.  Used by the charge-mode dropdown.

    `restart_pipeline=True` stops the camera, applies the new still_config
    and restarts.  When called from inside charge mode (where the pipeline
    is already stopped), pass False — _exit_charge_mode() will start it.

    Persistence only happens after a pipeline actually starts on the new
    mode: with `restart_pipeline=True` that's verified right here (reverting
    to the previous mode — see `_start_still_pipeline_with_fallback` — on
    failure so a bad mode is never the thing that gets saved); with
    `restart_pipeline=False` the caller (charge-mode dropdown) starts the
    pipeline later via `_exit_charge_mode`, which persists on its own
    success.
    """
    global _sensor_mode_idx
    if not (0 <= new_idx < len(SENSOR_MODE_OPTIONS)):
        return False
    if new_idx == _sensor_mode_idx:
        return False
    _prev_idx = _sensor_mode_idx
    _sensor_mode_idx = new_idx
    # Burst SR is refused on some cartridges, at the 47 MP modes, and in
    # Mono Raw (see _bm_unavailable); an armed session toggle is disarmed
    # when the user switches into one.  Session-only state, so nothing to
    # restore if the pipeline start below reverts the mode.
    _bm_why = _bm_unavailable()
    if _bm_why:
        with _bm_lock:
            _bm_was_armed = _bm_active
        if _bm_was_armed:
            _exit_burst_mode()
            _post_save_warning(f"Burst SR off — unavailable {_bm_why}")
    # Same rule for flash sync (refused at 47 MP: a ring of full-res raw
    # frames outruns MemAvailable) — deselect rather than leave a mode
    # selected that the shutter could never arm.
    _flash_why = _flash_unavailable()
    if _flash_why:
        with _flash_lock:
            _flash_was_on = _flash_mode_active
        if _flash_was_on:
            _exit_flash_mode()
            _post_save_warning(f"Flash sync off — unavailable {_flash_why}")
    _rebuild_camera_configs_for_active_sensor_mode()
    # The binned 47 MP mode offers fewer ISOs (the x4 capture boost must
    # stay within the sensor's gain ceiling), but the selection is NOT
    # clamped here: a switch can still fail and revert below, and the
    # fallback restores _sensor_mode_idx, not _iso_idx — clamping before
    # the start permanently lowered the user's ISO on a failed switch.
    # The clamp rides the success paths of
    # _start_still_pipeline_with_fallback instead (which also covers the
    # restart_pipeline=False charge-mode flow, whose pipeline starts later
    # through that same helper).
    print(f"[Camera] Sensor mode switched to {SENSOR_MODE_OPTIONS[new_idx]['label']}")
    if not restart_pipeline:
        return True
    try:
        picam2.stop()
    except Exception:
        pass
    if _start_still_pipeline_with_fallback(revert_idx=_prev_idx):
        _debounced_save_settings()
        return True
    # Even the fallback chain in _start_still_pipeline_with_fallback (previous
    # mode, then the binned default) failed to start anything — nothing to
    # persist; that helper already posted a user-visible warning.
    return False


def _log_configured_raw_stream():
    """One line stating the raw stream format libcamera actually granted
    (the config requests R16, but the pipeline aligns it per driver) — the
    mono JPG path depends on this format, so make it visible in the journal."""
    try:
        raw_now = (picam2.camera_configuration() or {}).get("raw") or {}
        print(f"[Camera] Raw stream: {raw_now.get('format')} "
              f"{raw_now.get('size')} stride={raw_now.get('stride')}")
    except Exception:
        pass


def _start_still_pipeline_with_fallback(revert_idx=None):
    """configure(still_config) + start with the standard preview frame cap.

    On failure the fallback chain is, in order:
      1. Unbinned-preview 47 MP special case (unchanged): that variant asks
         for the largest buffer set the firmware ever allocates (full-res
         main + raw at buffer_count=2), so an allocation failure on a
         constrained dma heap is plausible. Fall back to the binned-preview
         47 MP entry — same sensor, always present alongside.
      2. `revert_idx` — the mode that was actually running before this
         switch was attempted (passed by `_set_sensor_mode_idx`), if given
         and different from the mode that just failed.
      3. The binned-preview default entry (index 0, the sensor-agnostic
         lowest-MP mode every sensor exposes) as the last resort, so a
         failure never leaves the camera dead (frozen preview / boot
         crash-loop).
    A notice is posted whenever a fallback (any of the above) is used.
    Returns True when a pipeline is running."""
    global _sensor_mode_idx
    # An in-flight CMA warm holds hundreds of MB the buffer set below may
    # need — make it let go first (no-op when none is running).
    _hires_warm_yield("pipeline start")
    try:
        picam2.configure(still_config)
        picam2.start()
        picam2.set_controls({"FrameDurationLimits": _PREVIEW_FRAME_LIMITS})
        _log_configured_raw_stream()
        # A still pipeline is now RUNNING on the selected mode — the one
        # point every start funnels through (mode switch, charge exit,
        # sleep wake, self-heal), so apply the mode's ISO limit here and
        # never earlier: clamping before the start moved the user's ISO
        # even when the switch failed and reverted.  During the BOOT
        # invocation this call quietly no-ops (the 47 MP display
        # constants are defined just after it, so the multiplier reads
        # as 1) — the dedicated boot clamp below _apply_shutter_controls
        # covers that pass.
        _iso_clamp_to_available("pipeline start")
        return True
    except Exception as exc:
        print(f"[Camera] still pipeline start failed: {exc}")

    def _try_switch_to(idx, label):
        global _sensor_mode_idx
        if not (0 <= idx < len(SENSOR_MODE_OPTIONS)) or idx == _sensor_mode_idx:
            return False
        print(f"[Camera] falling back to {label}")
        _sensor_mode_idx = idx
        _rebuild_camera_configs_for_active_sensor_mode()
        try:
            picam2.stop()
        except Exception:
            pass
        try:
            picam2.configure(still_config)
            picam2.start()
            picam2.set_controls({"FrameDurationLimits": _PREVIEW_FRAME_LIMITS})
            _log_configured_raw_stream()
            # Same post-start ISO limit as the primary path: the mode now
            # running is whatever this fallback landed on (possibly the
            # restrictive binned 47 MP entry, possibly the reverted
            # previous mode, where this no-ops and the user's ISO stays).
            _iso_clamp_to_available("pipeline fallback")
            return True
        except Exception as exc2:
            print(f"[Camera] fallback pipeline start failed: {exc2}")
            return False

    # 1) Unbinned 47MP -> binned 47MP special case (kept intact).
    if SENSOR_MODE_OPTIONS[_sensor_mode_idx].get("key") == _HIGH_RES_UNBINNED_KEY:
        for _i, _o in enumerate(SENSOR_MODE_OPTIONS):
            if _o.get("key") == _HIGH_RES_KEY:
                if _try_switch_to(_i, "the binned-preview 47 MP mode"):
                    _debounced_save_settings()
                    _post_save_warning("Sensor mode unavailable — reverted")
                    return True
                break

    # 2) The mode that was running before this switch was attempted.
    if revert_idx is not None:
        label = SENSOR_MODE_OPTIONS[revert_idx]["label"] if 0 <= revert_idx < len(SENSOR_MODE_OPTIONS) else "previous sensor mode"
        if _try_switch_to(revert_idx, f"the previous sensor mode ({label})"):
            _post_save_warning("Sensor mode unavailable — reverted")
            return True

    # 3) Last resort: the binned-preview default entry.
    if _try_switch_to(0, "the default sensor mode"):
        _post_save_warning("Sensor mode unavailable — reverted")
        return True

    return False


# Elevated scheduler priority for the preview/UI process (best-effort).
# Done here rather than via Nice= in camera.service: the systemd *user*
# manager lacks CAP_SYS_NICE, so a negative Nice= there can never apply —
# this process runs with root privileges and can renice itself.
try:
    os.setpriority(os.PRIO_PROCESS, 0, -5)
except Exception:
    pass

# CPU thermal cap is deliberately NOT applied here: everything from now to
# the first main-loop iteration is boot-critical path (camera pipeline
# bring-up, config build, first capture), and it runs measurably faster at
# the full firmware ceiling (2.4 GHz). The main loop applies the cap on its
# first iteration — the moment the user has a picture. Boot-time cost of the
# uncapped window is ~10 J, unmeasurable against the pack.
_thermal_cap_pending = True

# Battery: drop a link-less ethernet PHY out of its polling loop (no-op when
# a cable is attached — see _idle_ethernet_down).
threading.Thread(target=_idle_ethernet_down, daemon=True).start()

# Run in still_config mode for instant capture (raw stream always available).
# The fallback keeps boot alive if the persisted mode is the unbinned 47 MP
# variant and its (largest-in-firmware) buffer allocation fails.
_boot_phase("camera config build")
_update_splash("Starting camera...", 0.80)
_start_still_pipeline_with_fallback()

# Pre-cache geometry for full resolution frames
_geom_cache[(FULL_H, FULL_W)] = _compute_display_geometry(FULL_W, FULL_H)


# The 11 MP preview reads out as a 2x2-binned area of the same sensor that
# the 47 MP capture reads at 1:1.  At identical ExposureTime and
# AnalogueGain the binned readout sums 4 pixels' worth of light, so a 47 MP
# capture using those raw values comes out ~2 stops dark.  Multiply the
# transferred AnalogueGain by this factor to compensate.  Adjust if the
# resulting captures look too bright/dark.
_HIGH_RES_GAIN_BOOST = 4.0
# How the ISP maps the boosted-gain capture onto the 8-bit main (JPG)
# stream has proven unstable across tuning/firmware combinations: the IPA
# sometimes rebalances DigitalGain down against the boosted AnalogueGain
# (JPG ~2 stops dark) and sometimes passes the boost straight through
# (JPG blown out).  A fixed open-loop multiplier tuned for one behaviour
# breaks on the other, so the JPG is instead brightness-matched to the
# binned preview frame the user composed on: measure both frames'
# approximate linear-light means and apply the ratio through a gamma-aware
# LUT.  The DNG (raw stream) is never touched by this correction.
_HIRES_MATCH_GAMMA = 2.2          # display-curve approximation for the match
_HIRES_MATCH_GAIN_MIN = 0.2      # never darken more than ~2.3 stops
_HIRES_MATCH_GAIN_MAX = 8.0      # never brighten more than 3 stops
_HIRES_MATCH_MIN_LIN_MEAN = 1e-5  # ~black frame: ratio too noisy, abstain


def _hires_linear_mean(frame_u8, step):
    """Approximate linear-light mean of a uint8 frame, sampled on a ::step
    decimated grid so even the 47 MP main array stays cheap to measure.
    Returns None when the frame is missing or too dark for the exposure
    ratio to be stable (the caller then skips the brightness match)."""
    if frame_u8 is None:
        return None
    try:
        samples = frame_u8[::step, ::step]
        lin = np.power(
            samples.astype(np.float32) * (1.0 / 255.0), _HIRES_MATCH_GAMMA
        )
        mean = float(lin.mean())
        return mean if mean >= _HIRES_MATCH_MIN_LIN_MEAN else None
    except Exception:
        return None


def _hires_exposure_match_lut(gain):
    """256-entry LUT applying `gain` in linear light under the display
    gamma — the closest a post-ISP 8-bit operation gets to a true exposure
    change.  Highlights can clip in the JPG only when brightening (the DNG
    keeps its headroom)."""
    codes = np.arange(256, dtype=np.float32) / 255.0
    lin = np.power(codes, _HIRES_MATCH_GAMMA) * float(gain)
    out = np.power(np.clip(lin, 0.0, 1.0), 1.0 / _HIRES_MATCH_GAMMA) * 255.0
    # (1, 256) shape: some OpenCV builds assert lut.rows == 1, and a 1-D
    # (256,) array maps to a 256x1 Mat.
    return np.clip(out + 0.5, 0.0, 255.0).astype(np.uint8).reshape(1, 256)


# Liveness bound for every blocking wait inside the 47 MP mode-switch
# capture.  The all-pixel read-out is the one pipeline the live preview has
# never proven (the binned variant switches to it cold at shutter press), so
# a failed mode switch / marginal link can deliver NO frames at all.  These
# waits used to be unbounded: the worker thread then blocked forever with
# _high_res_capture_busy set, which froze the preview, swallowed every
# subsequent shutter press, and disabled the main loop's self-heal (its
# error counter deliberately resets while the busy flag is up) — a battery
# pull was the only way out.  15 s is far beyond the slowest healthy leg
# (the whole capture normally takes ~2 s); on timeout the shot is aborted,
# picamera2's cancelled jobs are flushed, and the normal preview restore
# runs, so a dead 47 MP read-out degrades to a lost capture + HUD warning
# instead of a hang.
_HIGH_RES_WAIT_S = 15.0
try:
    # concurrent.futures raised its own TimeoutError before Python 3.11
    # (it aliases the builtin from 3.11 on); picamera2's bounded waits
    # surface whichever one the running interpreter uses.
    from concurrent.futures import TimeoutError as _FuturesTimeoutError
except Exception:
    _FuturesTimeoutError = TimeoutError


def _hires_wait_timed_out(exc):
    """True when a bounded picamera2 wait gave up rather than erroring —
    the signal that the 47 MP pipeline is not delivering frames at all."""
    return isinstance(exc, (TimeoutError, _FuturesTimeoutError))


def _hires_bounded_wait(job, timeout_s):
    """Resolve a picamera2 Job with a hard deadline on ANY picamera2 version.

    Current picamera2 documents a numeric ``wait`` as a timeout, but older
    releases (e.g. 0.3.12, the first Pi 5-capable one) treat any truthy
    ``wait`` as "block forever" — ``Picamera2.wait``/``Job.get_result`` there
    accept no timeout at all. So the capture calls dispatch with
    ``wait=False`` and the deadline is applied here: through the modern
    ``wait(job, timeout=)`` API when present, else directly on the Job's
    stdlib Future (present in every version; ``Future.result(timeout=)``
    raises the same concurrent.futures timeout `_hires_wait_timed_out`
    detects). A job that times out may still be queued inside picamera2 —
    the mode-dead path flushes it (see ``cancel_all_and_flush``)."""
    try:
        return picam2.wait(job, timeout=timeout_s)
    except TypeError:
        # Old picamera2: wait() has no timeout kwarg. (A TypeError raised by
        # the job's own functions re-raises identically below, so this can
        # never mask one.)
        pass
    fut = getattr(job, "_future", None)
    if fut is not None:
        return fut.result(timeout=timeout_s)
    # No timeout mechanism at all (unknown fork): degrade to the historical
    # unbounded wait rather than break the capture.
    return picam2.wait(job)


# Ceiling on the post-switch control drain (see the drain loop in
# _perform_high_res_capture).  The drain exists so the injected
# ExposureTime/AnalogueGain have actually reached the sensor before the
# capture request is issued.  At the 47 MP read-out's few-fps rate each
# drained frame costs ~400-500 ms of the user-visible mode-switch wait, so
# the loop stops the moment a frame's own metadata confirms the settings are
# live, and only burns the full count when it cannot confirm them.
_HIGH_RES_DRAIN_FRAMES = 4
# Match tolerances for that confirmation.  Both controls are quantized on the
# way to the sensor (exposure to whole line-times, gain to the sensor's
# register steps), so an equality test would never pass.  A few percent of
# slack cannot let an unsettled frame read as settled: the value an
# unsettled frame carries is the pre-transfer gain, which differs by the
# whole 4x _HIGH_RES_GAIN_BOOST.
_HIGH_RES_DRAIN_EXP_TOL = 0.05      # 5% of the requested ExposureTime...
_HIGH_RES_DRAIN_EXP_ABS_US = 100.0  # ...or this much, whichever is larger
_HIGH_RES_DRAIN_GAIN_TOL = 0.05     # 5% of the requested AnalogueGain
# Frames the 47 MP capture will wait for a just-changed ISO selection to
# reach the sensor before giving up and capturing on the plan anyway (see
# the coherence guard in _perform_high_res_capture).  The binned preview
# runs at ~20 fps here, so this is ~150 ms worst case and is only ever
# paid when the first frame does not already echo the selection.
_HIRES_SEL_SETTLE_FRAMES = 3


def _hires_boosted_gain(live_gain):
    """The 47 MP capture's AnalogueGain, CLAMPED to what the sensor can
    actually deliver, plus the shortfall factor left over.

    The unbinned read-out collects roughly a quarter of the signal per
    pixel that the 2x2-binned preview does, so the transfer asks for
    _HIGH_RES_GAIN_BOOST times the live gain.  At low ISO there is
    headroom and the sensor delivers it.  Near the gain ceiling there is
    not: the request used to go out unclamped, libcamera clamped it
    silently, and the capture came back UNDEREXPOSED by the shortfall —
    which `_hires_exposure_match_lut` then made up with a digital lift in
    linear light, amplifying read noise and any residual black-level
    offset with it (the offset reads blue, since blue carries the largest
    AWB gain under warm light).

    Clamping here also fixes a latency bug: `_hires_exposure_settled`
    compares frame metadata against the REQUESTED gain, so an unclamped
    request could never be confirmed and every capture spent the full
    fixed-length control drain.

    Returns (gain, shortfall) where shortfall >= 1.0 is the factor the
    sensor could not provide (1.0 = fully delivered).  Never raises — an
    unreadable control range falls back to the unclamped request, which
    is exactly the old behaviour."""
    try:
        want = float(live_gain) * _HIGH_RES_GAIN_BOOST
    except (TypeError, ValueError):
        return None, 1.0
    try:
        lo, hi, _default = picam2.camera_controls["AnalogueGain"]
        hi = float(hi)
        if hi > 0 and want > hi:
            return hi, want / hi
        lo = float(lo)
        if lo > 0 and want < lo:
            return lo, 1.0
    except Exception as exc:
        print(f"[HiRes] gain range unreadable, requesting unclamped: {exc}")
    return want, 1.0


def _hires_exposure_settled(md, want_exp_us, want_gain):
    """True when frame metadata `md` proves the injected 47 MP exposure
    controls are the ones the sensor actually used for that frame.

    Deliberately conservative: this may only ever END the drain early on
    positive evidence, never shorten it on a guess.  Missing metadata, a
    missing key, or nothing to compare against (neither control was
    injected) all return False, leaving the caller on the full fixed-length
    drain it used before.
    """
    if not md:
        return False
    checked = False
    try:
        if want_exp_us is not None:
            got = md.get("ExposureTime")
            if got is None:
                return False
            tol = max(abs(float(want_exp_us)) * _HIGH_RES_DRAIN_EXP_TOL,
                      _HIGH_RES_DRAIN_EXP_ABS_US)
            if abs(float(got) - float(want_exp_us)) > tol:
                return False
            checked = True
        if want_gain is not None:
            got = md.get("AnalogueGain")
            if got is None:
                return False
            tol = abs(float(want_gain)) * _HIGH_RES_DRAIN_GAIN_TOL
            if abs(float(got) - float(want_gain)) > tol:
                return False
            checked = True
    except (TypeError, ValueError):
        # Unparseable metadata is not evidence of anything.
        return False
    return checked


# Set while the 47 MP capture worker thread owns picam2 (during the
# stop / configure 47 MP / capture / configure 11 MP / start sequence).
# The main loop must NOT call picam2.capture_array() / capture_metadata()
# during this window — both threads accessing the camera object would
# fight for the libcamera pipeline.  Instead the main loop reuses
# _last_lores_frame so overlays keep updating and the UI stays
# responsive while the capture runs in the background.
_high_res_capture_busy = threading.Event()
# Set by the worker as soon as the sensor read-out is complete (the
# capture request is in hand — before the raw/main copies even run).
# The main loop watches this to lift the capture blackout flash early —
# the user only needs to hold the camera still until this fires; the
# remaining steps (copies, stop/teardown settle, restart, proof frame)
# run while the cached preview frame is shown instead of a black canvas.
_high_res_capture_done = threading.Event()
_last_lores_frame = None


# --- Post-capture preview restore (closed-loop, was a flat 2.0 s dwell) ---
#
# After the 47 MP capture the full-res pipeline is torn down and the binned
# preview one is built in its place.  libcamera finishes that teardown
# asynchronously, and handing it the new config too early used to leave the
# restored preview dead — so the old code slept a flat 2.0 s before
# reconfiguring, on every capture, whether or not it was needed.
#
# There is nothing to poll while the camera is stopped: the only evidence
# the pipeline is healthy is a delivered frame, and a frame requires the
# very configure/start the dwell was protecting.  So the wait is inverted
# rather than instrumented — settle briefly, bring the pipeline up, then
# PROVE it is alive by waiting for one real frame.  A restore that fails
# the proof is torn down and retried on the historical full dwell, so
# guessing short costs a retry instead of costing the user a dead preview.
#
# Two things make this safe now that were not true when 2.0 s was chosen
# (the dwell predates them by two weeks): the main loop's camera waits are
# bounded and it self-heals a persistently failing pipeline through
# _start_still_pipeline_with_fallback, and _high_res_capture_busy is
# cleared in the worker's finally — so even a total restore failure here
# degrades to the standard self-heal instead of the permanent freeze that
# the original "1.0 s caused intermittent freezes" note describes.
_HIGH_RES_SETTLE_S = 0.4          # first attempt's blind settle
_HIGH_RES_SETTLE_RETRY_S = 2.0    # historical dwell, used to retry
_HIGH_RES_RESTORE_ATTEMPTS = 2
# Pre-capture dwell: the flat sleep between stopping the binned preview and
# handing libcamera the 47 MP config (step 2 of _perform_high_res_capture).
# It is the one remaining fixed dwell on the BLACKOUT critical path — the
# restore direction's dwell is credited against the copy work and proven by
# a frame, but nothing runs between this stop and configure that could be
# credited, so it is paid in full on every shot.  Its value is inherited,
# not measured: libcamera's Camera::stop() is synchronous, and picamera2's
# own switch_mode_capture_request_and_stop() reconfigures with no dwell at
# all.  The default is kept until a field A/B says otherwise —
# WLV_HIRES_PRE_SETTLE_S=0.1 (or 0) on a unit file, then read the
# `[HiRes] blackout` breakdown: a configure/start that still comes up and
# a first frame that still lands on time at the shorter value is the
# evidence for lowering the default.
#
# It is now closed-loop, the same shape as the restore side: a short
# fast-path dwell (_HIGH_RES_PRE_SETTLE_S), then the 47 MP pipeline is
# brought up and PROVEN by its first frame inside a bound sized for a
# healthy start (_HIGH_RES_PRE_PROOF_S plus the exposure, never above
# _HIGH_RES_WAIT_S).  A configure/start that raises, or a first frame that
# does not arrive in that bound, is torn down (flush + stop) and retried
# ONCE on the historical dwell (_HIGH_RES_PRE_SETTLE_RETRY_S), which also
# becomes the session's dwell (_hires_pre_settle_s escalates permanently,
# exactly like _hires_settle_s) — so a stack that genuinely needs the
# long teardown pays one bounded retry rather than every shot, and one
# that does not never pays the 0.3 s at all.  The last attempt keeps the
# full _HIGH_RES_WAIT_S liveness bound and the existing mode-dead
# handling, so a truly dead read-out degrades exactly as before.
# WLV_HIRES_PRE_SETTLE_S overrides the fast-path dwell for A/B (0.3 turns
# the fast path back into the historical flat dwell).
_HIGH_RES_PRE_SETTLE_S = 0.1          # fast-path dwell (was a flat 0.3)
_HIGH_RES_PRE_SETTLE_RETRY_S = 0.3    # historical dwell, used to retry
_HIGH_RES_PRE_ATTEMPTS = 2
# First-frame proof bound for the fast path.  A healthy 47 MP start lands
# its first request in ~1 s (stream-on + exposure + a ~0.5 s read-out +
# ISP); a false negative costs this wait plus one retry, so it is
# generous, and it grows with the planned exposure (a 30 s manual speed
# cannot be proven in 4 s).
_HIGH_RES_PRE_PROOF_S = 4.0
try:
    _HIGH_RES_PRE_SETTLE_S = max(0.0, float(
        os.environ.get("WLV_HIRES_PRE_SETTLE_S", _HIGH_RES_PRE_SETTLE_S)))
except Exception:
    pass
# Session-learned pre-capture dwell (see above).
_hires_pre_settle_s = _HIGH_RES_PRE_SETTLE_S
# Proof-of-life bound.  Generous on purpose: a false negative tears down a
# perfectly good pipeline and re-cycles it, which is the very churn that
# destabilises the restore.  still_config pins FrameDurationLimits to the
# preview cap and the slow-shutter path simulates long exposures digitally
# (the sensor stays >= 30 fps), so the user's shutter setting can never
# make the first frame slow to arrive.
_HIGH_RES_RESTORE_PROOF_S = 3.0
try:
    _HIGH_RES_SETTLE_S = float(
        os.environ.get("WLV_HIRES_SETTLE_S", _HIGH_RES_SETTLE_S))
except Exception:
    pass
# Session-learned settle.  Escalates permanently to the historical dwell the
# first time the fast path fails to bring the pipeline up, so a camera that
# genuinely needs the long teardown pays the retry once instead of on every
# capture — and one that does not never pays it at all.  Session-only by
# design: it is a property of the running stack, not a user setting.
_hires_settle_s = _HIGH_RES_SETTLE_S
# ---- One-off CMA / heap warm for the 47 MP capture path ----
# Field case (IMX294, binned-preview 47 MP mode): the first one or two
# captures after boot take several seconds longer than every capture after
# them, with nothing in this file behaving differently per shot.  The cost
# is below the firmware.  picamera2 frees and re-allocates every stream's
# dmabufs on each configure(), and the 47 MP set — ~240 MB per buffer of
# physically CONTIGUOUS memory from the CMA-backed dma-heap — is cut from a
# region the kernel has meanwhile filled with movable page cache (the boot
# prewarm and the imports fill it on purpose).  The first cma_alloc has to
# migrate or evict all of that first; once done the region stays clear, so
# later allocations are near-instant.  The raw/main copies the capture then
# makes (another ~240 MB of process memory) pay the same reclaim once, and
# on a 2 GB board the SECOND shot often lands while the first shot's save
# job still pins its payload, so it pays it again — "the first couple".
#
# The fix moves that work off the shutter: once per session, when a binned
# 47 MP mode is live and the camera has been idle a few seconds, a
# low-priority thread allocates a buffer set of the same shape from the
# same dma-heap (per-stream buffers, exactly as picamera2 does — a single
# 240 MB chunk would be a stricter ask than the pipeline ever makes), frees
# it, then touches and frees the same amount of process memory.  It pins
# nothing, costs battery once, and journals its own timing — the elapsed
# time IS the measurement of what the first shutter press used to pay.
# Deliberately one-off: only file reads refill the region, and a running
# camera reads little.  The dma-heap ABI is spoken in-process (same rule
# as evdev — no dependency on picamera2 internals, which have moved the
# allocator between releases); the heap path order mirrors picamera2's.
# WLV_HIRES_CMA_WARM=0 disables for field A/B.
_HIRES_WARM_ENABLED = os.environ.get("WLV_HIRES_CMA_WARM", "1") != "0"
_HIRES_WARM_DELAY_S = 6.0          # idle settle before the warm starts
_HIRES_WARM_DEFER_S = 5.0          # re-check period while the camera is busy
_HIRES_WARM_MAX_DEFERS = 24        # ~2 min at that rate, then poll slowly
# After the fast defers the worker keeps waiting at this slower rate rather
# than giving up: a camera booted plugged in sits in charge mode far longer
# than two minutes, and a warm that gave up there cost the session's first
# shot ~1 s (field journal: first frame 1.72 s against 0.68 s once the
# warm had run — the reclaim lands in the FIRST FRAME leg, not configure).
# A sleeping daemon thread costs nothing, and the lock still makes a
# capture that arrives first win outright.
_HIRES_WARM_SLOW_DEFER_S = 30.0
_HIRES_WARM_HEADROOM_BYTES = 160 * 1024 * 1024   # keep free above the warm
_HIRES_WARM_DMA_HEAP_PATHS = (
    "/dev/dma_heap/vidbuf_cached",
    "/dev/dma_heap/linux,cma",
    "/dev/dma_heap/system",
)
# struct dma_heap_allocation_data { __u64 len; __u32 fd; __u32 fd_flags;
#                                   __u64 heap_flags; }  (24 bytes)
_DMA_HEAP_ALLOC_FMT = "QIIQ"
# One-shot latch consumed by the main loop the first time a binned 47 MP
# pipeline is live (boot in that mode, or a later switch into it).
_hires_warm_pending = True


def _hires_warm_plan(w, h, count, stride_align=64, page=4096):
    """Pure: the dma-heap allocations a 47 MP capture configure() makes —
    one R16 raw and one RGB888 main buffer per buffer_count — as byte sizes
    rounded up to a conservative stride/page alignment (an over-estimate
    warms a little more than needed, which is harmless; an under-estimate
    would leave the tail of the real allocation cold)."""
    try:
        w = int(w)
        h = int(h)
        count = max(1, int(count))
    except (TypeError, ValueError):
        return []
    if w <= 0 or h <= 0:
        return []

    def _aligned(stride):
        stride = (stride + stride_align - 1) // stride_align * stride_align
        nbytes = stride * h
        return (nbytes + page - 1) // page * page

    per_buffer = [_aligned(w * 2), _aligned(w * 3)]   # raw R16, main RGB888
    return per_buffer * count


def _dma_heap_ioc_alloc():
    """Pure: DMA_HEAP_IOCTL_ALLOC = _IOWR('H', 0, struct
    dma_heap_allocation_data), folded into the signed range fcntl.ioctl()
    accepts (the same fold _ev_ioc applies — the READ direction bit sets
    bit 31)."""
    req = (3 << 30) | (struct.calcsize(_DMA_HEAP_ALLOC_FMT) << 16) | (0x48 << 8)
    return req - (1 << 32) if req >= (1 << 31) else req


def _hires_warm_heap_open():
    """Open the first dma-heap device present, in picamera2's own search
    order.  Returns (fd, path) or (None, None)."""
    for path in _HIRES_WARM_DMA_HEAP_PATHS:
        try:
            return os.open(path, os.O_RDWR | os.O_CLOEXEC), path
        except OSError:
            continue
    return None, None


def _hires_warm_dma_alloc(heap_fd, nbytes):
    """Allocate one dmabuf of `nbytes` from an open dma-heap; returns its
    fd.  The kernel does the CMA allocation — and any page migration —
    synchronously inside this ioctl, so the caller's timing around it is
    the cost the capture path would otherwise pay."""
    import fcntl
    buf = struct.pack(_DMA_HEAP_ALLOC_FMT, int(nbytes), 0,
                      os.O_RDWR | os.O_CLOEXEC, 0)
    out = fcntl.ioctl(heap_fd, _dma_heap_ioc_alloc(), buf)
    _len, fd, _flags, _hflags = struct.unpack(_DMA_HEAP_ALLOC_FMT, out)
    return int(fd)


def _hires_warm_worker(sizes):
    """Background body of the warm.  Never raises; every outcome journals
    one `[HiRes] CMA warm` line so a field unit shows whether the warm ran,
    what it cost, or why it was skipped."""
    try:
        try:
            # Lowest CPU priority for this thread only (per-thread nice via
            # the tid is Linux-specific and always allowed in the lowering
            # direction) — the migration work must yield to the preview.
            os.setpriority(os.PRIO_PROCESS, threading.get_native_id(), 10)
        except Exception:
            pass
        total = sum(sizes)
        deferred = 0
        time.sleep(_HIRES_WARM_DELAY_S)
        # Wait for a quiescent camera: never overlap a real 47 MP capture
        # (it needs the same memory), never wake a sleeping one, and let a
        # charge-mode boot finish converging first.
        # The lock is the actual exclusion (see _hires_warm_claim): a
        # capture that starts after this check holds it, so the warm
        # either owns the memory window outright or does not run.
        while True:
            if _shutdown_flag.is_set():
                return
            quiescent = not (_high_res_capture_busy.is_set()
                             or sleep_mode_active or charge_mode_active)
            if quiescent and _hires_warm_lock.acquire(blocking=False):
                break
            deferred += 1
            if deferred == _HIRES_WARM_MAX_DEFERS + 1:
                print("[HiRes] CMA warm waiting: camera busy (capture / "
                      "sleep / charge) — polling slowly until it goes idle")
            time.sleep(_HIRES_WARM_DEFER_S
                       if deferred <= _HIRES_WARM_MAX_DEFERS
                       else _HIRES_WARM_SLOW_DEFER_S)
        try:
            _hires_warm_abort.clear()
            _hires_warm_locked_body(sizes, total)
        finally:
            _hires_warm_lock.release()
    except Exception as exc:
        print(f"[HiRes] CMA warm error: {exc}")


def _hires_warm_locked_body(sizes, total):
    """The allocation-and-touch interval, run with _hires_warm_lock held.
    Checks _hires_warm_abort between steps so a capture or pipeline start
    that claims the lock waits at most one buffer allocation."""

    def _aborted(stage):
        global _hires_warm_pending, _hires_warm_rearm
        if not _hires_warm_abort.is_set():
            return False
        if _hires_warm_rearm:
            # Yielded to a pipeline restart: the region is still cold, so
            # try again on the next idle period.
            _hires_warm_rearm = False
            _hires_warm_pending = True
            print(f"[HiRes] CMA warm aborted at {stage} (pipeline restart) "
                  f"— will retry when idle")
        else:
            # Yielded to a capture: the capture itself now does the work.
            print(f"[HiRes] CMA warm aborted at {stage} (capture)")
        return True

    avail = _bm_mem_available_bytes()
    if avail is not None and avail < total + _HIRES_WARM_HEADROOM_BYTES:
        print(f"[HiRes] CMA warm skipped: MemAvailable "
              f"{avail // (1024 * 1024)} MB < "
              f"{(total + _HIRES_WARM_HEADROOM_BYTES) // (1024 * 1024)} MB "
              f"needed (warm {total // (1024 * 1024)} MB + headroom)")
        return
    avail_before = avail
    heap_fd, heap_path = _hires_warm_heap_open()
    if heap_fd is None:
        print("[HiRes] CMA warm skipped: no dma-heap device found")
        return
    fds = []
    t0 = time.monotonic()
    cma_err = None
    aborted = False
    try:
        for nbytes in sizes:
            if _aborted("dma-heap allocation"):
                aborted = True
                break
            fds.append(_hires_warm_dma_alloc(heap_fd, nbytes))
    except Exception as exc:
        cma_err = exc
    finally:
        for fd in fds:
            try:
                os.close(fd)
            except OSError:
                pass
        try:
            os.close(heap_fd)
        except OSError:
            pass
    cma_s = time.monotonic() - t0
    if aborted or _aborted("process-memory warm"):
        return
    # Process-memory half: the capture's raw/main copies grow the
    # process by about the same amount, and the first growth has to
    # reclaim page cache exactly like the CMA cut did.  Touch and
    # release the same span now (numpy's large allocations are
    # mmap-backed, so the free returns the pages to the kernel).
    heap_s = None
    avail = _bm_mem_available_bytes()
    if avail is None or avail >= total + _HIRES_WARM_HEADROOM_BYTES:
        try:
            t1 = time.monotonic()
            _scratch = np.ones(total, dtype=np.uint8)
            _scratch[::4096] = 2
            del _scratch
            heap_s = time.monotonic() - t1
        except Exception as heap_exc:
            print(f"[HiRes] CMA warm: process-memory warm skipped "
                  f"({heap_exc})")
    avail_after = _bm_mem_available_bytes()
    mb = 1024 * 1024
    avail_txt = (f"MemAvailable {avail_before // mb if avail_before else '?'}"
                 f" -> {avail_after // mb if avail_after else '?'} MB")
    if cma_err is not None:
        print(f"[HiRes] CMA warm: {len(fds)}/{len(sizes)} buffer(s) from "
              f"{heap_path} before failing ({cma_err}); "
              f"{cma_s:.2f}s; {avail_txt}")
    else:
        heap_txt = (f"; process-memory warm {total // mb} MB in "
                    f"{heap_s:.2f}s" if heap_s is not None else "")
        print(f"[HiRes] CMA warm: {len(sizes)} buffer(s), {total // mb} MB "
              f"from {heap_path} allocated+freed in {cma_s:.2f}s"
              f"{heap_txt}; {avail_txt}")


def _hires_warm_kick():
    """Main loop: start the one-off warm if a binned 47 MP pipeline is live
    and it has not run this session.  One boolean test per iteration when
    there is nothing to do; the latch is consumed only when the mode
    qualifies, so a camera booted in another mode still warms on the first
    switch into 47 MP."""
    global _hires_warm_pending
    if not _hires_warm_pending:
        return
    if _high_res_capture_config is None:
        return
    _hires_warm_pending = False
    if not _HIRES_WARM_ENABLED:
        print("[HiRes] CMA warm disabled (WLV_HIRES_CMA_WARM=0)")
        return
    try:
        sizes = _hires_warm_plan(_CAPTURE_FULL_W, _CAPTURE_FULL_H,
                                 _HIGH_RES_BUFFER_COUNT)
    except Exception as exc:
        print(f"[HiRes] CMA warm skipped: plan error ({exc})")
        return
    if not sizes:
        return
    threading.Thread(target=_hires_warm_worker, args=(sizes,),
                     name="hires_cma_warm", daemon=True).start()



def _hires_restore_teardown():
    """Drop a restore attempt that failed its proof-of-life, so the next
    attempt starts from a clean stopped pipeline.  Never raises."""
    try:
        _cancel = getattr(picam2, "cancel_all_and_flush", None)
        if _cancel is not None:
            _cancel()
    except Exception as exc:
        print(f"[HiRes] restore flush error: {exc}")
    try:
        picam2.stop()
    except Exception as exc:
        print(f"[HiRes] restore stop error: {exc}")


def _hires_restore_preview(ae_seed=None, stopped_at=None):
    """Bring the binned preview pipeline back after a 47 MP capture, waiting
    on evidence rather than a fixed dwell.  Returns True once the restored
    pipeline has actually delivered a frame.

    `stopped_at` (monotonic timestamp of the post-capture picam2.stop())
    lets the first attempt CREDIT the time already elapsed since the stop
    against its settle dwell: the capture's raw/main copies (~0.2-0.5 s of
    unavoidable work) now run between the stop and this call, so libcamera's
    teardown has been settling the whole while and sleeping the full dwell
    on top of it was pure latency.  The known-safe stop-to-configure
    interval is preserved — the dwell is credited, never shortened below
    it — and the retry attempts keep the full uncredited historical dwell.

    The proof-of-life frame is pulled as a full request and its lores
    plane + metadata are stashed for the main loop
    (_captured_preview_lores / _captured_preview_meta), so the frame that
    proves the pipeline alive IS the first preview frame the user sees —
    the old flow discarded it and the main loop then blocked another frame
    period re-pulling one.  Only a successful attempt stashes; the write
    happens before the worker's finally clears _high_res_capture_busy,
    which is what orders it against the main loop's consumption.

    The configure/start recipe itself is unchanged — it mirrors
    _exit_charge_mode exactly (single configure, single start, preview frame
    cap; no double-cycle, no metadata drain, no ScalerCrop reset, no
    AeEnable=True override, all of which were tried and none of which fixed
    the original restore problem).  Only the waiting is different.

    `ae_seed` (optional dict of ExposureTime/AnalogueGain) re-seeds the
    exposure state: the capture runs the IPA's AGC through TWO sensor-mode
    switches with a manual, boosted exposure pinned in between, and the
    platform's per-mode sensitivity rescaling (CamHelperImx294
    getModeSensitivity: binned 1.0 vs QBC full-res 1/8) leaves AGC's
    carried exposure wrong on the way back — field case: AUTO resumed
    ~2 stops under after every binned-mode 47 MP capture and SETTLED
    there.  The seed is injected as CONFIG controls (the exact pattern
    the capture's own step 4 uses), NOT set_controls after start: the
    AGC's mode-switch bookkeeping runs AT configure time, and its
    fixed-values branch rewrites the carried exposure from pinned
    controls that are already in force — a post-start seed proved too
    late (the switch had already rescaled the carried state; field-
    verified still ~2 stops under).  The caller's step-9b
    _apply_shutter_controls() then re-enables the user's AE state from
    that known-good operating point (the dimmed-idle wake edge proves
    plain AeEnable=True cleanly resumes AE from pinned values on this
    stack).  The dicts are copied so the global still_config never keeps
    AeEnable=False / pinned exposure — charge exit and video exit
    configure from the same global.  A seed failure never fails the
    restore.
    """
    global _hires_settle_s, _captured_preview_lores, _captured_preview_meta

    for attempt in range(1, _HIGH_RES_RESTORE_ATTEMPTS + 1):
        settle = _hires_settle_s if attempt == 1 else _HIGH_RES_SETTLE_RETRY_S
        if attempt == 1 and stopped_at is not None:
            # Credit the copy/teardown time already elapsed since the
            # post-capture stop — the dwell protects the stop-to-configure
            # interval, and that interval has been running since stopped_at.
            settle = max(0.0, settle - (time.monotonic() - stopped_at))
        if attempt > 1:
            # The retry IS the field-validated conservative path: rebuild
            # every config dict exactly as _set_sensor_mode_idx does (the
            # dropdown flow field-confirmed to restore reliably) before
            # dwelling the full historical settle.
            try:
                _rebuild_camera_configs_for_active_sensor_mode()
            except Exception as rebuild_err:
                print(f"[HiRes] retry config rebuild error: {rebuild_err}")
                traceback.print_exc()
        t0 = time.monotonic()
        time.sleep(settle)
        try:
            cfg = still_config
            if ae_seed:
                try:
                    cfg = dict(still_config)
                    cfg["controls"] = dict(still_config.get("controls") or {})
                    cfg["controls"].update(ae_seed)
                    cfg["controls"]["AeEnable"] = False
                    print(f"[HiRes] AE re-seed in restore config: {ae_seed}")
                except Exception as seed_exc:
                    cfg = still_config
                    print(f"[HiRes] AE re-seed build failed (continuing): "
                          f"{seed_exc}")
            picam2.configure(cfg)
            picam2.start()
            picam2.set_controls({"FrameDurationLimits": _PREVIEW_FRAME_LIMITS})
        except Exception as exc:
            print(f"[HiRes] preview restore attempt {attempt} did not start "
                  f"(settle {settle:.2f}s): {exc}")
            traceback.print_exc()
            _hires_settle_s = _HIGH_RES_SETTLE_RETRY_S
            _hires_restore_teardown()
            continue
        # Proof of life: one real frame off the restored pipeline.  Bounded
        # like every other wait in this sequence — a pipeline that comes up
        # without streaming must not wedge the worker (see _HIGH_RES_WAIT_S).
        # Pulled as a full request so the frame is not wasted: its lores
        # plane + metadata seed the main loop's next preview pull, folding
        # the old separate proof, post-restore AE diagnostic and first
        # preview pull into this single round trip.
        try:
            proof_req = _hires_bounded_wait(
                picam2.capture_request(wait=False), _HIGH_RES_RESTORE_PROOF_S)
        except Exception as exc:
            print(f"[HiRes] preview restore attempt {attempt} started but "
                  f"delivered no frame in {_HIGH_RES_RESTORE_PROOF_S:.1f}s "
                  f"(settle {settle:.2f}s): {exc}")
            _hires_settle_s = _HIGH_RES_SETTLE_RETRY_S
            _hires_restore_teardown()
            continue
        _proof_lores = None
        _proof_md = None
        try:
            try:
                _proof_lores = proof_req.make_array("lores").copy()
                _proof_md = proof_req.get_metadata()
            except Exception as stash_exc:
                _proof_lores = None
                _proof_md = None
                # The delivered request IS the proof of life — a stash
                # failure only costs the frame reuse, never the restore.
                print(f"[HiRes] proof-frame stash skipped: {stash_exc}")
        finally:
            try:
                proof_req.release()
            except Exception as rel_exc:
                print(f"[HiRes] proof release error: {rel_exc}")
        if _proof_lores is not None:
            _captured_preview_lores = _proof_lores
            _captured_preview_meta = _proof_md
        print(f"[HiRes] preview restored in {time.monotonic() - t0:.2f}s "
              f"(attempt {attempt}, settle {settle:.2f}s, live frame "
              f"confirmed)")
        return True
    return False


def _perform_high_res_capture(dng_path, slow_shutter_us=None,
                              sel_gain=_ISO_SEL_UNSET, sel_stretch=None,
                              mono_raw=None, develop_mono=False, defer_processing=False,
                              live_md=None, dispatched_at=None):
    """47 MP capture sequence used only when the high-res mode is selected.

    `dispatched_at` is the monotonic time of the shutter dispatch (the
    moment the black canvas went up).  The blackout breakdown is anchored
    on it when given, so the line also carries the thread start and the
    CMA-warm claim that can precede the worker's entry — the very
    first-shot stall the instrumentation exists to diagnose.

    `live_md` is the exposure metadata of the LAST PREVIEW FRAME THE MAIN
    LOOP PULLED (its `_meta`, handed over in the dispatch snapshot).  That
    frame is `_last_lores_frame` — the very frame the user composed on and
    the one the JPG brightness match below measures its reference from —
    so planning the capture from its metadata keeps the exposure plan and
    the brightness reference coherent, and it is already in hand: the old
    step 1 dispatched a capture_metadata() job and blocked for the NEXT
    frame to complete, one preview period (50 ms; 100 ms from the dimmed
    idle rate) of pure blackout per shot.  A missing or incomplete dict
    falls back to that fresh read, so any caller that predates the
    parameter behaves exactly as before.

    `sel_gain` / `sel_stretch` are the ISO selection and its gain-trade
    factor SNAPSHOTTED at shutter dispatch (both callers pass them): the
    capture's gain plan and exposure handling must come from the
    selection the user pressed the shutter under, never from a read of
    the live globals seconds later — a web /api/camera change landing
    mid-capture would otherwise split the plan across two selections
    (the busy-guard in _camera_apply_setting narrows that window but is
    check-then-act, so the snapshot is what actually closes it).  Left
    unset they fall back to reading the current selection, preserving
    behaviour for any caller that predates the parameters.

    Strict sequence per the product spec:
      1. Read the running 11 MP preview's exposure metadata and build the
         capture's exposure plan from it.
      2. picam2.stop().
      3. Build a LOCAL capture config with main/raw at the mode's full
         read-out size (_CAPTURE_FULL_W x _CAPTURE_FULL_H — 8432x5648 on
         the 47 MP sensors), sensor block on the same full mode at
         12-bit.  The global still_config is never touched — it keeps
         describing the live 11 MP pipeline throughout, so the restore
         below configures straight from it.
      4. Inject ExposureTime / AnalogueGain (with AeEnable=False) from the
         exposure plan into the local config's controls.
      5. configure + start, then the settled control-drain request itself
         supplies both outputs: the raw buffer is grabbed in memory for a
         DEFERRED DNG write (queued to the save worker by the caller — the
         old synchronous capture_file here cost a multi-second encode + SD
         write inside the blackout window plus an extra frame wait), and
         the main array becomes the JPG source frame, brightness-matched
         to the binned preview the user composed on (closed loop — see
         _hires_exposure_match_lut); the DNG is never brightness-matched.
      6. picam2.stop() the moment the capture request is in hand, so
         libcamera's teardown settles WHILE the unavoidable raw/main
         copies run against the held request (the restore credits that
         elapsed time against its settle dwell).
      7. Resume the live preview from the untouched still_config
         (_hires_restore_preview: settle credit, configure + start,
         proof-of-life frame reused as the next preview frame).

    Returns (main_frame, dng_payload): the main array (numpy uint8, RGB888)
    or None, and the deferred-DNG payload tuple (raw buffer, metadata, raw
    config) or None — the caller queues both to the save worker.
    """
    global _hires_ae_probe_at, _hires_ae_log_first_frame, _hires_pre_settle_s
    capture_mono = _mono_raw_active() if mono_raw is None else bool(mono_raw)
    capture_quad_mono = capture_mono and _qbc_sensor_status() is True

    # Blackout breakdown.  Everything from here to the moment the capture
    # request is in hand is time the user spends holding still on a black
    # screen; each leg is timed and journalled as one `[HiRes] blackout`
    # line so a field unit shows where that time goes (see the print near
    # the unconditional _high_res_capture_done.set() below).
    _bo_worker_t0 = time.monotonic()
    _bo_t0 = _bo_worker_t0
    _bo_dispatch_s = None
    try:
        if dispatched_at is not None and float(dispatched_at) <= _bo_worker_t0:
            _bo_t0 = float(dispatched_at)
            _bo_dispatch_s = _bo_worker_t0 - _bo_t0
    except (TypeError, ValueError):
        pass
    _bo_stop_s = _bo_cfg_s = _bo_start_s = _bo_first_s = None
    _bo_plan_s = None
    _bo_settle_s = 0.0
    _bo_attempts = 0
    _bo_done_at = None
    # Bound before the try below so the breakdown line can name them even
    # when the config build raises ahead of the drain.
    req = None
    drained = 0
    drain_t0 = None

    # Step 1: snapshot live exposure.  The main loop's last-frame metadata
    # is preferred (see the docstring); only a caller that did not supply
    # one — or supplied one with no exposure in it — pays for a fresh read.
    # Bounded like every other wait in this sequence — a stalled preview
    # pipeline must not wedge the capture worker before it even starts.
    if (isinstance(live_md, dict)
            and live_md.get("ExposureTime") is not None
            and live_md.get("AnalogueGain") is not None):
        live_md = dict(live_md)
        _bo_md_src = "main-loop frame"
    else:
        _bo_md_src = "fresh read"
        try:
            live_md = _hires_bounded_wait(
                picam2.capture_metadata(wait=False), _HIGH_RES_WAIT_S)
        except Exception:
            live_md = {}
    _bo_md_s = time.monotonic() - _bo_worker_t0
    # `plan` leg: everything between the metadata read and the stop — the
    # low-ISO coherence guard below can block up to _HIRES_SEL_SETTLE_FRAMES
    # preview frames waiting for a just-changed selection to echo, and the
    # brightness reference is measured here too.
    _bo_plan_t0 = time.monotonic()
    # Sub-floor manual ISO (the true-ISO-100 / true-ISO-200 selections):
    # the preview runs at the sensor's gain floor, and instead of
    # transferring live x boost (which would land at floor x 4 — ISO 400)
    # the capture pins the gain at selection x boost (ISO 100 / 200) and
    # stretches ExposureTime by the parity factor (x4 / x2) instead — same
    # total exposure and preview-matched brightness, less analogue gain in
    # the raw.  1.0 stretch = the unchanged historical path.
    _hires_sel_gain = (
        _current_iso_gain() if sel_gain is _ISO_SEL_UNSET else sel_gain)
    _hires_stretch = (
        _iso_exposure_stretch(_hires_sel_gain)
        if sel_stretch is None else float(sel_stretch))
    # Coherence guard on the dispatch snapshot.  The snapshot is taken a
    # few lines before the busy flag is armed, and that gap spans real
    # work (basename + _ensure_dir + the EXIF snapshot), so a web
    # /api/camera change can slip in, re-program the preview pipeline,
    # and leave the snapshot's gain plan describing a DIFFERENT pipeline
    # than the live_md read above — e.g. snapshot ISO 1600 then a switch
    # to ISO 100: AE lengthens the live exposure ~4x while the capture
    # would still pin gain 16, badly overexposing the DNG.
    #
    # But a frame whose metadata does not echo the selection is NOT by
    # itself evidence of that: set_controls takes a couple of frames to
    # land (the latency _wb_meta_matches_applied exists for), so
    # selecting ISO 100 and pressing the shutter immediately produces the
    # same mismatch with nothing whatsoever wrong.  Discarding there
    # would capture at the OLD gain while the EXIF describes the new
    # selection — the very corruption this guard is meant to prevent.
    # The two are separable because the busy flag freezes the selection
    # for the whole worker run (HTTP refused, touch/GPIO dropped), so the
    # live selection can be compared against the snapshot:
    #
    #   echo                      -> plan stands (common case, no cost)
    #   no echo, same selection   -> control latency: drain a bounded few
    #                                frames for the echo and ADOPT the
    #                                confirming frame as live_md, so gain
    #                                and exposure then come from one
    #                                coherent frame (this also clears the
    #                                stale-exposure half of the same
    #                                window for the AUTO path)
    #   no echo, selection moved  -> a real re-program landed: discard the
    #                                plan and derive gain AND exposure
    #                                from live_md, which is internally
    #                                consistent by construction (and is
    #                                the pre-low-ISO behaviour)
    #
    # The "changed after the arm" interleaving cannot reach the discard
    # branch: _apply_shutter_controls defers while busy, so the pipeline
    # still matches the snapshot and the echo test passes above.  Absent
    # or unparseable metadata is never evidence of anything, so the plan
    # stands there too.
    if _hires_stretch > 1.0 and _hires_sel_gain is not None:
        try:
            _want_prev_gain = max(
                float(_hires_sel_gain),
                float(_iso_capture_gain_floor() or 1.0))

            def _echoes_selection(_md):
                if not _md:
                    return None          # no evidence either way
                _ag = _md.get("AnalogueGain")
                if _ag is None:
                    return None
                return abs(float(_ag) - _want_prev_gain) <= (
                    _want_prev_gain * _HIGH_RES_DRAIN_GAIN_TOL)

            if _echoes_selection(live_md) is False:
                _sel_now = _current_iso_gain()
                _sel_moved = (
                    _sel_now is None
                    or abs(float(_sel_now) - float(_hires_sel_gain))
                    > abs(float(_hires_sel_gain)) * 1e-6)
                if _sel_moved:
                    print(f"[HiRes] snapshot plan discarded: selection "
                          f"changed during dispatch (snapshot "
                          f"{float(_hires_sel_gain):.2f}, now {_sel_now}) "
                          f"and the preview gain "
                          f"{float(live_md.get('AnalogueGain')):.2f} does "
                          f"not echo it — deriving exposure and gain from "
                          f"live metadata instead")
                    _hires_stretch = 1.0
                else:
                    # Selection is unchanged, so this is set_controls
                    # latency.  Wait a bounded few frames for the sensor
                    # to report the selection's gain and adopt that frame.
                    _settled_after = 0
                    for _i in range(_HIRES_SEL_SETTLE_FRAMES):
                        try:
                            _md_try = _hires_bounded_wait(
                                picam2.capture_metadata(wait=False),
                                _PREVIEW_PULL_WAIT_S)
                        except Exception:
                            break
                        _settled_after += 1
                        if _echoes_selection(_md_try):
                            live_md = _md_try
                            break
                    print(f"[HiRes] low-ISO controls settling: waited "
                          f"{_settled_after} frame(s) for preview gain "
                          f"{_want_prev_gain:.2f}; "
                          + ("confirmed"
                             if _echoes_selection(live_md) else
                             "unconfirmed — keeping the selection's plan"))
        except (TypeError, ValueError):
            pass
    if _hires_stretch > 1.0 and _hires_sel_gain is not None:
        _hires_gain, _hires_short = _hires_boosted_gain(_hires_sel_gain)
        print(f"[HiRes] low-ISO capture: gain pinned at {_hires_gain:.2f} "
              f"(selection {float(_hires_sel_gain):.2f} x boost); exposure: "
              + ("selected manual speed verbatim" if slow_shutter_us is not None
                 else f"live x{_hires_stretch:.2f}"))
    else:
        _hires_stretch = 1.0
        _hires_gain, _hires_short = (
            _hires_boosted_gain(live_md["AnalogueGain"])
            if live_md.get("AnalogueGain") is not None else (None, 1.0))
    if _hires_short > 1.01:
        # The sensor could not deliver the full boost, so this capture is
        # short by that factor and the JPG's brightness match will make it
        # up digitally.  Name it: it is the difference between "high ISO
        # looks noisy" and "this mode ran out of analogue gain".
        print(f"[HiRes] gain boost clamped: wanted "
              f"{float(live_md['AnalogueGain']) * _HIGH_RES_GAIN_BOOST:.1f} "
              f"got {_hires_gain:.1f} — capture is "
              f"{float(np.log2(_hires_short)):.2f} stops short "
              f"({_hires_short:.2f}x), the JPG match "
              f"will lift it digitally (raw keeps the real exposure)")
    # Capture exposure target.  An explicit slow_shutter_us is the user's
    # MANUAL speed and is used VERBATIM — under the low-ISO trade
    # _apply_shutter_controls previews at eff/stretch and hands the true
    # target here, so re-stretching it would double-apply.  Exposure
    # transferred from the running preview is multiplied by the trade:
    # under AUTO shutter that preserves the brightness AE chose against
    # the dropped gain, and for a Brenizer tile (slow_shutter_us=None with
    # a locked manual state) the live value IS the shortened preview
    # equivalent, so the multiply recovers the selected speed.
    if slow_shutter_us is not None:
        _hires_cap_exp = int(slow_shutter_us)
    elif live_md.get("ExposureTime") is not None:
        _hires_cap_exp = int(round(
            int(live_md["ExposureTime"]) * _hires_stretch))
    else:
        _hires_cap_exp = None
    exposure_payload = {
        "ExposureTime": _hires_cap_exp,
        "AnalogueGain": _hires_gain,
        # AeEnable=False locks ExposureTime/AnalogueGain but does NOT freeze
        # DigitalGain — DigitalGain is not a settable control, and how the
        # IPA rebalances it against the boosted AnalogueGain varies by
        # tuning/firmware.  Snapshotted for the capture log only; the JPG's
        # exposure is corrected closed-loop against the preview instead
        # (see _hires_exposure_match_lut).
        "DigitalGain": (
            float(live_md["DigitalGain"])
            if live_md.get("DigitalGain") is not None
            else 1.0
        ),
        # Pinned whenever the target exposure is one the mode's default
        # frame duration may not cover: the slow-shutter path always, and
        # any stretched low-ISO exposure (libcamera clamps the pin into the
        # mode's own valid range, same as every other slow manual speed).
        "FrameDurationLimits": (
            (_hires_cap_exp, _hires_cap_exp)
            if _hires_cap_exp is not None
            and (slow_shutter_us is not None or _hires_stretch > 1.0)
            else None
        ),
    }
    # The plan is injected straight into the capture config below — the old
    # temp-file round trip (/tmp JSON written and read back inside this same
    # function) provided no isolation, and a failed write silently dropped
    # the exposure transfer while the EXIF still described the intended
    # plan.  The journal line keeps the same payload content for field greps.
    print(f"[HiRes] exposure controls: {exposure_payload}")

    # Closed-loop JPG exposure reference: the brightness of the binned
    # preview frame the user composed on (for manual slow shutter this
    # frame already carries the in-place preview brightness simulation,
    # so it is what was on screen in every mode).  Measured before the
    # pipeline stops; the captured main (JPG) stream is matched to it
    # after the capture.  None → the match is skipped and the ISP frame
    # is saved untouched — a capture is never lost to this step.
    ref_lin_mean = _hires_linear_mean(_last_lores_frame, 4)

    main_frame = None
    # Raw payload for the DEFERRED DNG write: (buffer, metadata, raw config),
    # grabbed in memory from the same request as the JPG frame and queued to
    # the save worker.  The old capture_file() wrote the DNG synchronously
    # right here — a multi-second encode + SD write inside the blackout
    # window, plus a whole extra sensor frame of waiting.  Deferring it
    # mirrors the instant path and lets the preview restore begin the moment
    # the single capture request lands.
    dng_payload = None
    # True once a bounded wait below timed out — the 47 MP read-out is not
    # delivering frames, so the remaining captures are skipped and the
    # restore path runs promptly instead of stacking more timeouts.
    mode_dead = False
    # Monotonic timestamp of the post-capture picam2.stop().  Set the
    # moment the capture request is in hand on the success path (step 6),
    # or by the failure-path stop below; the restore credits the time
    # already elapsed since it against its settle dwell.
    stopped_at = None

    _bo_plan_s = time.monotonic() - _bo_plan_t0

    # Step 2: stop the live preview pipeline.
    _bo_stop_t0 = time.monotonic()
    try:
        picam2.stop()
    except Exception as exc:
        print(f"[HiRes] picam2.stop() error: {exc}")
    _bo_stop_s = time.monotonic() - _bo_stop_t0

    try:
        # Step 3: build a LOCAL capture config with main/raw at the
        # mode's full read-out size (8432x5648 on the 47 MP sensors) —
        # the sensor block selects the same full mode, so the capture is
        # the entire frame with no crop.  The global still_config is
        # deliberately NOT touched (it is not even declared global
        # here): it keeps describing the live 11 MP pipeline, so the
        # restore configures from it directly and a failure anywhere in
        # this function can never strand the global in the 47 MP shape.
        # Built once, ahead of the settle, so it overlaps the dwell
        # rather than following it.
        cap_config = picam2.create_still_configuration(
            main={"size": ((640, 480) if defer_processing else (_CAPTURE_FULL_W, _CAPTURE_FULL_H)),
                  "format": "RGB888"},
            raw={"size": (_CAPTURE_FULL_W, _CAPTURE_FULL_H), "format": "R16"},
            sensor={"output_size": (_CAPTURE_FULL_W, _CAPTURE_FULL_H),
                    "bit_depth": 12},
            controls=dict(_STILL_CONTROLS),
            # One-shot capture: single-buffering on low-memory boards halves
            # the ~430 MB the 47 MP buffer set pins during the switch (the
            # drain/capture sequence is sequential, so pipelining buys
            # nothing here that's worth an OOM).
            buffer_count=_HIGH_RES_BUFFER_COUNT,
        )

        # Step 4: inject the exposure plan into the capture config.
        # AeEnable=False locks the values for the capture.  Same
        # None-guarded transfers and int/float/tuple coercions the old
        # temp-file read performed.
        ctrls = cap_config.setdefault("controls", {})
        ctrls["AeEnable"] = False
        if capture_mono and _imx294_quad_raw_available():
            ctrls["QbcRaw"] = True
        if exposure_payload.get("ExposureTime") is not None:
            ctrls["ExposureTime"] = int(exposure_payload["ExposureTime"])
        if exposure_payload.get("AnalogueGain") is not None:
            ctrls["AnalogueGain"] = float(exposure_payload["AnalogueGain"])
        if exposure_payload.get("FrameDurationLimits") is not None:
            ctrls["FrameDurationLimits"] = tuple(
                exposure_payload["FrameDurationLimits"])
        want_exp = ctrls.get("ExposureTime")
        want_gain = ctrls.get("AnalogueGain")
        # Fast-path first-frame bound: sized for a healthy start plus the
        # planned exposure, never above the liveness bound.
        try:
            _exp_s = max(0.0, float(want_exp or 0) / 1e6)
        except (TypeError, ValueError):
            _exp_s = 0.0
        _fast_first_wait = min(_HIGH_RES_WAIT_S,
                               _HIGH_RES_PRE_PROOF_S + 2.0 * _exp_s)

        # Step 5: settle, configure, start, then capture — closed-loop
        # (see _HIGH_RES_PRE_SETTLE_S): the fast-path dwell is proven by
        # the first 47 MP frame, and a start that fails that proof is
        # torn down and retried once on the historical dwell.  The raw
        # buffer feeds the deferred DNG write and the main array becomes
        # the JPG source frame; the save worker thread handles the JPG
        # asynchronously after the helper returns.
        for _attempt in range(1, _HIGH_RES_PRE_ATTEMPTS + 1):
            _bo_attempts = _attempt
            _last_attempt = _attempt >= _HIGH_RES_PRE_ATTEMPTS
            # Give libcamera's teardown of the 11 MP pipeline its dwell
            # before handing it the 47 MP config.  (The post-capture
            # direction pays its own in _hires_restore_preview's settle,
            # credited against the copy work — see step 6.)
            _settle = (_hires_pre_settle_s if _attempt == 1
                       else _HIGH_RES_PRE_SETTLE_RETRY_S)
            time.sleep(_settle)
            _bo_settle_s += _settle
            try:
                _bo_cfg_t0 = time.monotonic()
                picam2.configure(cap_config)
                _bo_cfg_s = time.monotonic() - _bo_cfg_t0
                _bo_start_t0 = time.monotonic()
                if capture_quad_mono:
                    _imx294_start_quad_capture(picam2)
                else:
                    picam2.start()
                _bo_start_s = time.monotonic() - _bo_start_t0
            except Exception as up_err:
                if _last_attempt:
                    raise
                print(f"[HiRes] 47 MP pipeline did not come up after a "
                      f"{_settle:.2f}s settle ({up_err}) — retrying on the "
                      f"{_HIGH_RES_PRE_SETTLE_RETRY_S:.2f}s dwell")
                _hires_pre_settle_s = _HIGH_RES_PRE_SETTLE_RETRY_S
                _hires_restore_teardown()
                continue
            # Drain frames so the locked controls land on the buffer we
            # capture; otherwise the first request can be from buffers
            # configured before the switch took effect.  The drain is
            # closed-loop rather than a fixed count: each frame's own
            # metadata reports the exposure the sensor actually used for
            # it, so the loop stops on the first confirmed frame instead
            # of always spending _HIGH_RES_DRAIN_FRAMES of them.  The
            # drain pulls full REQUESTS, not metadata, and the confirming
            # request IS the photograph: its own metadata proves the
            # injected controls were live for that very frame — strictly
            # stronger evidence than capturing the frame after it, and
            # one whole read-out period (~400-500 ms at this rate)
            # cheaper.  Unsettled requests are released before the next
            # wait so at most ONE request is ever held — mandatory with
            # buffer_count=1 on low-memory boards, where a held request
            # would starve the single buffer and fake a mode-dead
            # timeout.  An unconfirmed drain captures ONE more frame
            # instead (the pre-reuse "unconfirmed" policy, unchanged).
            # Once confirmed it stays confirmed: AeEnable is False, so
            # nothing moves the settings again.  Bounded via
            # _hires_bounded_wait: a 47 MP mode that starts but never
            # streams used to block this loop forever (see
            # _HIGH_RES_WAIT_S) — on the last attempt a timeout marks the
            # mode dead so the capture is abandoned and the preview
            # restore runs promptly; on the fast path a FIRST frame that
            # misses its shorter proof bound retries instead.
            drain_t0 = time.monotonic()
            drained = 0
            settled = False
            req = None
            _retry_start = False
            for _ in range(_HIGH_RES_DRAIN_FRAMES):
                _wait_s = (_HIGH_RES_WAIT_S
                           if drained or _last_attempt else _fast_first_wait)
                try:
                    _drain_req = _hires_bounded_wait(
                        picam2.capture_request(wait=False), _wait_s)
                except Exception as drain_err:
                    if _hires_wait_timed_out(drain_err):
                        if drained == 0 and not _last_attempt:
                            _retry_start = True
                        else:
                            mode_dead = True
                            print(f"[HiRes] 47 MP read-out not streaming — "
                                  f"no frame in {_wait_s:.0f}s, abandoning "
                                  f"capture")
                    break
                drained += 1
                if drained == 1:
                    _bo_first_s = time.monotonic() - drain_t0
                try:
                    drain_md = _drain_req.get_metadata()
                except Exception:
                    # Absent metadata is not evidence of settledness —
                    # counts as unsettled, matching
                    # _hires_exposure_settled's policy.
                    drain_md = None
                if (_hires_exposure_settled(drain_md, want_exp, want_gain)
                        and (not capture_quad_mono or (drain_md or {}).get('QbcRaw') is True)):
                    settled = True
                    req = _drain_req
                    break
                # Unsettled: release and keep draining.  A drain frame is
                # only ever reused on POSITIVE settledness — a frame whose
                # metadata just failed the check must not become the
                # photograph, so the unconfirmed case falls through to
                # the post-drain capture below (the pre-reuse policy: the
                # next frame is also unverified, but strictly more likely
                # settled than one that provably is not).
                try:
                    _drain_req.release()
                except Exception as rel_err:
                    print(f"[HiRes] drain release error: {rel_err}")
            if _retry_start:
                print(f"[HiRes] fast-path start delivered no frame in "
                      f"{_fast_first_wait:.1f}s (settle {_settle:.2f}s) — "
                      f"retrying on the {_HIGH_RES_PRE_SETTLE_RETRY_S:.2f}s "
                      f"dwell (session dwell escalated)")
                _hires_pre_settle_s = _HIGH_RES_PRE_SETTLE_RETRY_S
                _hires_restore_teardown()
                continue
            break
        if not mode_dead:
            _drain_src = ("capture reuses the drain frame"
                          if req is not None else "post-drain capture")
            print(f"[HiRes] control drain: {drained}/{_HIGH_RES_DRAIN_FRAMES} "
                  f"frame(s) in {time.monotonic() - drain_t0:.2f}s "
                  f"({'confirmed' if settled else 'unconfirmed'}; "
                  f"exp={want_exp} gain={want_gain}; {_drain_src})")
            if req is None:
                # Unconfirmed drain, or a non-timeout error mid-drain: one
                # direct capture so the shot is never lost outright.  The
                # released-then-requested ordering also keeps the
                # one-held-request invariant — holding the last drain frame
                # while waiting for this one would deadlock buffer_count=1.
                try:
                    req = _hires_bounded_wait(
                        picam2.capture_request(wait=False), _HIGH_RES_WAIT_S)
                except Exception as req_err:
                    req = None
                    print(f"[HiRes] capture request error: {req_err}")
                    traceback.print_exc()
                    mode_dead = _hires_wait_timed_out(req_err)
        if req is not None:
            # Step 6 (early half): read-out complete — the frame is in
            # hand, so lift the blackout blink NOW (the user can move the
            # camera) and stop the 47 MP pipeline immediately.  libcamera's
            # teardown then settles in the background while the unavoidable
            # raw/main copies below run against the held request; the
            # restore credits that elapsed time against its settle dwell.
            # Stopping while holding a completed request is the shape
            # picamera2's own switch_mode_capture_request_and_stop uses —
            # the request's buffers stay valid until release().
            _high_res_capture_done.set()
            _bo_done_at = time.monotonic()
            try:
                picam2.stop()
            except Exception as exc:
                print(f"[HiRes] post-capture picam2.stop() error: {exc}")
            stopped_at = time.monotonic()
            try:
                # Raw payload first (deferred DNG — see dng_payload above).
                # A raw grab failure loses only the DNG; the JPG capture
                # below continues regardless.
                try:
                    capture_raw_meta = req.get_metadata()
                    _imx294_require_quad_metadata(capture_raw_meta, capture_quad_mono)
                    _raw_buf = req.make_buffer("raw")
                    if not _raw_buf.flags.owndata:
                        _raw_buf = _raw_buf.copy()
                    dng_payload = (
                        _raw_buf,
                        capture_raw_meta,
                        req.config["raw"],
                    )
                    _raw_buf = None
                except Exception as raw_err:
                    dng_payload = None
                    print(f"[HiRes] raw payload grab error (DNG will be "
                          f"skipped): {raw_err}")
                    traceback.print_exc()
                    _post_save_warning("RAW skipped — JPG kept")
                main_frame = req.make_array("main")
                # True once main_frame is a freshly-materialized array
                # detached from the request's buffers.
                main_frame_owned = False
                # The full-res read-out transmits the sensor's left
                # optical-black column band and the ISP demosaics it into
                # the main stream like picture, so it reaches the JPG as
                # a black band down the finished image's right edge
                # (post-rotate).  The DNG hides the same columns behind
                # ActiveArea; the JPG — and the Brenizer / double-exposure
                # consumers of this frame — need them physically removed.
                # Cropped HERE, before the brightness match below, so the
                # match measures only real picture; the slice is a view,
                # so the ownership/detach logic below is unchanged.
                try:
                    _ob_cols = _frame_edge_ob_cols(
                        req.config.get("raw"), main_frame.shape[1])
                except Exception as _ob_err:
                    _ob_cols = 0
                    print(f"[HiRes] OB column crop skipped: {_ob_err}")
                if _ob_cols:
                    main_frame = main_frame[:, _ob_cols:]
                    print(f"[HiRes] optical-black crop: {_ob_cols} left "
                          f"column(s) removed -> "
                          f"{main_frame.shape[1]}x{main_frame.shape[0]}")
                # Match the JPG's exposure to the binned preview the user
                # composed on.  How the ISP maps the ×4 boosted AnalogueGain
                # onto the 8-bit main stream is not stable across
                # tuning/firmware (sometimes rebalanced ~2 stops dark,
                # sometimes passed straight through and blown out), so
                # measure both sides and correct the actual difference
                # instead of trusting a fixed factor.  The DNG — already
                # written above — is never touched by this correction.
                try:
                    cap_md = req.get_metadata() or {}
                except Exception:
                    cap_md = {}
                try:
                    cap_lin_mean = _hires_linear_mean(main_frame, 16)
                    if ref_lin_mean is not None and cap_lin_mean is not None:
                        match_gain = min(
                            _HIRES_MATCH_GAIN_MAX,
                            max(_HIRES_MATCH_GAIN_MIN,
                                ref_lin_mean / cap_lin_mean),
                        )
                        if abs(match_gain - 1.0) > 0.05:
                            main_frame = cv2.LUT(
                                main_frame,
                                _hires_exposure_match_lut(match_gain),
                            )
                            main_frame_owned = True
                        print(
                            f"[HiRes] JPG exposure match ×{match_gain:.3f} "
                            f"(preview lin mean {ref_lin_mean:.5f}, "
                            f"capture lin mean {cap_lin_mean:.5f}, "
                            f"capture DG={cap_md.get('DigitalGain')}, "
                            f"capture AG={cap_md.get('AnalogueGain')})"
                        )
                    else:
                        print(
                            "[HiRes] JPG exposure match skipped "
                            f"(preview lin mean={ref_lin_mean}, "
                            f"capture lin mean={cap_lin_mean})"
                        )
                except Exception as match_err:
                    # Never lose a capture to the brightness match — save
                    # the ISP frame as-is.
                    print(f"[HiRes] JPG exposure match error: {match_err}")
                if main_frame is not None and not main_frame_owned:
                    # When the match was skipped or near-neutral, main_frame
                    # may still be make_array's view of the request's DMA
                    # buffer, which release() below recycles (the old fixed
                    # boost always materialized a new array).  Detach before
                    # releasing so the queued JPG save can never read a
                    # recycled buffer.
                    main_frame = main_frame.copy()
            finally:
                req.release()
            if main_frame is not None:
                print(f"[HiRes] main frame captured: shape={main_frame.shape}")
    except Exception as cap_err:
        print(f"[HiRes] capture sequence error: {cap_err}")
        traceback.print_exc()

    if mode_dead:
        # The 47 MP read-out never delivered a frame (failed mode switch /
        # link fault).  Flush the timed-out jobs picamera2 may still hold so
        # the stop/reconfigure below starts clean, and surface the lost shot
        # on the HUD — the standard preview restore continues underneath, so
        # the camera comes back live instead of hanging on the busy flag.
        try:
            _cancel = getattr(picam2, "cancel_all_and_flush", None)
            if _cancel is not None:
                _cancel()
            else:
                # Pre-0.3.13 picamera2 has no job-flush API; the stop /
                # reconfigure below still tears the stalled pipeline down.
                print("[HiRes] cancel_all_and_flush unavailable "
                      "(old picamera2) — relying on stop/reconfigure")
        except Exception as flush_err:
            print(f"[HiRes] cancel_all_and_flush error: {flush_err}")
        _post_save_warning("47 MP capture failed — preview restored")

    # Sensor capture attempt over (captured, errored or mode-dead) —
    # signal the main loop so the blackout flash drops even on the
    # failure paths (the success path already set this the moment the
    # request landed; the Event is idempotent).
    _high_res_capture_done.set()
    if _bo_done_at is None:
        _bo_done_at = time.monotonic()
    try:
        # One line per shot naming where the hold-still window went.  The
        # legs are sequential and sum to the total (less a few ms of
        # bookkeeping); `first frame` is start -> first 47 MP request,
        # `drain` the extra frames spent past it confirming the controls.
        _bo_drain_extra = None
        if _bo_first_s is not None and drained > 0:
            _bo_drain_extra = max(0.0, (_bo_done_at - drain_t0) - _bo_first_s)

        def _bo_fmt(v):
            return "n/a" if v is None else f"{v:.2f}"

        print(f"[HiRes] blackout {_bo_done_at - _bo_t0:.2f}s: "
              + (f"dispatch {_bo_dispatch_s:.2f} | "
                 if _bo_dispatch_s is not None else "")
              + f"metadata {_bo_fmt(_bo_md_s)} ({_bo_md_src}) | plan "
              f"{_bo_fmt(_bo_plan_s)} | stop {_bo_fmt(_bo_stop_s)} "
              f"| settle {_bo_settle_s:.2f} | configure "
              f"{_bo_fmt(_bo_cfg_s)} | start {_bo_fmt(_bo_start_s)} | first "
              f"frame {_bo_fmt(_bo_first_s)} | drain +{_bo_fmt(_bo_drain_extra)}"
              + (f" ({drained} frame(s))" if _bo_first_s is not None else "")
              + (f" | {_bo_attempts} attempts" if _bo_attempts > 1 else "")
              + ("" if req is not None else " | no capture"))
    except Exception:
        # Diagnostics only — never let the journal line cost a capture.
        pass

    # Step 6 (failure half): stop the 47 MP pipeline if the success path
    # did not already — the flush above must run first on a dead mode so
    # the stop starts from flushed jobs, which is why the early stop only
    # happens once a request is actually in hand.
    if stopped_at is None:
        try:
            picam2.stop()
        except Exception as exc:
            print(f"[HiRes] post-capture picam2.stop() error: {exc}")
        stopped_at = time.monotonic()

    # Step 7: settle, then resume the binned preview — and confirm it is
    # actually live before declaring the capture over.  The worker thread
    # owns picam2 throughout, so the main loop reuses _last_lores_frame and
    # the UI stays responsive while this runs.  See _hires_restore_preview
    # for why the old flat 2.0 s dwell became a proof-of-life loop.
    #
    # The restore is handed the PRE-capture achieved exposure (step-1
    # metadata, pre-boost) as an AE seed — the double mode switch runs the
    # IPA's AGC through two per-mode sensitivity rescales with the boosted
    # manual exposure pinned in between, and without the seed AUTO resumed
    # ~2 stops under and settled there (see _hires_restore_preview).
    # Brenizer is excluded: its tile-to-tile exposure lock deliberately
    # keeps the capture's surviving pinned state until its exit path
    # restores, and a seed would replace those values mid-sequence.
    ae_seed = {}
    try:
        if not globals().get("_bren_capturing"):
            if live_md.get("ExposureTime") is not None:
                ae_seed["ExposureTime"] = int(live_md["ExposureTime"])
            if live_md.get("AnalogueGain") is not None:
                ae_seed["AnalogueGain"] = float(live_md["AnalogueGain"])
    except Exception:
        # A malformed metadata value must never cost the restore itself.
        ae_seed = {}
    try:
        restored = _hires_restore_preview(ae_seed=ae_seed or None,
                                          stopped_at=stopped_at)
    except Exception as restore_exc:
        # Belt and braces: the helper guards its own calls, so reaching here
        # means something unforeseen — never let it escape into the worker.
        restored = False
        print(f"[HiRes] preview restore error: {restore_exc}")
        traceback.print_exc()

    if restored:
        try:
            _apply_shutter_controls()
        except Exception as ctrl_exc:
            print(f"[HiRes] _apply_shutter_controls failed: {ctrl_exc}")
        # AE diagnostics: the main loop journals its first post-restore
        # frame's metadata ("AE just after restore") and a second sample
        # ~2 s later (_hires_ae_probe_at).  Together they show whether AE
        # resumed at the seeded operating point and whether it then WALKS
        # away from it — the discriminator between carried-state
        # corruption (the config seed fixes it) and a measurement-side
        # error (it cannot).  DigitalGain matters: a DG the AGC believes
        # in that the pipeline does not render is the one state that
        # leaves AE satisfied with a dark preview.  Both samples used to
        # cost a dedicated blocking capture_metadata here in the worker
        # (with the busy flag still set); deferring them to frames the
        # main loop pulls anyway makes them free.
        _hires_ae_log_first_frame = True
        _hires_ae_probe_at = time.monotonic() + 2.0
    else:
        # Every attempt failed.  _high_res_capture_busy is cleared in the
        # worker's finally, which re-arms the main loop's self-heal — it
        # restarts the pipeline through the same _start_still_pipeline_with_
        # fallback chain used at boot / mode switch / wake.  Deliberately not
        # duplicated here: one recovery mechanism, not two racing ones.
        print(f"[HiRes] preview restore failed after "
              f"{_HIGH_RES_RESTORE_ATTEMPTS} attempts — handing over to the "
              f"main-loop self-heal")
        _post_save_warning("Preview restore failed — recovering")

    if (develop_mono and main_frame is not None and dng_payload is not None
            and (dng_payload[1] or {}).get("QbcRaw") is True):
        # Synchronous double-exposure/Brenizer consumers use this frame
        # before the save worker. Develop before any blending or staging.
        developed = _maybe_develop_mono_frame(dng_payload, main_frame, mono_raw=True)
        if developed is None:
            raise RuntimeError("Quad raw monochrome development failed")
        main_frame = developed
        dng_payload = (dng_payload[0], dict(dng_payload[1], WlvMonoDeveloped=True), dng_payload[2])
    return main_frame, dng_payload


def _high_res_capture_worker(snapshot):
    """Run _perform_high_res_capture from a background thread and queue the
    main frame straight into _capture_save_queue, where the existing save
    worker thread will write the JPG asynchronously.  The main render loop
    is gated by _high_res_capture_busy so it does not touch picam2 while
    this is running.

    `snapshot` is a dict captured at the moment of shutter press so the
    worker is not racing against later UI changes (aspect / film / dir).
    """
    _warm_held = False
    try:
        # Serialise against the one-off CMA warm: it must release its
        # buffers before this capture allocates the real 47 MP set.
        _warm_held = _hires_warm_claim("47 MP capture")
        full_frame, dng_payload = _perform_high_res_capture(
            snapshot["dng_path"],
            slow_shutter_us=snapshot["slow_shutter_us"],
            sel_gain=snapshot.get("iso_gain", _ISO_SEL_UNSET),
            sel_stretch=snapshot.get("iso_stretch"),
            mono_raw=snapshot.get("pan_mono", False),
            defer_processing=snapshot.get("defer_processing", False),
            live_md=snapshot.get("live_md"),
            dispatched_at=snapshot.get("dispatched_at"),
        )
        # Queue whenever EITHER output survived: a raw payload with no main
        # frame still carries the DNG (the old synchronous path wrote the
        # DNG before the JPG grab, so a main-stream failure must not lose
        # the RAW now that both defer) — the save worker handles the
        # RAW-only job shape.
        if full_frame is not None or dng_payload is not None:
            print(
                f"[HiRes] queueing frame for save: "
                f"shape={'RAW-only' if full_frame is None else full_frame.shape} "
                f"jpg={snapshot['jpg_path']} dng={snapshot['dng_path']} "
                f"dng_deferred={dng_payload is not None}"
            )
            _capture_save_queue.put((
                full_frame,
                snapshot["target_dims"],
                snapshot["target_ratio"],
                snapshot["film_key"],
                snapshot["jpg_path"],
                snapshot["overlay_frame"],
                snapshot["dng_path"] if dng_payload is not None else None,
                dng_payload,  # DNG encode+write deferred to the save worker
                snapshot.get("exif_desc"),
                False,  # keep the JPG on the brightness-matched ISP frame
                snapshot.get("pan_mono", False),
                time.monotonic(),   # queue timestamp (worker logs the wait)
                snapshot.get("defer_processing", False),
            ))
            _mark_capture_queued(_capture_job_bytes(full_frame, dng_payload))
    except Exception as exc:
        print(f"[HiRes worker] error: {exc}")
        traceback.print_exc()
    finally:
        # Safety net: ensure the blackout always lifts even if the
        # worker bailed before reaching the explicit set() inside
        # _perform_high_res_capture.
        _high_res_capture_done.set()
        _high_res_capture_busy.clear()
        _hires_warm_release(_warm_held)


# Kick off lazy loaders so the preview appears immediately while secondary assets load.
threading.Thread(target=_lazy_startup_loader, daemon=True).start()

# -------------------- Shutter set mode (dual use BTN26) --------------------
# None = Auto; otherwise microseconds.  1/6000 and 1/10000 sit past some
# sensor modes' minimum exposure — libcamera clamps to the mode limit, same
# convention as every other manual speed.  New speeds are APPENDED so the
# persisted shutter_idx of an updated camera keeps meaning the same speed.
_SHUTTER_BUILTIN_US = [None, 125000, 66667, 33333, 16667, 8000, 4000, 2000, 1000, 500, 250, 167, 100]
_SHUTTER_BUILTIN_LABELS = ["AUTO","1/8","1/15","1/30","1/60","1/125","1/250","1/500","1/1000","1/2000","1/4000","1/6000","1/10000"]
# Tripwire: the two lists are indexed in lockstep everywhere (HUD, EXIF,
# popup, persistence) — a mismatched edit must fail loudly at boot.
assert len(_SHUTTER_BUILTIN_US) == len(_SHUTTER_BUILTIN_LABELS)

# The RUNNING table is the built-in ladder merged with the user's custom
# speeds (web Settings tab -> "Custom shutter speeds"), ordered slowest ->
# fastest with AUTO first.  Every consumer reads these two lists — the
# on-camera popup, viewfinder strip, HUD, grip cycle, EXIF, anti-banding
# quantization, the slow-shutter preview sim and the 47 MP capture — so a
# custom speed behaves exactly like a built-in one everywhere, with no
# second code path.  SHUTTER_IS_CUSTOM marks which entries the user added
# (the Settings tab lists those for deletion; nothing on the camera treats
# them differently).  See the pure core at the top of the file.
_custom_shutter_us = _shutter_sanitize_custom(
    _PERSISTED_SETTINGS.get("custom_shutter_speeds_us"), _SHUTTER_BUILTIN_US)
SHUTTER_OPTIONS_US, SHUTTER_LABELS, SHUTTER_IS_CUSTOM = _shutter_merge_table(
    _SHUTTER_BUILTIN_US, _SHUTTER_BUILTIN_LABELS, _custom_shutter_us)
assert len(SHUTTER_OPTIONS_US) == len(SHUTTER_LABELS) == len(SHUTTER_IS_CUSTOM)

# ---- Anti-banding (flicker-safe shutter) ----
# The user picks the local mains frequency from the shutter popup's
# Anti-band chips.  Manual speeds are then driven at the nearest flicker-safe
# exposure (_antibanding_quantize_us — the selected chip is untouched and the
# HUD shows the effective speed), and AUTO is constrained through libcamera's
# AeFlickerMode/AeFlickerPeriod where the running stack advertises it.
# Persisted by key (reorder-proof, like wb_mode_key).
ANTIBANDING_OPTIONS = [
    {"key": "off",  "label": "Off",   "period_us": None},
    {"key": "50hz", "label": "50 Hz", "period_us": 10000.0},   # 100 Hz flicker
    {"key": "60hz", "label": "60 Hz", "period_us": 8333.33},   # 120 Hz flicker
]


def _antibanding_idx_from_key(key):
    for _i, _opt in enumerate(ANTIBANDING_OPTIONS):
        if _opt["key"] == key:
            return _i
    return 0


_antibanding_idx = _antibanding_idx_from_key(
    str(_PERSISTED_SETTINGS.get("antibanding_key") or "off"))
# Effective (quantized) manual exposure in µs when anti-banding changed it;
# None whenever the applied exposure equals the selection (off / AUTO /
# already-safe speed).  Read by the HUD and the capture EXIF snapshot.
_antibanding_eff_us = None
_antibanding_flicker_ctrl_warned = False


def _antibanding_period_us():
    """Active flicker half-period in µs, or None when anti-banding is off."""
    try:
        return ANTIBANDING_OPTIONS[_antibanding_idx]["period_us"]
    except Exception:
        return None


def _shutter_load_persisted_idx():
    """Restore the shutter selection from the settings file.

    Value-based (`shutter_us`), with the legacy `shutter_idx` as the
    fallback — the same reorder-proof pattern as iso_gain / film_key /
    wb_mode_key, and load-bearing here because adding or deleting a custom
    speed RE-ORDERS the table: an index alone would silently come back
    meaning a different exposure.  A stored speed that no longer exists (its
    custom entry was deleted, or the file was hand-edited) lands on the
    nearest speed in stops rather than falling back to AUTO."""
    s = _PERSISTED_SETTINGS
    if "shutter_us" in s:
        us = s.get("shutter_us")
        if us is None:
            return 0                       # AUTO persists as an explicit null
        idx = _shutter_idx_for_us(SHUTTER_OPTIONS_US, us)
        if idx is not None:
            return idx
        return _shutter_nearest_idx(SHUTTER_OPTIONS_US, us)
    # Legacy file (no shutter_us): the index was written against the built-in
    # ladder, which is what it must be read against — bound it there, then
    # translate the SPEED into the merged table.
    legacy = _bounded_int(s.get("shutter_idx", 0), 0, 0,
                          len(_SHUTTER_BUILTIN_US) - 1)
    idx = _shutter_idx_for_us(SHUTTER_OPTIONS_US, _SHUTTER_BUILTIN_US[legacy])
    return 0 if idx is None else idx


current_shutter_idx = _shutter_load_persisted_idx()


def _shutter_persisted_payload():
    """(legacy_shutter_idx, shutter_us) for the settings payload.

    The microsecond VALUE is authoritative on load; the index is kept
    LEGACY-SAFE for OTA rollbacks — a custom selection writes the nearest
    BUILT-IN index, so a firmware that has never heard of custom speeds
    comes up on the closest speed it does have instead of indexing into a
    table that no longer matches."""
    with _shutter_button_lock:
        idx = current_shutter_idx
    try:
        us = SHUTTER_OPTIONS_US[idx]
    except Exception:
        return 0, None
    if us is None:
        return 0, None
    return _shutter_nearest_idx(_SHUTTER_BUILTIN_US, us), int(us)


def _set_custom_shutter_speeds(values):
    """Replace the custom speed list and rebuild the running table.

    Returns (ok, reason).  Safe to call from the HTTP thread: readers index
    the two tables without the lock, so the swap is ordered to keep every
    index valid at every instant — clamp the selection into BOTH tables
    first, publish the new lists, then land the remapped selection.  The
    worst a racing reader can see is one frame of the previous speed, which
    the _apply_shutter_controls() below immediately corrects."""
    global SHUTTER_OPTIONS_US, SHUTTER_LABELS, SHUTTER_IS_CUSTOM
    global _custom_shutter_us, current_shutter_idx
    cleaned = _shutter_sanitize_custom(values, _SHUTTER_BUILTIN_US)
    new_us, new_labels, new_flags = _shutter_merge_table(
        _SHUTTER_BUILTIN_US, _SHUTTER_BUILTIN_LABELS, cleaned)
    with _shutter_button_lock:
        selected_us = SHUTTER_OPTIONS_US[current_shutter_idx] \
            if 0 <= current_shutter_idx < len(SHUTTER_OPTIONS_US) else None
        new_idx = _shutter_idx_for_us(new_us, selected_us)
        if new_idx is None:
            # The selected speed was the custom entry just deleted.
            new_idx = _shutter_nearest_idx(new_us, selected_us)
        current_shutter_idx = min(current_shutter_idx,
                                  len(new_us) - 1, len(SHUTTER_OPTIONS_US) - 1)
        SHUTTER_LABELS = new_labels
        SHUTTER_IS_CUSTOM = new_flags
        SHUTTER_OPTIONS_US = new_us
        current_shutter_idx = new_idx
        _custom_shutter_us = cleaned
    print(f"[Shutter] Custom speeds: {[_shutter_label_for_us(v) for v in cleaned]}"
          f" — now on {new_labels[new_idx]}")
    _debounced_save_settings()
    try:
        _apply_shutter_controls()
    except Exception as exc:
        # A control re-apply can be deferred (47 MP worker owns picam2); the
        # table swap itself has already landed and the next apply picks it up.
        print("[Shutter] custom-speed control re-apply deferred:", exc)
    return True, "ok"


def _add_custom_shutter_speed(text):
    """Parse a typed speed and add it to the custom list.  (ok, reason)."""
    us, why = _shutter_parse_text(text)
    if us is None:
        return False, why
    if _shutter_too_close(us, [v for v in _SHUTTER_BUILTIN_US if v]):
        return False, ("%s is already a built-in speed"
                       % _shutter_label_for_us(us))
    if _shutter_too_close(us, _custom_shutter_us):
        return False, "%s is already in your list" % _shutter_label_for_us(us)
    if len(_custom_shutter_us) >= _CUSTOM_SHUTTER_MAX_COUNT:
        return False, ("Room for %d custom speeds — remove one first"
                       % _CUSTOM_SHUTTER_MAX_COUNT)
    return _set_custom_shutter_speeds(list(_custom_shutter_us) + [us])


def _remove_custom_shutter_speed(us):
    """Drop one custom speed by its microsecond value.  (ok, reason)."""
    us = _finite_number(us)
    if us is None:
        return False, "Unknown speed"
    us = int(round(us))
    remaining = [v for v in _custom_shutter_us if int(v) != us]
    if len(remaining) == len(_custom_shutter_us):
        return False, "Not one of your custom speeds"
    return _set_custom_shutter_speeds(remaining)


shutter_set_mode = False        # False = normal capture
_hold_fired = False             # guards short vs long press
_zoom_hold_fired_epoch = -1     # press epoch whose 1 s zoom-hold actually acted
# ONE arbiter for the whole hold gesture.  Three threads decide the fate of a
# single press -- the 1 s zoom Timer, gpiozero's 2 s `when_held`, and the
# release -- and assembling that outcome from separate flag writes is what
# produced three distinct races (reviewed on PR #270): a second lock
# acquisition the epoch could advance through, a 2 s hold and a delayed 1 s
# timer both acting on the same press, and a release deciding while the zoom
# was still running.  So the press is CLAIMED once, under one lock, and the
# first claimant owns it; everything else reads that claim rather than
# reconstructing it.
_hold_claim_epoch = -1          # press epoch that has been claimed
_hold_claim_owner = None        # "zoom" (1 s timer) | "held" (2 s when_held)
_zoom_hold_inflight_epoch = -1  # a zoom-hold action is running for this epoch
_zoom_hold_release_pending = False  # the button was released mid-action
# _hold_fired is written from three places (the 1s zoom-hold Timer callback,
# _on_held on the gpiozero hold thread, and _on_released on the gpiozero
# release thread) with no natural ordering between them. A Timer that fires
# right as the button is released (or a hold whose 2s `when_held` lands just
# after release) can otherwise mark a brand-new press as already "consumed",
# silently swallowing the next deliberate shutter tap. Guard with a lock plus
# a press epoch: the epoch increments on every _on_pressed, and a writer only
# marks _hold_fired if its captured epoch still matches — so a stale
# timer/hold callback from a previous (already-released) press can never
# consume the current one.
_hold_fired_lock = threading.Lock()
_press_epoch = 0
# Wall-clock start of the current physical-button hold (monotonic seconds),
# used ONLY to drive the display-only hold-progress ring in the main loop
# (see _hold_progress_state / _draw_hold_progress_indicator) — it never
# feeds any actual timer/hold-firing logic. Set in _on_pressed, cleared in
# _on_released. Written from the gpiozero callback thread and read from the
# main loop with no lock: a float/None assignment is atomic enough for a
# display value that is, worst case, one frame stale.
_shutter_press_start = None
# Pins ("b26" body shutter / "b21" grip button) whose current press arrived
# while the camera was asleep or in the low-power dim-idle state: that
# press/release pair is consumed as wake-only (no capture/zoom/shutter-set/
# grip-enable), and the pin clears on its own release — or on its next awake
# press, so a mis-paired latch can never suppress a real shot. Tracked per
# pin because two buttons can be down across a wake: a single shared flag
# let the first release consume the latch and the second fall through to a
# stray action. set.add/.discard are GIL-atomic, so the gpiozero callback
# threads and main loop need no lock. (Touch is one atomic event, handled
# inline in _on_touch, so it doesn't need the latch.)
_wake_swallow_pins = set()
# Hold-to-zoom: a dedicated short-hold timer on the hardware shutter fires
# the zoom gesture (Viewfinder 2x center zoom, Focus Point box zoom, Face
# Detect face zoom). Faster than the gpiozero `hold_time` of 2s used
# elsewhere (which still drives shutter-set / minimal-mode toggles in the
# other UIs). The slider (Viewfinder) UI uses the shorter 0.5 s hold — the
# same threshold as the grip's zoom hold — since shutter-set / minimal mode
# are not reachable there anyway; the other UIs keep 1 s.
_VIEWFINDER_ZOOM_HOLD_S = 1.0
_VIEWFINDER_SLIDER_ZOOM_HOLD_S = 0.5
_viewfinder_zoom_hold_timer = None


def _zoom_hold_threshold_s():
    """Shutter hold that fires the zoom gesture in the current UI mode —
    the one seam the timer and the hold-progress ring both read, so the
    ring can never count to a different threshold than the timer fires at."""
    return _VIEWFINDER_SLIDER_ZOOM_HOLD_S if _ui_viewfinder_mode else _VIEWFINDER_ZOOM_HOLD_S


shoot_event = threading.Event() # main loop performs capture

# -------------------- Grip mode (optional GPIO21 grip accessory) -----------
# Grip mode is a SESSION-ONLY state (never persisted) that repurposes the two
# hardware buttons when the grip accessory is attached:
#   - GPIO21 (grip)  -> shutter (take a photo); 0.5 s hold -> 2x center zoom.
#   - GPIO26 (body)  -> modifier: a short tap cycles the adjustable setting
#                       (None -> Shutter -> ISO -> EV); held >=1 s it becomes a
#                       "decrease" modifier.
# Two-button value adjust (a GPIO21 hold used as the decrease modifier crosses
# the 0.5 s zoom threshold first; the zoom it toggled is undone the moment the
# partner press reveals the hold as a chord — see _grip_undo_hold_zoom):
#   - hold GPIO26 >=1 s, then tap GPIO21  -> increase the selected setting
#   - hold GPIO21 >=1 s, then tap GPIO26  -> decrease the selected setting
# A second press that lands BEFORE the modifier crosses 1 s is still a chord,
# not a mistap: both presses are consumed (no stray capture / target cycle)
# and the first step is deferred to the repeat timer, firing the moment the
# modifier hold qualifies while both buttons stay down.
# Enabled by a single press of the grip button while grip mode is off; once on
# it stays on until reboot (no persisted flag, no manual off gesture).
_grip_mode_active = False
GRIP_ADJUST_NONE = 0
GRIP_ADJUST_SHUTTER = 1
GRIP_ADJUST_ISO = 2
GRIP_ADJUST_EV = 3
_GRIP_ADJUST_COUNT = 4
_grip_adjust_target = GRIP_ADJUST_NONE
# Per-button "consumed" guards: a press used as a modifier / value-trigger /
# zoom must not also fall through to its default action (cycle / capture).
_grip_b21_consumed = False      # GPIO21 press already acted (trigger/zoom) -> no capture
_grip_b26_consumed = False      # GPIO26 press already acted (trigger/modifier) -> no cycle
_grip_b26_press_t = 0.0         # monotonic time GPIO26 was pressed (tap detection)
_GRIP_MOD_HOLD_S = 1.0          # partner must be held this long before a press adjusts
_GRIP_TAP_MAX_S = 0.6           # GPIO26 press shorter than this counts as a cycle tap
_GRIP_FLASH_HOLD_S = 1.1        # how long the grip OSD message holds before fading
_GRIP_ZOOM_HOLD_S = 0.5         # Button(21, hold_time=...) reads this: the hold that fires zoom
_grip_b21_zoomed = False        # this GPIO21 press's hold toggled zoom (undone if it becomes a chord)
# Hold-to-fast-scroll: while the modifier stays held AND the value-trigger
# button is held down, auto-repeat the adjust on a self-re-arming timer that
# accelerates.  The first step still fires on the press, so a tap = one step.
# The timers only run while a button is physically held (power budget safe).
_grip_repeat_timer = None
_grip_repeat_direction = 0
_grip_repeat_epoch = 0          # invalidates in-flight fires across start/stop
_grip_repeat_count = 0
_grip_repeat_lock = threading.Lock()
_GRIP_REPEAT_DELAY_S = 0.45     # wait after the first step before auto-repeat
_GRIP_REPEAT_INTERVAL_S = 0.28  # initial repeat cadence
_GRIP_REPEAT_FAST_S = 0.12      # accelerated cadence
_GRIP_REPEAT_ACCEL_AFTER = 4    # steps before speeding up

# --- Slow-shutter preview simulation ---
# When the effective exposure exceeds _PREVIEW_MAX_EXPOSURE_US the sensor is
# kept at a fast frame rate and the preview frame is digitally brightened so
# the live view remains smooth while the histogram and exposure appearance
# stay correct.
_PREVIEW_MAX_EXPOSURE_US = 33333           # 1/30s – keep preview >= 30 fps
_preview_brightness_gain = 1.0             # digital gain for preview brightness
# Cached linear-light LUT for the sub-1.0 (dim) direction of the preview
# sim.  _preview_brightness_gain is an EXPOSURE ratio, so it may only be
# applied in linear light: multiplying the gamma-encoded 8-bit codes by
# 0.5 lands at 0.5**2.2 = 0.22x linear (over a stop too dark), and that
# frame is also the closed-loop JPG reference (_hires_linear_mean measures
# it in linear light), so the error would propagate straight into the
# saved JPG.  Rebuilt only when the gain changes (on a selection change,
# never per frame).  The >1 brightening direction deliberately keeps its
# historical encoded-domain multiply — changing it would alter the
# appearance of every slow-shutter preview.
_preview_dim_lut_cache = (0.0, None)


def _preview_dim_lut(gain):
    """256-entry LUT applying `gain` (<1) in linear light, cached by gain.
    Reuses _hires_exposure_match_lut, which is the same operation the 47 MP
    JPG brightness match already performs."""
    global _preview_dim_lut_cache
    try:
        g = round(float(gain), 4)
    except (TypeError, ValueError):
        return None
    if _preview_dim_lut_cache[0] == g and _preview_dim_lut_cache[1] is not None:
        return _preview_dim_lut_cache[1]
    try:
        lut = _hires_exposure_match_lut(g)
    except Exception:
        return None
    _preview_dim_lut_cache = (g, lut)
    return lut
_slow_shutter_capture_us = None            # real exposure µs for capture (None = use current)

def _preview_floor_us(include_shed=True):
    """Minimum preview frame duration (us) = display period, relaxed when idle.

    Uses the literal _PREVIEW_FRAME_DUR* constants (not TARGET_FPS) so it is safe
    to call at module load, before TARGET_FPS is defined.  When the backlight is
    dimmed the UI is already at 10 fps, so the sensor can drop to match.  The
    thermal load-shed tiers sit between the two (dimmed idle is already the
    slowest state, so the dim branch keeps precedence).

    include_shed=False skips the load-shed tiers: with an AUTO shutter the AE
    treats the frame duration as its exposure ceiling and stills capture
    straight from the running pipeline, so a shed-relaxed floor would let a
    dark-scene AUTO capture pick up a 1/15-1/12s exposure (extra motion blur)
    — heat shedding must never change a capture.  The AUTO branch of
    _apply_shutter_controls therefore passes False; manual-shutter branches
    pin ExposureTime explicitly and can shed the readout safely.  (The dimmed
    idle relaxation has no such leak: the dim path freezes AE at the pre-dim
    achieved values, so the ceiling is never explored.)
    """
    if _backlight_dimmed:
        return _PREVIEW_FRAME_DUR_IDLE_US
    # Field mitigation: the shed tiers never reach the sensor while
    # _HEAT_SHED_READOUT_ENABLED is False (see its comment at the governor).
    if include_shed and _HEAT_SHED_READOUT_ENABLED:
        if _heat_shed_level >= 2:
            return _PREVIEW_FRAME_DUR_SHED2_US
        if _heat_shed_level == 1:
            return _PREVIEW_FRAME_DUR_SHED1_US
    return _PREVIEW_FRAME_DUR_US

def _apply_shutter_controls():
    """Apply the currently selected shutter to the *running* pipeline (auto-ISO).

    When a manual shutter speed is slower than 1/30s the sensor stays at
    1/30s for smooth preview; the brightness difference is compensated with
    a digital gain applied in the main loop.  For capture the real exposure
    time is restored momentarily.
    """
    global _preview_brightness_gain, _slow_shutter_capture_us
    global _antibanding_eff_us, _antibanding_flicker_ctrl_warned
    # Block calls from threads OTHER than the high-res worker while the
    # worker owns picam2.  Without this, a touch handler / timer / HTTP
    # trigger that fires _apply_shutter_controls during the worker's
    # stop / configure / start cycle races libcamera and can hang the
    # camera.  The worker itself calls this function during its restore
    # step, so allow it through by name.
    if (
        _high_res_capture_busy.is_set()
        and threading.current_thread().name != "hires_capture_worker"
    ):
        return
    # Flash sync holds the pipeline hard-locked while armed: exposure pinned
    # equal to the frame duration, gains and white balance frozen.  Re-applying
    # the user's shutter/ISO here would unpin the frame duration mid-arming and
    # break the complementary-split arithmetic the mode depends on.  _flash_disarm
    # calls this function itself, after clearing the flag, to hand the exposure
    # state back.
    if _flash_armed:
        return
    us = SHUTTER_OPTIONS_US[current_shutter_idx]
    iso_gain = _current_iso_gain()
    if iso_gain is not None:
        # Sub-floor extension entries (the true-ISO-100 / true-ISO-200
        # selections, gains 0.25 / 0.5) run the PREVIEW at the sensor's
        # analogue-gain floor — the sensor cannot go lower, and the binned
        # 47 MP capture makes up the difference by stretching ExposureTime
        # instead of boosting gain (see _iso_exposure_stretch).  Classic
        # selections pass through untouched.
        _gain_floor = _iso_capture_gain_floor() or 1.0
        if float(iso_gain) < float(_gain_floor):
            iso_gain = float(_gain_floor)
    controls = {}

    # Anti-banding: ask the AE loop to only pick flicker-safe exposures
    # (AeFlickerMode 1 = FlickerManual + the half-period).  Matters for the
    # AUTO branch below; harmless alongside a pinned manual ExposureTime.
    # Both keys are filtered against what the running libcamera advertises
    # (same pattern as _wb_controls — passing unknown controls raises); an
    # older stack simply leaves AUTO unconstrained, and the manual branches
    # never need the control — they pin a quantized ExposureTime themselves.
    ab_period = _antibanding_period_us()
    try:
        _ab_avail = picam2.camera_controls or {}
    except Exception:
        _ab_avail = {}
    # Re-assert the Normal AGC constraint list on every control apply (see
    # _AE_CONSTRAINT_NORMAL).  The config dicts carry it too, but a mid-session
    # flip into the highlight list is exactly the failure this defends against,
    # and a configure is not guaranteed between one and the next.  Filtered
    # against what the running libcamera advertises, like AeFlickerMode below.
    if "AeConstraintMode" in _ab_avail:
        controls["AeConstraintMode"] = _AE_CONSTRAINT_NORMAL

    if ab_period and "AeFlickerMode" in _ab_avail and "AeFlickerPeriod" in _ab_avail:
        controls["AeFlickerMode"] = 1  # FlickerManual
        controls["AeFlickerPeriod"] = int(round(ab_period))
    elif "AeFlickerMode" in _ab_avail:
        controls["AeFlickerMode"] = 0  # FlickerOff
    elif ab_period and not _antibanding_flicker_ctrl_warned:
        _antibanding_flicker_ctrl_warned = True
        print("[AB] AeFlickerMode unsupported by running libcamera — "
              "AUTO shutter unconstrained (manual snapping unaffected)")

    fd_floor = _preview_floor_us()
    if us is None:
        # AUTO mode – pin frame duration to the display rate so AE cannot drive
        # the sensor faster than we can show.  The AE compensates with ISO.
        # Load-shed tiers are excluded here (include_shed=False): the frame
        # duration is also the ceiling AE may assign to still exposure, and
        # stills capture the current request as-is — relaxing it under shed
        # would let a hot camera add motion blur to dark-scene AUTO captures.
        # The UI pacing / overlay / stream sheds still apply in AUTO; only the
        # sensor readout keeps the normal rate.
        fd_ae = _preview_floor_us(include_shed=False)
        controls["FrameDurationLimits"] = (fd_ae, fd_ae)
        _preview_brightness_gain = 1.0
        _slow_shutter_capture_us = None
        _antibanding_eff_us = None   # AE owns the exposure (flicker ctrl above)
        if iso_gain is None:
            controls["AeEnable"] = True
        else:
            controls["AeEnable"] = True
            controls["AnalogueGain"] = float(iso_gain)
    else:
        # Anti-banding: drive the sensor at the nearest flicker-safe exposure
        # while the user's selected chip stays put — the HUD shows the
        # effective speed, and turning the mode off restores the exact
        # selection.  A pass-through (off / already-safe) keeps eff == us.
        eff_us = int(_antibanding_quantize_us(int(us), ab_period))
        _antibanding_eff_us = eff_us if eff_us != int(us) else None
        # Sub-floor manual ISO (true ISO 100 / 200): the capture uses the
        # selected (flicker-quantized) speed VERBATIM — a manual shutter is
        # an instruction, never a brightness target — and the binned
        # preview runs the stretch-adjusted EQUIVALENT exposure in the
        # background: the binned read-out collects ~stretch times the
        # signal per pixel that the capture's pinned low-ISO gain records,
        # so eff/stretch (e.g. 1/500 for a selected 1/125 at ISO 100) is
        # an exact OPTICAL brightness match to the capture — no digital
        # sim, honest histogram.  pv_us == eff_us whenever no trade is
        # active (every classic selection, AUTO ISO, video/LE), keeping
        # this branch bit-for-bit the historical path.  The capture-side
        # target rides _slow_shutter_capture_us (its documented meaning:
        # "real exposure for capture") so every 47 MP dispatch injects the
        # true speed; a preview-equivalent below the sensor's minimum
        # exposure clamps up in libcamera — at those speeds the capture is
        # near-black at ISO 100 anyway.
        _pv_trade = _iso_exposure_stretch()
        pv_us = max(1, int(round(eff_us / _pv_trade)))
        if pv_us > _PREVIEW_MAX_EXPOSURE_US:
            # Slow manual shutter: preview at 1/30s, simulate brightness.
            # Digital gain is only applied when ISO is manual (AE off),
            # because with auto ISO the AE already raises gain to match
            # the target exposure — adding digital gain on top would
            # double-compensate and over-expose the preview.  Under the
            # low-ISO trade the sim brightens to the PREVIEW-equivalent
            # exposure (pv_us), which is the capture's true brightness.
            _slow_shutter_capture_us = eff_us
            controls["ExposureTime"] = _PREVIEW_MAX_EXPOSURE_US
            fd = max(_PREVIEW_MAX_EXPOSURE_US, fd_floor)
            controls["FrameDurationLimits"] = (fd, fd)
            if iso_gain is None:
                # Auto ISO: AE compensates via ISO, no digital gain needed
                _preview_brightness_gain = 1.0
            else:
                # Manual ISO: simulate the longer exposure digitally
                _preview_brightness_gain = float(pv_us) / float(_PREVIEW_MAX_EXPOSURE_US)
        else:
            _preview_brightness_gain = 1.0
            # Under the trade the preview is deliberately NOT at the real
            # exposure, so the capture target must ride along explicitly.
            _slow_shutter_capture_us = eff_us if _pv_trade > 1.0 else None
            if _pv_trade > 1.0:
                # Fastest shutters at the sub-floor ISOs can put pv_us
                # below the mode's minimum exposure (1/10000 at ISO 100 →
                # 25 us).  libcamera would clamp the request up silently,
                # leaving the preview — and the closed-loop JPG reference
                # measured from it — brighter than the verbatim capture.
                # Clamp it here instead and cover the residual with a
                # digital DIM (the inverse of the slow-shutter sim), so
                # preview, histogram and the JPG match all stay on the
                # capture's true brightness.  Unreadable minimum → fail
                # open to the historical libcamera clamp.
                _pv_min = _iso_min_exposure_us()
                if _pv_min and pv_us < _pv_min:
                    _preview_brightness_gain = float(pv_us) / float(_pv_min)
                    pv_us = int(_pv_min)
            controls["ExposureTime"] = pv_us
            # Exposure is shorter than the display period; bound the readout to
            # the display rate (exposure itself is unchanged).
            fd = max(pv_us, fd_floor)
            controls["FrameDurationLimits"] = (fd, fd)

        if iso_gain is None:
            controls["AeEnable"] = True
        else:
            controls["AeEnable"] = False
            controls["AnalogueGain"] = float(iso_gain)

    # Dimmed idle: freeze the AE loops at their current converged values.
    # The camera idles lens-down against a bag or clothing, so with AE left
    # running the AGC ratchets shutter x gain to its ceiling within seconds
    # of the dim; on wake the preview is then blown white for seconds while
    # the AGC claws back down through saturated stats. The freeze pins the
    # loops at the last completed frame's ACHIEVED ExposureTime /
    # AnalogueGain (_meta, refreshed by the main loop from every lores
    # request), so the dark scene never contaminates the AGC state and wake
    # resumes from the sane pre-dim exposure. Explicit values matter: the
    # original bare AeEnable=False rode through the same set_controls that
    # relaxes FrameDurationLimits to the 100 ms idle readout, and the IPA
    # re-split its frozen exposure target against the new limits — the
    # dimmed preview blew out the moment the dim landed, leaving the user
    # unable to see the scene at 10 fps. Pinning the achieved values keeps
    # the dimmed preview at the exact pre-dim brightness. Values a manual
    # branch already set stay authoritative (never overwritten here); the
    # wake edge re-runs this function with _backlight_dimmed False,
    # restoring auto. Metadata missing (first frames after boot) falls back
    # to the bare freeze rather than guessing values.
    # Video mode is exempt from the freeze even though video STANDBY now
    # dims (and relaxes its readout floor below — that part is the battery
    # win).  A recording started from a dimmed standby runs on the GPIO
    # thread and can land before the main loop's wake edge; once
    # _video_recording is set nothing in the video path re-enables AE
    # (_stop_video_recording deliberately never calls this function), so
    # the whole clip would be shot with AE locked at the dim-time exposure.
    with _video_lock:
        _in_video = _video_mode_active
        _vid_rec = _video_recording
    if _backlight_dimmed and not _in_video and controls.get("AeEnable"):
        controls["AeEnable"] = False
        _md = globals().get("_meta") or {}
        if "ExposureTime" not in controls:
            _md_exp = _md.get("ExposureTime")
            if _md_exp:
                # Never request an exposure longer than the frame duration
                # applied above — the pipeline would stretch the frame.
                _fd_hi = controls.get(
                    "FrameDurationLimits", (fd_floor, fd_floor))[1]
                controls["ExposureTime"] = min(int(_md_exp), int(_fd_hi))
        if "AnalogueGain" not in controls:
            _md_gain = _md.get("AnalogueGain")
            if _md_gain:
                controls["AnalogueGain"] = float(_md_gain)

    # Apply exposure compensation (works with AeEnable=True).  The Focus
    # Point spot-metering bias rides on top of the user's EV comp so a popup
    # touch mid-meter can't snap the exposure back (see _spot_meter_tick).
    controls["ExposureValue"] = float(_spot_meter_applied_ev())

    # In video mode (standby or recording) the frame duration must stay
    # pinned to _VIDEO_FPS. ISO/shutter/EV are live-adjustable in video
    # standby, and the still/preview logic above just computed a
    # FrameDurationLimits meant for the photo pipeline — applying it here
    # would clobber the 24 fps lock the moment one of those popups is
    # touched. Leave gain/AE/exposure-comp as computed above; only the
    # frame-duration clamp differs from the still path.
    if _in_video:
        _vid_fd_us = int(1e6 / _VIDEO_FPS)
        # Video STANDBY is as idle as plain preview, so while the backlight
        # is dimmed it follows the idle readout floor instead of burning
        # 24 fps of sensor readout for a picture nobody is looking at
        # (battery).  Never while RECORDING — the encoder's rate lock must
        # not move underneath it.  _start_video_recording re-pins the video
        # frame duration itself before starting the encoder, so a shutter
        # press from a dimmed standby (GPIO thread; the wake edge only lands
        # on the main loop's next frame) cannot record at the idle rate.
        if _backlight_dimmed and not _vid_rec:
            _vid_fd_us = max(_vid_fd_us, int(_preview_floor_us()))
        controls["FrameDurationLimits"] = (_vid_fd_us, _vid_fd_us)

    picam2.set_controls(controls)

# Booting straight into the binned 47 MP mode with a persisted ISO that
# mode does not offer (its boosted capture gain exceeds the sensor's
# ceiling — e.g. a pre-update "6400" selection): clamp before the first
# control apply, same one-way migration as a persisted unbinned key.
# This is the BOOT clamp point on purpose: the in-seam clamp inside
# _start_still_pipeline_with_fallback no-ops during the boot start (the
# 47 MP display constants are defined after that call).
_iso_clamp_to_available("boot")
# Apply persisted shutter/ISO settings to the camera pipeline so manual
# exposure values saved from the previous session take effect immediately.
# Without this, the camera starts with AeEnable=True (full auto-exposure)
# regardless of what the UI displays, causing the sensor to auto-compensate
# for aperture changes on manual lenses.
_apply_shutter_controls()


def _enter_charge_mode():
    global charge_mode_active, _charge_shutdown_triggered, _charge_fan_forced
    global _ui_minimal_mode, _icons_fade, _icons_fade_target
    if charge_mode_active:
        return

    # Exit video mode first so the flag is cleared and still_config is restored
    # cleanly before charge mode stops the pipeline.
    if _video_mode_active:
        _exit_video_mode()

    # Same for a flash-sync arming: charge mode stops the pipeline, and the
    # locks it holds would be restored against a stopped camera.
    _flash_disarm("charge mode")

    # Close the Wi-Fi overlay if it was open so charge-mode UI remains usable.
    try:
        _close_wifi_overlay()
    except Exception:
        pass

    charge_mode_active = True
    _charge_shutdown_triggered = False
    # Minimal (auto-hidden) UI is a live-view state, but its icon fade is
    # applied inside _draw_icon_to_dst — shared by the charge-menu buttons.
    # If AC is plugged in while the live UI is hidden (auto-hide fires after
    # 30 s idle), the charge screen would inherit _icons_fade == 0 and draw
    # every icon invisible yet still tappable. Leave minimal mode and snap
    # the fade fully opaque so the charge UI always comes up complete.
    _ui_minimal_mode = False
    _cancel_minimal_mode_timer()
    _icons_fade = 1.0
    _icons_fade_target = 1.0
    _record_activity(wake=True)
    shoot_event.clear()
    try:
        picam2.stop()
    except Exception as exc:
        print("Preview stop error:", exc)
    _charge_stats_cache["timestamp"] = 0.0
    _update_charge_stats(force=True)

    # --- Charge-mode power reductions (restored in _exit_charge_mode) ---
    # The camera pipeline is already stopped above; the charge UI only renders
    # static stats + a battery animation, so drop the CPU to its low-power
    # state and dim the panel. _backlight_dimmed is intentionally left False so
    # the idle wake-on-touch path never fights this dim — only the brightness
    # +/- buttons (a deliberate user override) change it.
    _set_cpu_low_power(True)
    if _BACKLIGHT_AVAILABLE:
        _set_backlight_level(_CHARGE_BACKLIGHT_DIM_LEVEL)
    # Run the cooling fan to pull heat off the cells, but only while the X1200
    # is actually charging — AC plugged in AND a battery pack present. It starts
    # at a moderate baseline and steps up with SoC temperature (see
    # _apply_charge_fan), rather than slamming to 100%. On battery, or on AC
    # with no pack — e.g. a manually opened charge screen — leave cooling to the
    # kernel governor to protect the power budget. The render loop re-asserts/
    # releases this as AC and the pack come and go. Restored on exit.
    _snapshot_fan_state()
    if _read_pld_state(use_cache=True) == 1 and _charge_battery_present():
        _apply_charge_fan()


@_web_update_charge_gate
def _exit_charge_mode():
    global charge_mode_active, _charge_shutdown_triggered, _delete_confirm_active
    global _video_mode_active, _video_recording, _video_config
    global _sensor_mode_popup_visible, _charge_auto_forced, _charge_fan_forced
    global _charge_shoot_override, _charge_overheat_parked, _charge_shoot_hot_since
    global _charge_fan_level, _power_menu_visible, _quit_confirm_active
    _delete_confirm_active = False
    _quit_confirm_active = False
    _sensor_mode_popup_visible = False
    _power_menu_visible = False
    if not charge_mode_active:
        return
    charge_mode_active = False
    _charge_auto_forced = False
    _charge_shutdown_triggered = False
    # Any "shoot while charging" session ends when charge mode is fully exited
    # (the shoot path sets the override again immediately after this returns).
    _charge_shoot_override = False
    _charge_overheat_parked = False
    _charge_shoot_hot_since = None

    # Reverse the charge-mode power reductions before the pipeline restarts.
    # _set_cpu_low_power(False) restores the governor and the 1.2 GHz thermal
    # cap from its own snapshot.
    _set_cpu_low_power(False)
    if _BACKLIGHT_AVAILABLE:
        _set_backlight_level(_BACKLIGHT_NORMAL_LEVEL)
    # Hand the fan back to the kernel thermal governor.
    _restore_fan_state()
    _charge_fan_forced = False
    _charge_fan_level = 0
    # Charge mode always restores still_config, so ensure the video mode flag
    # is cleared.  _enter_charge_mode() calls _exit_video_mode() on entry, but
    # if that failed or a race left the flag set the shutter button would
    # route to the record start/stop path on a still pipeline.
    with _video_lock:
        _video_mode_active = False
        _video_recording = False
        _video_config = None
    _charge_stats_cache["timestamp"] = 0.0
    _record_activity(wake=True)
    # Generalized fallback (reverts to a working mode rather than leaving the
    # camera dead) if the mode picked from the charge-mode dropdown fails to
    # start — see _start_still_pipeline_with_fallback.  A sensor-mode change
    # made from that dropdown is only persisted here, once the pipeline for
    # it (or whatever it fell back to) has actually started.
    if _start_still_pipeline_with_fallback():
        _debounced_save_settings()
        try:
            time.sleep(0.1)
            _apply_shutter_controls()
        except Exception as exc:
            print("Preview restart error:", exc)

@_web_update_charge_gate
def _enter_charge_shoot_mode():
    """"Shoot while charging": leave the charge screen into the live preview
    while staying on AC.  _exit_charge_mode() restarts the pipeline and restores
    the normal CPU/backlight; the main-loop on-AC block then holds the fan on
    the pack and arms the SoC-temp overheat auto-park safeguard.  Session-only
    (never persisted) — each fresh plug-in parks to the charge screen first."""
    global _charge_shoot_override, _charge_overheat_parked, _charge_shoot_hot_since
    _exit_charge_mode()
    _charge_shoot_override = True
    _charge_overheat_parked = False
    _charge_shoot_hot_since = None
    _record_activity(wake=True)


def _toggle_shutter_set_mode():
    global shutter_set_mode
    shutter_set_mode = not shutter_set_mode
    mode = "ON" if shutter_set_mode else "OFF"
    print(f"[Shutter Set Mode] {mode} – {SHUTTER_LABELS[current_shutter_idx]}")
    # Apply selection immediately to preview so you see the effect live
    _apply_shutter_controls()

def _trigger_shutter_osd():
    """Show the shutter speed OSD flash after a swipe gesture."""
    global _shutter_osd_text, _shutter_osd_fade_target, _shutter_osd_timer
    _shutter_osd_text = SHUTTER_LABELS[current_shutter_idx]
    _shutter_osd_fade_target = 1.0
    _shutter_osd_timer = _SHUTTER_OSD_HOLD_S

def _cycle_shutter():
    # Steps through the speeds the MENU offers, so a hardware cycle can
    # never stop on an entry the user hid (_menu_step keeps the current
    # selection reachable even when it is one of them).
    global current_shutter_idx
    current_shutter_idx = _menu_step(
        _menu_indices("shutter", active=current_shutter_idx),
        current_shutter_idx, 1)
    print(f"[Shutter] {SHUTTER_LABELS[current_shutter_idx]}")
    _debounced_save_settings()
    _apply_shutter_controls()
    _trigger_shutter_osd()


def _cycle_shutter_reverse():
    """Cycle shutter speed in reverse (toward slower / Auto)."""
    global current_shutter_idx
    current_shutter_idx = _menu_step(
        _menu_indices("shutter", active=current_shutter_idx),
        current_shutter_idx, -1)
    print(f"[Shutter] {SHUTTER_LABELS[current_shutter_idx]}")
    _debounced_save_settings()
    _apply_shutter_controls()
    _trigger_shutter_osd()

# Button wiring (hold=2s) — also initialises PLD sense button deferred earlier.
from gpiozero import Button
_init_pld_button()
button = Button(26, pull_up=True, bounce_time=0.05, hold_time=2.0)
# Second hardware shutter input on GPIO21, wired to the same handlers as
# GPIO26 so either pin triggers identical press/hold/release actions.
# NB: GPIO16 is NOT usable here — the X1200 UPS reserves it for charge
# control, and claiming it disrupts power management (boot loop). GPIO21
# (header pin 40) is free on this build.
try:
    # hold_time only drives grip mode's zoom (GPIO21's hold is unused with
    # grip mode off), so it IS the grip zoom threshold.
    button_gpio21 = Button(21, pull_up=True, bounce_time=0.05,
                           hold_time=_GRIP_ZOOM_HOLD_S)
except Exception as _exc:
    print(f"[GPIO] GPIO21 shutter input unavailable: {_exc}")
    button_gpio21 = None

def _toggle_viewfinder_mode():
    """Toggle Viewfinder UI: dark side panel with the context-aware
    Shutter / ISO / EV / Film / Aspect strip.

    Designed for use with a physical viewfinder attached over the screen — the
    strip keeps the key exposure controls accessible while the preview area
    shrinks to the canvas-right half. Replaces the main-UI button column
    and its popup selectors while active.
    """
    global _ui_viewfinder_mode, _ui_minimal_mode
    global _shutter_popup_visible, _aspect_popup_visible, _film_popup_visible
    global _iso_popup_visible, _focus_popup_visible, _multishot_popup_visible
    global _last_button_activity_time
    global _viewfinder_active_setting, _viewfinder_slider_rects
    global _viewfinder_slider_bounds, _viewfinder_value_label_rect
    global _viewfinder_slider_dragging

    _ui_viewfinder_mode = not _ui_viewfinder_mode
    _last_button_activity_time = time.monotonic()

    # Reset strip state on every toggle so re-entering lands on the default
    # setting and stale rects from a previous session don't consume taps.
    with _viewfinder_lock:
        _viewfinder_active_setting = _VIEWFINDER_DEFAULT_SETTING
        _viewfinder_slider_rects = []
        _viewfinder_slider_bounds = None
        _viewfinder_value_label_rect = (0, 0, 0, 0)
    _viewfinder_slider_dragging = False

    if _ui_viewfinder_mode:
        # Mutually exclusive with minimal mode — entering viewfinder leaves
        # minimal mode and cancels its pending hold-timer.
        _ui_minimal_mode = False
        _cancel_minimal_mode_timer()
        # Close any main-UI popups that were open before the swipe.
        _shutter_popup_visible = False
        _aspect_popup_visible = False
        _film_popup_visible = False
        _iso_popup_visible = False
        _focus_popup_visible = False
        _multishot_popup_visible = False

    print(f"[UI] Viewfinder mode {'enabled' if _ui_viewfinder_mode else 'disabled'}")


def _toggle_minimal_mode():
    """Toggle minimal UI mode (hide all buttons except preview, histogram, battery, settings)."""
    global _ui_minimal_mode, shutter_set_mode
    global _shutter_popup_visible, _aspect_popup_visible, _film_popup_visible, _iso_popup_visible
    global _focus_popup_visible, _multishot_popup_visible
    global _last_button_activity_time
    global _minimal_hint_started, _minimal_hint_until

    _ui_minimal_mode = not _ui_minimal_mode
    # Reset the inactivity timer so re-entering non-minimal gets a fresh
    # window, and so auto-hide can't immediately re-fire after toggling.
    _last_button_activity_time = time.monotonic()

    # Exit shutter set mode on 7-second hold (shutter set mode only for 2-7 second holds)
    if shutter_set_mode:
        shutter_set_mode = False
        print("[Shutter] Set mode OFF (7s hold)")

    if _ui_minimal_mode:
        # Close any open popups (button rects are kept so a tap in the button
        # region can restore the UI from minimal mode).  Must include Multishot:
        # otherwise it stays logically open but invisible, and a tap on its stale
        # (undrawn) rects silently enters Brenizer/Video/Long-Exposure instead of
        # restoring the UI. (Exposure-comp now lives inside the ISO popup, closed
        # by clearing _iso_popup_visible.)
        _shutter_popup_visible = False
        _aspect_popup_visible = False
        _film_popup_visible = False
        _iso_popup_visible = False
        _focus_popup_visible = False
        _multishot_popup_visible = False
        # Arm the fading "tap to show controls" hint — only on the entry edge
        # (this whole branch only runs when minimal mode just turned on), so
        # it can't be re-triggered every frame while minimal mode sits idle.
        _minimal_hint_started = _last_button_activity_time
        _minimal_hint_until = (_minimal_hint_started + _MINIMAL_HINT_HOLD_S
                                + _MINIMAL_HINT_FADE_OUT_S)

    print(f"[UI] Minimal mode {'enabled' if _ui_minimal_mode else 'disabled'}")


def _arm_minimal_mode_timer():
    """Arm the 7-second-total minimal-mode hold timer (race-safe: lock + epoch,
    same pattern as _grip_repeat_timer — armed on the gpiozero hold thread,
    cancelled on the release/event threads)."""
    global _minimal_mode_timer, _minimal_mode_epoch
    with _minimal_mode_timer_lock:
        if _minimal_mode_timer is not None:
            _minimal_mode_timer.cancel()
        _minimal_mode_epoch += 1
        epoch = _minimal_mode_epoch
        _minimal_mode_timer = threading.Timer(
            _MINIMAL_MODE_HOLD_EXTRA_S, _minimal_mode_timer_fire, args=(epoch,))
        _minimal_mode_timer.daemon = True
        _minimal_mode_timer.start()


def _cancel_minimal_mode_timer():
    """Cancel any pending minimal-mode hold timer (idempotent, race-safe)."""
    global _minimal_mode_timer, _minimal_mode_epoch
    with _minimal_mode_timer_lock:
        _minimal_mode_epoch += 1          # invalidate any in-flight fire
        if _minimal_mode_timer is not None:
            _minimal_mode_timer.cancel()
            _minimal_mode_timer = None


def _minimal_mode_timer_fire(epoch):
    """Timer callback: only toggle if this arm is still the current epoch (a
    cancel/re-arm that raced the fire wins, so a stale timer can't toggle
    minimal mode seconds after the button was released)."""
    global _minimal_mode_timer
    with _minimal_mode_timer_lock:
        if epoch != _minimal_mode_epoch:
            return
        _minimal_mode_timer = None
    # Toggle outside the lock (it touches unrelated UI globals).
    _toggle_minimal_mode()


def _mark_hold_fired(epoch):
    """Set `_hold_fired` iff `epoch` still matches the current press (see the
    `_hold_fired_lock` / `_press_epoch` comment above).  Returns True when the
    mark took effect.  A stale timer/hold callback whose press has already
    been released (epoch advanced) is a no-op, so it can never swallow the
    NEXT press's release."""
    global _hold_fired
    with _hold_fired_lock:
        if epoch != _press_epoch:
            return False
        _hold_fired = True
        return True


def _claim_hold(epoch, owner):
    """Claim this press for `owner` ("zoom" = the 1 s timer, "held" = the 2 s
    `when_held`).  Returns True when the claim took — and the FIRST claimant
    wins, so exactly one handler ever acts on a press.

    Everything happens in ONE critical section, which is the whole point.
    The previous shape marked `_hold_fired` under the lock, released it, then
    took it again to record the epoch — and the press could be released and a
    new one begun in that gap, so the stale callback recorded the old epoch,
    returned success, and went on to zoom during the NEW press, defeating the
    epoch guard it was written to enforce (reviewed on PR #270).

    First-claimant-wins is also what removes the 1 s-timer-versus-2 s-hold
    race.  Those two are scheduled independently, and a `threading.Timer`
    delayed past gpiozero's `when_held` used to let BOTH act: shutter-set and
    minimal mode armed by the hold, then a centre zoom from the late timer —
    the hybrid state the old unconditional Viewfinder branch existed to
    prevent.  Now whichever runs first owns the press and the other is a
    no-op, with no ordering assumption at all.
    """
    global _hold_fired, _zoom_hold_fired_epoch
    global _hold_claim_epoch, _hold_claim_owner, _zoom_hold_inflight_epoch
    with _hold_fired_lock:
        if epoch != _press_epoch:
            return False
        if _hold_claim_epoch == epoch and _hold_claim_owner is not None:
            return False
        _hold_claim_epoch = epoch
        _hold_claim_owner = owner
        _hold_fired = True
        if owner == "zoom":
            _zoom_hold_fired_epoch = epoch
            _zoom_hold_inflight_epoch = epoch
        return True


def _settle_zoom_hold(epoch, acted):
    """Close a "zoom" claim once the action has run.  `acted` is what the
    zoom reported.  Returns True when the caller must now perform the
    short-press the release deferred.

    Two things close here, and they have to close together.  A zoom that
    DECLINED (the main loop dropped the tracked face between the timer's own
    check and the call) must not leave the press consumed — that is the
    complete no-op this gesture has been fixed for twice.  And a release that
    landed WHILE the zoom was running must not have decided on its own: it
    would have read the in-flight `_hold_fired` as a real long press and
    swallowed itself, so the rollback would arrive too late to help and the
    press would do nothing despite ending unmarked (reviewed on PR #270).
    `_on_released` therefore defers to here instead of deciding, and this is
    where the two outcomes are resolved under one lock.

    Only ever touches its OWN epoch, so a stale callback cannot clear a newer
    press's legitimate claim.
    """
    global _hold_fired, _zoom_hold_fired_epoch
    global _hold_claim_epoch, _hold_claim_owner
    global _zoom_hold_inflight_epoch, _zoom_hold_release_pending
    with _hold_fired_lock:
        if _zoom_hold_inflight_epoch != epoch:
            return False
        _zoom_hold_inflight_epoch = -1
        released = _zoom_hold_release_pending
        _zoom_hold_release_pending = False
        if acted:
            # The zoom happened: the press is legitimately consumed, and a
            # release that arrived mid-action stays swallowed.
            return False
        if _hold_claim_epoch == epoch:
            _hold_claim_epoch = -1
            _hold_claim_owner = None
        if _zoom_hold_fired_epoch == epoch:
            _zoom_hold_fired_epoch = -1
        _hold_fired = False
        return bool(released) and epoch == _press_epoch


def _viewfinder_zoom_hold_fire(epoch):
    """Fired by the zoom-hold timer (0.5 s in the Viewfinder/slider UI, else
    1 s — `_zoom_hold_threshold_s()`). In Focus Point mode it toggles a 2×
    zoom centred on the focus box; in Face Detect it toggles a zoom onto the
    tracked face at the level that frames it; in the Viewfinder UI it does a
    2× center zoom. Marks the press as a long-press so the release won't
    capture.

    `_on_pressed` only arms the timer when one of those three is available —
    keep that gate and this branch set in step, or the gesture is dead.
    """
    global zoom_active, zoom_center_norm, _zoom_level_idx
    global _viewfinder_zoom_hold_timer
    _viewfinder_zoom_hold_timer = None
    if sleep_mode_active or charge_mode_active:
        return
    with _video_lock:
        in_video = _video_mode_active
    if in_video:
        return
    # Face Detect: the hold zooms onto the tracked face, at the level that
    # frames it (see _face_zoom_into_face).  Same capture-mode courtesy as
    # Focus Point below — while LE / Brenizer own the shutter the press
    # falls through to _on_released instead of being consumed here.  With no
    # face tracked the hold does nothing rather than zooming somewhere
    # arbitrary, and is NOT marked as a long press, so the release still
    # takes the picture the user was asking for.
    if face_detect_enabled or object_track_enabled:
        with _le_lock:
            le_busy = _le_active
        with _brenizer_lock:
            bren_busy = _brenizer_active
        if le_busy or bren_busy:
            return
        if _face_tracked_rect() is None and not zoom_active:
            return
        if not _claim_hold(epoch, "zoom"):
            return
        # The face can still be dropped by the main loop between the check
        # above and this call, so the claim is settled on what the zoom
        # actually did — and a release that landed mid-action is performed
        # here rather than having decided for itself.
        if _settle_zoom_hold(epoch, bool(_face_zoom_into_face())):
            _perform_shutter_short_press(allow_shutter_set=True)
        return
    # Focus Point: 1 s hold zooms into the boxed region (any UI mode) — but not
    # while a capture mode owns the shutter. If LE / Brenizer is active, let the
    # press fall through so _on_released can start/stop/save the stack instead
    # of this hold consuming it (don't set _hold_fired).
    if focus_point_enabled:
        with _le_lock:
            le_busy = _le_active
        with _brenizer_lock:
            bren_busy = _brenizer_active
        if le_busy or bren_busy:
            return
        if not _claim_hold(epoch, "zoom"):
            return
        _focus_point_zoom_into_box()
        if _settle_zoom_hold(epoch, True):
            _perform_shutter_short_press(allow_shutter_set=True)
        return
    if not _ui_viewfinder_mode:
        return
    if not _claim_hold(epoch, "zoom"):
        return
    zoom_active = True
    zoom_center_norm = (0.5, 0.5)
    _zoom_level_idx = 0  # ZOOM_LEVELS[0] == 2.0
    _record_activity(wake=True)
    if _settle_zoom_hold(epoch, True):
        _perform_shutter_short_press(allow_shutter_set=True)


def _focus_point_zoom_into_box():
    """Focus Point hold-to-zoom: toggle a 2× zoom centred on the focus box.

    A first 1 s hold zooms 2× into the boxed region; a second hold zooms back
    out. (A short shutter press still captures and exits zoom, like elsewhere.)
    """
    global zoom_active, zoom_center_norm, _zoom_level_idx
    if zoom_active:
        zoom_active = False
        _zoom_level_idx = 0
    else:
        zoom_active = True
        _zoom_level_idx = 0  # ZOOM_LEVELS[0] == 2.0
        zoom_center_norm = _focus_point_norm
    _record_activity(wake=True)


def _set_self_timer_idx(idx):
    """Select a self-timer option (called from the shutter popup's Timer
    chips) and persist the choice."""
    global _self_timer_idx
    _self_timer_idx = max(0, min(int(idx), len(SELF_TIMER_OPTIONS) - 1))
    print(f"[Timer] Self-timer {SELF_TIMER_OPTIONS[_self_timer_idx]['label']}")
    _debounced_save_settings()


def _set_antibanding_option(idx):
    """Select an anti-banding option (called from the shutter popup's
    Anti-band chips), persist it, and re-apply the exposure controls so the
    flicker-safe quantization (or its removal) lands immediately."""
    global _antibanding_idx
    _antibanding_idx = max(0, min(int(idx), len(ANTIBANDING_OPTIONS) - 1))
    print(f"[AB] Anti-banding {ANTIBANDING_OPTIONS[_antibanding_idx]['label']}")
    _debounced_save_settings()
    _apply_shutter_controls()


def _self_timer_arm(action):
    """Arm the self-timer countdown for `action` ("still" | "le").  Returns
    True when armed — the caller defers the capture to the main loop, which
    polls the deadline and fires the shot.  Returns False when the timer is
    off so the caller captures immediately.  Brenizer tile captures bypass
    the timer: the sequence rhythm matters more than press shake there and
    tile alignment absorbs small jitters."""
    global _self_timer_deadline, _self_timer_action
    secs = SELF_TIMER_OPTIONS[_self_timer_idx]["seconds"]
    if secs <= 0 or _brenizer_active:
        return False
    with _self_timer_lock:
        _self_timer_deadline = time.monotonic() + secs
        _self_timer_action = action
    print(f"[Timer] Countdown armed: {secs}s ({action})")
    return True


def _self_timer_cancel():
    """Abort a pending self-timer countdown. Returns True if one was armed."""
    global _self_timer_deadline, _self_timer_action
    with _self_timer_lock:
        if _self_timer_deadline is None:
            return False
        _self_timer_deadline = None
        _self_timer_action = None
    print("[Timer] Countdown canceled")
    return True


# --- Shutter hold-progress indicator (display-only) ---
# Maps a physical-button hold's elapsed time + current UI mode into what the
# main-loop ring/label should show. Pure (no globals touched, no I/O) so it
# can be unit-checked headless; the real hold/timer firing logic lives
# entirely in _on_pressed / _on_held / _on_released / _viewfinder_zoom_hold_fire
# above and is untouched by this — the indicator only ever reads outcomes,
# never causes them.
_HOLD_INDICATOR_REVEAL_S = 0.35  # ignore quick taps — only show once a hold is real
# Mirrors Button(26, hold_time=2.0) below: the same 2 s threshold drives both
# shutter-set mode (normal stills) and the video-mode exit request.
_SHUTTER_SET_HOLD_S = 2.0


def _hold_progress_state(elapsed, mode_flags):
    """Return (fraction, label, active) for the shutter hold-progress ring.

    `elapsed` is seconds since the button went down (None/negative -> not
    active). `mode_flags` is a dict of booleans describing the mode that
    determines which threshold applies:
      - "capturing_exclusive": Long-Exposure or Brenizer mode is entered
        (armed or capturing) — holding the shutter does nothing there in
        either state (press/release drives start/stop instead), so there is
        no threshold to preview.
      - "video_mode": video mode is active. The caller is expected to have
        already excluded active recording (see the render call site) —
        this only fires for standby, where a 2 s hold requests exit.
      - "zoom_hold": Focus Point, Face Detect or the Viewfinder UI is
        active, so the short hold gesture (zoom) applies instead of
        shutter-set/minimal.
      - "zoom_hold_s": that gesture's threshold in seconds (0.5 s in the
        Viewfinder/slider UI, else 1 s — `_zoom_hold_threshold_s()`).

    `fraction` is 0..1 progress toward the next not-yet-passed threshold;
    `label` is the short name of what firing it does; `active` is False
    before the reveal delay, in capturing-exclusive modes, or once no
    further threshold remains.
    """
    if elapsed is None or elapsed < _HOLD_INDICATOR_REVEAL_S:
        return 0.0, "", False
    if mode_flags.get("capturing_exclusive"):
        return 0.0, "", False
    if mode_flags.get("video_mode"):
        return min(1.0, elapsed / _SHUTTER_SET_HOLD_S), "Exit", True
    if mode_flags.get("zoom_hold"):
        hold_s = mode_flags.get("zoom_hold_s") or _VIEWFINDER_ZOOM_HOLD_S
        return min(1.0, elapsed / hold_s), "Zoom", True
    # Normal stills: 2 s -> shutter-set ("Set"), then _MINIMAL_MODE_HOLD_EXTRA_S
    # more (7 s total) -> minimal mode ("Hide").
    if elapsed < _SHUTTER_SET_HOLD_S:
        return elapsed / _SHUTTER_SET_HOLD_S, "Set", True
    hide_frac = (elapsed - _SHUTTER_SET_HOLD_S) / _MINIMAL_MODE_HOLD_EXTRA_S
    return min(1.0, hide_frac), "Hide", True


_HOLD_INDICATOR_RADIUS = 20
_HOLD_INDICATOR_THICKNESS = 4


def _draw_hold_progress_indicator(canvas, fraction, label):
    """Draw the shutter hold-progress ring: a dim background track plus a
    filled arc that sweeps clockwise from 12 o'clock as `fraction` (0..1)
    approaches the next hold threshold, with a short label above it naming
    what firing that threshold will do. Bottom-edge anchored, centered in
    the gap between the histogram and the battery/warning stack so it never
    touches the composition area. Cheap: the caller only invokes this while
    a hold is actually in progress (see the main-loop call site)."""
    cx = SCREEN_W // 2
    cy = SCREEN_H - BAR_H // 2
    r = _HOLD_INDICATOR_RADIUS
    cv2.circle(canvas, (cx, cy), r, UI_TEXT_DIM, _HOLD_INDICATOR_THICKNESS, cv2.LINE_AA)
    frac = max(0.0, min(1.0, fraction))
    if frac > 0.0:
        end_angle = -90.0 + 360.0 * frac
        cv2.ellipse(canvas, (cx, cy), (r, r), 0, -90.0, end_angle,
                    UI_ACCENT_EXPOSURE, _HOLD_INDICATOR_THICKNESS, cv2.LINE_AA)
    if label:
        label_block = make_rotated_text_block(
            [[{"text": label, "color": UI_TEXT_PRIMARY}]],
            font_scale=0.9, thickness=1, rotate_180=True, max_h=24,
            pad_x=6, pad_y=2,
        )
        lx = cx - label_block.shape[1] // 2
        ly = cy - r - _HOLD_INDICATOR_THICKNESS - label_block.shape[0]
        blit_text_with_plate(canvas, label_block, lx, ly)


def _on_pressed():
    """Hardware shutter button press — kick off the zoom-hold timer (0.5 s in
    the Viewfinder/slider UI, else 1 s) for the
    sub-2 s hold gestures (Focus Point zoom-into-box, Viewfinder center zoom).
    The standard 2-second `when_held` callback keeps driving shutter-set and
    minimal-mode toggles in other UIs.
    """
    global _viewfinder_zoom_hold_timer, _press_epoch, _hold_fired, _shutter_press_start
    # Display-only bookkeeping for the hold-progress ring (see
    # _hold_progress_state) — set unconditionally, before the sleep/charge
    # early-returns below, since it never drives any real behavior.
    _shutter_press_start = time.monotonic()
    # Advance the press epoch first (unconditionally) so any hold/timer
    # callback still in flight from a previous, already-released press can
    # never mark THIS press as consumed (see the _hold_fired_lock comment).
    # Also clear _hold_fired here: a stale hold callback can fire in the gap
    # between the previous release and this press and set the flag under the
    # (then-current) old epoch — if we didn't reset it, this press's release
    # would read that leftover True and silently drop a valid shutter tap.
    with _hold_fired_lock:
        _press_epoch += 1
        epoch = _press_epoch
        _hold_fired = False
    if _viewfinder_zoom_hold_timer is not None:
        _viewfinder_zoom_hold_timer.cancel()
        _viewfinder_zoom_hold_timer = None
    if sleep_mode_active or charge_mode_active:
        if sleep_mode_active:
            # This press's pair (release or 2 s hold) is the wake trigger.
            # Latch it as wake-only NOW: if the hold wakes the camera while
            # the button is still down, the eventual release would otherwise
            # arrive with sleep_mode_active already False and fall through
            # to a stray capture of whatever the lens is facing.
            _wake_swallow_pins.add("b26")
        return
    # First input from the dim-idle low-power state only wakes — it must not
    # capture/zoom/toggle. Latch it so the paired release (a separate callback)
    # is swallowed too; clear the latch on a normal (awake) press so a stale
    # mis-paired latch can never suppress a real shot. Wake and return before
    # arming the zoom-hold timer, and don't show the hold-progress ring.
    if _backlight_dimmed:
        _wake_swallow_pins.add("b26")
        _shutter_press_start = None
        _record_activity(wake=True)
        return
    _wake_swallow_pins.discard("b26")
    # Start the zoom-hold timer (0.5 s in the Viewfinder/slider UI, else 1 s)
    # when a sub-2 s hold gesture is available:
    #  - Focus Point: zoom 2× into the boxed region (any UI mode)
    #  - Face Detect: zoom onto the tracked face (any UI mode)
    #  - Object Track: zoom onto the tapped subject (any UI mode)
    #  - Viewfinder UI: 2× center zoom
    if not (focus_point_enabled or face_detect_enabled or object_track_enabled
            or _ui_viewfinder_mode):
        return
    _viewfinder_zoom_hold_timer = threading.Timer(
        _zoom_hold_threshold_s(), _viewfinder_zoom_hold_fire, args=(epoch,),
    )
    _viewfinder_zoom_hold_timer.daemon = True
    _viewfinder_zoom_hold_timer.start()


def _cancel_viewfinder_zoom_hold_timer():
    global _viewfinder_zoom_hold_timer
    if _viewfinder_zoom_hold_timer is not None:
        _viewfinder_zoom_hold_timer.cancel()
        _viewfinder_zoom_hold_timer = None


def _on_held():
    global _video_exit_requested
    epoch = _press_epoch
    if sleep_mode_active:
        # Waking via a hold: the button is still down when the camera comes
        # back, so the release lands with sleep_mode_active False — latch it
        # as wake-only so it can't fall through to a capture.
        _wake_swallow_pins.add("b26")
        _sleep_wake_event.set()
        return
    # A hold that began as the dim-wake press is consumed (no shutter-set /
    # minimal / zoom); the release clears the latch.
    if "b26" in _wake_swallow_pins:
        return
    if charge_mode_active:
        return
    # In video mode, long-press exits video mode entirely.  Only REQUEST the
    # exit here (this callback runs on the gpiozero hold thread) — the actual
    # stop()/configure()/start() reconfigure must happen on the main preview
    # loop thread, which may be blocked inside picam2.capture_request() and
    # can hang libcamera if a cross-thread stop() lands on it.  The main loop
    # polls _video_exit_requested and runs the exit itself.
    with _video_lock:
        _in_video = _video_mode_active
    if _in_video:
        _mark_hold_fired(epoch)
        _video_exit_requested = True
        return
    # Long-exposure / Brenizer: a 2 s hold must not toggle shutter-set mode
    # mid-stack — the swipe touch handler above has the identical guard
    # ("would jump the exposure mid-stack or call _enter_sleep_mode()").
    # Return WITHOUT marking hold_fired: the intent (see
    # _viewfinder_zoom_hold_fire's LE/Brenizer guard) is that release should
    # still be free to stop/save the LE stack, so a >=2s squeeze during LE
    # must not be consumed here.
    with _le_lock:
        _le_busy = _le_active
    with _brenizer_lock:
        _bren_busy = _brenizer_active
    if _le_busy or _bren_busy:
        return
    # Claiming the press IS the swallow rule.  Losing the claim means the
    # 1 s zoom-hold already owns this press (Focus Point's box, Face
    # Detect's face, or the Viewfinder UI's centre zoom), so the 2 s hold
    # must not also toggle back out or fall through to shutter-set; winning
    # it means no zoom happened and the ordinary behaviour is correct.
    #
    # ONE claim rather than a condition per mode.  This was two separate
    # returns — a zoom-hold gate for Focus Point / Face Detect
    # and an UNCONDITIONAL `if _ui_viewfinder_mode: return` beneath it — and
    # Face Detect in the Viewfinder UI with no face fell through the first
    # into the second, marking the press and swallowing it with no zoom, no
    # capture and no shutter-set.  Merging those two into one predicate then
    # left a THIRD hole, because the predicate assumed the 1 s timer had
    # already run: a `threading.Timer` delayed past this callback let the
    # hold take the fallback path and the late timer zoom as well, which is
    # the hybrid the unconditional branch had been preventing.  Both are
    # gone once the press is claimed instead of inferred — whichever handler
    # arrives first owns it, with no ordering assumption (PR #270).
    if not _claim_hold(epoch, "held"):
        return
    _toggle_shutter_set_mode()
    # Start timer for 7-second total hold to toggle minimal UI mode
    _arm_minimal_mode_timer()

def _perform_shutter_short_press(allow_shutter_set=True):
    """Run the short-press shutter logic shared by the body button and the
    grip-mode shutter.  Routes through video / long-exposure / Brenizer modes
    exactly like a normal shutter tap.  `allow_shutter_set=False` (grip mode)
    forces a capture instead of cycling the legacy shutter-set value, since the
    grip has its own modifier scheme.
    """
    global zoom_active, _zoom_level_idx
    # Self-timer: a short press while the countdown is armed aborts it
    # (press to arm, press again to cancel).
    if _self_timer_cancel():
        return
    # Short press — in video mode, toggle recording on/off
    with _video_lock:
        in_video = _video_mode_active
        is_recording = _video_recording
    if in_video:
        _record_activity(wake=True)
        if is_recording:
            _stop_video_recording()
        else:
            _start_video_recording()
        return
    # Short press — flash sync owns the shutter while the mode is selected:
    # it ARMS and DISARMS, it does not take a picture.  The moment of exposure
    # belongs to the flash, not the button.  Checked before long exposure for
    # the same reason LE is checked before the normal still path — the modes
    # are mutually exclusive and mode entry disables the others.
    with _flash_lock:
        _flash_press_mode = _flash_mode_active
    if _flash_press_mode:
        _record_activity(wake=True)
        _flash_request_toggle()
        return

    # Short press — long-exposure mode takes precedence (it owns the
    # shutter while armed: first press starts stacking, second press stops).
    with _le_lock:
        _le_press_active = _le_active
        _le_press_state = _le_state
    if _le_press_active:
        if _le_press_state == "idle":
            _record_activity(wake=True)
            if _self_timer_arm("le"):
                return
            _le_start_capture()
            return
        if _le_press_state == "capturing":
            _record_activity(wake=True)
            # Stop + save runs on this thread because it has to read the
            # current aspect/film selections under their existing locks
            # (the processor loop should not touch those globals).
            with _aspect_button_lock:
                capture_aspect_idx = _aspect_idx
            target_ratio = ASPECT_OPTIONS[capture_aspect_idx]["ratio"]
            target_dims = _aspect_capture_dims[capture_aspect_idx]
            with _film_button_lock:
                capture_film_key = FILM_OPTIONS[_film_idx]["key"]
            _le_stop_capture(
                target_dims=target_dims,
                target_ratio=target_ratio,
                film_key=capture_film_key,
            )
            return
        # "finishing" — already saving; ignore.
        return

    # Short press — normal still mode
    if allow_shutter_set and shutter_set_mode:
        _cycle_shutter()
    else:
        # Block shutter during Brenizer completion screen
        with _brenizer_lock:
            if _brenizer_active and _brenizer_state == "complete":
                return
        # Block re-trigger while the 47 MP capture worker is still
        # running — picam2 cannot service a second capture before the
        # mode-switch round-trip completes.
        if _high_res_capture_busy.is_set():
            return
        # The shutter always returns to the full view before firing: the
        # focus zoom is an aid for judging sharpness, never a crop, and the
        # capture is full-frame regardless — so leaving the preview
        # magnified would show a framing the file does not have.  Face
        # Detect's tracking zoom is dropped here through the same two
        # assignments, plus its follow flag.
        zoom_active = False
        _zoom_level_idx = 0
        _face_zoom_clear()
        _record_activity(wake=True)
        if _self_timer_arm("still"):
            return
        _start_capture_sequence()
        shoot_event.set()


def _on_released():
    global _hold_fired, _shutter_press_start, _zoom_hold_release_pending
    global _hold_claim_epoch, _hold_claim_owner
    # Display-only: end the hold-progress ring regardless of what else this
    # release does below.
    _shutter_press_start = None
    # Cancel minimal mode timer if button released before 7 seconds
    _cancel_minimal_mode_timer()
    # Cancel Viewfinder 1-second zoom-hold timer if released before it fires
    _cancel_viewfinder_zoom_hold_timer()
    if sleep_mode_active:
        _sleep_wake_event.set()
        return
    if charge_mode_active:
        return
    # Release of the sleep/dim-wake press: consume it (no capture), clear this
    # pin's latch so its next press behaves normally.
    if "b26" in _wake_swallow_pins:
        _wake_swallow_pins.discard("b26")
        _record_activity(wake=True)
        return
    # Read-and-clear under the same lock the writers use — see the
    # _hold_fired_lock comment above _hold_fired's declaration.  While a
    # zoom-hold ACTION is in flight the decision is deferred to
    # `_settle_zoom_hold` instead: `_hold_fired` is set for the duration of
    # that call, so deciding here would read a zoom that may still decline
    # as a completed long press and swallow the release, which no later
    # rollback can undo (PR #270).
    with _hold_fired_lock:
        if _zoom_hold_inflight_epoch == _press_epoch:
            _zoom_hold_release_pending = True
            return
        _fired = _hold_fired
        _hold_fired = False
        if not _fired:
            # The release WINS this press, so it claims it like any other
            # handler.  Cancelling the 1 s timer above cannot stop a callback
            # that has already begun, and `_press_epoch` only advances on the
            # next press — so without this the timer would resume, find the
            # press unclaimed, and zoom AFTER the capture (reviewed on
            # PR #270).  The release was deciding the press without being a
            # claimant in the arbitration meant to order it.
            _hold_claim_epoch = _press_epoch
            _hold_claim_owner = "released"
    if _fired:
        return
    _perform_shutter_short_press(allow_shutter_set=True)


# -------------------- Grip-mode button handlers --------------------
def _grip_flash(msg):
    """Flash a short message in the centered OSD (reuses the shutter OSD)."""
    global _shutter_osd_text, _shutter_osd_fade_target, _shutter_osd_timer
    _shutter_osd_text = msg
    _shutter_osd_fade_target = 1.0
    _shutter_osd_timer = _GRIP_FLASH_HOLD_S


def _grip_enable():
    """Enable grip mode for the rest of the session (single grip-button press
    while grip mode is off).  Never persisted."""
    global _grip_mode_active, _grip_adjust_target, shutter_set_mode, _shutter_press_start
    if _grip_mode_active:
        return
    _grip_mode_active = True
    _grip_adjust_target = GRIP_ADJUST_NONE
    # Leaving legacy shutter-set mode on would strand the "SET" HUD suffix —
    # GPIO26 becomes the modifier in grip mode and can no longer turn it off.
    shutter_set_mode = False
    # Drop any legacy hold timers still pending from a body-button press so they
    # can't fire after the mode switch (grip mode owns the hold gestures now).
    # The minimal-mode timer is started by the GPIO26 2 s hold; in grip mode its
    # release routes to _grip_on_released and would otherwise never cancel it.
    _cancel_viewfinder_zoom_hold_timer()
    _cancel_minimal_mode_timer()
    # If this enable raced a body-button hold already in progress (BTN26 down
    # when BTN21 flips grip mode on), that press's release routes to
    # _grip_on_released from here on and would never clear the display-only
    # hold-progress start — clear it now so the ring can't get stuck on.
    _shutter_press_start = None
    _record_activity(wake=True)
    _grip_flash("GRIP ENABLED")
    print("[Grip] Grip mode enabled (session only)")


def _grip_button_state(btn):
    """(is_down, held_s) for a hardware button — hardware errors read as up,
    so callers degrade to the button's default behaviour instead of raising."""
    if btn is None:
        return False, 0.0
    try:
        if not btn.is_active:
            return False, 0.0
        return True, float(btn.active_time or 0.0)
    except Exception:
        return False, 0.0


def _grip_hold_progress_state():
    """Grip-mode source for the on-screen hold-progress ring: (fraction,
    label, active), derived straight from the two buttons' live hold times
    (display-only reads from the main loop — never drives any firing logic,
    mirroring _shutter_press_start's contract for the legacy ring).

    Same grammar as _hold_progress_state — the ring sweeps toward the next
    hold threshold and the label names what reaching it does:
      - chord (both buttons down): sweep of the modifier's hold toward the
        1 s qualify threshold -> "Adjust"; once stepping starts the value
        flashes on the OSD, so the ring retires.
      - GPIO26 alone: sweep to 1 s -> "Adjust", then the ring holds full
        with "Tap grip +" while it stays armed as the increase modifier.
      - GPIO21 alone: sweep to the 0.5 s zoom toggle -> "Zoom" (a decrease
        chord can still start any time while it is down).
    """
    b26_down, b26_t = _grip_button_state(button)
    b21_down, b21_t = _grip_button_state(button_gpio21)
    if b26_down and b21_down:
        mod_t = max(b26_t, b21_t)
        if mod_t < _HOLD_INDICATOR_REVEAL_S or mod_t >= _GRIP_MOD_HOLD_S:
            return 0.0, "", False
        return mod_t / _GRIP_MOD_HOLD_S, "Adjust", True
    if b26_down:
        if b26_t < _HOLD_INDICATOR_REVEAL_S:
            return 0.0, "", False
        if b26_t < _GRIP_MOD_HOLD_S:
            return b26_t / _GRIP_MOD_HOLD_S, "Adjust", True
        return 1.0, "Tap grip +", True
    if b21_down:
        if b21_t < _HOLD_INDICATOR_REVEAL_S or b21_t >= _GRIP_ZOOM_HOLD_S:
            return 0.0, "", False
        return b21_t / _GRIP_ZOOM_HOLD_S, "Zoom", True
    return 0.0, "", False


def _grip_cycle_target():
    """Cycle the grip adjustable setting: None -> Shutter -> ISO -> EV -> None."""
    global _grip_adjust_target
    _grip_adjust_target = (_grip_adjust_target + 1) % _GRIP_ADJUST_COUNT
    labels = ("ADJUST OFF", "ADJUST SHUTTER", "ADJUST ISO", "ADJUST EV")
    _grip_flash(labels[_grip_adjust_target])
    _record_activity(wake=True)
    print(f"[Grip] Adjust target -> {labels[_grip_adjust_target]}")


def _grip_adjust_value(direction):
    """Increase (+1) or decrease (-1) the currently selected grip setting and
    flash its new value.  Values wrap around at the ends of their option lists
    (e.g. fastest shutter +1 -> AUTO, AUTO -1 -> fastest)."""
    target = _grip_adjust_target
    if target == GRIP_ADJUST_SHUTTER:
        with _shutter_button_lock:
            cur = current_shutter_idx
        new_idx = _menu_step(_menu_indices("shutter", active=cur),
                             cur, direction)
        _set_shutter_option(new_idx)
        _grip_flash(SHUTTER_LABELS[new_idx])
    elif target == GRIP_ADJUST_ISO:
        with _iso_button_lock:
            cur = _iso_idx
        # Cycle within the offered list (the binned 47 MP mode withholds
        # ISOs whose boosted capture gain the sensor cannot deliver, and
        # the user's hidden chips are removed on top — both compose inside
        # _iso_available_indices).
        avail = _iso_available_indices()
        try:
            pos = avail.index(cur)
        except ValueError:
            pos = 0
        new_idx = avail[(pos + direction) % len(avail)]
        _set_iso_option(new_idx)
        _grip_flash("ISO " + _current_iso_label())
    elif target == GRIP_ADJUST_EV:
        with _exp_comp_lock:
            cur = _exp_comp_idx
        new_idx = _menu_step(_menu_indices("exp_comp", active=cur),
                             cur, direction)
        _set_exp_comp_option(new_idx)
        _grip_flash("EV " + _current_exp_comp_label())
    else:
        # Chord fired with no adjustable setting selected — tell the user why
        # nothing changed instead of silently eating the gesture, and halt the
        # fast-scroll repeat so the no-op doesn't keep re-firing while the
        # buttons stay held. Safe from here: both call sites run outside
        # _grip_repeat_lock (the repeat thread adjusts outside the lock by
        # design), and the epoch bump stops any in-flight fire from re-arming.
        _grip_flash("NO SETTING SELECTED")
        _grip_stop_repeat()
        _record_activity(wake=True)
        return
    _record_activity(wake=True)


def _grip_start_repeat(direction, first_delay=_GRIP_REPEAT_DELAY_S):
    """Arm hold-to-fast-scroll for ``direction`` after ``first_delay``.  On a
    qualified chord the first step has already fired on the press and the
    default delay just paces the auto-repeat; the deferred-chord path passes
    the time remaining until the modifier qualifies instead, so the first
    step lands the moment the chord becomes valid while both stay held."""
    global _grip_repeat_timer, _grip_repeat_direction, _grip_repeat_epoch, _grip_repeat_count
    with _grip_repeat_lock:
        if _grip_repeat_timer is not None:
            _grip_repeat_timer.cancel()
        _grip_repeat_epoch += 1
        epoch = _grip_repeat_epoch
        _grip_repeat_direction = direction
        _grip_repeat_count = 0
        _grip_repeat_timer = threading.Timer(
            max(0.05, first_delay), _grip_repeat_fire, args=(epoch,))
        _grip_repeat_timer.daemon = True
        _grip_repeat_timer.start()


def _grip_stop_repeat():
    """Cancel any active fast-scroll repeat (idempotent)."""
    global _grip_repeat_timer, _grip_repeat_direction, _grip_repeat_epoch
    with _grip_repeat_lock:
        _grip_repeat_epoch += 1          # invalidate any in-flight fire
        if _grip_repeat_timer is not None:
            _grip_repeat_timer.cancel()
            _grip_repeat_timer = None
        _grip_repeat_direction = 0


def _grip_repeat_fire(epoch):
    """Auto-repeat tick: step the value, then re-arm while both buttons remain
    held.  Stops the moment either button releases or grip mode ends."""
    global _grip_repeat_timer, _grip_repeat_count
    with _grip_repeat_lock:
        if epoch != _grip_repeat_epoch or not _grip_mode_active:
            return
        direction = _grip_repeat_direction
        try:
            both_held = (bool(button.is_active)
                         and button_gpio21 is not None
                         and bool(button_gpio21.is_active))
        except Exception:
            both_held = False
        if direction == 0 or not both_held:
            _grip_repeat_timer = None
            return
        _grip_repeat_count += 1
        count = _grip_repeat_count
    # Adjust outside the lock (it acquires the shutter/iso/ev locks).
    _grip_adjust_value(direction)
    interval = _GRIP_REPEAT_FAST_S if count >= _GRIP_REPEAT_ACCEL_AFTER else _GRIP_REPEAT_INTERVAL_S
    with _grip_repeat_lock:
        if epoch != _grip_repeat_epoch:
            return                       # stopped/superseded while adjusting
        _grip_repeat_timer = threading.Timer(
            interval, _grip_repeat_fire, args=(epoch,))
        _grip_repeat_timer.daemon = True
        _grip_repeat_timer.start()


def _grip_zoom_toggle():
    """Toggle a 2x center zoom (GPIO21 held 0.5 s in grip mode).

    In Face Detect the grip zoom goes to the face at the level that frames
    it, like every other zoom affordance in that mode — the accessory must
    not be the one control that ignores what the bracket is pointing at.
    """
    global zoom_active, zoom_center_norm, _zoom_level_idx
    if ((face_detect_enabled or object_track_enabled)
            and (zoom_active or _face_tracked_rect() is not None)):
        if _face_zoom_into_face():
            _grip_flash(("ZOOM %s %gX" % ("FACE" if face_detect_enabled
                                          else "SUBJECT",
                                          ZOOM_LEVELS[_zoom_level_idx]))
                        if zoom_active else "ZOOM OFF")
            return
    if zoom_active:
        zoom_active = False
        _zoom_level_idx = 0
    else:
        zoom_active = True
        _zoom_level_idx = 0  # ZOOM_LEVELS[0] == 2.0
        zoom_center_norm = (0.5, 0.5)
    _face_zoom_clear()
    _grip_flash("ZOOM 2X" if zoom_active else "ZOOM OFF")
    _record_activity(wake=True)


def _grip_on_pressed(is_grip):
    """Grip-mode press handler. is_grip=True -> GPIO21 (shutter); is_grip=False
    -> GPIO26 (modifier).  A press whose partner is already held >=1 s performs
    a value adjust instead of its default action."""
    global _grip_b21_consumed, _grip_b26_consumed, _grip_b26_press_t
    global _grip_b21_zoomed
    _pin = "b21" if is_grip else "b26"
    if sleep_mode_active or charge_mode_active:
        if sleep_mode_active:
            # Same wake-only latch as _on_pressed: the paired release wakes,
            # and a partner button still held across the wake must not act.
            _wake_swallow_pins.add(_pin)
        return
    # Dim-idle wake: consume this press (and its release) as wake-only.
    if _backlight_dimmed:
        _wake_swallow_pins.add(_pin)
        _record_activity(wake=True)
        return
    _wake_swallow_pins.discard(_pin)
    if is_grip:
        # GPIO21: increase when GPIO26 is held as a modifier, else a normal
        # press (capture on release, or 0.5 s hold -> zoom).
        _grip_b21_zoomed = False
        down, held_s = _grip_button_state(button)
        if down and held_s >= _GRIP_MOD_HOLD_S:
            _grip_b26_consumed = True   # GPIO26 was used as modifier -> no cycle
            _grip_b21_consumed = True   # this press is a trigger -> no capture
            _grip_adjust_value(+1)
            _grip_start_repeat(+1)      # hold both -> fast-scroll up
        elif down:
            # Chord landed before the modifier qualified. Falling through
            # here used to fire a capture on release — the "dual press does
            # nothing but take a photo" failure. Consume both presses and
            # defer the first step to the repeat timer, which fires the
            # moment the modifier hold crosses the threshold if both
            # buttons are still down (releasing either cancels it).
            _grip_b26_consumed = True
            _grip_b21_consumed = True
            _grip_start_repeat(+1, first_delay=_GRIP_MOD_HOLD_S - held_s)
        else:
            _grip_b21_consumed = False
    else:
        # GPIO26: decrease when GPIO21 is held as a modifier, else a tap that
        # cycles the adjustable setting (resolved on release).
        _grip_b26_press_t = time.monotonic()
        down, held_s = _grip_button_state(button_gpio21)
        if down:
            # GPIO21 is being used as the decrease modifier: its hold has
            # already crossed the 0.5 s zoom threshold, so take that back.
            _grip_undo_hold_zoom()
        if down and held_s >= _GRIP_MOD_HOLD_S:
            _grip_b21_consumed = True   # GPIO21 was used as modifier -> no capture/zoom
            _grip_b26_consumed = True   # this press is a trigger -> no cycle
            _grip_adjust_value(-1)
            _grip_start_repeat(-1)      # hold both -> fast-scroll down
        elif down:
            # Early chord, mirror of the GPIO21 branch above: consuming
            # GPIO21's press here also keeps its zoom hold from firing
            # mid-chord (_grip_on_held_grip checks _grip_b21_consumed).
            _grip_b21_consumed = True
            _grip_b26_consumed = True
            _grip_start_repeat(-1, first_delay=_GRIP_MOD_HOLD_S - held_s)
        else:
            _grip_b26_consumed = False


def _grip_on_released(is_grip):
    """Grip-mode release handler."""
    global _grip_b21_consumed, _grip_b26_consumed
    _grip_stop_repeat()                 # releasing either button halts fast-scroll
    _pin = "b21" if is_grip else "b26"
    if sleep_mode_active:
        _sleep_wake_event.set()
        return
    if charge_mode_active:
        return
    # Release of the sleep/dim-wake press: consume it, clear this pin's latch.
    if _pin in _wake_swallow_pins:
        _wake_swallow_pins.discard(_pin)
        _record_activity(wake=True)
        return
    if is_grip:
        # GPIO21 released: capture unless this press was already consumed by a
        # value trigger or the 0.5 s zoom hold.
        if _grip_b21_consumed:
            _grip_b21_consumed = False
            return
        _perform_shutter_short_press(allow_shutter_set=False)
    else:
        # GPIO26 released: cycle the adjustable setting only on a genuine quick
        # tap that wasn't consumed as a decrease modifier.
        consumed = _grip_b26_consumed
        _grip_b26_consumed = False
        if consumed:
            return
        if (time.monotonic() - _grip_b26_press_t) <= _GRIP_TAP_MAX_S:
            _grip_cycle_target()


def _grip_undo_hold_zoom():
    """Revert the zoom toggled by the CURRENT GPIO21 hold.

    The zoom fires at 0.5 s but the same hold qualifies as the decrease
    modifier only at 1 s, so a decrease chord always passes through the zoom
    first. When the partner press shows the hold was a chord, toggling back
    leaves the view as it was before the press. One-shot per press.
    """
    global _grip_b21_zoomed
    if not _grip_b21_zoomed:
        return
    _grip_b21_zoomed = False
    try:
        _grip_zoom_toggle()
    except Exception as exc:
        print(f"[Grip] zoom undo failed: {exc}")


def _grip_on_held_grip():
    """GPIO21 held 0.5 s in grip mode -> toggle zoom (unless the hold was used
    as a decrease modifier / value trigger)."""
    global _grip_b21_consumed, _grip_b21_zoomed
    if sleep_mode_active or charge_mode_active:
        return
    if "b21" in _wake_swallow_pins:      # sleep/dim-wake hold -> no zoom
        return
    if _grip_b21_consumed:
        return
    _grip_b21_consumed = True   # zoom fired -> release must not capture
    _grip_b21_zoomed = True     # a later chord press on this hold undoes it
    _grip_zoom_toggle()


# -------------------- Button wiring (grip-aware dispatch) --------------------
# Each pin gets a thin dispatcher: in grip mode the two pins diverge (GPIO21 =
# shutter, GPIO26 = modifier); otherwise GPIO26 keeps its full legacy behaviour
# and GPIO21's single press enables grip mode.
def _btn26_pressed():
    if _grip_mode_active:
        _grip_on_pressed(is_grip=False)
    else:
        _on_pressed()


def _btn26_held():
    # In grip mode the body button has no hold gesture (all legacy hold logic
    # is suppressed); otherwise it drives shutter-set / minimal mode as before.
    if _grip_mode_active:
        return
    _on_held()


def _btn26_released():
    if _grip_mode_active:
        _grip_on_released(is_grip=False)
    else:
        _on_released()


def _btn21_pressed():
    if _grip_mode_active:
        _grip_on_pressed(is_grip=True)
        return
    # Grip mode off: GPIO21 does nothing on press — it enables grip mode on the
    # release (single press), with no capture or hold gestures of its own.
    # But a press that begins during sleep must still latch wake-only: if the
    # camera is woken by the OTHER button (or a hold) before this one
    # lifts, the release below would otherwise land awake and stray-enable
    # grip mode. An awake press clears its own stale latch (a sleep-time
    # press whose release also landed during sleep exits via the release's
    # sleep branch without consuming it) — same hygiene as _on_pressed /
    # _grip_on_pressed, without which the NEXT awake press's release would
    # be swallowed and grip enable would need two presses.
    if sleep_mode_active:
        _wake_swallow_pins.add("b21")
    else:
        _wake_swallow_pins.discard("b21")


def _btn21_held():
    if _grip_mode_active:
        _grip_on_held_grip()
    # Grip mode off: GPIO21 hold has no function (it is the grip-enable button).


def _btn21_released():
    if _grip_mode_active:
        _grip_on_released(is_grip=True)
        return
    # Grip mode off: a single grip-button press enables grip mode.
    if sleep_mode_active:
        _sleep_wake_event.set()
        return
    if charge_mode_active:
        return
    # Release of a press that began during sleep: wake-only, no grip enable.
    if "b21" in _wake_swallow_pins:
        _wake_swallow_pins.discard("b21")
        _record_activity(wake=True)
        return
    # Dim-idle wake: this press only wakes; don't enable grip mode.
    if _backlight_dimmed:
        _record_activity(wake=True)
        return
    _grip_enable()


button.when_pressed = _btn26_pressed
button.when_held = _btn26_held
button.when_released = _btn26_released

if button_gpio21 is not None:
    button_gpio21.when_pressed = _btn21_pressed
    button_gpio21.when_held = _btn21_held
    button_gpio21.when_released = _btn21_released

# -------------------- Display window --------------------
# Window already created at top of file for early splash screen;
# just wire up the touch callback now that _on_touch is defined.
_display_set_mouse_callback("Camera", _on_touch)

# ---- Graceful shutdown: flush settings + stop camera on SIGTERM/SIGINT ----
_shutdown_flag = threading.Event()


def _graceful_shutdown(signum, frame):
    """Handle SIGTERM/SIGINT: flush pending settings and signal main loop to exit."""
    print(f"[Shutdown] Signal {signum} received, shutting down gracefully...")
    _shutdown_flag.set()
    try:
        _download_server_stop()
    except Exception:
        pass
    try:
        _restore_hardware_state()
    except Exception:
        pass


signal.signal(signal.SIGTERM, _graceful_shutdown)
signal.signal(signal.SIGINT, _graceful_shutdown)


def _flush_pending_settings():
    """Atexit handler: cancel debounce timer and write settings immediately."""
    with _settings_save_timer_lock:
        if _settings_save_timer is not None:
            _settings_save_timer.cancel()
    _save_persistent_settings()
    try:
        _download_server_stop()
    except Exception:
        pass


atexit.register(_flush_pending_settings)

# -------------------- Main loop --------------------
canvas = np.zeros((SCREEN_H, SCREEN_W, 3), dtype=np.uint8)
_black_canvas = np.zeros((SCREEN_H, SCREEN_W, 3), dtype=np.uint8)
# Pre-allocated buffer for flip operations (avoids per-frame allocation)
_flip_buffer = np.zeros((SCREEN_H, SCREEN_W, 3), dtype=np.uint8)
# Reused dst for the HQ-sensor (IMX477) 180° preview rotate so the per-frame
# rotate writes into a persistent buffer instead of allocating ~2 MB each
# frame. Lazily (re)allocated to match the lores frame shape (which can change
# across high-res restore / video mode). Unused for every other sensor.
_hq_rot_buf = None
# Capture confirmation: black-out "shutter flash" (Sony-style).
# The instant-capture paths present the blink explicitly (imshow + wall-clock
# sleep — see _shutter_blink) instead of counting displayed frames: the main
# loop presents at the SENSOR rate, so on the unbinned 47 MP read-out (a few
# fps) a 3-displayed-frames counter stretched the blink into 1 s+ of dead
# black screen after every shot. _black_flash_frames remains for the binned
# 47 MP mode-switch paths, whose blackout must span a multi-second round trip
# while the loop keeps iterating (and is cut short by _high_res_capture_done).
_BLACK_FLASH_S = 0.12  # wall-clock blink for instant captures
_black_flash_frames = 0
# Threaded binned 47 MP path: True from the shutter press until the main
# loop observes _high_res_capture_done (read-out complete).  Holds the
# "Image capturing / Hold still" canvas for the whole read-out — the
# counter above expires after 30 presented frames (~1.5 s), which a
# multi-frame control drain at the 47 MP read-out's few-fps rate can
# outlast — and lets _pace_frame wake on the Event instead of sleeping
# out its frame period, so the black lifts the instant the sensor is
# done rather than up to one UI period later.  Set only at the threaded
# dispatch, never by the synchronous paths or the other busy-flag users
# (video enter/exit, pipeline rebuilds), which never fire the Event.
_hires_blackout_active = False

# Pre-rendered status canvas shown in place of _black_canvas during the
# 47 MP capture blackout — gives the user explicit feedback that the
# camera is busy capturing (rather than the screen looking dead).
# Rotated 180° to match the rest of the UI (the screen is mounted
# such that canvas-as-drawn appears upside-down to the user).
_HIGH_RES_STATUS_FONT = 22
_HIGH_RES_STATUS_COLOR = (255, 255, 255)
_HIGH_RES_STATUS_OUTLINE = (0, 0, 0)
_HIGH_RES_STATUS_PAD = 16
# Secondary line under the status text (the "Hold still" instruction shown
# while a sensor-limited read-out is in flight): smaller and slightly
# dimmer so it reads as a subtitle, not a second heading.
_HIGH_RES_STATUS_SUB_FONT = 16
_HIGH_RES_STATUS_SUB_COLOR = (205, 205, 205)
_HIGH_RES_STATUS_SUB_GAP = 6


def _build_high_res_status_canvas(text, subtext=None):
    """Full-screen black canvas with `text` centered, rotated 180°.

    `subtext`, when given, is drawn as a smaller second line below it (the
    panel is rotated as a whole, so pre-rotation draw order is the order
    the user sees on the upside-down-mounted panel).
    """
    img = np.zeros((SCREEN_H, SCREEN_W, 3), dtype=np.uint8)
    tw, th = _ui_measure_text(text, _HIGH_RES_STATUS_FONT)
    if subtext:
        stw, sth = _ui_measure_text(subtext, _HIGH_RES_STATUS_SUB_FONT)
        total_h = th + _HIGH_RES_STATUS_SUB_GAP + sth
    else:
        stw = sth = 0
        total_h = th
    x = (SCREEN_W - tw) // 2
    y = (SCREEN_H - total_h) // 2
    _ui_draw_text(
        img, text, x, y,
        _HIGH_RES_STATUS_FONT,
        _HIGH_RES_STATUS_COLOR,
        outline_bgr=_HIGH_RES_STATUS_OUTLINE,
    )
    if subtext:
        _ui_draw_text(
            img, subtext,
            (SCREEN_W - stw) // 2, y + th + _HIGH_RES_STATUS_SUB_GAP,
            _HIGH_RES_STATUS_SUB_FONT,
            _HIGH_RES_STATUS_SUB_COLOR,
            outline_bgr=_HIGH_RES_STATUS_OUTLINE,
        )
    return cv2.rotate(img, cv2.ROTATE_180)


def _build_high_res_status_overlay(text, subtext=None):
    """Small text panel + paste rect for compositing onto the live canvas.

    Returns (panel, x, y) where panel is a rotated BGR image and (x, y)
    is the top-left position to paste it on the main canvas. `subtext`,
    when given, becomes a smaller second line below `text`.
    """
    tw, th = _ui_measure_text(text, _HIGH_RES_STATUS_FONT)
    if subtext:
        stw, sth = _ui_measure_text(subtext, _HIGH_RES_STATUS_SUB_FONT)
        text_h = th + _HIGH_RES_STATUS_SUB_GAP + sth
        text_w = max(tw, stw)
    else:
        stw = sth = 0
        text_h = th
        text_w = tw
    pw = text_w + _HIGH_RES_STATUS_PAD * 2
    ph = text_h + _HIGH_RES_STATUS_PAD * 2
    panel = np.zeros((ph, pw, 3), dtype=np.uint8)
    _ui_draw_text(
        panel, text, (pw - tw) // 2, _HIGH_RES_STATUS_PAD,
        _HIGH_RES_STATUS_FONT,
        _HIGH_RES_STATUS_COLOR,
        outline_bgr=_HIGH_RES_STATUS_OUTLINE,
    )
    if subtext:
        _ui_draw_text(
            panel, subtext,
            (pw - stw) // 2,
            _HIGH_RES_STATUS_PAD + th + _HIGH_RES_STATUS_SUB_GAP,
            _HIGH_RES_STATUS_SUB_FONT,
            _HIGH_RES_STATUS_SUB_COLOR,
            outline_bgr=_HIGH_RES_STATUS_OUTLINE,
        )
    panel = cv2.rotate(panel, cv2.ROTATE_180)
    x = (SCREEN_W - pw) // 2
    y = (SCREEN_H - ph) // 2
    return panel, x, y


_high_res_capturing_canvas = _build_high_res_status_canvas(
    "Image capturing", "Hold still")
(
    _high_res_processed_panel,
    _HIGH_RES_PROCESSED_X,
    _HIGH_RES_PROCESSED_Y,
) = _build_high_res_status_overlay("Image processed")
_HIGH_RES_PROCESSED_PH, _HIGH_RES_PROCESSED_PW = _high_res_processed_panel.shape[:2]

# Instant-capture wait cue: on sensor-limited pipelines (the unbinned 47 MP
# read-out at a few fps, or a drained slow manual shutter) the capture
# branch's next-request wait is user-visible — paste a small "Image
# capturing" panel over the held frame so the pause reads as intentional
# (and marks the hold-still window while the read-out is in flight) instead
# of a frozen viewfinder. Fast modes (~50 ms wait) skip the cue entirely.
# The "Hold still" subtitle names what that window is for: the read-out is
# the exact interval in which camera/subject motion smears the frame.
(
    _capture_wait_panel,
    _CAPTURE_WAIT_X,
    _CAPTURE_WAIT_Y,
) = _build_high_res_status_overlay("Image capturing", "Hold still")
_CAPTURE_WAIT_PH, _CAPTURE_WAIT_PW = _capture_wait_panel.shape[:2]
_CAPTURE_WAIT_HINT_US = 150000  # show the cue only when the wait is visible

# Lores plane of the request an instant capture just grabbed — or of the
# 47 MP restore's proof-of-life request (see _hires_restore_preview):
# consumed by the preview pull below in place of another blocking
# capture_request, so the loop never waits a second (possibly
# sensor-limited) frame period re-pulling a frame it already holds.
# _captured_preview_meta carries that same request's metadata for the
# cross-thread case (the 47 MP worker can't write the loop's _meta
# directly); the busy-flag branch order below sequences the worker's
# write before the loop's read.
_captured_preview_lores = None
_captured_preview_meta = None

# Measured blocking time of the last preview pull (µs). This is the ground
# truth for how long a capture's next-request wait will feel to the user —
# on the unbinned 47 MP read-out the paced loop arrives early and blocks
# most of the frame period here. The capture wait cue keys off it so the
# cue can never be defeated by a missing/odd FrameDuration metadata key.
_last_pull_wait_us = 0


def _shutter_blink():
    """Capture-confirmation blink for the instant-capture paths: hard cut
    to black for a fixed wall-clock beat, then restore the last presented
    canvas immediately — the viewfinder never sits black waiting out the
    next (possibly sensor-limited) sensor frame."""
    try:
        _display_show("Camera", _black_canvas)
        _display_pump(1)
        try:
            # The direct presents here bypass the display tail, whose
            # publish mirrors every presented frame to the LAN live view —
            # mirror both blink transitions explicitly (forced past the
            # publish throttle; no-op without an MJPEG subscriber).
            _preview_publish(_black_canvas, force=True)
        except Exception:
            pass
        time.sleep(_BLACK_FLASH_S)
        _dc = globals().get("display_canvas")
        if _dc is not None and _dc is not _black_canvas:
            _display_show("Camera", _dc)
            _display_pump(1)
            try:
                _preview_publish(_dc, force=True)
            except Exception:
                pass
    except Exception:
        pass


_meta = {}  # latest exposure metadata, refreshed each frame from the lores request

# --- Frame pacing + smoothing (production UX) ---
TARGET_FPS = 20
TARGET_FPS_IDLE = 10  # Lower FPS when backlight is dimmed to save power

# Auto-sleep: after the user-configured idle timeout (_sleep_timeout_s(),
# charge-menu sleep submenu; Off disables it), fall into the existing
# low-power sleep mode (camera/ISP stopped, radio off, CPU powersave).  Wakes
# on a shutter press via _sleep_wake_event.  The backlight dim
# (_low_power_timeout_s()) is the earlier, shallower idle step.
# How long the sleep loop blocks on the wake event before re-asserting
# fan/backlight off; a shutter press fires the event and wakes instantly.
_SLEEP_WAKE_POLL_TIMEOUT_S = 2.0
_FRAME_DT = 1.0 / TARGET_FPS
_FRAME_DT_IDLE = 1.0 / TARGET_FPS_IDLE
# Charge/stats screen: near-static content that can otherwise render at full
# TARGET_FPS for hours (even on battery for a manually opened session). 10 fps
# halves the render cost while a 100 ms waitKey cadence keeps taps responsive.
TARGET_FPS_CHARGE = 10
_FRAME_DT_CHARGE = 1.0 / TARGET_FPS_CHARGE
# While recording 4K, the software H.264 encoder contends for every core, so a
# 20 fps preview pacing slips erratically (visible stutter).  Dropping the live
# preview to a steadier 15 fps gives each frame more scheduling headroom — even
# pacing reads as smoother than a faster-but-jittery one, and it matches the
# "drop the rate, don't chase fps" power philosophy.  4K only; 1080p keeps 20.
TARGET_FPS_VIDEO_4K = 15
_FRAME_DT_VIDEO_4K = 1.0 / TARGET_FPS_VIDEO_4K
# Thermal load-shed UI pacing (see _thermal_shed_tick): matches the sensor
# readout tiers in _PREVIEW_FRAME_DUR_SHED1/2_US so display and pipeline shed
# together. 15 fps is barely distinguishable from 20 on the 4" panel; 12 fps
# still tracks motion for framing while cutting per-frame work by 40%.
TARGET_FPS_SHED1 = 15
TARGET_FPS_SHED2 = 12
_FRAME_DT_SHED1 = 1.0 / TARGET_FPS_SHED1
_FRAME_DT_SHED2 = 1.0 / TARGET_FPS_SHED2
# Throttle for re-asserting the reserved UI core while 4K-recording.
_video_affinity_last_apply = 0.0
_next_frame_t = time.monotonic()

EMA_ALPHA = 0.20  # 0.10-0.30 feels good; lower = smoother/slower response
_ema_shutter_us = None
_ema_iso = None
# Display-scale multiplier the smoothed AUTO ISO readout was last
# accumulated under — the main loop rescales _ema_iso when the active
# multiplier changes (video enter/exit in the binned 47 MP mode) so the
# old scale never bleeds through the EMA.
_iso_readout_mult = 1.0
# Deferred AE diagnostics after a 47 MP restore: the capture worker arms
# these and the main loop journals a metadata sample when each fires —
# the first post-restore frame ("AE just after restore") and one ~2 s
# later, showing where AE resumed after the re-seed and whether it then
# walks away from it (see the diagnostics comment in
# _perform_high_res_capture).  0.0 / False = disarmed.
_hires_ae_probe_at = 0.0
_hires_ae_log_first_frame = False

def _ema(prev, new, alpha=EMA_ALPHA):
    if new is None:
        return prev
    if prev is None:
        return float(new)
    return float(prev) * (1.0 - alpha) + float(new) * alpha

def _quantize_log_third_stop(value, base):
    """Snap a positive value to the nearest 1/3-stop (the photographic standard)
    multiple of `base`.  Used only for the AUTO-mode SS/ISO *readout*: the raw
    EMA jitters every frame, so formatting it directly changes the HUD label
    nearly every frame, which both looks unsettled and thrashes the text-block
    render cache (a full PIL re-render + resizes per frame).  Quantizing the
    displayed value makes the label change only when the exposure actually
    crosses a stop, leaving the cache effective."""
    if not value or value <= 0:
        return value
    stops = round(float(np.log2(value / base)) * 3.0) / 3.0
    return base * (2.0 ** stops)

def _pace_frame():
    """Cap UI refresh using monotonic scheduling. Drops to TARGET_FPS_IDLE when
    the backlight is dimmed (idle for 2+ min) and to TARGET_FPS_CHARGE on the
    charge/stats screen to reduce CPU load and save battery."""
    global _next_frame_t
    if _flash_armed:
        # Flash sync: the loop must consume EVERY sensor frame or the ring is
        # not contiguous and a split flash loses its complementary half
        # (see _flash_strict_run).  Sleeping to a UI target would drop
        # frames outright, so the blocking preview pull is the pacer instead —
        # it already runs at exactly the pinned frame duration.  Checked FIRST,
        # above the dimmed-idle tier: a dropped frame corrupts a capture while
        # a bright backlight only costs battery, so armed must win every
        # pacing tier (dim should never engage while armed anyway —
        # _flash_tick keeps the activity clock fresh — but pacing must not
        # depend on that).  The load-shed tiers are bypassed for the same
        # reason; every other shed (overlays, histogram, stream, focus
        # assist) still applies, and the mode disarms itself after
        # _flash_auto_disarm_s so a hot camera is never held in it
        # indefinitely.
        dt = 0.0
    elif _backlight_dimmed:
        dt = _FRAME_DT_IDLE
    elif charge_mode_active:
        dt = _FRAME_DT_CHARGE
    elif _video_recording and _video_is_4k():
        # 4K recording has its own steadier pacing; the encoder is the heat
        # source there and the load-shed tiers must not fight the recording.
        dt = _FRAME_DT_VIDEO_4K
    elif _heat_shed_level >= 2:
        dt = _FRAME_DT_SHED2
    elif _heat_shed_level == 1:
        dt = _FRAME_DT_SHED1
    else:
        dt = _FRAME_DT
    _next_frame_t += dt
    now = time.monotonic()
    sleep_t = _next_frame_t - now
    if sleep_t > 0:
        if _hires_blackout_active and not _high_res_capture_done.is_set():
            # 47 MP read-out in flight: the only thing this iteration is
            # waiting for is the worker's done Event, so wait on THAT for
            # the frame period instead of sleeping it out — the next
            # iteration then lifts the blackout immediately rather than
            # up to a whole UI period later.  The schedule is unchanged:
            # an early wake leaves _next_frame_t where it is, so the
            # following call sleeps the remainder and the cadence holds.
            _high_res_capture_done.wait(sleep_t)
        else:
            time.sleep(sleep_t)
    else:
        # We're behind; reset so we don't spiral.
        _next_frame_t = now
# Complete the boot bar just before the first live preview frame replaces it.
_sensor_startup_healthy()
_boot_phase("pipeline start")
_update_splash("Ready", 1.0)
_last_loop_t = time.monotonic()
# Record the preview/UI thread's TID so 4K recording can pin it to a reserved
# core (keeps the live view smooth against the software H.264 encoder).
try:
    _main_loop_tid = threading.get_native_id()
except Exception:
    _main_loop_tid = None
# Per-frame exception containment: one bad frame must never kill the firmware.
# A failed iteration is skipped (paced, rate-limited log); only a sustained run
# of nothing but consecutive failures falls through to the fatal exit path.
_MAIN_LOOP_MAX_CONSEC_FAILURES = 120   # several seconds of errors and no good frame
_MAIN_LOOP_ERR_PRINT_PERIOD_S = 5.0    # per-signature traceback rate limit
_main_loop_consec_failures = 0
_main_loop_err_last_print = {}         # (exc type, msg) -> last print monotonic ts
# Preview-pull failure containment: consecutive capture_request() errors on
# the still pipeline before the loop attempts a fallback pipeline restart
# (~2 s at the 0.05 s error cadence). Reset on every good frame.
_PREVIEW_ERR_RESTART_AFTER = 40
# Deadline for the main loop's per-frame camera waits (preview pull and the
# slow-shutter convergence drain). These were the last UNBOUNDED camera
# waits on the UI thread: a pipeline that stops delivering frames (control
# race, stuck read-out — field signature: idle a few minutes, then a capture
# freezes the app until the process dies) blocked the loop inside
# capture_request() forever, and the self-heal below could never run because
# the loop was stuck inside the very call it recovers from. 5 s is ~50x the
# slowest legitimate frame gap (100 ms at the 10 fps idle readout).
_PREVIEW_PULL_WAIT_S = 5.0
# A timed-out pull already proves seconds of pipeline silence, so it counts
# for more than a plain per-iteration error: two consecutive timeouts
# (~10 s) trigger the restart instead of 40 iterations' worth.
_PREVIEW_ERR_TIMEOUT_WEIGHT = 20
_preview_err_count = 0
# Self-heal backoff: a pipeline that comes back up dead every time (stopped
# after "fallback chain exhausted", or a libcamera fault whose
# capture_request() raises immediately) must not have the restart above
# retried every ~2 s forever. Left unbounded that spins the loop at the
# preview rate, prints a fresh journal line every pass, and re-runs a full
# stop/configure/start each cycle — while the OUTER consecutive-failure
# counter (_main_loop_consec_failures) never moves, because the whole thing
# is caught right here inside one iteration, so the fatal-exit path at the
# bottom of the loop (the one that hands the process to camera.service's
# Restart=on-failure for a fresh libcamera init) can never be reached.
# Escalate the wait between attempts instead, and after enough failures
# exit deliberately — a clean process restart is the one recovery an
# in-process retry loop cannot perform for itself.
_PREVIEW_HEAL_BACKOFF_S = (2.0, 5.0, 15.0)  # escalates, holds at last
_PREVIEW_HEAL_MAX_FAILURES = 4               # the 4th consecutive failure exits
_preview_heal_failures = 0
_preview_heal_next_attempt_t = 0.0


def _preview_heal_backoff_s(n):
    """Seconds to wait before self-heal attempt N (1-based count of
    consecutive failed heals so far, N<=0 -> no wait). Pure so it can be
    exercised without a camera HAL (AST-extracted, like flash_sync_diag.py
    does for the flash core). Escalates 2 -> 5 -> 15, then holds at 15 for
    any further attempt (the 4th consecutive failure exits before one is
    scheduled, see _PREVIEW_HEAL_MAX_FAILURES).
    """
    if n <= 0:
        return 0.0
    idx = min(int(n), len(_PREVIEW_HEAL_BACKOFF_S)) - 1
    return _PREVIEW_HEAL_BACKOFF_S[idx]


while not _shutdown_flag.is_set():
    _main_loop_iter_failed = False
    try:
        # First iteration only: apply the CPU thermal cap now rather than at
        # startup — everything before this point is boot-critical path that
        # benefits from the full firmware ceiling, and from here the user has
        # a live picture. Threaded so the sysfs writes never stall a frame;
        # placed ahead of the mode branches so it fires on a straight-to-
        # charge-mode boot too. The worker re-asserts until the read-back
        # verifies (a boot-time actor can briefly pin the policy floor at
        # the ceiling, which would otherwise defeat the cap).
        if _thermal_cap_pending:
            _thermal_cap_pending = False
            threading.Thread(target=_thermal_cap_converge_worker,
                             daemon=True).start()
        # One-off CMA / process-memory warm for the 47 MP capture path
        # (see _hires_warm_kick): a boolean test per iteration until a
        # binned 47 MP pipeline is live, then a background thread once.
        _hires_warm_kick()

        # A theme change made from the web UI invalidates every cached
        # glyph/icon raster. The HTTP thread only flags it; the clear
        # happens here so no cache is emptied underneath a half-composited
        # frame. One boolean test per iteration when nothing changed.
        if _theme_invalidate_pending:
            _theme_service_pending()

        # Same seam for the face detector: leaving Face Detect only raises a
        # flag, because only this thread may free a cv2 object it can be
        # inside detect() on.  One boolean test per iteration otherwise.
        if _face_release_pending:
            _face_service_release()

        # Update popup fade animations using the *measured* wall-clock delta so
        # fades/OSD run at real time regardless of the loop rate (the loop drops
        # to TARGET_FPS_IDLE when the backlight dims). Clamp to avoid a fade jump
        # after a blocking op (capture, mode switch).
        _loop_now = time.monotonic()
        _frame_dt = _loop_now - _last_loop_t
        _last_loop_t = _loop_now
        if _frame_dt < 1e-3:
            _frame_dt = 1e-3
        elif _frame_dt > 0.25:
            _frame_dt = 0.25
        _update_popup_fades(_frame_dt)

        # --- Thermal safety watchdog (runs in every mode, throttled to ~5 s) ---
        _thermal_watchdog_check()
        # Load-shed governor rides the watchdog's temp poll: sheds preview-side
        # work at 65/70 C so sustained shooting settles in the 60-65 C band,
        # restores full rate once cooled below 60 C (see _thermal_shed_tick).
        _thermal_shed_tick()

        # --- Low power sleep mode ---
        if sleep_mode_active:
            # Block until a shutter press wakes us (fires instantly) or a 2s
            # timeout elapses.  This replaces a 100ms poll loop: ~20x fewer CPU
            # wakeups in the deepest power-saving state, and wake-on-press is no
            # longer up to 100ms late.
            if _sleep_wake_event.wait(timeout=_SLEEP_WAKE_POLL_TIMEOUT_S):
                _sleep_wake_event.clear()
                # Drain touch events queued while asleep BEFORE leaving sleep
                # (waitKey is never pumped in this branch, so taps on the dark
                # panel accumulate): dispatched now they hit _on_touch's sleep
                # guard and are swallowed, instead of replaying as live taps
                # on the restored UI a frame later.
                try:
                    for _ in range(5):
                        _display_pump(1)
                except Exception:
                    pass
                _exit_sleep_mode()
                _record_activity(wake=True)
            else:
                # Timed out still asleep: re-assert fan/backlight off (the driver
                # may re-enable the fan when the SoC warms up).
                try:
                    _set_fan_state(0)
                    _set_backlight_brightness(0)
                    _sleep_state['last_fan_assert'] = time.monotonic()
                except Exception:
                    pass
            continue
        _update_backlight()
        # Deferred sleep entry from the touch handlers (swipe-up, charge-menu
        # Sleep Now): consumed here so _enter_sleep_mode's wake-hint waitKey
        # pump runs from the loop body — never re-entrantly from inside
        # _on_touch's own waitKey dispatch, which wedged the GUI event loop
        # and left the camera unwakeable on the frozen hint. Guarded like
        # auto-sleep below; a request that raced a mode change is dropped
        # rather than fired into an active capture.
        if _sleep_entry_requested:
            _sleep_entry_requested = False
            _sleep_block = _sleep_blocked_reason()
            if _sleep_block:
                print(f"[Sleep] request dropped — {_sleep_block}")
            else:
                _enter_sleep_mode()
                continue
        # Auto-sleep after a long idle, but never while ACTIVE work owns the
        # pipeline — a recording, an LE stack, a Brenizer sequence with tiles
        # already shot, charge mode or the 47 MP worker (see
        # _sleep_blocked_reason; those have their own branches/locks).  A mode
        # that is merely SELECTED and quiescent — video standby, the LE idle
        # panel, a Brenizer sequence with zero tiles — is as idle as plain
        # preview and DOES sleep: excluding it kept the camera awake
        # indefinitely on battery.  _enter_sleep_mode handles its own teardown.
        _auto_sleep_s = _sleep_timeout_s()
        if (
            _BACKLIGHT_AVAILABLE
            and _auto_sleep_s > 0
            and (time.monotonic() - _last_activity_time) >= _auto_sleep_s
            and not _sleep_blocked_reason()
        ):
            _enter_sleep_mode()
            continue
        _sleep_button_rect = (0, 0, 0, 0)
        if _update_prompt_ready.is_set():
            # Defer the prompt — WITHOUT consuming the pending flag — while
            # any active capture/mode owns the pipeline or the screen. The
            # prompt's own stop()/configure()/start() would otherwise race
            # (or just interrupt) whatever is in flight; it re-checks every
            # iteration once the busy state clears.
            with _le_lock:
                _upd_le_busy = _le_active and _le_state == "capturing"
            with _brenizer_lock:
                _upd_bren_busy = _brenizer_active
            with _video_lock:
                _upd_vid_rec = _video_recording
            _update_deferred = (
                charge_mode_active
                or _high_res_capture_busy.is_set()
                or _upd_le_busy
                or _upd_bren_busy
                or _upd_vid_rec
            )
            if not _update_deferred:
                with _pending_update_lock:
                    update_path = _pending_update_path
                    _pending_update_path = None
                    _update_prompt_ready.clear()

                if update_path:
                    # The pipeline isn't running in charge mode (it's
                    # stopped for the static stats screen) — only
                    # reconfigure/start afterward if it was actually running
                    # before the prompt, so this can't spin the camera back
                    # up under a charge-mode screen and burn battery.
                    _pipeline_was_running = not charge_mode_active

                    # Exit video mode cleanly before the update prompt takes over
                    if _video_mode_active:
                        _exit_video_mode()

                    if _pipeline_was_running:
                        try:
                            picam2.stop()
                        except Exception:
                            pass

                    _prompt_for_update(update_path)

                    if _pipeline_was_running:
                        try:
                            picam2.configure(still_config)
                            picam2.start()
                            picam2.set_controls({"FrameDurationLimits": _PREVIEW_FRAME_LIMITS})
                            _apply_shutter_controls()
                        except Exception as exc:
                            print("Preview restart error after update prompt:", exc)
                    _record_activity(wake=True)
                    continue

        if _update_sh_prompt_ready.is_set():
            # Mirrors the update.py prompt-deferral above: a bare update.sh
            # (no update.py) still must not interrupt an active capture/mode.
            with _le_lock:
                _upd_le_busy = _le_active and _le_state == "capturing"
            with _brenizer_lock:
                _upd_bren_busy = _brenizer_active
            with _video_lock:
                _upd_vid_rec = _video_recording
            _update_sh_deferred = (
                charge_mode_active
                or _high_res_capture_busy.is_set()
                or _upd_le_busy
                or _upd_bren_busy
                or _upd_vid_rec
            )
            if not _update_sh_deferred:
                with _pending_update_lock:
                    sh_path = _pending_update_sh_path
                    _pending_update_sh_path = None
                    _update_sh_prompt_ready.clear()

                if sh_path:
                    _pipeline_was_running = not charge_mode_active

                    if _video_mode_active:
                        _exit_video_mode()

                    if _pipeline_was_running:
                        try:
                            picam2.stop()
                        except Exception:
                            pass

                    sh_choice = _prompt_for_update_sh(sh_path)
                    if sh_choice is False:
                        # Remember the refusal for this boot session so a
                        # declined script (deliberately left in place) isn't
                        # re-queued and re-prompted.
                        _update_sh_declined = True

                    if _pipeline_was_running:
                        try:
                            picam2.configure(still_config)
                            picam2.start()
                            picam2.set_controls({"FrameDurationLimits": _PREVIEW_FRAME_LIMITS})
                            _apply_shutter_controls()
                        except Exception as exc:
                            print("Preview restart error after update.sh prompt:", exc)
                    _record_activity(wake=True)
                    continue

        # --- Auto charge mode: force while USB power + battery pack present ---
        # Plugging in (with a pack inserted) drops the camera into the low-power
        # charge screen; unplugging or removing the pack returns to live preview.
        # On USB power with no pack the camera stays usable. Only a force-entered
        # session auto-exits on unplug, so a manually opened charge screen is left
        # alone. The active-capture guard upholds the "never drop a capture"
        # invariant — forcing waits until any capture in flight finishes.
        _force_charge = _charge_should_force()
        if charge_mode_active:
            if _charge_auto_forced and not _force_charge:
                _exit_charge_mode()
                _charge_auto_forced = False
                continue
        elif _force_charge and not (
                _video_mode_active or _video_recording or _le_active
                or _brenizer_active or _high_res_capture_busy.is_set()):
            _enter_charge_mode()
            _charge_auto_forced = True
            continue

        # --- Shoot while charging: keep the fan on the pack + overheat park ---
        # The user tapped "Shoot" on the charge screen to keep using the camera
        # on AC. Hold the fan at full while charging, and if the SoC-temp proxy
        # (no pack sensor exists) stays high, auto-park back to the cooling
        # charge screen before the general 82/88 C thermal thresholds escalate.
        if _charge_shoot_override and not charge_mode_active:
            _cs_now = time.monotonic()
            if _read_pld_state(use_cache=True) == 1 and _charge_battery_present():
                # Temp-stepped fan (moderate baseline, steps up with SoC heat),
                # first force + throttled reassert.
                if not _charge_fan_forced or _cs_now - _charge_fan_last_assert >= 2.0:
                    _apply_charge_fan()
                _cs_temp = _thermal_temp
                if _cs_temp is not None and _cs_temp >= _CHARGE_SHOOT_OVERHEAT_C:
                    if _charge_shoot_hot_since is None:
                        _charge_shoot_hot_since = _cs_now
                    elif _cs_now - _charge_shoot_hot_since >= _CHARGE_SHOOT_OVERHEAT_HOLD_S:
                        _charge_shoot_override = False
                        _charge_overheat_parked = True
                        _charge_shoot_hot_since = None
                        _enter_charge_mode()
                        _charge_auto_forced = True
                        continue
                else:
                    _charge_shoot_hot_since = None
            else:
                # AC unplugged / pack pulled: end the override and hand the fan
                # back to the kernel governor. Normal battery use resumes; a
                # later re-plug parks to the charge screen again.
                _charge_shoot_override = False
                _charge_overheat_parked = False
                _charge_shoot_hot_since = None
                if _charge_fan_forced:
                    _restore_fan_state()
                    _charge_fan_forced = False
                    _charge_fan_level = 0

        if charge_mode_active:
            lines, pct, gauges = _update_charge_stats()
            _maybe_trigger_charge_shutdown(pct)
            # Re-enable the Shoot button once the pack/enclosure has cooled after
            # an overheat park (hysteresis vs the trip threshold).
            if (_charge_overheat_parked and _thermal_temp is not None
                    and _thermal_temp < _CHARGE_SHOOT_RESUME_C):
                _charge_overheat_parked = False
            ac_ok = _charge_stats_cache.get("ac_ok")
            # Run the fan only while the X1200 is actually charging — AC plugged
            # in AND a pack present. Moderate baseline that steps up with SoC
            # temperature (see _apply_charge_fan), reasserted every 2 s in case
            # the governor lowered it. On battery, or AC with no pack, release it
            # back to the governor. Gate on a LIVE (2 s-cached) PLD read, not the
            # 5 s-stale stats `ac_ok`, so it drops back to normal promptly on
            # unplug.
            if _read_pld_state(use_cache=True) == 1 and _charge_battery_present():
                if not _charge_fan_forced or time.monotonic() - _charge_fan_last_assert >= 2.0:
                    _apply_charge_fan()
            elif _charge_fan_forced:
                _restore_fan_state()
                _charge_fan_forced = False
                _charge_fan_level = 0
            canvas[:] = 0
            # Gesture walkthrough (info button): the charge screen is dense
            # with stats text, so dimming it under the card would leave an
            # illegible double exposure of text. Hide the charge UI entirely
            # while the card is visible and draw it over plain black instead
            # (taps still dismiss the card first — see _on_touch — and the
            # charge-shutdown logic above keeps running).
            if _gesture_help_active or _gesture_help_fade > 0.01:
                _render_overlay_with_fade(canvas, _render_gesture_help_overlay,
                                          _gesture_help_fade)
                if flip_mode == FLIP_MODE_MIRROR:
                    cv2.flip(canvas, 1, dst=_flip_buffer)
                    display_canvas = _flip_buffer
                elif flip_mode == FLIP_MODE_MIRROR_ROTATE:
                    cv2.flip(canvas, 0, dst=_flip_buffer)
                    display_canvas = _flip_buffer
                else:
                    display_canvas = canvas
                # This charge path continues before the main display tail —
                # mirror it to the live view here so a connected browser
                # doesn't freeze on the last live frame.
                try:
                    _preview_publish(display_canvas)
                except Exception:
                    pass
                _display_show("Camera", display_canvas)
                if _display_pump(1) == 27:
                    # Leave charge mode cleanly (restores CPU/backlight/fan)
                    # before the loop exits.
                    try:
                        _exit_charge_mode()
                    except Exception:
                        pass
                    break
                _pace_frame()
                continue
            if _sensor_dialog_request.is_set():
                _sensor_dialog_request.clear()
                _sensor_dialog()
            # Stats fill the full area above the brightness/battery row. The
            # battery icon now shares the raw-bottom strip with the brightness
            # panel (display top), so the stats can use everything above that
            # row without being blocked.
            stats_max_h = 300
            block = make_rotated_text_block(
                lines,
                font_scale=1.0,
                thickness=1,
                rotate_180=True,
                max_h=stats_max_h,
            )
            bh, bw = block.shape[:2]
            cx = max(0, (SCREEN_W - bw) // 2)
            cy = max(16, stats_max_h - bh + 16)
            blit_add(canvas, block, cx, cy)
            # Compact STORAGE fill + CPU-TEMP gauges next to the stats text —
            # the fraction/color tiers are already computed in
            # _collect_power_stats, this just makes them scannable at a glance
            # instead of requiring a read of the numbers.
            _draw_charge_gauge_bars(canvas, gauges, cx, cy, bw, bh)
            # Show the SOC whenever a pack is present — including while charging —
            # so the user can watch charge progress. Only hide the number when
            # there's genuinely no pack (USB-tethered, no cells), where the gauge
            # reads a phantom value.
            # On battery (not charging), surface the learned runtime estimate
            # right next to the percentage instead of only mid-list, so the
            # single most-asked question ("how much longer?") is answered at
            # a glance.
            _runtime_label = None
            if _charge_battery_present() and not ac_ok:
                _rt_s = _batt_runtime_estimate_s()
                if _rt_s is not None:
                    _runtime_label = f"~{_format_runtime(_rt_s)}"
            _draw_big_battery_icon(
                canvas, pct if _charge_battery_present() else None, bool(ac_ok),
                runtime_label=_runtime_label)
            # Controls in Charge mode. The charge icon is intentionally
            # omitted here — tapping anywhere outside the other controls
            # already exits charge mode, and drawing the charge icon here
            # would overlap the battery readout in the top-right corner.
            button_size = 72
            control_gap = 18
            column_right = SCREEN_W - 18
            column_top = 18  # match the normal-mode column so buttons don't shift between modes
            _charge_button_rect = (0, 0, 0, 0)

            sleep_rect = draw_sleep_button(canvas, _power_menu_visible, column_top, column_right, size=button_size, margin=16)
            _sleep_button_rect = sleep_rect if sleep_rect else (0, 0, 0, 0)
            if sleep_rect:
                column_top = sleep_rect[3] + control_gap

            trash_rect = draw_trash_button(canvas, column_top, column_right, size=button_size, margin=16)
            _trash_button_rect = trash_rect if trash_rect else (0, 0, 0, 0)
            if trash_rect:
                column_top = trash_rect[3] + control_gap

            exit_rect = draw_x_exit_button(canvas, column_top, column_right, size=button_size, margin=16)
            _exit_button_rect = exit_rect if exit_rect else (0, 0, 0, 0)
            if exit_rect:
                column_top = exit_rect[3] + control_gap

            info_rect = draw_info_button(canvas, column_top, column_right, size=button_size, margin=16)
            _info_button_rect = info_rect if info_rect else (0, 0, 0, 0)

            # "Shoot while charging" — left edge, only when a pack is actually
            # charging (AC + pack). Greyed/disabled while parked to cool.
            if ac_ok and _charge_battery_present():
                # Left column, below the battery icon (ends y72) and the gauge
                # bars (end y180) — top=18 previously overlapped the battery
                # charging animation at x[30,88].
                _charge_shoot_button_rect = draw_charge_shoot_button(
                    canvas, not _charge_overheat_parked, top=200,
                    size=button_size, margin=16)
            else:
                _charge_shoot_button_rect = (0, 0, 0, 0)

            # Back arrow — always-visible return to the shooting screen.
            # Fixed slot below the (conditional) Shoot button + its caption
            # so it never shifts as Shoot appears/disappears.
            _charge_back_button_rect = draw_charge_back_button(
                canvas, not _charge_overheat_parked, top=310,
                size=button_size, margin=16)

            _sensor_draw_button(canvas, _sensor_change_rect, "Change sensor")
            _sensor_draw_button(canvas, (170,330,390,376),
                                "47 MP: Later" if _deferred_enabled else "47 MP: Immediate")
            _draw_brightness_control(canvas)
            _draw_sensor_mode_button(canvas)

            # Sensor-mode dropdown overlays everything else when open.
            if _sensor_mode_popup_visible:
                _draw_sensor_mode_popup(canvas)

            # Sleep-button power submenu (mutually exclusive with the sensor
            # dropdown — opening one closes the other in _on_touch).
            if _power_menu_visible:
                _draw_power_menu_popup(canvas)

            # Draw delete confirmation overlay on top of everything if active
            if _delete_confirm_active:
                _draw_delete_confirm_overlay(canvas)

            # Quit (X button) confirmation overlay, same layer.
            if _quit_confirm_active:
                _draw_quit_confirm_overlay(canvas)

            # Over-temp banner sits above the charge UI (safety event).
            _render_thermal_warning(canvas)

            # Optimized: use pre-allocated buffer for flip operations
            if flip_mode == FLIP_MODE_MIRROR:
                cv2.flip(canvas, 1, dst=_flip_buffer)
                display_canvas = _flip_buffer
            elif flip_mode == FLIP_MODE_MIRROR_ROTATE:
                cv2.flip(canvas, 0, dst=_flip_buffer)
                display_canvas = _flip_buffer
            else:
                display_canvas = canvas
            # Charge mode continues before the main display tail — mirror the
            # stats screen to the live view so a connected browser doesn't
            # freeze on the last live frame when the camera is docked.
            try:
                _preview_publish(display_canvas)
            except Exception:
                pass
            _display_show("Camera", display_canvas)
            if _display_pump(1) == 27:
                # Leave charge mode cleanly (restores CPU/backlight/fan)
                # before the loop exits.
                try:
                    _exit_charge_mode()
                except Exception:
                    pass
                break
            _pace_frame()
            continue
        # --- Deferred video-mode exit (armed by _on_held() on the gpiozero
        #     hold thread) — stop()/configure()/start() must only run on this
        #     (main preview loop) thread; a cross-thread stop() landing while
        #     this loop is blocked in picam2.capture_request() can hang
        #     libcamera. Runs the same exit _on_held used to call directly.
        if _video_exit_requested:
            _video_exit_requested = False
            try:
                _exit_video_mode()
            except Exception as exc:
                print("[Video] Deferred exit error:", exc)
            _record_activity(wake=True)
            continue

        # --- Deferred live-pipeline rebuild (live-main fast-path engage/
        #     disengage on double-exposure / Brenizer transitions).  Runs only
        #     here on the main loop, through the same guarded stop/rebuild/
        #     start seam as a sensor-mode switch, and no-ops unless the
        #     desired main-stream size actually differs from the running
        #     config's — so the request is safe to fire from any transition
        #     on any sensor/mode combination.
        # A learned cartridge flip changes which Mono Raw twins exist, and
        # the dropdown was built once at boot from the persisted verdict.
        # Rebuilt here (main loop) rather than in _set_mono_sensor_active,
        # which runs on the save worker — SENSOR_MODE_OPTIONS is read by the
        # UI and indexed by _sensor_mode_idx, so it must not be swapped from
        # another thread.  Without this, the first boot after a mono->colour
        # swap offers no Mono Raw entry until the NEXT reboot.
        if _sensor_mode_options_rebuild_requested:
            _rebuild_sensor_mode_options()

        # --- Sensor-mode switch requested from the web Settings tab ---
        # The switch stops and restarts picam2, which only the main loop may
        # do (same rule as the pipeline rebuild below).  Serviced AFTER the
        # dropdown rebuild above, and by KEY rather than index, so a list that
        # changed shape under a parked request (a cartridge verdict flip adds
        # or removes the Mono Raw twins) can never resolve it to a different
        # mode.  The request is dropped after one attempt either way — a
        # failed switch already reverts and warns inside _set_sensor_mode_idx.
        if _settings_sensor_mode_request is not None:
            _sm_key = _settings_sensor_mode_request
            _settings_sensor_mode_request = None
            try:
                _sm_req = _settings_choice_index(
                    SENSOR_MODE_OPTIONS, lambda o: o.get("key"), _sm_key)
                if _sm_req is None:
                    print(f"[Settings] sensor-mode switch dropped — "
                          f"{_sm_key} is no longer offered")
                elif (not _video_mode_active and not charge_mode_active
                        and not sleep_mode_active
                        and not _high_res_capture_busy.is_set()):
                    _high_res_capture_busy.set()
                    try:
                        _set_sensor_mode_idx(_sm_req, restart_pipeline=True)
                    finally:
                        _high_res_capture_busy.clear()
                    try:
                        _apply_shutter_controls()
                    except Exception as _sm_exc:
                        print("[Settings] mode-switch control restore failed:",
                              _sm_exc)
                else:
                    print("[Settings] sensor-mode switch dropped — another "
                          "mode owns the pipeline")
            except Exception as exc:
                print("[Settings] sensor-mode switch error:", exc)

        if _still_pipeline_rebuild_requested:
            try:
                _desired_main = tuple(_live_still_main_size())
                _current_main = tuple(
                    ((still_config.get("main") or {}).get("size")) or ())
                with _le_lock:
                    _le_busy_now = _le_state != "idle"
                if _desired_main == _current_main:
                    # Nothing would change — the request is moot.
                    _still_pipeline_rebuild_requested = False
                elif (not _video_mode_active and not charge_mode_active
                        and not sleep_mode_active and not _le_busy_now
                        and not _high_res_capture_busy.is_set()):
                    # Eligible: consume the request and rebuild.  While an
                    # exclusive mode owns the pipeline the flag stays ARMED
                    # (neither branch taken) and is re-checked every frame,
                    # so e.g. a mono-verdict flip during video is honoured
                    # right after the video exit restores the still pipeline
                    # instead of being silently dropped.
                    _still_pipeline_rebuild_requested = False
                    print(f"[Camera] Rebuilding live pipeline: main "
                          f"{_current_main} -> {_desired_main}")
                    _high_res_capture_busy.set()
                    try:
                        try:
                            picam2.stop()
                        except Exception:
                            pass
                        _rebuild_camera_configs_for_active_sensor_mode()
                        _rebuild_ok = _start_still_pipeline_with_fallback()
                    finally:
                        _high_res_capture_busy.clear()
                    if _rebuild_ok:
                        try:
                            _apply_shutter_controls()
                        except Exception as _rb_exc:
                            print("[Camera] rebuild control restore failed:",
                                  _rb_exc)
                    else:
                        print("[Camera] live-pipeline rebuild failed — "
                              "fallback chain exhausted")
            except Exception as exc:
                # Never spin on a broken request — drop it with a log line.
                _still_pipeline_rebuild_requested = False
                print("[Camera] live-pipeline rebuild error:", exc)

        # --- Video mode: auto-stop on duration limit, low battery, or low disk ---
        with _video_lock:
            _vmode = _video_mode_active
            _vrec = _video_recording
        if _vmode and _vrec:
            # Re-assert the reserved UI core every ~2 s while 4K-recording:
            # libav can spawn encode worker threads lazily after recording
            # starts, and those would otherwise land on the core set aside for
            # the preview.  Cheap (a /proc/self/task walk) and throttled.
            if _video_is_4k():
                _now_aff = time.monotonic()
                if _now_aff - _video_affinity_last_apply >= 2.0:
                    _video_affinity_last_apply = _now_aff
                    _apply_video_cpu_affinity(True)
            if _video_elapsed_s() >= _VIDEO_MAX_DURATION_S:
                print("[Video] Maximum clip duration reached — auto-stopping")
                _stop_video_recording()
            elif not _disk_can_capture():
                print("[Video] Disk space critical — auto-stopping recording")
                _grip_flash("Storage full — recording stopped")
                _stop_video_recording()
            elif not _batt_can_record():
                with _batt_lock:
                    _vbatt = batt_percent_cached
                print(f"[Video] Battery critically low ({_vbatt}%) — auto-stopping recording")
                _grip_flash("Battery low — recording stopped")
                _stop_video_recording()

        # Flash sync: auto-disarm after the configured idle period.  One
        # monotonic compare while armed, an immediate return when not.
        _flash_tick()

        # Handle capture requests first (single-threaded Picamera2 usage)
        # Skip still capture when in video mode (recording controlled by shutter handler)
        if _vmode and shoot_event.is_set():
            shoot_event.clear()

        # --- Self-timer countdown: fire the deferred capture when the
        #     deadline passes.  The shutter OSD machinery shows the remaining
        #     whole seconds (its hold timer is refreshed every frame, so the
        #     number fades out by itself right after firing or canceling).  A
        #     stale deadline — armed just before a modal/charge branch owned
        #     the loop for a while — is dropped rather than fired late.
        with _self_timer_lock:
            _st_deadline = _self_timer_deadline
            _st_action = _self_timer_action
        if _st_deadline is not None:
            _st_remaining = _st_deadline - time.monotonic()
            if _st_remaining > 0:
                _shutter_osd_text = str(int(np.ceil(_st_remaining)))
                _shutter_osd_fade_target = 1.0
                _shutter_osd_timer = 0.2
            else:
                # Compare-and-clear under the lock so a cancel (GPIO thread)
                # that landed after the snapshot above wins over the fire.
                with _self_timer_lock:
                    _st_fire = _self_timer_deadline == _st_deadline
                    if _st_fire:
                        _self_timer_deadline = None
                        _self_timer_action = None
                if _st_fire:
                    # 2 s grace: a slow-shutter capture can block the loop
                    # for over a second, but anything older means a modal/
                    # charge branch owned the loop — firing then would
                    # surprise.
                    if _st_remaining < -2.0:
                        print("[Timer] Stale countdown dropped")
                    elif _st_action == "le":
                        with _le_lock:
                            _st_le_ok = _le_active and _le_state == "idle"
                        if _st_le_ok:
                            _record_activity(wake=True)
                            _le_start_capture()
                    elif (not _vmode and not shutter_set_mode
                            and not _high_res_capture_busy.is_set()):
                        # shutter_set_mode guard: the capture handler below
                        # skips shoot_event while set mode is on, so setting
                        # it here would latch a surprise capture for when set
                        # mode ends. The user re-purposed the button mid-
                        # countdown — drop the deferred shot instead.
                        _record_activity(wake=True)
                        _start_capture_sequence()
                        shoot_event.set()

        if shoot_event.is_set() and not shutter_set_mode:
            shoot_event.clear()

            # --- Disk space guard ---
            if not _disk_can_capture():
                print("[Capture] Blocked: disk space critical — clear internal memory to continue")
                _post_save_warning("Storage full — clear memory")
                # Per-press rejection cue: flash the HUD frame count in the
                # danger accent (the film-advance that didn't happen).
                _capture_blocked_flash_until = (
                    time.monotonic() + _CAPTURE_BLOCKED_FLASH_S)
                continue

            # --- Save-pipeline memory guard ---
            # Each in-flight job pins its full-res frame (plus, on the
            # instant path, the raw DNG payload) until the save worker
            # resolves it. At 47 MP that is ~240 MB per shot, and a burst
            # that outruns the JPEG/DNG writers OOM-kills the firmware —
            # a SIGKILL no exception guard can catch. Pace the shutter with
            # the same blocked-flash cue as a full disk instead.
            _job_bytes = _CAPTURE_FULL_W * _CAPTURE_FULL_H * 3
            # Every capture path defers its DNG now, so the job also pins the
            # raw payload — estimated at 2 bytes/px (a packed grant is less;
            # queue-time accounting uses the real nbytes either way).
            if _high_res_capture_config is None:
                _job_bytes += SENSOR_MODE_W * SENSOR_MODE_H * 2
            else:
                _job_bytes += _CAPTURE_FULL_W * _CAPTURE_FULL_H * 2
            # A double-exposure SECOND shot additionally pins the held first
            # frame as the job's overlay for its whole queue life — charge it
            # too, or two 47 MP double-exposure jobs could be admitted with
            # ~286 MB of untracked overlays on top of the budget.
            with _double_exposure_lock:
                if (double_exposure_enabled
                        and double_exposure_first_frame is not None):
                    _job_bytes += int(getattr(
                        double_exposure_first_frame, "nbytes", 0) or 0)
            if not _capture_mem_budget_ok(_job_bytes):
                print("[Capture] Blocked: save pipeline at memory budget — "
                      "waiting for pending saves")
                _post_save_warning("Saving — one moment")
                _capture_blocked_flash_until = (
                    time.monotonic() + _CAPTURE_BLOCKED_FLASH_S)
                continue

            # Determine if this is a Brenizer capture
            with _brenizer_lock:
                _bren_capturing = _brenizer_active and _brenizer_state == "awaiting_capture"
                _bren_tile_num = _brenizer_tile_idx + 1 if _bren_capturing else 0

            if _bren_capturing:
                # Brenizer mode: override paths to sequence directory
                _ensure_dir(_brenizer_seq_dir)
                bren_base = f"brenizer_{_brenizer_seq_id}_{_bren_tile_num:02d}"
                jpg_path = os.path.join(_brenizer_seq_dir, f"{bren_base}.jpg")
                dng_path = os.path.join(_brenizer_seq_dir, f"{bren_base}.dng")
            else:
                with _capture_dir_lock:
                    target_dir = _capture_dir
                _ensure_dir(target_dir)
                base_name = _next_capture_basename()
                jpg_path = os.path.join(target_dir, f"{base_name}.jpg")
                dng_path = os.path.join(target_dir, f"{base_name}.dng")

            with _aspect_button_lock:
                capture_aspect_idx = _aspect_idx
            target_ratio = ASPECT_OPTIONS[capture_aspect_idx]["ratio"]
            target_dims = _aspect_capture_dims[capture_aspect_idx]
            with _film_button_lock:
                capture_film_idx = _film_idx
                capture_film_key = FILM_OPTIONS[capture_film_idx]["key"]
            # Snapshot the human-readable settings summary now (not in the
            # save worker) so the EXIF tag reflects the moment of capture.
            capture_exif_desc = _capture_settings_exif_desc(capture_film_key)
            full_frame = None
            capture_error = None
            capture_request = None
            # Exposure-state snapshot for the 47 MP paths, taken as one
            # tight sequence at the press: the worker runs for seconds and
            # must plan from the selection the shutter was pressed under,
            # never from a later read of the live globals (see
            # _perform_high_res_capture's sel_gain/sel_stretch).
            _cap_slow_us = _slow_shutter_capture_us
            _cap_iso_gain = _current_iso_gain()
            _cap_iso_stretch = _iso_exposure_stretch(_cap_iso_gain)
            _cap_pan_mono = _mono_raw_active()

            # --- Burst SR: divert the press into the adaptive burst capture.
            # Runs synchronously on this thread against the RUNNING pipeline
            # (no mode switch — a per-frame mode switch could never sustain
            # a burst).  The merge runs off a bounded job queue
            # on its own worker, so the shutter is free again the moment the
            # ~1 s pull loop ends — back-to-back shots are allowed while the
            # previous merge resolves.  Only a press past the queue depth or
            # the byte budget gets the danger-flash pacing cue; the burst
            # never exposes the shutter to a dropped capture.
            with _bm_lock:
                _bm_shoot_armed = _bm_active
                _bm_shoot_state = _bm_state
                _bm_shoot_pending = _bm_merge_pending
            if _bm_shoot_armed and _bm_unavailable():
                # Should be unreachable (arming is refused and a mode
                # switch disarms), but a 47 MP burst OOM-kills the process
                # and a Mono Raw burst would write a mismatched pair —
                # disarm and fall through to a normal capture so the press
                # still lands a shot.
                _exit_burst_mode()
                _bm_shoot_armed = False
            if _bm_shoot_armed and not _bren_capturing:
                if (_bm_shoot_state != "idle"
                        or _bm_shoot_pending >= _BM_MERGE_QUEUE_MAX):
                    print("[BurstSR] Blocked: merge queue full "
                          f"({_bm_shoot_pending} pending)")
                    _post_save_warning("Merging — one moment")
                    _capture_blocked_flash_until = (
                        time.monotonic() + _CAPTURE_BLOCKED_FLASH_S)
                    continue
                # Byte-budget admission for the WHOLE burst (the generic
                # single-frame gate above under-counts it): a typical burst
                # pins ~target-frames payloads until its merge resolves.
                _bm_frame_est = (
                    SENSOR_MODE_W * SENSOR_MODE_H * 2 if _mono_sensor_active
                    else _CAPTURE_FULL_W * _CAPTURE_FULL_H * 3)
                if not _capture_mem_budget_ok(
                        _BM_TARGET_FRAMES * _bm_frame_est):
                    print("[BurstSR] Blocked: save pipeline at memory "
                          "budget — waiting for pending merges/saves")
                    _post_save_warning("Merging — one moment")
                    _capture_blocked_flash_until = (
                        time.monotonic() + _CAPTURE_BLOCKED_FLASH_S)
                    continue
                _bm_started = False
                try:
                    _bm_started = _bm_run_burst_capture(
                        jpg_path, dng_path, target_ratio, capture_film_key,
                        capture_exif_desc)
                except Exception as _bm_exc:
                    # Belt over the function's own guards — the preview loop
                    # must survive anything the burst path does.
                    print(f"[BurstSR] unexpected burst error: {_bm_exc}")
                    traceback.print_exc()
                    with _bm_lock:
                        _bm_state = "idle"
                if _bm_started:
                    _shutter_blink()
                _record_activity(wake=True)
                continue

            # 47 MP threaded path: when high-res mode is selected and we are
            # not in brenizer or double-exposure (which need synchronous
            # state coordination), spawn a worker thread that does the
            # mode-switch capture and queues the result, then continue the
            # main loop.  The main loop's preview path is gated by
            # _high_res_capture_busy so it does not touch picam2 while the
            # worker owns the camera.  This keeps the UI responsive — the
            # screen does not freeze for the ~2 s capture, only the live
            # preview pixels are paused (overlays, settings, time keep
            # updating).
            with _double_exposure_lock:
                _de_enabled_now = double_exposure_enabled
            if (
                _high_res_capture_config is not None
                and not _bren_capturing
                and not _de_enabled_now
            ):
                if _high_res_capture_busy.is_set():
                    # A previous capture is still running; drop this event.
                    continue
                _black_flash_frames = _HIGH_RES_BLACK_FLASH_FRAMES
                _cap_dispatched_at = time.monotonic()
                _display_show("Camera", _black_canvas)
                _display_pump(1)
                _high_res_capture_done.clear()
                # The hold-still cue is held on the done Event, not the
                # frame counter above (which only guarantees the FIRST
                # presented frame is the status canvas): the read-out can
                # outlast 30 presented frames, and a cue that drops before
                # the sensor has finished invites the motion it exists to
                # prevent.  Cleared by the main loop the iteration it sees
                # the Event (or the busy flag drop).
                _hires_blackout_active = True
                _high_res_capture_busy.set()
                threading.Thread(
                    target=_high_res_capture_worker,
                    args=({
                        "dng_path": dng_path,
                        "jpg_path": jpg_path,
                        "target_dims": target_dims,
                        "target_ratio": target_ratio,
                        "film_key": capture_film_key,
                        "overlay_frame": None,
                        "slow_shutter_us": _cap_slow_us,
                        "iso_gain": _cap_iso_gain,
                        "iso_stretch": _cap_iso_stretch,
                        "pan_mono": _cap_pan_mono,
                        "exif_desc": capture_exif_desc,
                        "defer_processing": _deferred_wanted(),
                        # Exposure metadata of the frame on screen — the
                        # worker plans the capture from it instead of
                        # blocking a preview period for the next frame.
                        "live_md": (dict(_meta)
                                    if isinstance(_meta, dict) and _meta
                                    else None),
                        # Anchors the blackout breakdown on the press, so
                        # the thread start and any CMA-warm claim wait
                        # ahead of the worker are on the line too.
                        "dispatched_at": _cap_dispatched_at,
                    },),
                    name="hires_capture_worker",
                    daemon=True,
                ).start()
                _record_activity(wake=True)
                continue

            # Sensor-limited wait cue (instant path only — the binned
            # mode-switch paths present their own status canvas): when the
            # time from press to grab is user-visible — the unbinned 47 MP
            # read-out at hundreds of ms per frame, or a manual slow shutter
            # whose drain below spans multiples of the exposure — paste the
            # "Image capturing" panel over the held frame NOW so the whole
            # wait reads as intentional rather than a frozen viewfinder.
            # The estimate takes the largest of the measured blocking time
            # of the last preview pull (ground truth for the freeze the
            # user actually experiences — never dependent on a metadata
            # key), the sensor-reported FrameDuration, and the slow-shutter
            # target.
            if _high_res_capture_config is None:
                _wait_us = int(_last_pull_wait_us)
                try:
                    _wait_us = max(_wait_us,
                                   int(_meta.get("FrameDuration") or 0))
                except Exception:
                    pass
                if _cap_slow_us:
                    _wait_us = max(_wait_us, int(_cap_slow_us))
                _dc = globals().get("display_canvas")
                if _wait_us >= _CAPTURE_WAIT_HINT_US and _dc is not None:
                    try:
                        _wait_canvas = _dc.copy()
                        _wait_canvas[
                            _CAPTURE_WAIT_Y:_CAPTURE_WAIT_Y
                            + _CAPTURE_WAIT_PH,
                            _CAPTURE_WAIT_X:_CAPTURE_WAIT_X
                            + _CAPTURE_WAIT_PW,
                        ] = _capture_wait_panel
                        _display_show("Camera", _wait_canvas)
                        _display_pump(1)
                        # Mirror to the LAN live view (forced past the
                        # publish throttle, like the binned blackout).
                        _preview_publish(_wait_canvas, force=True)
                    except Exception:
                        pass

            # Lift the preview frame-rate cap so the capture can use the full
            # exposure range.  Manual slow shutter: exact target exposure.
            # AUTO mode: capture immediately with current AE state (preview
            # already converged at up to 1/30s, ISO compensates in low light).
            # For Brenizer mode: after first shot exposure is locked, so
            # _slow_shutter_capture_us should be None (AE disabled).
            if _cap_slow_us is not None and not _bren_capturing:
                _target_us = int(_cap_slow_us)
                picam2.set_controls({
                    "ExposureTime": _target_us,
                    "FrameDurationLimits": (_target_us, _target_us),
                })
                # picamera2 applies set_controls on the next request, but
                # requests already buffered at the preview-capped 1/30s
                # exposure must drain first before a frame with the real
                # slow exposure is available.  Pull metadata until the
                # sensor reports the target exposure — capture_metadata()
                # blocks for one frame, so it doubles as a drain.
                _tol_us = max(1000, _target_us // 20)
                _deadline = time.monotonic() + (_target_us / 1e6) * 6 + 0.5
                while time.monotonic() < _deadline:
                    try:
                        # Bounded like the preview pull — this drain runs on
                        # the UI thread and must never wedge on a dead
                        # pipeline.
                        _md = _hires_bounded_wait(
                            picam2.capture_metadata(wait=False),
                            _PREVIEW_PULL_WAIT_S)
                    except Exception:
                        break
                    if abs(_md.get("ExposureTime", 0) - _target_us) <= _tol_us:
                        break
            _pending_dng_path = None
            _pending_dng_raw = None
            try:
                if _high_res_capture_config is not None:
                    # 47 MP capture path.  Show blackout, then call the
                    # dedicated high-res helper which:
                    #   - snapshots the live preview's exposure
                    #   - stops the preview, switches to the 47 MP still
                    #     config (with that exposure locked in)
                    #   - grabs the raw payload + 47 MP main array from one
                    #     request (the DNG encode/write is deferred to the
                    #     save worker, off the frozen-screen window)
                    #   - switches back to the 11 MP preview pipeline
                    # The main array is then queued to _capture_save_queue
                    # so the existing save worker thread does the JPG
                    # processing asynchronously, identical to 11 MP.  The
                    # 11 MP path below is unchanged.
                    _black_flash_frames = _HIGH_RES_BLACK_FLASH_FRAMES
                    _display_show("Camera", _black_canvas)
                    _display_pump(1)
                    # The loop blocks for ~2 s inside the synchronous 47 MP
                    # capture below; push the blackout to the live-view
                    # stream now (force past the publish throttle) so the
                    # remote mirror cuts to black with the panel instead of
                    # freezing on a stale frame.
                    try:
                        _preview_publish(_black_canvas, force=True)
                    except Exception:
                        pass
                    # Arm the busy flag for the duration of this SYNCHRONOUS 47 MP
                    # reconfigure+capture (Brenizer / double-exposure path).  GPIO
                    # and touch callbacks run on other threads and check this flag
                    # to drop input, and _apply_shutter_controls defers on it —
                    # without it a concurrent set_controls can race the
                    # stop/configure/start cycle and hang the camera.  The
                    # threaded path sets this too; the two paths are mutually
                    # exclusive (this one only runs for bren/double-exp).
                    _high_res_capture_busy.set()
                    _warm_held = False
                    try:
                        # Same warm exclusion as the threaded worker.
                        _warm_held = _hires_warm_claim("47 MP capture")
                        full_frame, _pending_dng_raw = _perform_high_res_capture(
                            dng_path,
                            slow_shutter_us=(
                                _cap_slow_us if not _bren_capturing else None
                            ),
                            sel_gain=_cap_iso_gain,
                            sel_stretch=_cap_iso_stretch,
                            mono_raw=_cap_pan_mono, develop_mono=True,
                        )
                    finally:
                        _hires_warm_release(_warm_held)
                        _high_res_capture_busy.clear()
                        # _black_flash_frames only counts down on PRESENTED frames (see
                        # the display tail below) and the loop was blocked inside the call
                        # above with none presented -- the blackout the user saw WAS this
                        # capture. Left at _HIGH_RES_BLACK_FLASH_FRAMES, the tail would then
                        # paint ~1.25 s of MORE solid black after the preview is already
                        # restored, on every Brenizer tile / double-exposure shot. Clear it
                        # in this finally (not after) so it fires on the exception path too
                        # -- a raise from _perform_high_res_capture skips straight past the
                        # code below to the outer `except Exception as e: capture_error = e`.
                        _black_flash_frames = 0
                    # The helper's own step-9 _apply_shutter_controls() call
                    # silently early-returns on this SYNCHRONOUS path: the
                    # busy flag is still set and this is MainThread, not the
                    # "hires_capture_worker" thread the guard whitelists. The
                    # 47 MP capture's AeEnable=False + boosted-gain lock then
                    # survives into the restored preview (blown ~2 stops,
                    # AE frozen, HUD claiming AUTO). Re-apply the user's
                    # exposure state now that the flag is clear — except for
                    # Brenizer, whose tile-to-tile exposure lock must not be
                    # unfrozen mid-sequence (its exit path restores).
                    if not _bren_capturing:
                        try:
                            _apply_shutter_controls()
                        except Exception as _restore_exc:
                            print(f"[HiRes] sync-path control restore failed: {_restore_exc}")
                    if full_frame is not None and _pending_dng_raw is not None:
                        # DNG rides the save queue (deferred write); when the
                        # raw grab failed only the JPG is saved.
                        _pending_dng_path = dng_path
                else:
                    # Instant capture - already running in still_config with raw
                    # stream.  Grab the main array AND the raw DNG payload from a
                    # SINGLE request (fast in-memory copies), release the request
                    # immediately, then DEFER the DNG encode+write to the save
                    # worker.  This keeps the multi-MB RAW DNG disk write off the
                    # preview thread, which was the main source of the per-capture
                    # freeze.  make_buffer copies, but we copy again defensively
                    # so the data is fully independent of the recycled DMA buffer.
                    # Bounded: a still pipeline that stopped delivering must
                    # fail this capture (caught below, HUD-warned) instead of
                    # freezing the UI thread — the bounded preview pull will
                    # then drive the self-heal restart.  (The sensor-limited
                    # wait cue for this blocking grab was presented above,
                    # before the slow-shutter drain.)
                    capture_request = _hires_bounded_wait(
                        picam2.capture_request(wait=False), _HIGH_RES_WAIT_S)
                    # make_array views the request's DMA buffer, which the
                    # camera recycles on release(); copy so full_frame stays
                    # valid after release — critical for double exposure, where
                    # the first frame is held across many preview iterations
                    # (its buffer is otherwise recycled and the stored shot is
                    # garbage by the time the second shot blends it).
                    full_frame = capture_request.make_array("main").copy()
                    try:
                        # make_buffer materialises a fresh array from the
                        # mapped DMA buffer (np.array of the memoryview), so
                        # it is already detached from the recycled buffer.
                        # The old extra np.array(copy=True) wrapper doubled
                        # the raw payload for nothing — ~95 MB per shot at
                        # 47 MP, on the preview thread, in the middle of the
                        # capture's peak-memory window. Keep a guard for a
                        # hypothetical picamera2 that returns a view.
                        _raw_buf = capture_request.make_buffer("raw")
                        if not _raw_buf.flags.owndata:
                            _raw_buf = _raw_buf.copy()
                        _pending_dng_raw = (
                            _raw_buf,
                            capture_request.get_metadata(),
                            capture_request.config["raw"],
                        )
                        _raw_buf = None
                        _pending_dng_path = dng_path
                    except Exception as dng_err:
                        print("DNG buffer grab error:", dng_err)
                        _pending_dng_raw = None
                    try:
                        # The same request also carries the lores plane —
                        # hand it to this iteration's preview pull so the
                        # loop does not block a second full frame period
                        # re-pulling what it already holds (halves the
                        # post-capture freeze on the sensor-limited
                        # unbinned 47 MP read-out).
                        _captured_preview_lores = (
                            capture_request.make_array("lores").copy())
                        _meta = capture_request.get_metadata()
                    except Exception:
                        _captured_preview_lores = None
                    capture_request.release()
                    # Blink after the grab — read-out is complete, this is
                    # the "you can move the camera again" cue.
                    _shutter_blink()
            except Exception as e:
                capture_error = e
                if capture_request is not None:
                    try:
                        capture_request.release()
                    except Exception:
                        pass

            if capture_error is not None:
                print("Capture error:", capture_error)
                if _high_res_capture_config is not None:
                    traceback.print_exc()
            elif full_frame is not None:
                if _high_res_capture_config is not None:
                    print(f"[HiRes] queueing frame for save: shape={full_frame.shape} "
                          f"jpg={jpg_path} dng={_pending_dng_path}")
                if _bren_capturing:
                    # Brenizer mode: save frame and advance tile
                    _capture_save_queue.put(
                        (
                            full_frame,
                            target_dims,
                            target_ratio,
                            capture_film_key,
                            jpg_path,
                            None,  # no overlay frame
                            _pending_dng_path,
                            _pending_dng_raw,
                            capture_exif_desc,
                            # 47 MP-sourced tiles keep the ISP frame (their
                            # raw payload is only the deferred DNG); instant
                            # tiles keep the historical mono develop.
                            _high_res_capture_config is None,
                            # Mono Raw as of THIS shutter press — read on the
                            # main loop in the same iteration as the grab, so
                            # a later dropdown change cannot retarget it.
                            _mono_raw_active(),
                            time.monotonic(),   # queue timestamp
                        )
                    )
                    _mark_capture_queued(
                        _capture_job_bytes(full_frame, _pending_dng_raw))
                    # Store cell-sized thumbnail for minimap display
                    _cell_w, _cell_h = 56, 36  # must match minimap cell size
                    try:
                        _tile_thumb = cv2.resize(full_frame, (_cell_w, _cell_h),
                                                 interpolation=cv2.INTER_AREA)
                        if _tile_thumb.ndim == 3 and _tile_thumb.shape[2] == 4:
                            _tile_thumb = cv2.cvtColor(_tile_thumb, cv2.COLOR_BGRA2BGR)
                    except Exception:
                        _tile_thumb = None
                    _brenizer_tile_thumbs.append(_tile_thumb)
                    _brenizer_on_capture(jpg_path)
                else:
                    # Normal / Double Exposure capture flow
                    overlay_frame = None
                    skip_save = False
                    with _double_exposure_lock:
                        if double_exposure_enabled:
                            if double_exposure_first_frame is None:
                                double_exposure_first_frame = full_frame
                                _double_preview_cache = {"key": None, "image": None}
                                skip_save = True
                            else:
                                overlay_frame = double_exposure_first_frame
                                double_exposure_first_frame = None
                                _double_preview_cache = {"key": None, "image": None}
                        else:
                            double_exposure_first_frame = None
                            _double_preview_cache = {"key": None, "image": None}
                    if skip_save:
                        # Restore preview frame rate even when skipping save
                        if _cap_slow_us is not None:
                            _apply_shutter_controls()
                        _record_activity(wake=True)
                        continue
                    # Backpressure guard: warn if save queue is backing up
                    _save_depth = _capture_save_queue.qsize()
                    if _save_depth >= 5:
                        print(f"[Capture] Save queue depth: {_save_depth} — saves may be slow")
                    _capture_save_queue.put(
                        (
                            full_frame,
                            target_dims,
                            target_ratio,
                            capture_film_key,
                            jpg_path,
                            overlay_frame,
                            _pending_dng_path,
                            _pending_dng_raw,
                            capture_exif_desc,
                            # Instant captures keep the mono raw develop; a
                            # 47 MP-sourced frame (sync bren/double path) is
                            # already the brightness-matched ISP frame.
                            _high_res_capture_config is None,
                            # Mono Raw as of THIS shutter press — read on the
                            # main loop in the same iteration as the grab, so
                            # a later dropdown change cannot retarget it.
                            _mono_raw_active(),
                            time.monotonic(),   # queue timestamp
                        )
                    )
                    _mark_capture_queued(
                        _capture_job_bytes(full_frame, _pending_dng_raw,
                                           overlay_frame))

            # Restore preview frame-rate cap after capture
            if _cap_slow_us is not None and not _bren_capturing:
                _apply_shutter_controls()

        # Preview frame + overlays (read the lores stream — cheap downscale).
        # If the 47 MP capture worker currently owns picam2, we cannot read
        # from it without racing the worker's mode switch — reuse the last
        # good lores frame so the rest of the loop (overlays, status text,
        # touch handling) keeps running.  When the worker clears the busy
        # flag the next iteration goes back to live capture_array.
        if _high_res_capture_busy.is_set() and _last_lores_frame is not None:
            # Work on a COPY of the frozen frame.  Downstream steps mutate
            # `frame` in place — notably the slow-shutter brightness gain
            # (cv2.convertScaleAbs(..., dst=frame)) — and writing into the
            # cached _last_lores_frame would re-brighten the same buffer every
            # frozen iteration, blowing the held preview out to solid white
            # within a few frames (and publishing that to the MJPEG stream).
            frame = _last_lores_frame.copy()
        elif _captured_preview_lores is not None:
            # An instant capture just pulled a complete request — or the
            # 47 MP restore proved the pipeline live with one — reuse its
            # lores plane (the shot itself / the first live preview frame)
            # instead of blocking another (possibly sensor-limited) frame
            # period on capture_request.
            frame = _captured_preview_lores
            _captured_preview_lores = None
            if _captured_preview_meta is not None:
                _meta = _captured_preview_meta
                _captured_preview_meta = None
            _last_lores_frame = frame
            _preview_err_count = 0
            _preview_heal_failures = 0
        else:
            # Pull the lores frame AND its exposure metadata from a SINGLE
            # completed request.  The old path called capture_array() here and
            # a separate periodic capture_metadata() further down — each
            # dispatches its own job to the camera thread and waits, so a
            # metadata refresh cost an extra sensor-frame of latency (a visible
            # pacing hitch).  One request yields both, so metadata is now fresh
            # every frame at no extra pipeline cost.
            _req = None
            _pull_t0 = time.monotonic()
            try:
                # Bounded (see _PREVIEW_PULL_WAIT_S): a stalled pipeline must
                # raise here — feeding the containment below — instead of
                # freezing the UI thread inside an unbounded wait.
                _req = _hires_bounded_wait(
                    picam2.capture_request(wait=False), _PREVIEW_PULL_WAIT_S)
                _last_pull_wait_us = int(
                    (time.monotonic() - _pull_t0) * 1e6)
                # make_array can view the request's DMA buffer, which the camera
                # recycles on release(); copy so the cached frame stays valid.
                frame = _req.make_array("lores").copy()
                try:
                    _meta = _req.get_metadata()
                except Exception:
                    pass
                _last_lores_frame = frame
                _preview_err_count = 0
                _preview_heal_failures = 0
                # Flash sync: feed the SAME request's raw plane into the ring
                # and run detection.  Reusing the viewfinder's own request is
                # what keeps the live view at its normal rate while a
                # free-running raw ring is active — there is no second pull
                # and no second pipeline.  Costs nothing when disarmed.
                if _flash_armed:
                    _flash_ring_push(_req, _meta)
            except Exception as e:
                # Rate-limit per exception signature on the SAME dict/period
                # the outer per-frame containment uses below — a pipeline
                # stuck raising immediately used to print this every pass
                # (~20 Hz) forever, and sharing the limiter keeps the two
                # prints from flooding the journal together.
                _pv_err_sig = ("PreviewCaptureError", type(e).__name__, str(e))
                _pv_err_now = time.monotonic()
                if (_pv_err_now - _main_loop_err_last_print.get(_pv_err_sig, -1e9)
                        >= _MAIN_LOOP_ERR_PRINT_PERIOD_S):
                    if len(_main_loop_err_last_print) > 32:
                        _main_loop_err_last_print.clear()
                    _main_loop_err_last_print[_pv_err_sig] = _pv_err_now
                    print("Preview capture error:", e)
                # Keep the GUI event pump alive while the preview is down —
                # this path used to skip both imshow and waitKey, so a dead
                # pipeline also killed touch input and (because the outer
                # containment counter reset every pass) could never reach
                # the fatal-exit/systemd-restart escape hatch. The camera
                # sat frozen on its last canvas forever.
                try:
                    _display_pump(1)
                except Exception:
                    pass
                # Video / 47 MP-worker states are not self-heal territory
                # (their own machinery owns the pipeline) — and errors seen
                # there must not accumulate either, or the first transient
                # error after returning to plain preview would instantly
                # trip a restart with a stale count. Count only in the
                # eligible state; reset otherwise.
                if _video_mode_active or _high_res_capture_busy.is_set():
                    _preview_err_count = 0
                else:
                    # A timeout proves seconds of pipeline silence — weight it
                    # so the restart fires after ~2 timeouts, not 40 spins.
                    _preview_err_count += (
                        _PREVIEW_ERR_TIMEOUT_WEIGHT
                        if _hires_wait_timed_out(e) else 1)
                # Only actually attempt the heal once the escalating backoff
                # deadline (set below on a failed attempt) has passed — a
                # pipeline that comes back up dead every time would otherwise
                # get restarted every ~2 s forever with no escalation and no
                # way out (see _PREVIEW_HEAL_BACKOFF_S above).
                if (_preview_err_count >= _PREVIEW_ERR_RESTART_AFTER
                        and time.monotonic() >= _preview_heal_next_attempt_t):
                    # Seconds of consecutive capture failures on the still
                    # pipeline: self-heal with the same fallback chain used
                    # at boot / mode switch / wake instead of spinning dead.
                    # LE / Brenizer stay eligible on purpose — they source
                    # from this same still pipeline, so a restart is their
                    # rescue too — but a mid-sequence Brenizer must get its
                    # tile-to-tile exposure lock back, not the user's live
                    # AE (which _apply_shutter_controls would re-enable).
                    _preview_err_count = 0
                    print("[Preview] persistent capture failure — "
                          "restarting still pipeline")
                    # Same reconfigure-race guard as the 47 MP paths: GPIO/
                    # touch/HTTP callbacks defer their set_controls while
                    # this flag is up, so none can land mid stop/configure/
                    # start and hang libcamera. Controls are re-applied
                    # after the clear (the guard would swallow them inside).
                    _heal_ok = False
                    _high_res_capture_busy.set()
                    try:
                        # Timed-out pulls may have left cancelled/stale jobs
                        # queued inside picamera2 — flush them (when the API
                        # exists) so the restart starts clean.
                        try:
                            _cancel = getattr(
                                picam2, "cancel_all_and_flush", None)
                            if _cancel is not None:
                                _cancel()
                        except Exception:
                            pass
                        try:
                            picam2.stop()
                        except Exception:
                            pass
                        try:
                            _heal_ok = _start_still_pipeline_with_fallback()
                        except Exception as _heal_exc:
                            print("[Preview] pipeline restart failed:", _heal_exc)
                    finally:
                        _high_res_capture_busy.clear()
                    if _heal_ok:
                        _preview_heal_failures = 0
                        _preview_heal_next_attempt_t = 0.0
                        with _brenizer_lock:
                            _heal_bren_lock = (
                                dict(_brenizer_locked_controls)
                                if (_brenizer_active and _brenizer_locked_controls)
                                else None
                            )
                        try:
                            if _heal_bren_lock is not None:
                                picam2.set_controls(
                                    {"AeEnable": False, **_heal_bren_lock})
                            else:
                                _apply_shutter_controls()
                        except Exception as _heal_exc:
                            print("[Preview] control restore failed:", _heal_exc)
                    else:
                        print("[Preview] pipeline restart failed — "
                              "fallback chain exhausted")
                        _preview_heal_failures += 1
                        if _preview_heal_failures >= _PREVIEW_HEAL_MAX_FAILURES:
                            # The in-process fallback chain has now failed
                            # _PREVIEW_HEAL_MAX_FAILURES times running: this
                            # process cannot bring libcamera back up on its
                            # own. Exit deliberately (mirrors the fatal path
                            # below the main loop) so camera.service's
                            # Restart=on-failure (see update.sh) gets a
                            # fresh process — the one recovery a same-process
                            # retry loop cannot perform for itself.
                            print("[Preview] pipeline dead after "
                                  f"{_PREVIEW_HEAL_MAX_FAILURES} failed "
                                  "restarts — exiting for a supervised "
                                  "restart")
                            try:
                                _post_save_warning("Camera fault — restarting")
                            except Exception:
                                pass
                            try:
                                _drain_save_queues()
                            except Exception:
                                pass
                            try:
                                _restore_hardware_state()
                            except Exception:
                                pass
                            sys.exit(1)
                        # Keep the restart trigger ARMED so the deadline
                        # below is the only thing pacing the next attempt:
                        # the count was zeroed before this attempt, and a
                        # stopped pipeline raises immediately (weight 1 per
                        # iteration), so re-accumulating 40 at the 0.25 s
                        # spin would take ~10 s — longer than every step of
                        # the ladder, which would leave it inert.
                        _preview_err_count = _PREVIEW_ERR_RESTART_AFTER
                        _pv_bo_wait = _preview_heal_backoff_s(
                            _preview_heal_failures)
                        _preview_heal_next_attempt_t = (
                            time.monotonic() + _pv_bo_wait)
                        _pv_bo_sig = ("PreviewHealBackoff",
                                      _preview_heal_failures)
                        _pv_bo_now = time.monotonic()
                        if (_pv_bo_now - _main_loop_err_last_print.get(
                                _pv_bo_sig, -1e9) >= _MAIN_LOOP_ERR_PRINT_PERIOD_S):
                            if len(_main_loop_err_last_print) > 32:
                                _main_loop_err_last_print.clear()
                            _main_loop_err_last_print[_pv_bo_sig] = _pv_bo_now
                            print(f"[Preview] restart failed "
                                  f"({_preview_heal_failures}/"
                                  f"{_PREVIEW_HEAL_MAX_FAILURES}) — next "
                                  f"attempt in {_pv_bo_wait:.0f} s")
                # While a failed heal is in its backoff window, slow the
                # per-iteration spin from 0.05 s (20 Hz) to 0.25 s (4 Hz) —
                # touch stays pumped above, and there is nothing useful to do
                # faster than that while waiting out the deadline; a dead
                # pipeline must not burn battery spinning at full rate.
                time.sleep(0.25 if _preview_heal_failures > 0 else 0.05)
                continue
            finally:
                # Always hand the request back, even on the error path above
                # (the continue runs after this finally).
                if _req is not None:
                    try:
                        _req.release()
                    except Exception:
                        pass

        # --- Long-exposure: route incoming frames to the processor and
        #     substitute the published building-preview for the rest of the
        #     pipeline.  Auto-stop fires here so the save runs on the main
        #     thread (same as a manual second-shutter-press).
        with _le_lock:
            _le_loop_capturing = _le_state == "capturing"
        if _le_loop_capturing:
            # Convert BGRA->BGR before submission so the blend math gets a
            # consistent 3-channel uint8 frame.
            _le_input = frame
            if _le_input.ndim == 3 and _le_input.shape[2] == 4:
                _le_input = cv2.cvtColor(_le_input, cv2.COLOR_BGRA2BGR)
            _le_submit_frame(_le_input)
            if _le_should_auto_stop():
                with _aspect_button_lock:
                    _le_cap_aspect_idx = _aspect_idx
                _le_target_ratio = ASPECT_OPTIONS[_le_cap_aspect_idx]["ratio"]
                _le_target_dims = _aspect_capture_dims[_le_cap_aspect_idx]
                with _film_button_lock:
                    _le_film_key = FILM_OPTIONS[_film_idx]["key"]
                _le_stop_capture(
                    target_dims=_le_target_dims,
                    target_ratio=_le_target_ratio,
                    film_key=_le_film_key,
                )
            else:
                _le_pub = _le_get_preview()
                if _le_pub is not None:
                    # Lores-sized BGR — same shape as the raw lores frame
                    # so the downstream pipeline (crop, scale, film sim,
                    # focus peaking) keeps working unchanged.
                    # Copy on read: the same _le_pub reference is reused
                    # across main-loop iterations until the next ~10 Hz
                    # publish, and downstream stages (e.g. slow-shutter
                    # gain via cv2.convertScaleAbs(..., dst=frame)) write
                    # in place — without the copy those writes would
                    # compound on the shared accumulator preview.
                    if _le_pub.shape == frame.shape or _le_pub.shape[:2] == frame.shape[:2]:
                        frame = _le_pub.copy()
        # Diagnostic: log when the lores frame size changes so we can see
        # exactly what dimensions picamera2 is producing after a high-res
        # capture's auto-restore.  Logs the first frame and any subsequent
        # change; never spams.
        _last_logged_shape = globals().get("_last_logged_lores_shape")
        if _last_logged_shape != frame.shape:
            print(f"[Preview] lores frame.shape={frame.shape}")
            globals()["_last_logged_lores_shape"] = frame.shape
        # _meta was refreshed from the same request as the lores frame above, or
        # retained from the last good frame while the 47 MP worker owns picam2
        # (we must not touch the camera then).  No separate capture_metadata()
        # poll — that dispatched a second job and cost an extra frame of latency.
        meta = _meta

        if frame.ndim == 3 and frame.shape[2] == 4:
            frame = cv2.cvtColor(frame, cv2.COLOR_BGRA2BGR)

        # HQ sensor (IMX477) is mounted 180° from the other sensors, so its
        # frames arrive flipped.  Rotate the camera image here — before it is
        # scaled and composited onto the canvas — so the whole downstream
        # pipeline (preview, focus/zoom geometry) operates on an upright
        # frame.  The UI is drawn on the canvas AFTER this point, so
        # buttons/text/overlays are unaffected.  No-op for
        # every other sensor (single-rotation invariant preserved).  Rotate
        # into a reused dst buffer to avoid a ~2 MB allocation every frame;
        # `frame` is a fresh array each iteration (capture/copy), so it never
        # aliases the dst (ROTATE_180 is not safe in-place).
        if _HQ_SENSOR_ACTIVE:
            if _hq_rot_buf is None or _hq_rot_buf.shape != frame.shape:
                _hq_rot_buf = np.empty_like(frame)
            cv2.rotate(frame, cv2.ROTATE_180, dst=_hq_rot_buf)
            frame = _hq_rot_buf

        # --- Slow-shutter preview simulation: digitally brighten the preview
        #     frame to match the target exposure so the histogram and live view
        #     show the correct brightness even though the sensor is running at
        #     a faster frame rate.  cv2.convertScaleAbs clips to [0,255].
        #     While flash sync is ARMED this slot belongs to the focus-preview
        #     boost instead (display-only auto-gain toward a mid target, so a
        #     scene set up dark for flash can still be framed and manually
        #     focused — the peaking/rangefinder overlays downstream see the
        #     brightened frame too, and captures come from the raw ring,
        #     untouched).  Owning the slot outright also keeps a STALE
        #     slow-shutter gain from applying while armed:
        #     _apply_shutter_controls early-returns for the whole arming, so
        #     a 2 s shutter selected before arming would otherwise leave its
        #     ~40x sim gain blowing the armed preview out white.
        if _flash_armed:
            if (_flash_preview_boost_on
                    and os.environ.get("WLV_FLASH_PREVIEW_BOOST", "1") != "0"):
                try:
                    _fpb_mean = float(frame[::8, ::8].mean())
                except Exception:
                    _fpb_mean = 0.0
                _flash_preview_gain = _flash_preview_gain_step(
                    _flash_preview_gain, _fpb_mean)
            else:
                # Ambient rendering: show the true (dark) frame.  Reset the
                # servo so toggling Boost back on ramps up smoothly from 1x
                # instead of snapping to the last held gain.
                _flash_preview_gain = 1.0
            _gain = _flash_preview_gain
        else:
            _gain = _preview_brightness_gain
        if _gain > 1.01:
            # Slow-shutter brightening: historical encoded-domain multiply.
            cv2.convertScaleAbs(frame, alpha=_gain, beta=0, dst=frame)
        elif _gain < 0.99:
            # The low-ISO trade's min-exposure residual dim (see
            # _apply_shutter_controls).  This one is an exposure ratio and
            # MUST be applied in linear light — an encoded multiply would
            # be ~2.2x too strong in stops and would corrupt the
            # closed-loop JPG reference measured off this frame.
            _dim_lut = _preview_dim_lut(_gain)
            if _dim_lut is not None:
                cv2.LUT(frame, _dim_lut, dst=frame)

        with _film_button_lock:
            film_entry = FILM_OPTIONS[_film_idx]
            film_key = film_entry["key"]
            film_label = film_entry["label"]

        # Face Detect runs on the UNZOOMED frame and BEFORE the crop: a face
        # found inside the zoomed view could never say where to move the
        # zoom, and the tracked centre has to be in place before
        # _apply_zoom reads it or the view would lag the face by a frame.
        # Zero cost in every other mode (one boolean test).
        if face_detect_enabled:
            _face_detect_tick(frame)
            _face_track_zoom()
        elif object_track_enabled:
            # Same placement and reasons as Face Detect: the tracker needs
            # the unzoomed frame, and the zoom must follow before it crops.
            _obj_track_tick(frame)
            _face_track_zoom()
        _frame_h0, _frame_w0 = frame.shape[:2]

        zoom_factor = 0.0
        _zoom_centre_used = None
        if zoom_active and ZOOM_LEVELS:
            zoom_factor = ZOOM_LEVELS[_zoom_level_idx]
            # Snapshot the centre the crop actually used.  The touch thread
            # can move it (or drop the zoom entirely) part-way through this
            # frame, and the Face Detect overlay has to walk the SAME crop
            # to place its bracket — re-reading the global below would map
            # through a crop this frame never took.
            _zoom_centre_used = zoom_center_norm
            view_frame = _apply_zoom(frame, zoom_factor, _zoom_centre_used)
        else:
            view_frame = frame

        fh, fw = view_frame.shape[:2]
        # In video mode the lores already arrives at the aspect locked in at
        # entry, so crop to that snapshot (a no-op on the already-cropped frame)
        # rather than the animated chip value — keeps the standby/recording
        # preview framing matched to the recorded FOV even if the user nudges
        # the aspect chip (which is locked for the session, see _enter_video_mode).
        if _video_mode_active:
            aspect_ratio = _video_aspect_ratio
        else:
            aspect_ratio = _aspect_ratio_current  # animated ratio for smooth transitions
        _pre_aspect_h = fh
        _pre_aspect_w = fw
        if aspect_ratio > 0:
            crop_w, crop_h = _largest_ratio_crop_dims(fw, fh, aspect_ratio)
            if (crop_w, crop_h) != (fw, fh):
                view_frame = _center_crop(view_frame, crop_w, crop_h)
                fh, fw = view_frame.shape[:2]
        # What fraction of the frame's height and width survives the aspect
        # crop.  The Face Detect zoom needs both: its rect is normalised
        # against the FULL frame, so a crop magnifies the face again on top
        # of the zoom and would otherwise cut the head off (see
        # _face_zoom_level_idx).  Both axes, because the crop takes from
        # whichever is in surplus — a wide aspect trims the height, a
        # portrait one the width.  Measured here rather than derived, so the
        # numbers are whatever this frame actually did — animation included.
        _face_view_retained_h = fh / float(max(1, _pre_aspect_h))
        _face_view_retained_w = fw / float(max(1, _pre_aspect_w))
        # Object Track maps a tap back through the crops the frame on
        # screen took, so publish them (one tuple assignment, read by the
        # touch thread) — see _track_display_to_frame.
        if object_track_enabled:
            _obj_last_view = (_frame_w0, _frame_h0, zoom_factor,
                              _zoom_centre_used, fw, fh)
        if _ui_viewfinder_mode:
            preview_bbox_w = max(1, SCREEN_W - VIEWFINDER_PANEL_W)
            preview_x_origin = VIEWFINDER_PANEL_W
            geom_key = (fh, fw, preview_bbox_w, preview_x_origin)
        else:
            preview_bbox_w = SCREEN_W
            preview_x_origin = 0
            geom_key = (fh, fw)
        if geom_key not in _geom_cache:
            if len(_geom_cache) > 16:
                _geom_cache.clear()
            if _ui_viewfinder_mode:
                _geom_cache[geom_key] = _compute_display_geometry(
                    fw, fh, max_w=preview_bbox_w, x_origin=preview_x_origin,
                )
            else:
                _geom_cache[geom_key] = _compute_display_geometry(fw, fh)
        new_w, new_h, x_off, y_off, bar_y = _geom_cache[geom_key]
        scaled = cv2.resize(view_frame, (new_w, new_h), interpolation=cv2.INTER_AREA)
        # The focus-assist downscale is only consumed by the rangefinder,
        # focus-peaking, and focus-box paths.  In the common plain-preview case
        # nothing reads it, so skip the per-frame resize entirely.  Focus Point
        # only needs it when zoomed in (it then peaks the whole frame), and
        # Face Detect only when it has no detector and degrades to plain
        # peaking — that degradation should cost what peaking costs, not more.
        if (rangefinder_assist_enabled or focus_peaking_enabled or focus_box_enabled
                or (focus_point_enabled and zoom_active)
                or (face_detect_enabled and _face_unavailable())):
            assist_frame = _prepare_focus_assist_frame(view_frame)
        else:
            assist_frame = None

        _preview_geom["x"], _preview_geom["y"], _preview_geom["w"], _preview_geom["h"] = x_off, y_off, new_w, new_h

        if rangefinder_assist_enabled:
            _update_rangefinder_shift(assist_frame if assist_frame is not None else scaled)

        # Spot metering: while Focus Point is up (and not zoomed into the box,
        # where the box coordinates no longer map), servo ExposureValue so the
        # AGC exposes for the box region.  Metered here — pre-film-sim — so a
        # look's tone curve can't skew the reading.  An LE capture substitutes
        # the building accumulator for the live frame, so the servo holds its
        # bias until the capture ends.
        if focus_point_enabled and not zoom_active and _le_state == "idle":
            _spot_meter_tick(scaled)

        # A pending web LUT-editor grab gets this clean pre-film-sim frame
        # (zero cost while idle: one float truthiness check per frame).
        if _lut_edit_frame_wanted:
            _lut_editor_offer_frame(scaled)

        # A pending custom-WB pick resolves against the same clean
        # pre-film-sim frame (a look's cast would skew the neutral solve);
        # a committed pick then runs its bounded refinement passes here.
        # Near-zero cost while idle: two None checks per frame.
        if _wb_pick_point is not None:
            _wb_pick_sample(scaled)
        elif (_wb_refine_point is not None
                and time.monotonic() >= _wb_refine_due):
            _wb_refine_tick(scaled)

        # Clip-aware AWB hold (see _awb_clip_tick): freezes preset AWB while
        # blown highlights poison its zone statistics.  Self rate-limited —
        # one clock read per frame outside its 0.5 s cadence.
        _awb_clip_tick(scaled)

        # Mono Raw preview: the selected mode commits the capture to a
        # monochrome negative, so the viewfinder composes in monochrome —
        # otherwise the user frames B&W tonality on a colour image and only
        # discovers the difference in the gallery.  A plain desaturation,
        # deliberately: cheap (~1-2 ms at preview size), and placed AFTER
        # the WB-pick / spot-meter / LUT-editor hooks above (which need the
        # colour frame) and BEFORE the film sim, matching the save path's
        # order (mono develop first, film sim on top).  Derived per frame
        # from the selected mode key, so switching back to a normal mode
        # reverts instantly with nothing persisted.  Skipped while an LE
        # capture is building and in video mode — both of those paths save
        # COLOUR output even in a Mono Raw mode, and the preview must not
        # promise otherwise.
        if (_mono_raw_active() and not _video_mode_active
                and _le_state == "idle"):
            scaled = cv2.cvtColor(
                cv2.cvtColor(scaled, cv2.COLOR_BGR2GRAY),
                cv2.COLOR_GRAY2BGR)

        # Apply film simulation to display-sized frame instead of full-resolution
        # frame to avoid buffer starvation freezes (12.3M → ~150K pixels).
        if film_key != "none":
            scaled = apply_film_simulation_rgb(scaled, film_key)

        if focus_peaking_enabled:
            disp, gray_for_hist = apply_focus_peaking(scaled, assist_frame=assist_frame)
        elif focus_box_enabled:
            disp, gray_for_hist = apply_focus_box(scaled, assist_frame=assist_frame)
        elif focus_point_enabled:
            if zoom_active:
                # Zoomed into the box: hide the box and peak the whole (zoomed)
                # frame so the magnified region is fully evaluated.
                disp, gray_for_hist = apply_focus_peaking(scaled, assist_frame=assist_frame)
            else:
                # Focus Point runs on the small box ROI of the display frame, so
                # it doesn't consume the downscaled assist frame.
                disp, gray_for_hist = apply_focus_point(scaled)
        elif face_detect_enabled:
            # The bracket is drawn by mapping the full-frame tracked rect
            # through the very crops this frame just took — hence the six
            # values, all in scope here.  `fw`/`fh` are the view frame's
            # post-aspect-crop size, which IS the crop the map needs.  No
            # zoomed-in branch: zoom in and the box grows to fill the panel,
            # so the peaked ROI becomes the frame on its own.
            disp, gray_for_hist = apply_face_focus(
                scaled, (_frame_w0, _frame_h0, zoom_factor,
                         _zoom_centre_used, fw, fh),
                assist_frame=assist_frame)
        elif object_track_enabled:
            disp, gray_for_hist = apply_object_focus(
                scaled, (_frame_w0, _frame_h0, zoom_factor,
                         _zoom_centre_used, fw, fh))
        else:
            disp = scaled
            gray_for_hist = _mono_to_gray(scaled)

        double_overlay = _get_double_preview_overlay(
            new_w,
            new_h,
            aspect_ratio,
            film_key,
            zoom_factor if zoom_active else 1.0,
            zoom_center_norm if zoom_active else None,
        )
        if double_overlay is not None:
            cv2.addWeighted(double_overlay, _DOUBLE_PREVIEW_ALPHA, disp, 1.0 - _DOUBLE_PREVIEW_ALPHA, 0, dst=disp)

        if rangefinder_assist_enabled:
            _draw_rangefinder_overlay(disp)

        # Draw grid overlay on preview only (not included in captured image)
        _draw_grid_overlay(disp, _current_grid_key())

        # Optimized: clear only margins instead of entire canvas
        _clear_canvas_margins(canvas, x_off, y_off, new_w, new_h)
        canvas[y_off:y_off+new_h, x_off:x_off+new_w] = disp
        hist_w = min(256, new_w // 3)
        # Throttle histogram recompute — every 2nd frame in active use
        # (imperceptible at 20fps), and every 4th while the screen is dimmed
        # (idle): the histogram is barely visible then, so skip the bincount.
        _hist_frame_counter += 1
        # Dimmed idle and the thermal load-shed tiers share the relaxed
        # cadence — at the reduced frame rates a 4-frame-stale histogram is
        # imperceptible.
        _hist_interval = (_HIST_INTERVAL_DIMMED
                          if (_backlight_dimmed or _heat_shed_level)
                          else _HIST_INTERVAL_ACTIVE)
        if _hist_cached_img is None or (_hist_frame_counter % _hist_interval) == 0:
            _hist_cached_img = draw_histogram(gray_for_hist, height=BAR_H, width=hist_w, rotated=True)
        left_margin = 18
        # Viewfinder UI puts the control panel on the canvas-LEFT, so the
        # histogram has to start past the panel to stay on the preview area.
        if _ui_viewfinder_mode:
            hist_x = VIEWFINDER_PANEL_W + left_margin
        else:
            hist_x = left_margin
        blit_add(canvas, _hist_cached_img, hist_x, bar_y)

        # Battery icon in bottom row, left-aligned after histogram
        # Only re-render when battery % or charge state changes
        with _batt_lock:
            pct = batt_percent_cached
        ac_state = _read_pld_state()
        # AC-power display rule: only drop the displayed percent when plugged in
        # with NO pack installed — there the gauge senses the charge rail and
        # reads a phantom SOC. With a pack present the cached SOC is trustworthy
        # (same gate the charge screen uses, _draw_big_battery_icon), so keep it
        # and let the battery fill to the real level while the charging bolt
        # signals the AC state. Downstream readouts guard on `pct is not None`.
        if ac_state == 1 and not _charge_battery_present():
            pct = None
        # `pct` is also what draw_battery's fill-color tier (danger/warn/normal)
        # is derived from, so keying the cache on it already forces a re-render
        # the instant a charge crossing changes the fill color — no separate
        # color-state key needed.
        _batt_key = (pct, ac_state)
        if _batt_render_key != _batt_key:
            batt_iw, batt_ih = 30, 13
            bolt_size = 14 if ac_state == 1 else 0
            batt_buf = _batt_buf_with_bolt if bolt_size else _batt_buf_no_bolt
            batt_buf[:] = 0
            batt_buf_h = batt_buf.shape[0]
            batt_x_off = bolt_size + 2 if bolt_size else 0
            batt_y_off = (batt_buf_h - batt_ih) // 2
            draw_battery(batt_buf, pct, bar_y=batt_y_off, right_margin=0, left_margin=batt_x_off, align_top=True)
            if bolt_size:
                _bolt_canvas[:] = 0
                _draw_charge_icon(_bolt_canvas, True)
                bolt_y_in_buf = (batt_buf_h - bolt_size) // 2
                blit_add(batt_buf, _bolt_canvas, 0, bolt_y_in_buf)
            _batt_render_cache = cv2.rotate(batt_buf, cv2.ROTATE_180)
            _batt_render_key = _batt_key
        # Battery sits at the canvas-right edge in the bottom bar. In
        # Viewfinder UI mode the canvas-LEFT side is the control panel, so
        # the battery's existing right-edge anchor already keeps it inside
        # the preview area.
        batt_x = SCREEN_W - 18 - _batt_render_cache.shape[1]
        fixed_bar_y = SCREEN_H - BAR_H
        batt_y = fixed_bar_y + (BAR_H - _batt_render_cache.shape[0]) // 2
        blit_add(canvas, _batt_render_cache, batt_x, batt_y)

        # --- Flash sync last-capture histogram ------------------------------
        # The camera has no image review by design, so this is the ONLY
        # reading of what the flash did: the live histogram (bar-left)
        # measures the PREVIEW, which with Boost on is a display-gain image
        # and says nothing about the capture.  Sits between the chip and the
        # battery — the span the bar leaves clear — at half the live width
        # and shorter, so it reads as secondary without needing a label.
        # Rebuilt only when a new capture lands (gen change), then blitted;
        # per-frame cost is one integer compare.
        with _flash_lock:
            _lh_mode = _flash_mode_active
        _lh = _flash_last_hist
        # Not gated on _icons_fade: the live histogram beside it is always
        # drawn, so hiding only this one in minimal mode would read as a
        # glitch rather than a rule.
        if _lh is not None and _lh_mode:
            _lh_w, _lh_h = 128, 44
            if (_flash_hist_cached is None
                    or _flash_hist_cached[0] != _lh.get("gen")):
                # copy=True: a private array, so this never disturbs the
                # live histogram's shared buffer (which the live path
                # caches BY REFERENCE) nor thrashes it between two widths.
                _lh_img = draw_histogram(_lh["gray"], height=_lh_h,
                                         width=_lh_w, rotated=True,
                                         copy=True)
                if float(_lh.get("clip") or 0.0) >= _FLASH_HIST_CLIP_FRAC:
                    # rotated=True MIRRORS the columns, so the highlight
                    # end (bin 255) is at the image's LEFT.  Painting the
                    # right would flag crushed shadows as blown.
                    _acc = np.array(UI_ACCENT_DANGER, dtype=np.uint8)
                    _band = _lh_img[:, :_FLASH_HIST_ACCENT_BINS]
                    _band[_band.any(axis=2)] = _acc
                _flash_hist_cached = (_lh.get("gen"), _lh_img)
            _lh_x = max(0, batt_x - 12 - _lh_w)
            blit_add(canvas, _flash_hist_cached[1], _lh_x,
                     fixed_bar_y + (BAR_H - _lh_h) // 2)

        # --- Flash sync Boost/Ambient preview chip --------------------------
        # On-screen toggle for the armed focus-preview boost, so checking the
        # true ambient rendering is one tap instead of a popup round-trip.
        # Bottom-bar CENTER: the histogram owns the bar's left, the battery
        # its right, and the span between them is clear — nothing persistent
        # is obstructed and the composition area above stays untouched
        # (transient bottom warnings may draw over it; they fade).  Label
        # shows the CURRENT state.  Gated on mode selection (armed or not, so
        # the control never appears/vanishes mid-arming under a moving
        # finger); rect is None whenever hidden so a stale rect can't eat
        # taps.
        with _flash_lock:
            _fpc_mode = _flash_mode_active
        if _fpc_mode:
            _fpc_w, _fpc_h = 92, 34
            _flash_preview_chip_rect = _draw_exit_chip(
                canvas, (SCREEN_W - _fpc_w) // 2,
                fixed_bar_y + (BAR_H - _fpc_h) // 2,
                label="BOOST" if _flash_preview_boost_on else "AMBIENT",
                chip_w=_fpc_w, chip_h=_fpc_h)
        else:
            _flash_preview_chip_rect = None

        # --- Bottom-bar transient warnings: disk / battery / health ---
        # Collected into `_bottom_warn_specs` and handed to the shared
        # stacker so simultaneous warnings lay out in one column instead of
        # each guessing an offset (see _draw_bottom_warning_stack).
        with _disk_lock:
            _dl = _disk_level
            _dfm = _disk_free_mb
        _bottom_warn_specs = {}

        if _dl in ("warning", "critical"):
            if _dl == "critical":
                _disk_text = "NO SPACE — Clear internal memory to continue"
                _disk_color = (0, 0, 255)  # red (BGR)
            else:
                _disk_text = "LOW DISK — Enter charging mode to clear memory"
                _disk_color = (0, 180, 255)  # orange (BGR)
            if _dfm is not None:
                _disk_text += f"  ({_dfm / 1024:.1f} GB free)"
            _bottom_warn_specs["disk"] = (_disk_text, _disk_color)

        # Reuse `pct` from the battery icon section above (same frame, same lock)
        _batt_runtime_s = None
        if pct is not None and pct < _BATT_RUNTIME_HINT_PCT and ac_state != 1:
            _batt_runtime_s = _batt_runtime_estimate_s()
        if pct is not None and pct < _BATT_WARN_PCT:
            if pct < _BATT_CRITICAL_PCT:
                _batt_text = f"BATTERY CRITICAL ({pct:.0f}%) — Charge battery to record"
            else:
                _batt_text = f"LOW BATTERY ({pct:.0f}%)"
            if _batt_runtime_s is not None:
                _batt_text += f" — ~{_format_runtime(_batt_runtime_s)} left"
            _bottom_warn_specs["battery"] = (_batt_text, UI_TEXT_PRIMARY)
        elif _batt_runtime_s is not None:
            # Below the hint threshold but above the warning: a quiet runtime
            # readout next to the battery icon instead of the full warning.
            _bottom_warn_specs["battery"] = (f"~{_format_runtime(_batt_runtime_s)}", UI_TEXT_DIM)

        # Independent of charge %: a spiky pack at any SOC warrants a heads-up.
        if _batt_health_warn:
            _bottom_warn_specs["health"] = ("CHECK BATTERY — unstable voltage", _CHARGE_WARN_COLOR)

        _draw_bottom_warning_stack(canvas, _bottom_warn_specs, batt_x, fixed_bar_y, BAR_H, _frame_dt)

        hist_left = hist_x
        right_bound = hist_left - 20

        # Deferred 47 MP-restore AE diagnostics (armed by the capture
        # worker): journal the first post-restore frame's metadata — the
        # restore's own proof frame, stashed via _captured_preview_lores /
        # _captured_preview_meta — and where AE settled ~2 s after the
        # re-seed.  One bool/float compare per frame while disarmed.  The
        # busy guard keeps the frozen-frame iterations (stale meta) from
        # consuming the first-frame log.
        if _hires_ae_log_first_frame and not _high_res_capture_busy.is_set():
            _hires_ae_log_first_frame = False
            try:
                print(f"[HiRes] AE just after restore: "
                      f"exp={meta.get('ExposureTime')} "
                      f"AG={meta.get('AnalogueGain')} "
                      f"DG={meta.get('DigitalGain')} Lux={meta.get('Lux')} "
                      f"constraint={meta.get('AeConstraintMode')}")
            except Exception:
                pass
        if _hires_ae_probe_at and time.monotonic() >= _hires_ae_probe_at:
            _hires_ae_probe_at = 0.0
            try:
                print(f"[HiRes] AE 2s after restore: "
                      f"exp={meta.get('ExposureTime')} "
                      f"AG={meta.get('AnalogueGain')} "
                      f"DG={meta.get('DigitalGain')} Lux={meta.get('Lux')} "
                      f"constraint={meta.get('AeConstraintMode')}")
            except Exception:
                pass

        # Live metadata + status.  The ISO readout is scaled to the CAPTURE's
        # true ISO (x _HIGH_RES_GAIN_BOOST in the binned 47 MP mode — the
        # AUTO value must name the raw file's ISO, not the preview
        # pipeline's internal gain, same as the manual labels).  And clamped
        # the same way the capture is: in a dark scene AUTO can drive the
        # preview gain past a quarter of the sensor ceiling, where
        # _hires_boosted_gain caps the transferred gain — an unclamped
        # readout would promise an ISO the raw file cannot record (the
        # manual labels never need this; their menu is pre-filtered).
        raw_shutter_us = meta.get("ExposureTime", 0)
        _iso_disp_mult = _iso_display_multiplier()
        _iso_disp_hi = (_iso_capture_gain_ceiling()
                        if _iso_disp_mult > 1.0 else None)
        _iso_disp_gain = meta.get("AnalogueGain", 0) * _iso_disp_mult
        if _iso_disp_hi and _iso_disp_gain > _iso_disp_hi:
            _iso_disp_gain = _iso_disp_hi
        raw_iso = _iso_disp_gain * 100

        # The smoothed readout lives in display scale, so a multiplier flip
        # (entering/leaving video mode in the binned 47 MP mode) would bleed
        # the old scale through the EMA for several frames — rescale the
        # running value instead of resetting it, so the readout stays
        # smooth and lands on the new scale immediately (re-capped at the
        # ceiling, which the rescaled history can overshoot).
        if _iso_disp_mult != _iso_readout_mult:
            if _ema_iso:
                _ema_iso *= _iso_disp_mult / _iso_readout_mult
                if _iso_disp_hi and _ema_iso > _iso_disp_hi * 100:
                    _ema_iso = _iso_disp_hi * 100
            _iso_readout_mult = _iso_disp_mult

        # EMA smoothing for a more natural "camera-like" readout (does not affect exposure)
        _ema_shutter_us = _ema(_ema_shutter_us, raw_shutter_us)
        _ema_iso = _ema(_ema_iso, raw_iso)

        shutter_us = int(_ema_shutter_us) if _ema_shutter_us else raw_shutter_us
        iso = float(_ema_iso) if _ema_iso else raw_iso
        target_label = SHUTTER_LABELS[current_shutter_idx]
        with _aspect_button_lock:
            aspect_label = ASPECT_OPTIONS[_aspect_idx]["label"]
        iso_label = _current_iso_label()

        # Low-ISO (sub-floor) selection in the binned 47 MP mode: a MANUAL
        # speed is captured verbatim, so the manual readout below needs no
        # scaling — the chip IS the file's shutter.  Only the AUTO readout
        # scales by the gain trade: there the capture lengthens AE's live
        # exposure to preserve the brightness AE chose, and the readout
        # must name the exposure the file will record.
        _ss_stretch = _iso_exposure_stretch()
        shutter_label = target_label
        if not shutter_set_mode and SHUTTER_OPTIONS_US[current_shutter_idx] is None and shutter_us:
            # Quantize the smoothed AUTO exposure to the nearest 1/3-stop for a
            # stable, standard-looking readout (and to stop the per-frame cache
            # churn from jittering 1/247s -> 1/251s labels).
            shutter_label = format_shutter_speed(
                _quantize_log_third_stop(shutter_us * _ss_stretch, 1e6))
        elif (not shutter_set_mode and _antibanding_eff_us
                and SHUTTER_OPTIONS_US[current_shutter_idx] is not None):
            # Anti-banding snapped the manual exposure to a flicker-safe
            # value — show the EFFECTIVE speed so the HUD never displays a
            # shutter the sensor isn't actually using.  (The explicit manual
            # check keeps a control re-apply deferred by the 47 MP worker
            # from ever labelling AUTO with a stale effective value.)
            shutter_label = format_shutter_speed(_antibanding_eff_us)

        iso_display = iso_label
        if not shutter_set_mode and _current_iso_gain() is None and iso:
            iso_display = str(int(round(_quantize_log_third_stop(iso, 100.0))))

        right_control_rects = []
        left_control_rects = []
        control_gap = 12
        column_top = 18
        left_column_top = 18
        button_size = 72
        column_right = SCREEN_W - 18
        left_column_right = LEFT_COLUMN_MARGIN + button_size

        # Draw UI buttons with fade (smooth hide/show for minimal / viewfinder mode)
        if _icons_fade > 0.01 and not _brenizer_active and not _ui_viewfinder_mode:
            flip_rect = draw_flip_button(
                canvas,
                flip_mode != FLIP_MODE_NORMAL,
                left_column_top,
                left_column_right,
                size=button_size,
                margin=LEFT_COLUMN_MARGIN,
            )
            _flip_button_rect = flip_rect if flip_rect else (0, 0, 0, 0)
            if flip_rect:
                left_control_rects.append(flip_rect)
                left_column_top = flip_rect[3] + control_gap
            else:
                left_column_top += button_size + control_gap

            shutter_rect = _draw_shutter_controls(
                canvas,
                left_column_top,
                left_column_right,
                size=button_size,
                margin=LEFT_COLUMN_MARGIN,
            )
            if shutter_rect:
                left_control_rects.append(shutter_rect)
                left_column_top = shutter_rect[3] + control_gap
            else:
                left_column_top += button_size + control_gap

            # Multishot button (Double Exposure / Brenizer) — replaces standalone DE button
            double_rect = _draw_multishot_controls(
                canvas,
                left_column_top,
                left_column_right,
                size=button_size,
                margin=LEFT_COLUMN_MARGIN,
            )
            _double_exposure_button_rect = double_rect if double_rect else (0, 0, 0, 0)
            if double_rect:
                left_control_rects.append(double_rect)
                left_column_top = double_rect[3] + control_gap
            else:
                left_column_top += button_size + control_gap

            focus_rect = _draw_focus_controls(
                canvas,
                left_column_top,
                left_column_right,
                size=button_size,
                margin=LEFT_COLUMN_MARGIN,
            )
            _rangefinder_button_rect = focus_rect if focus_rect else (0, 0, 0, 0)
            if focus_rect:
                left_control_rects.append(focus_rect)
                left_column_top = focus_rect[3] + control_gap
            else:
                left_column_top += button_size + control_gap

            # Gesture walkthrough — reachable in normal shooting (previously
            # only from the charge-menu info button). Smaller than the
            # primary buttons since it's a secondary, occasional-use control;
            # the left column has room (4 buttons vs the right column's 5).
            info_rect = draw_info_button(
                canvas,
                left_column_top,
                left_column_right,
                size=56,
                margin=LEFT_COLUMN_MARGIN,
                subtle=True,
            )
            _gesture_info_button_rect = info_rect if info_rect else (0, 0, 0, 0)
            if info_rect:
                left_control_rects.append(info_rect)
                left_column_top = info_rect[3] + control_gap
            else:
                left_column_top += button_size + control_gap

            aspect_rect = _draw_aspect_controls(
                canvas,
                column_top,
                column_right,
                size=button_size,
                margin=16,
            )
            if aspect_rect:
                right_control_rects.append(aspect_rect)
                column_top = aspect_rect[3] + control_gap
            else:
                column_top += button_size + control_gap

            film_rect = _draw_film_controls(
                canvas,
                column_top,
                column_right,
                size=button_size,
                margin=16,
            )
            if film_rect:
                right_control_rects.append(film_rect)
                column_top = film_rect[3] + control_gap
            else:
                column_top += button_size + control_gap

            wifi_rect = draw_wifi_button(
                canvas,
                wifi_enabled,
                column_top,
                column_right,
                size=button_size,
                margin=16,
            )
            if wifi_rect:
                _wifi_button_rect = wifi_rect
                right_control_rects.append(wifi_rect)
                column_top = wifi_rect[3] + control_gap
            else:
                _wifi_button_rect = (0, 0, 0, 0)
                column_top += button_size + control_gap

            charge_rect = draw_charge_button(
                canvas,
                charge_mode_active,
                column_top,
                column_right,
                size=button_size,
                margin=16,
            )
            _charge_button_rect = charge_rect if charge_rect else (0, 0, 0, 0)
            if charge_rect:
                right_control_rects.append(charge_rect)
                column_top = charge_rect[3] + control_gap
            else:
                column_top += button_size + control_gap

            iso_rect = _draw_iso_controls(
                canvas,
                column_top,
                column_right,
                size=button_size,
                margin=16,
            )
            if iso_rect:
                right_control_rects.append(iso_rect)
                column_top = iso_rect[3] + control_gap
            else:
                column_top += button_size + control_gap

            # Exposure comp is rendered as a section inside the ISO popup
            # (drawn by _draw_iso_controls above) — no standalone overlay.

        if right_control_rects:
            control_left = min(rect[0] for rect in right_control_rects)
            right_bound = min(right_bound, control_left - 18)
        right_bound = min(SCREEN_W - 18, right_bound)

        # Skip SS/ISO and zoom text when Brenizer, Video, or Long-Exposure
        # capture provides its own status overlay.  During an LE capture the
        # shutter speed isn't meaningful (we're stacking short frames) and
        # the LE HUD already shows elapsed time + frame count; letting the
        # SS/ISO block render too would overlay-collide at the top of the
        # preview.
        with _le_lock:
            _le_hud_capturing = _le_state == "capturing"
        if not _brenizer_active and not _video_mode_active and not _le_hud_capturing:
            _set_suffix = "  SET   " if shutter_set_mode else "   "
            # Grip mode: bold the setting currently selected as the adjustable
            # target so the user sees what the two-button adjust will change.
            _grip_t = _grip_adjust_target if _grip_mode_active else GRIP_ADJUST_NONE
            _ss_bold = _grip_t == GRIP_ADJUST_SHUTTER
            _iso_bold = _grip_t == GRIP_ADJUST_ISO
            _ev_bold = _grip_t == GRIP_ADJUST_EV
            shutter_line = make_rotated_text_block(
                [[{"text": "SS ", "font_scale": 1.2, "color": UI_TEXT_PRIMARY, "bold": _ss_bold}, {"text": f"{shutter_label}{_set_suffix}", "color": UI_TEXT_PRIMARY, "bold": _ss_bold}, {"text": "ISO ", "font_scale": 1.0, "color": UI_TEXT_PRIMARY, "bold": _iso_bold}, {"text": iso_display, "font_scale": 1.4, "color": UI_TEXT_PRIMARY, "bold": _iso_bold}]],
                font_scale=1.8,
                thickness=2,
                rotate_180=True,
                max_h=BAR_H + 8,
                pad_x=4,
                pad_y=2,
                line_gap=2,
            )
            with _double_exposure_lock:
                double_on = double_exposure_enabled
                double_waiting = double_exposure_first_frame is not None
            double_suffix = ""
            if double_on:
                double_suffix = "   DE: 1/2" if double_waiting else "   DE: ON"
            # Burst SR rides the same status strip (no extra overlay): armed
            # shows SR: ON, background merges show SR: MERGE (with the queue
            # depth when a second burst is already waiting).
            with _bm_lock:
                _bm_strip_active = _bm_active
                _bm_strip_pending = _bm_merge_pending
            if _bm_strip_pending >= 2:
                double_suffix += f"   SR: MERGE x{_bm_strip_pending}"
            elif _bm_strip_pending == 1:
                double_suffix += "   SR: MERGE"
            elif _bm_strip_active:
                double_suffix += "   SR: ON"
            ev_label = _current_exp_comp_label()
            # Show EV when non-zero, or whenever it is the grip adjust target so
            # the value is visible (and bolded) while being changed.
            ev_text = f"   EV: {ev_label}" if (ev_label != "0" or _ev_bold) else ""
            timer_suffix = ""
            if _self_timer_idx > 0:
                timer_suffix = f"   T: {SELF_TIMER_OPTIONS[_self_timer_idx]['label']}"
            # Film-advance metaphor: show image_count + the optimistic
            # in-flight count so "IC:" advances the instant the shutter
            # fires rather than lagging the async save (~1 s). A brief
            # accent-color emphasis right after capture makes the advance
            # noticeable without ever showing the captured image itself.
            with _captures_in_flight_lock:
                _displayed_ic = image_count + _captures_in_flight
            _ic_now = time.monotonic()
            # Blocked (danger) outranks the normal advance emphasis — a
            # rejected press must never flash the success accent.
            _ic_blocked = _ic_now < _capture_blocked_flash_until
            _ic_flash = _ic_blocked or _ic_now < _frame_advance_flash_until
            if _ic_blocked:
                _ic_color = UI_ACCENT_DANGER
            elif _ic_flash:
                _ic_color = UI_ACCENT_EXPOSURE
            else:
                _ic_color = UI_TEXT_PRIMARY
            zoom_line = make_rotated_text_block(
                [[{"text": f"{zoom_factor:.1f}x", "color": UI_TEXT_PRIMARY}, {"text": "   IC: ", "color": _ic_color, "bold": _ic_flash}, {"text": f"{_displayed_ic}", "color": _ic_color, "bold": _ic_flash}, {"text": ev_text, "color": UI_TEXT_PRIMARY, "bold": _ev_bold}, {"text": f"{double_suffix}{timer_suffix}", "color": UI_TEXT_PRIMARY}]],
                font_scale=1.0,
                thickness=1,
                rotate_180=True,
                max_h=BAR_H - 10,
                pad_x=4,
                pad_y=2,
                line_gap=2,
            )

            # Default left margin for the zoom/IC/EV/DE label. In Viewfinder
            # UI the canvas-left holds the control panel, so push the text
            # past the panel so it stays on the preview area.
            text_left = (VIEWFINDER_PANEL_W + 18) if _ui_viewfinder_mode else 18
            if left_control_rects:
                left_bound = max(rect[2] for rect in left_control_rects)
                text_left = max(text_left, left_bound + 18)
            # If zoom text would straddle the preview edge, push it inside
            if text_left < x_off and text_left + zoom_line.shape[1] > x_off:
                text_left = x_off + 8
            text_top = max(12, y_off + 12)

            # Center: SS/ISO aligned to the visible preview area's center.
            # Viewfinder UI shifts the preview to the canvas-RIGHT half, so
            # center within that region instead of the full canvas width.
            if _ui_viewfinder_mode:
                preview_left = VIEWFINDER_PANEL_W
                preview_w = SCREEN_W - VIEWFINDER_PANEL_W
                center_x = preview_left + (preview_w - shutter_line.shape[1]) // 2
            else:
                center_x = SCREEN_W // 2 - shutter_line.shape[1] // 2
            blit_text_with_plate(canvas, shutter_line, center_x, text_top)

            # Left: zoom, image count, DE status
            # If zoom text would overlap centered SS/ISO, stack below instead.
            # Gaps are sized off the plate padding so the two backdrop plates
            # sit flush rather than overlapping into a double-dark band.
            min_gap = 2 * _HUD_PLATE_PAD_X
            if text_left + zoom_line.shape[1] + min_gap > center_x:
                zoom_y = text_top + shutter_line.shape[0] + 2 * _HUD_PLATE_PAD_Y
            else:
                zoom_y = text_top + (shutter_line.shape[0] - zoom_line.shape[0]) // 2
            blit_text_with_plate(canvas, zoom_line, text_left, zoom_y)

        # --- Viewfinder UI overlay (right-side S/S + ISO panel) ---
        # Drawn last among normal-mode overlays so it cleanly covers any
        # preview content that fell within the panel column.
        if _ui_viewfinder_mode and not _brenizer_active and not _video_mode_active:
            _draw_viewfinder_ui(canvas)

        # --- Brenizer Mode overlay rendering ---
        with _brenizer_lock:
            _bren_overlay_active = _brenizer_active
            _bren_overlay_state = _brenizer_state
            _bren_overlay_help = _brenizer_show_help

        if _bren_overlay_active:
            if _bren_overlay_help or _brenizer_help_fade > 0.01:
                # Full-screen help/instruction overlay (eased in/out)
                _render_overlay_with_fade(canvas, _render_brenizer_help_overlay,
                                          _brenizer_help_fade)
            elif _bren_overlay_state == "complete":
                # Completion screen with buttons
                _render_brenizer_complete_screen(canvas)
            elif _bren_overlay_state == "awaiting_capture":
                # Live capture guidance: mini-map + status + direction prompt
                # Mini-map in bottom-right area, above histogram bar
                # Pass the live preview frame so the active tile shows the camera feed
                # Right-anchor to the same margin as the control column so the
                # minimap tracks the screen edge like every other edge element.
                minimap_y = bar_y - 125
                _render_brenizer_minimap(canvas, 0, minimap_y,
                                        live_frame=view_frame,
                                        right_anchor=SCREEN_W - 18)

                # Status text replaces normal SS/ISO at top
                status_bottom = _render_brenizer_status(canvas, x_off, y_off, new_w, new_h)
                # Direction prompt below status
                _render_brenizer_direction_prompt(canvas, status_bottom)
                # Mid-sequence abort: same chip/position as the LE panel's
                # Exit (canvas top-right → user bottom-left). Abandons the
                # sequence; tiles already shot stay on disk.
                _brenizer_abort_rect = _draw_exit_chip(canvas, SCREEN_W - 96, 16)

        # --- Long-exposure mode overlay rendering ---
        with _le_lock:
            _le_ov_active = _le_active
            _le_ov_state = _le_state
            _le_ov_help = _le_show_help
            _le_ov_panel = _le_panel_visible
        if _le_ov_active:
            if _le_ov_help or _le_help_fade > 0.01:
                _render_overlay_with_fade(canvas, _render_long_exposure_help_overlay,
                                          _le_help_fade)
            elif _le_ov_state == "capturing":
                _render_long_exposure_hud(canvas)
            elif _le_ov_panel:
                _render_long_exposure_panel(canvas)

        # --- Video Mode overlay rendering ---
        with _video_lock:
            _vid_overlay_active = _video_mode_active
        if _vid_overlay_active:
            _draw_video_overlay(canvas)

        # --- Shutter hold-progress indicator (display-only) ---
        # Live-preview only: skipped entirely while charge/sleep own the loop
        # (unreachable here — both `continue` earlier), while the 47 MP worker
        # owns the canvas (it gets overwritten below anyway), and while video
        # is actively recording (its own REC HUD owns this space, and a hold
        # mid-recording ends the recording rather than previewing a threshold).
        # Grip mode never sets _shutter_press_start (its handlers replace the
        # legacy ones wholesale), so its ring is derived straight from the
        # buttons' live hold times instead — same visual, grip thresholds.
        if _grip_mode_active:
            if not _wake_swallow_pins and not _high_res_capture_busy.is_set():
                _hp_frac, _hp_label, _hp_active = _grip_hold_progress_state()
                if _hp_active:
                    with _video_lock:
                        _hp_video_recording = _video_recording
                    with _le_lock:
                        _hp_le_active = _le_active
                    with _brenizer_lock:
                        _hp_bren_active = _brenizer_active
                    if not (_hp_video_recording or _hp_le_active or _hp_bren_active):
                        _draw_hold_progress_indicator(canvas, _hp_frac, _hp_label)
        elif _shutter_press_start is not None and not _high_res_capture_busy.is_set():
            with _video_lock:
                _hp_video_recording = _video_recording
            if not _hp_video_recording:
                with _le_lock:
                    _hp_le_active = _le_active
                with _brenizer_lock:
                    _hp_bren_active = _brenizer_active
                _hp_elapsed = time.monotonic() - _shutter_press_start
                _hp_mode_flags = {
                    "capturing_exclusive": _hp_le_active or _hp_bren_active,
                    "video_mode": _vid_overlay_active,
                    "zoom_hold": (focus_point_enabled or face_detect_enabled
                                  or object_track_enabled
                                  or _ui_viewfinder_mode),
                    "zoom_hold_s": _zoom_hold_threshold_s(),
                }
                _hp_frac, _hp_label, _hp_active = _hold_progress_state(
                    _hp_elapsed, _hp_mode_flags)
                if _hp_active:
                    _draw_hold_progress_indicator(canvas, _hp_frac, _hp_label)

        with _wifi_lock:
            wifi_on = wifi_enabled
        _wifi_info_now = time.monotonic()
        show_wifi_info = wifi_on and (_wifi_info_now < _wifi_info_until)
        if show_wifi_info:
            _wifi_info_alpha = _transient_toast_alpha(
                _wifi_info_now, _wifi_info_started, _wifi_info_until)
        if show_wifi_info and _wifi_info_alpha > 0.01:
            ip_addr = _get_ip_address()
            with _wifi_overlay_lock:
                active_ssid = _wifi_active_ssid
            wifi_lines = []
            if active_ssid:
                wifi_lines.append([f"Connected: {active_ssid}"])
            wifi_lines.append(
                [f"Download Images: http://{ip_addr}:{DOWNLOAD_SERVER_PORT}"]
            )
            wifi_block = make_rotated_text_block(
                wifi_lines,
                font_scale=1.1,
                thickness=2,
                rotate_180=True,
                max_h=min(SCREEN_H // 2, SCREEN_W // 2),
                pad_x=12,
                pad_y=8,
                line_gap=8,
            )
            wb_h, wb_w = wifi_block.shape[:2]
            wx = max(0, (SCREEN_W - wb_w) // 2)
            wy = max(0, (SCREEN_H - wb_h) // 2)
            blit_text_with_plate(canvas, wifi_block, wx, wy,
                                 pad_x=18, pad_y=18, alpha=_wifi_info_alpha)

        # --- Transient save-failure warning (posted by the save workers) ---
        # Same visual grammar as the LE warning toast: danger accent, rotated
        # text block, screen-centered at the larger toast size so it never
        # paints over the SS/ISO readout on the top edge (see
        # _draw_center_toast).
        _save_warn_now = time.monotonic()
        if _save_warning_text and _save_warn_now < _save_warning_until:
            _draw_center_toast(
                canvas, _save_warning_text, UI_ACCENT_DANGER,
                alpha=_transient_toast_alpha(
                    _save_warn_now, _save_warning_started, _save_warning_until))

        # --- Custom-WB pick hint (armed from the film popup's Custom chip) ---
        # Same top-edge plate grammar as the save warning, but steady (no
        # fade) and cached — the pick can stay armed for many seconds.
        # Expiry is checked here so a forgotten arm quietly disappears.
        if _wb_pick_pending:
            if _save_warn_now > _wb_pick_deadline:
                _wb_cancel_pick()
            else:
                try:
                    if _wb_hint_block is None:
                        _wb_hint_block = make_rotated_text_block(
                            [[{"text": "Tap a white or gray area to set WB",
                               "font_scale": 1.0, "color": UI_TEXT_PRIMARY}]],
                            font_scale=1.1, thickness=2, rotate_180=True,
                            max_h=40, pad_x=10, pad_y=4,
                        )
                    # The save warning now plates in the screen center, so the
                    # hint no longer has to step down out of its way.
                    blit_text_with_plate(
                        canvas, _wb_hint_block,
                        (SCREEN_W - _wb_hint_block.shape[1]) // 2, 16)
                except Exception:
                    pass

        # --- Minimal-mode entry hint ("tap to show controls") ---
        # Armed once by _toggle_minimal_mode on the False->True edge; fades
        # in/out with the same _transient_toast_alpha idiom as the toasts
        # above so it never lingers and defeats the point of minimal mode.
        # Bottom-edge anchored (same row as the histogram/battery) — never
        # drawn over the clear composition center.
        _mh_now = time.monotonic()
        if _ui_minimal_mode and _mh_now < _minimal_hint_until:
            _mh_alpha = _transient_toast_alpha(
                _mh_now, _minimal_hint_started, _minimal_hint_until,
                fade_in_s=0.15, fade_out_s=_MINIMAL_HINT_FADE_OUT_S)
            if _mh_alpha > 0.01:
                _mh_block = make_rotated_text_block(
                    [[{"text": "Tap where a button was to show controls",
                       "color": UI_TEXT_DIM}]],
                    font_scale=0.9, thickness=1, rotate_180=True, max_h=30,
                    pad_x=10, pad_y=4,
                )
                _mh_x = (SCREEN_W - _mh_block.shape[1]) // 2
                _mh_y = SCREEN_H - BAR_H - _mh_block.shape[0] - 8
                blit_text_with_plate(canvas, _mh_block, _mh_x, _mh_y, alpha=_mh_alpha)

        # --- Focus Box / Focus Point / Face Detect entry hint ---
        # Armed once by _set_focus_mode on entering any of them; same
        # transient-toast fade idiom as the minimal-mode hint above, so it
        # never becomes a persistent overlay.  Face Detect gets its own
        # wording: its box is the detector's, not something you place, so
        # the shared text would name a gesture that does nothing there.
        _fh_now = time.monotonic()
        if _fh_now < _focus_hint_until:
            _fh_alpha = _transient_toast_alpha(
                _fh_now, _focus_hint_started, _focus_hint_until,
                fade_in_s=0.15, fade_out_s=_FOCUS_HINT_FADE_OUT_S)
            if _fh_alpha > 0.01:
                _fh_text = ("Tap or hold shutter to zoom to the face"
                            if face_detect_enabled
                            else "Tap a subject to track · Hold shutter to zoom"
                            if object_track_enabled
                            else "Tap to move box · Hold shutter to zoom")
                _fh_block = make_rotated_text_block(
                    [[{"text": _fh_text,
                       "color": UI_TEXT_DIM}]],
                    font_scale=0.9, thickness=1, rotate_180=True, max_h=30,
                    pad_x=10, pad_y=4,
                )
                _fh_x = (SCREEN_W - _fh_block.shape[1]) // 2
                _fh_y = SCREEN_H - BAR_H - _fh_block.shape[0] - 8
                blit_text_with_plate(canvas, _fh_block, _fh_x, _fh_y, alpha=_fh_alpha)

        # --- Shutter speed swipe OSD (centered fade-in / fade-out text) ---
        if _shutter_osd_fade > 0.01 and _shutter_osd_text:
            # Build text + pre-blurred shadow once per text change
            if _osd_composite_cache_key != _shutter_osd_text:
                _osd_font = max(28, int(SCREEN_H * 0.09))
                _osd_tw, _osd_th = _ui_measure_text(_shutter_osd_text, _osd_font)
                _osd_buf = np.zeros((_osd_th, _osd_tw, 3), dtype=np.uint8)
                _ui_draw_text(_osd_buf, _shutter_osd_text, 0, 0, _osd_font,
                              UI_ACCENT_CREATIVE, outline_bgr=(0, 0, 0))
                _osd_buf = cv2.rotate(_osd_buf, cv2.ROTATE_180)
                _osd_composite_text = _osd_buf
                # Pre-compute shadow (GaussianBlur) at full opacity
                _osd_composite_shadow = cv2.convertScaleAbs(
                    cv2.GaussianBlur(_osd_buf, (5, 5), 0), alpha=0.5, beta=0)
                _osd_composite_cache_key = _shutter_osd_text
            _osd_th, _osd_tw = _osd_composite_text.shape[:2]
            _osd_x = (SCREEN_W - _osd_tw) // 2
            _osd_y = (SCREEN_H - _osd_th) // 2
            _osd_x1 = max(0, _osd_x)
            _osd_y1 = max(0, _osd_y)
            _osd_x2 = min(SCREEN_W, _osd_x + _osd_tw)
            _osd_y2 = min(SCREEN_H, _osd_y + _osd_th)
            if _osd_x1 < _osd_x2 and _osd_y1 < _osd_y2:
                _osd_sx1 = _osd_x1 - _osd_x
                _osd_sy1 = _osd_y1 - _osd_y
                _osd_crop = (slice(_osd_sy1, _osd_sy1 + (_osd_y2 - _osd_y1)),
                             slice(_osd_sx1, _osd_sx1 + (_osd_x2 - _osd_x1)))
                _osd_roi = canvas[_osd_y1:_osd_y2, _osd_x1:_osd_x2]
                _osd_src = _osd_composite_text[_osd_crop]
                _osd_shd = _osd_composite_shadow[_osd_crop]
                if _shutter_osd_fade < 1.0:
                    _osd_src = cv2.convertScaleAbs(_osd_src, alpha=_shutter_osd_fade, beta=0)
                    _osd_shd = cv2.convertScaleAbs(_osd_shd, alpha=_shutter_osd_fade, beta=0)
                cv2.subtract(_osd_roi, _osd_shd, dst=_osd_roi)
                cv2.add(_osd_roi, _osd_src, dst=_osd_roi)

        # --- Wi-Fi selection / login overlay (modal, draws on top of everything) ---
        with _wifi_overlay_lock:
            _wifi_overlay_on = _wifi_overlay_visible
        if _wifi_overlay_on:
            _draw_wifi_overlay(canvas)

        # --- Gesture walkthrough card (first boot; tap anywhere to close) ---
        if _gesture_help_active or _gesture_help_fade > 0.01:
            _render_overlay_with_fade(canvas, _render_gesture_help_overlay,
                                      _gesture_help_fade)

        # Apply capture black-flash overlay (if active).  For the 47 MP
        # path the worker fires _high_res_capture_done as soon as the
        # sensor capture finishes (DNG written + main array grabbed),
        # well before the preview restore completes.  Drop the blackout
        # immediately at that point so the user knows they can move
        # again — _last_lores_frame is displayed during the remaining
        # preview-restore work, with an "Image processed" overlay so
        # the user knows the frozen frame is intentional.
        _hires_busy = _high_res_capture_busy.is_set()
        _hires_done = _high_res_capture_done.is_set()
        # Only let _hires_done cancel the blackout while a high-res capture is
        # actually in progress (the worker sets done mid-capture, before the
        # preview restore finishes — busy is still set then).  The done event is
        # never cleared after a 47 MP capture, so without the busy gate every
        # subsequent NORMAL capture's shutter-flash would be cancelled on its
        # first frame, making the confirmation nearly invisible.
        if _hires_done and _hires_busy and _black_flash_frames > 0:
            _black_flash_frames = 0
        # Threaded 47 MP path: the hold-still canvas stays up until the
        # worker signals the read-out complete (or drops the busy flag on
        # any exit path — its finally sets both), however many frames that
        # takes.  The frame counter is left to count down alongside; it is
        # what the synchronous Brenizer / double-exposure paths still use.
        if _hires_blackout_active and (_hires_done or not _hires_busy):
            _hires_blackout_active = False
        if _black_flash_frames > 0 or _hires_blackout_active:
            if _hires_busy:
                # 47 MP capture: show the labelled status canvas instead
                # of plain black so the user has explicit feedback.
                display_canvas = _high_res_capturing_canvas
            else:
                # Normal capture: hard cut to solid black for the flash frames
                # (Sony-style shutter blink) — a crisp snap, not a fade.
                display_canvas = _black_canvas
        else:
            if _hires_busy and _hires_done:
                canvas[
                    _HIGH_RES_PROCESSED_Y:_HIGH_RES_PROCESSED_Y + _HIGH_RES_PROCESSED_PH,
                    _HIGH_RES_PROCESSED_X:_HIGH_RES_PROCESSED_X + _HIGH_RES_PROCESSED_PW,
                ] = _high_res_processed_panel
            # Over-temp banner above the live preview (safety event, any mode).
            _render_thermal_warning(canvas)
            # Flash sync armed indicator — deliberately the ONLY one, and
            # deliberately last, so nothing else paints over it.  Border tint
            # only: no text, no icons, no overlays (the camera has no image
            # review by design and the centre stays clear for composition).
            if _flash_armed:
                _flash_draw_border(canvas)
            # Optimized: use pre-allocated buffer for flip operations
            if flip_mode == FLIP_MODE_MIRROR:
                cv2.flip(canvas, 1, dst=_flip_buffer)
                display_canvas = _flip_buffer
            elif flip_mode == FLIP_MODE_MIRROR_ROTATE:
                cv2.flip(canvas, 0, dst=_flip_buffer)
                display_canvas = _flip_buffer
            else:
                display_canvas = canvas

        # Mirror exactly what the panel shows (incl. blackout/status/flip)
        # to the LAN live view. No-op unless an MJPEG subscriber is connected.
        try:
            _preview_publish(display_canvas)
        except Exception:
            pass

        _display_show("Camera", display_canvas)
        if not _first_preview_frame_logged:
            # Boot metric: systemd-analyze stops at multi-user.target and
            # never sees the imports/Picamera2 init that dominate the
            # user-perceived boot. Measured from _PROC_START_MONO, which is
            # taken before the heavy imports — add the service's own
            # ExecMainStartTimestampMonotonic for time-to-picture from
            # power-on.
            _first_preview_frame_logged = True
            _boot_phase("first sensor frame")
            print(f"[BOOT] First preview frame presented "
                  f"{time.monotonic() - _PROC_START_MONO:.2f}s after "
                  f"process start (incl. imports)")
        if _display_pump(1) == 27:
            user_exit = True
            break

        # Decrement black-flash frames after presenting a frame
        if _black_flash_frames > 0:
            _black_flash_frames -= 1

        _pace_frame()
    except (KeyboardInterrupt, SystemExit):
        # The exit machinery relies on these propagating — never contain them.
        raise
    except Exception as exc:
        _main_loop_iter_failed = True
        _main_loop_consec_failures += 1
        # Rate-limit the traceback per exception signature so a persistent
        # per-frame error doesn't flood the journal.
        _err_sig = (type(exc).__name__, str(exc))
        _err_now = time.monotonic()
        if _err_now - _main_loop_err_last_print.get(_err_sig, -1e9) >= _MAIN_LOOP_ERR_PRINT_PERIOD_S:
            if len(_main_loop_err_last_print) > 32:
                _main_loop_err_last_print.clear()
            _main_loop_err_last_print[_err_sig] = _err_now
            print(f"[MainLoop] Frame error ({_main_loop_consec_failures} consecutive), skipping frame:", exc)
            traceback.print_exc()
        if _main_loop_consec_failures <= _MAIN_LOOP_MAX_CONSEC_FAILURES:
            # Skip the frame but keep pacing so a persistent error can't
            # busy-spin the CPU (battery budget).
            try:
                _pace_frame()
            except Exception:
                time.sleep(_FRAME_DT)
            continue
        # Seconds of nothing but consecutive failures: unrecoverable.
        print("Camera preview crash:", exc)
        traceback.print_exc()
        # A crash exit must still land any queued captures — the daemon save
        # workers die with the process otherwise.
        try:
            _drain_save_queues()
        except Exception:
            pass
        try:
            _restore_hardware_state()
        except Exception:
            pass
        sys.exit(1)
    finally:
        if not _main_loop_iter_failed:
            _main_loop_consec_failures = 0

_display_close_all()
# Stop video recording gracefully before shutting down
try:
    if _video_recording:
        _stop_video_recording()
except Exception:
    pass
# Land any queued captures / USB fsyncs before tearing the camera down —
# the save workers are daemon threads and would be killed mid-write at exit.
try:
    _drain_save_queues()
except Exception:
    pass
# Leave the hardware in a sane state whatever mode we exited from (sleep may
# have the backlight at 0 and Wi-Fi blocked; charge mode forces fan/CPU).
try:
    _restore_hardware_state()
except Exception:
    pass
try:
    picam2.stop()
except Exception:
    pass
if user_exit:
    sys.exit(0)
sys.exit(0)
